export const stingers=[{"id":"sting-flash-wipe","name":"Speed-Ramp Flash Wipe","category":"sting","blurb":"An accelerating diagonal bar reveals the logo, flashes on the hit, then rips it away.","params":[{"name":"uProgress","label":"Cue Progress","type":"float","default":0.4,"min":0,"max":1,"driver":"cue","hint":"Driven by TAKE in the app; map to a clip timeline / BPM in the host."},{"name":"uLoop","label":"Self-Run Loop","type":"bool","default":true,"hint":"On: the stinger runs on TIME in any host. Off: follows Cue Progress."},{"name":"uDuration","label":"Transition Duration","type":"float","default":1.2,"min":0.3,"max":4,"unit":"s","hint":"Cue length. The self-run loop adds a gap of max(0.6\u00c3\u2014duration, 0.5 s) so cues never exceed ~2/s."},{"name":"uShutter","label":"Motion Blur Shutter","type":"float","default":180,"min":0,"max":360,"unit":"\u00c2\u00b0","hint":"Shutter angle: 180\u00c2\u00b0 = half-frame exposure (film look), 360\u00c2\u00b0 = full smear."},{"name":"uShake","label":"Impact Shake","type":"float","default":0.5,"min":0,"max":1,"hint":"Damped camera shake after the hit (0 = locked off)."},{"name":"uHitPoint","label":"Sound-Sync Hit Point","type":"float","default":0.35,"min":0.05,"max":0.95,"hint":"Where the impact lands, as a fraction of the duration (0.35 \u00c3\u2014 1.2 s = 0.42 s). Put it on the downbeat."},{"name":"uTint","label":"Brand Primary","type":"color","default":[0,0.9,1,1],"hint":"Main light / bar colour."},{"name":"uTint2","label":"Brand Accent","type":"color","default":[1,0.18,0.55,1],"hint":"Secondary colour: exit bar, rings, sparks, impact burst."},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Broadcast Wipe","values":{}},{"name":"Fast Snap","values":{"uDuration":0.6,"uHitPoint":0.25,"uShutter":300}},{"name":"Sunset Wipe","values":{"uTint":[1,0.55,0.1,1],"uTint2":[1,0.15,0.35,1]}}],"source":"/*{\n  \"DESCRIPTION\": \"Speed-Ramp Flash Wipe \u00e2\u20ac\u201d An accelerating diagonal bar reveals the logo, flashes on the hit, then rips it away.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Stingers & Transitions\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uProgress\",\"TYPE\":\"float\",\"LABEL\":\"Cue Progress\",\"DEFAULT\":0.4,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uLoop\",\"TYPE\":\"bool\",\"LABEL\":\"Self-Run Loop\",\"DEFAULT\":true},\n    {\"NAME\":\"uDuration\",\"TYPE\":\"float\",\"LABEL\":\"Transition Duration\",\"DEFAULT\":1.2,\"MIN\":0.3,\"MAX\":4},\n    {\"NAME\":\"uShutter\",\"TYPE\":\"float\",\"LABEL\":\"Motion Blur Shutter\",\"DEFAULT\":180,\"MIN\":0,\"MAX\":360},\n    {\"NAME\":\"uShake\",\"TYPE\":\"float\",\"LABEL\":\"Impact Shake\",\"DEFAULT\":0.5,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHitPoint\",\"TYPE\":\"float\",\"LABEL\":\"Sound-Sync Hit Point\",\"DEFAULT\":0.35,\"MIN\":0.05,\"MAX\":0.95},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Brand Primary\",\"DEFAULT\":[0,0.9,1,1]},\n    {\"NAME\":\"uTint2\",\"TYPE\":\"color\",\"LABEL\":\"Brand Accent\",\"DEFAULT\":[1,0.18,0.55,1]},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Speed-Ramp Flash Wipe \u00c2\u00b7 Stingers & Transitions\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nfloat vnoise(vec2 p) {\n  vec2 i = floor(p); vec2 f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x), mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\nfloat easeOutExpo(float x) { x = clamp(x, 0.0, 1.0); return x >= 1.0 ? 1.0 : 1.0 - pow(2.0, -10.0 * x); }\nfloat easeInExpo(float x) { x = clamp(x, 0.0, 1.0); return x <= 0.0 ? 0.0 : pow(2.0, 10.0 * x - 10.0); }\nfloat easeInOutCubic(float x) { x = clamp(x, 0.0, 1.0); return x < 0.5 ? 4.0 * x * x * x : 1.0 - pow(-2.0 * x + 2.0, 3.0) * 0.5; }\nfloat easeOutBack(float x) { x = clamp(x, 0.0, 1.0); float y = x - 1.0; return 1.0 + 2.70158 * y * y * y + 1.70158 * y * y; }\n\n// Stinger timeline. Self-runs on TIME when uLoop is on, otherwise follows the host-driven uProgress.\n// Returns raw progress: outside 0..1 the stinger is idle (nothing drawn), so it never leaves remnants.\n// Loop period = duration + max(0.6*duration, 0.5 s): a fixed gap caps the cue rate at ~2/s (photosensitivity).\nfloat stingerClock() {\n  float dur = max(uDuration, 0.05);\n  if (bool(uLoop)) { float cyc = dur + max(0.6 * dur, 0.5); return mod(TIME, cyc) / dur; }\n  return uProgress;\n}\n// Impact envelope in seconds after the hit (t and hit are cue progress 0..1, dur in seconds).\n// hitFlash: 2-3 frame pop. hitSpring: damped spring (overshoot + 2 rebounds, ~0.35 s). hitEnv: their max, for legacy callers.\nfloat hitFlash(float t, float hit, float dur) { float x = (t - hit) * max(dur, 0.05); return t < hit ? 0.0 : exp(-x * 60.0); }\nfloat hitSpring(float t, float hit, float dur) { float x = (t - hit) * max(dur, 0.05); return t < hit ? 0.0 : exp(-x * 10.0) * cos(x * 38.0); }\nfloat hitEnv(float t, float hit, float dur) { float x = (t - hit) * max(dur, 0.05); return t < hit ? 0.0 : exp(-x * 7.0); }\n// Camera shake: continuous (interpolated between 60 Hz random targets, so shutter taps never straddle a jump),\n// directional, damped with the spring. amt 0..1 -> up to ~0.06 height units at the hit.\nvec2 shakeOffset(float t, float hit, float dur, float amt) {\n  float s = max(t - hit, 0.0) * max(dur, 0.05) * 60.0;\n  float k = floor(s); float f = s - k; f = f * f * (3.0 - 2.0 * f);\n  vec2 r0 = hash22(vec2(k, 3.1)) - 0.5; vec2 r1 = hash22(vec2(k + 1.0, 3.1)) - 0.5;\n  vec2 r = mix(r0, r1, f);\n  float env = t < hit ? 0.0 : exp(-(t - hit) * max(dur, 0.05) * 9.0);\n  return r * vec2(1.0, 0.6) * amt * 0.12 * env;\n}\n\n// ---- effect ----\n// Speed-ramp flash wipe. In-phase: an accelerating bar (accelerates THROUGH the logo so its tail clears\n// 1-2 frames before the hit), hit: 2-frame full-frame flash behind the logo + 6% scale pop with a spring,\n// hold ~35% of the out-phase, then the accent bar rips the logo away. Audio: kick pumps the logo scale.\nvec4 stingerFrame(vec2 p, float t) {\n  float hit = uHitPoint;\n  float a = clamp(t / hit, 0.0, 1.0);\n  float b = clamp((t - hit) / (1.0 - hit), 0.0, 1.0);\n  float bb = holdRamp(b, 0.35, 1.0);\n  float px = 1.5 / RENDERSIZE.y;\n  float kick = kickN();\n  vec2 dir = normalize(vec2(1.0, 0.35));\n  vec2 perp = vec2(-dir.y, dir.x);\n  float coord = dot(p, dir);\n  float span = 1.2;\n  float wIn = mix(-span, span, pow(a, 1.6));\n  float wOut = mix(-span, span, easeInOutCubic(bb));\n  float revealed = smoothstep(coord - px, coord + px, wIn) * smoothstep(wOut - px, wOut + px, coord);\n  float spring = hitSpring(t, hit, uDuration);\n  float flash = hitFlash(t, hit, uDuration);\n  float pop = 1.0 + 0.06 * spring + 0.04 * kick * step(hit, t) * (1.0 - bb);\n  vec2 slide = dir * (0.12 * (1.0 - easeOutExpo(a)) - 0.25 * easeInExpo(bb));\n  vec4 lg = logoRGBA((p + slide) / pop);\n  vec3 col = lg.rgb * lg.a * revealed;\n  float alpha = lg.a * revealed;\n  // light bar: wide at peak speed, hard white core, speed streaks\n  float speedIn = pow(a, 0.6) * (1.0 - a * 0.3);\n  float speedOut = 1.0 - abs(bb * 2.0 - 1.0);\n  float lines = 0.55 + 0.45 * step(0.45, vnoise(vec2(dot(p, perp) * 90.0, 3.0)));\n  float wa = 0.03 + 0.37 * speedIn;\n  float dIn = wIn - coord;\n  float gIn = step(0.001, a) * step(a, 0.999);\n  float barIn = (1.0 - smoothstep(0.0, wa, dIn)) * smoothstep(-px, px, dIn) * gIn;\n  float coreIn = exp(-max(dIn, 0.0) / (wa * 0.22)) * smoothstep(-px, px, dIn) * gIn;\n  float wb = 0.03 + 0.3 * speedOut;\n  float dOut = wOut - coord;\n  float gOut = step(0.001, bb) * step(bb, 0.999);\n  float barOut = (1.0 - smoothstep(0.0, wb, dOut)) * smoothstep(-px, px, dOut) * gOut;\n  float coreOut = exp(-max(dOut, 0.0) / (wb * 0.22)) * smoothstep(-px, px, dOut) * gOut;\n  col += uTint.rgb * barIn * lines * 1.1 + vec3(1.0) * coreIn * 1.2;\n  col += uTint2.rgb * barOut * lines * 1.1 + vec3(1.0) * coreOut * 1.2;\n  alpha = max(alpha, max(max(barIn * lines, coreIn), max(barOut * lines, coreOut)));\n  // hit: full-frame flash behind the logo (never whitening the letters), then a glint sweeping the mark\n  vec3 flashCol = mix(vec3(1.0), uTint.rgb, 0.25);\n  float r = length(p);\n  float fl = flash * (0.55 + 0.45 * exp(-r * 1.2));\n  col += flashCol * fl * (1.0 - lg.a * revealed) * 1.1;\n  alpha = max(alpha, min(fl * 1.1, 1.0));\n  float sweep = fract(b * 1.6) * 2.4 - 1.2;\n  float glint = exp(-abs(dot(p, vec2(0.8, 0.6)) - sweep) * 40.0) * step(b, 0.6);\n  vec3 glintCol = mix(uTint.rgb, vec3(1.0), 0.5);\n  col = mix(col, glintCol, glint * lg.a * revealed * 0.85);\n  return vec4(col, alpha);\n}\n\n#ifndef STING_TAPS\n#define STING_TAPS 8\n#endif\nvoid main() {\n  vec2 p = uv2p(isf_FragNormCoord);\n  float t0 = stingerClock();\n  float dt = (TIMEDELTA > 0.0005 && TIMEDELTA < 0.1) ? TIMEDELTA : (1.0 / 60.0);\n  float expo = (uShutter / 360.0) * dt / max(uDuration, 0.05);\n  float jit = hash12(floor(isf_FragNormCoord * RENDERSIZE) + 0.37);\n  vec4 acc = vec4(0.0);\n  float n = 0.0;\n  for (int i = 0; i < STING_TAPS; i++) {\n    float t = t0 - expo * (float(i) + jit) / float(STING_TAPS);\n    if (t <= 0.0 || t >= 1.0) continue;\n    acc += stingerFrame(p + shakeOffset(t, uHitPoint, uDuration, uShake), t);\n    n += 1.0;\n  }\n  if (n > 0.0) acc /= float(STING_TAPS);\n  gl_FragColor = vjOutPM(acc);\n}\n"},{"id":"sting-iris","name":"Logo Mask Iris Collapse","category":"sting","blurb":"A brand-gradient window shrinks into the exact logo shape, holds, then irises shut to a glint.","params":[{"name":"uProgress","label":"Cue Progress","type":"float","default":0.4,"min":0,"max":1,"driver":"cue","hint":"Driven by TAKE in the app; map to a clip timeline / BPM in the host."},{"name":"uLoop","label":"Self-Run Loop","type":"bool","default":true,"hint":"On: the stinger runs on TIME in any host. Off: follows Cue Progress."},{"name":"uDuration","label":"Transition Duration","type":"float","default":1.2,"min":0.3,"max":4,"unit":"s","hint":"Cue length. The self-run loop adds a gap of max(0.6\u00c3\u2014duration, 0.5 s) so cues never exceed ~2/s."},{"name":"uShutter","label":"Motion Blur Shutter","type":"float","default":180,"min":0,"max":360,"unit":"\u00c2\u00b0","hint":"Shutter angle: 180\u00c2\u00b0 = half-frame exposure (film look), 360\u00c2\u00b0 = full smear."},{"name":"uShake","label":"Impact Shake","type":"float","default":0.5,"min":0,"max":1,"hint":"Damped camera shake after the hit (0 = locked off)."},{"name":"uHitPoint","label":"Sound-Sync Hit Point","type":"float","default":0.35,"min":0.05,"max":0.95,"hint":"Where the impact lands, as a fraction of the duration (0.35 \u00c3\u2014 1.2 s = 0.42 s). Put it on the downbeat."},{"name":"uTint","label":"Brand Primary","type":"color","default":[0,0.9,1,1],"hint":"Main light / bar colour."},{"name":"uTint2","label":"Brand Accent","type":"color","default":[1,0.18,0.55,1],"hint":"Secondary colour: exit bar, rings, sparks, impact burst."},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Classic Iris","values":{}},{"name":"Long Hold","values":{"uDuration":2.4,"uHitPoint":0.3}},{"name":"Acid Window","values":{"uTint":[0.75,1,0.1,1],"uTint2":[0.1,0.3,1,1]}}],"source":"/*{\n  \"DESCRIPTION\": \"Logo Mask Iris Collapse \u00e2\u20ac\u201d A brand-gradient window shrinks into the exact logo shape, holds, then irises shut to a glint.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Stingers & Transitions\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uProgress\",\"TYPE\":\"float\",\"LABEL\":\"Cue Progress\",\"DEFAULT\":0.4,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uLoop\",\"TYPE\":\"bool\",\"LABEL\":\"Self-Run Loop\",\"DEFAULT\":true},\n    {\"NAME\":\"uDuration\",\"TYPE\":\"float\",\"LABEL\":\"Transition Duration\",\"DEFAULT\":1.2,\"MIN\":0.3,\"MAX\":4},\n    {\"NAME\":\"uShutter\",\"TYPE\":\"float\",\"LABEL\":\"Motion Blur Shutter\",\"DEFAULT\":180,\"MIN\":0,\"MAX\":360},\n    {\"NAME\":\"uShake\",\"TYPE\":\"float\",\"LABEL\":\"Impact Shake\",\"DEFAULT\":0.5,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHitPoint\",\"TYPE\":\"float\",\"LABEL\":\"Sound-Sync Hit Point\",\"DEFAULT\":0.35,\"MIN\":0.05,\"MAX\":0.95},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Brand Primary\",\"DEFAULT\":[0,0.9,1,1]},\n    {\"NAME\":\"uTint2\",\"TYPE\":\"color\",\"LABEL\":\"Brand Accent\",\"DEFAULT\":[1,0.18,0.55,1]},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Logo Mask Iris Collapse \u00c2\u00b7 Stingers & Transitions\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// 25-tap disk coverage of the logo around p (radius r, height-normalized units).\n// x = coverage 0..1 (0.5 on the outline), yz = vector pointing into the logo.\nvec3 logoField(vec2 p, float r) {\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n// Approximate signed distance (positive outside) from a logoField sample of radius r.\nfloat fieldSD(vec3 f, float r) { return (0.5 - f.x) * 2.0 * r; }\n// Edge glow that falls to exactly zero at the field radius r (no full-frame haze floor).\nfloat edgeGlow(float sd, float k, float r) { float f = exp(-r * k); return max(exp(-abs(sd) * k) - f, 0.0) / (1.0 - f); }\n\n// logoField with the 12-direction ring rotated by a per-pixel hash: the polygonal iso-lines of the\n// fixed ring (the \"blocky banding\" and 12-ray stars seen in reviews) become fine, frame-stable noise.\n// Same cost as logoField; use it for anything that draws contours / distances, keep logoField for bevel normals.\nvec3 logoFieldJ(vec2 p, float r) {\n  float j = hash12(floor(isf_FragNormCoord * RENDERSIZE)) * 0.5235988;\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988 + j;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\nfloat easeOutExpo(float x) { x = clamp(x, 0.0, 1.0); return x >= 1.0 ? 1.0 : 1.0 - pow(2.0, -10.0 * x); }\nfloat easeInExpo(float x) { x = clamp(x, 0.0, 1.0); return x <= 0.0 ? 0.0 : pow(2.0, 10.0 * x - 10.0); }\nfloat easeInOutCubic(float x) { x = clamp(x, 0.0, 1.0); return x < 0.5 ? 4.0 * x * x * x : 1.0 - pow(-2.0 * x + 2.0, 3.0) * 0.5; }\nfloat easeOutBack(float x) { x = clamp(x, 0.0, 1.0); float y = x - 1.0; return 1.0 + 2.70158 * y * y * y + 1.70158 * y * y; }\n\n// Stinger timeline. Self-runs on TIME when uLoop is on, otherwise follows the host-driven uProgress.\n// Returns raw progress: outside 0..1 the stinger is idle (nothing drawn), so it never leaves remnants.\n// Loop period = duration + max(0.6*duration, 0.5 s): a fixed gap caps the cue rate at ~2/s (photosensitivity).\nfloat stingerClock() {\n  float dur = max(uDuration, 0.05);\n  if (bool(uLoop)) { float cyc = dur + max(0.6 * dur, 0.5); return mod(TIME, cyc) / dur; }\n  return uProgress;\n}\n// Impact envelope in seconds after the hit (t and hit are cue progress 0..1, dur in seconds).\n// hitFlash: 2-3 frame pop. hitSpring: damped spring (overshoot + 2 rebounds, ~0.35 s). hitEnv: their max, for legacy callers.\nfloat hitFlash(float t, float hit, float dur) { float x = (t - hit) * max(dur, 0.05); return t < hit ? 0.0 : exp(-x * 60.0); }\nfloat hitSpring(float t, float hit, float dur) { float x = (t - hit) * max(dur, 0.05); return t < hit ? 0.0 : exp(-x * 10.0) * cos(x * 38.0); }\nfloat hitEnv(float t, float hit, float dur) { float x = (t - hit) * max(dur, 0.05); return t < hit ? 0.0 : exp(-x * 7.0); }\n// Camera shake: continuous (interpolated between 60 Hz random targets, so shutter taps never straddle a jump),\n// directional, damped with the spring. amt 0..1 -> up to ~0.06 height units at the hit.\nvec2 shakeOffset(float t, float hit, float dur, float amt) {\n  float s = max(t - hit, 0.0) * max(dur, 0.05) * 60.0;\n  float k = floor(s); float f = s - k; f = f * f * (3.0 - 2.0 * f);\n  vec2 r0 = hash22(vec2(k, 3.1)) - 0.5; vec2 r1 = hash22(vec2(k + 1.0, 3.1)) - 0.5;\n  vec2 r = mix(r0, r1, f);\n  float env = t < hit ? 0.0 : exp(-(t - hit) * max(dur, 0.05) * 9.0);\n  return r * vec2(1.0, 0.6) * amt * 0.12 * env;\n}\n\n// ---- effect ----\n// Iris: a brand-gradient window opens from emblem size (0.42 s build), covers the frame just before the\n// hit, then collapses onto the exact logo in the last ~25% of the in-phase so the logo locks on the hit.\n// Hold, then an eased iris closes over the logo to a streaked glint. Flood alpha is capped (brand-safe).\nvec4 stingerFrame(vec2 p, float t) {\n  float hit = uHitPoint;\n  float a = clamp(t / hit, 0.0, 1.0);\n  float b = clamp((t - hit) / (1.0 - hit), 0.0, 1.0);\n  float r = length(p);\n  float maxR = 1.15;\n  float kick = kickN();\n  float open = easeInOutCubic(holdRamp(a, 0.0, 0.6));\n  float collapse = easeInOutCubic(holdRamp(a, 0.74, 1.0));\n  float R = mix(0.22, maxR, open) * (1.0 - collapse);\n  float Rout = mix(maxR, 0.0, easeInOutCubic(holdRamp(b, 0.45, 0.97)));\n  float pump = 1.0 + 0.025 * kick * step(hit, t);\n  float la = logoP(p / pump);\n  vec4 lg = logoRGBA(p / pump);\n  float circIn = (1.0 - smoothstep(R - 0.003, R, r)) * smoothstep(0.0, 0.2, R);\n  float circOut = 1.0 - smoothstep(Rout - 0.003, Rout, r);\n  float field = max(circIn, la * step(0.02, open)) * circOut;\n  float gph = dot(p, vec2(0.87, 0.5)) + 0.08 * sin(r * 5.0 - t * uDuration * 6.0) + 0.35 * kick;\n  vec3 grad = mix(uTint.rgb, uTint2.rgb, smoothstep(-0.6, 0.6, gph));\n  vec3 inside = mix(grad * 0.9, lg.rgb, smoothstep(0.9, 1.0, a) * la);\n  float flood = min(field, mix(0.85, 1.0, la));\n  vec3 col = inside * flood;\n  // lens rings riding the iris edges (wide enough to survive the shutter)\n  float ringIn = exp(-abs(r - R) * 90.0) * step(0.03, R) * step(a, 0.999) * (1.0 - collapse);\n  float ringOut = exp(-abs(r - Rout) * 90.0) * step(0.001, b) * step(0.02, Rout);\n  col += uTint2.rgb * ringIn * 1.2 + uTint.rgb * ringOut * 1.2;\n  // hit: edge flash + scale spring on the logo\n  float spring = hitSpring(t, hit, uDuration);\n  vec3 Fe = logoFieldJ(p, 0.02 * (1.0 + 0.6 * kick));\n  float rim = edgeGlow(fieldSD(Fe, 0.02), 120.0, 0.02);\n  float fl = hitFlash(t, hit, uDuration) + 0.5 * hitEnv(t, hit, uDuration);\n  col += mix(uTint2.rgb, vec3(1.0), 0.5) * rim * fl * 1.4;\n  col += lg.rgb * lg.a * abs(spring) * 0.25 * circOut;\n  // exit glint: soft core + horizontal streak\n  float gw = smoothstep(0.86, 0.95, b) * (1.0 - smoothstep(0.97, 1.0, b));\n  float glint = (exp(-r * 14.0) + 0.6 * exp(-abs(p.y) * 120.0) * exp(-abs(p.x) * 5.0)) * gw;\n  col += vec3(1.0) * glint * 2.0;\n  return vec4(col, max(max(flood, max(ringIn, ringOut)), max(min(glint * 2.0, 1.0), rim * fl)));\n}\n\n#ifndef STING_TAPS\n#define STING_TAPS 8\n#endif\nvoid main() {\n  vec2 p = uv2p(isf_FragNormCoord);\n  float t0 = stingerClock();\n  float dt = (TIMEDELTA > 0.0005 && TIMEDELTA < 0.1) ? TIMEDELTA : (1.0 / 60.0);\n  float expo = (uShutter / 360.0) * dt / max(uDuration, 0.05);\n  float jit = hash12(floor(isf_FragNormCoord * RENDERSIZE) + 0.37);\n  vec4 acc = vec4(0.0);\n  float n = 0.0;\n  for (int i = 0; i < STING_TAPS; i++) {\n    float t = t0 - expo * (float(i) + jit) / float(STING_TAPS);\n    if (t <= 0.0 || t >= 1.0) continue;\n    acc += stingerFrame(p + shakeOffset(t, uHitPoint, uDuration, uShake), t);\n    n += 1.0;\n  }\n  if (n > 0.0) acc /= float(STING_TAPS);\n  gl_FragColor = vjOutPM(acc);\n}\n"},{"id":"sting-portal","name":"Portal Vortex Tunnel","category":"sting","blurb":"A twisting tunnel opens, the logo bursts out on the hit, then everything is sucked back in.","params":[{"name":"uProgress","label":"Cue Progress","type":"float","default":0.4,"min":0,"max":1,"driver":"cue","hint":"Driven by TAKE in the app; map to a clip timeline / BPM in the host."},{"name":"uLoop","label":"Self-Run Loop","type":"bool","default":true,"hint":"On: the stinger runs on TIME in any host. Off: follows Cue Progress."},{"name":"uDuration","label":"Transition Duration","type":"float","default":1.2,"min":0.3,"max":4,"unit":"s","hint":"Cue length. The self-run loop adds a gap of max(0.6\u00c3\u2014duration, 0.5 s) so cues never exceed ~2/s."},{"name":"uShutter","label":"Motion Blur Shutter","type":"float","default":180,"min":0,"max":360,"unit":"\u00c2\u00b0","hint":"Shutter angle: 180\u00c2\u00b0 = half-frame exposure (film look), 360\u00c2\u00b0 = full smear."},{"name":"uShake","label":"Impact Shake","type":"float","default":0.5,"min":0,"max":1,"hint":"Damped camera shake after the hit (0 = locked off)."},{"name":"uHitPoint","label":"Sound-Sync Hit Point","type":"float","default":0.35,"min":0.05,"max":0.95,"hint":"Where the impact lands, as a fraction of the duration (0.35 \u00c3\u2014 1.2 s = 0.42 s). Put it on the downbeat."},{"name":"uTint","label":"Brand Primary","type":"color","default":[0,0.9,1,1],"hint":"Main light / bar colour."},{"name":"uTint2","label":"Brand Accent","type":"color","default":[1,0.18,0.55,1],"hint":"Secondary colour: exit bar, rings, sparks, impact burst."},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Wormhole","values":{}},{"name":"Inferno Gate","values":{"uTint":[1,0.35,0.05,1],"uTint2":[1,0.85,0.2,1]}},{"name":"Slow Rift","values":{"uDuration":3,"uShutter":90}}],"source":"/*{\n  \"DESCRIPTION\": \"Portal Vortex Tunnel \u00e2\u20ac\u201d A twisting tunnel opens, the logo bursts out on the hit, then everything is sucked back in.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Stingers & Transitions\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uProgress\",\"TYPE\":\"float\",\"LABEL\":\"Cue Progress\",\"DEFAULT\":0.4,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uLoop\",\"TYPE\":\"bool\",\"LABEL\":\"Self-Run Loop\",\"DEFAULT\":true},\n    {\"NAME\":\"uDuration\",\"TYPE\":\"float\",\"LABEL\":\"Transition Duration\",\"DEFAULT\":1.2,\"MIN\":0.3,\"MAX\":4},\n    {\"NAME\":\"uShutter\",\"TYPE\":\"float\",\"LABEL\":\"Motion Blur Shutter\",\"DEFAULT\":180,\"MIN\":0,\"MAX\":360},\n    {\"NAME\":\"uShake\",\"TYPE\":\"float\",\"LABEL\":\"Impact Shake\",\"DEFAULT\":0.5,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHitPoint\",\"TYPE\":\"float\",\"LABEL\":\"Sound-Sync Hit Point\",\"DEFAULT\":0.35,\"MIN\":0.05,\"MAX\":0.95},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Brand Primary\",\"DEFAULT\":[0,0.9,1,1]},\n    {\"NAME\":\"uTint2\",\"TYPE\":\"color\",\"LABEL\":\"Brand Accent\",\"DEFAULT\":[1,0.18,0.55,1]},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Portal Vortex Tunnel \u00c2\u00b7 Stingers & Transitions\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nmat2 rot2(float a) { float c = cos(a); float s = sin(a); return mat2(c, -s, s, c); }\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// 25-tap disk coverage of the logo around p (radius r, height-normalized units).\n// x = coverage 0..1 (0.5 on the outline), yz = vector pointing into the logo.\nvec3 logoField(vec2 p, float r) {\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n// Approximate signed distance (positive outside) from a logoField sample of radius r.\nfloat fieldSD(vec3 f, float r) { return (0.5 - f.x) * 2.0 * r; }\n// Edge glow that falls to exactly zero at the field radius r (no full-frame haze floor).\nfloat edgeGlow(float sd, float k, float r) { float f = exp(-r * k); return max(exp(-abs(sd) * k) - f, 0.0) / (1.0 - f); }\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\nfloat easeOutExpo(float x) { x = clamp(x, 0.0, 1.0); return x >= 1.0 ? 1.0 : 1.0 - pow(2.0, -10.0 * x); }\nfloat easeInExpo(float x) { x = clamp(x, 0.0, 1.0); return x <= 0.0 ? 0.0 : pow(2.0, 10.0 * x - 10.0); }\nfloat easeInOutCubic(float x) { x = clamp(x, 0.0, 1.0); return x < 0.5 ? 4.0 * x * x * x : 1.0 - pow(-2.0 * x + 2.0, 3.0) * 0.5; }\nfloat easeOutBack(float x) { x = clamp(x, 0.0, 1.0); float y = x - 1.0; return 1.0 + 2.70158 * y * y * y + 1.70158 * y * y; }\n\n// Stinger timeline. Self-runs on TIME when uLoop is on, otherwise follows the host-driven uProgress.\n// Returns raw progress: outside 0..1 the stinger is idle (nothing drawn), so it never leaves remnants.\n// Loop period = duration + max(0.6*duration, 0.5 s): a fixed gap caps the cue rate at ~2/s (photosensitivity).\nfloat stingerClock() {\n  float dur = max(uDuration, 0.05);\n  if (bool(uLoop)) { float cyc = dur + max(0.6 * dur, 0.5); return mod(TIME, cyc) / dur; }\n  return uProgress;\n}\n// Impact envelope in seconds after the hit (t and hit are cue progress 0..1, dur in seconds).\n// hitFlash: 2-3 frame pop. hitSpring: damped spring (overshoot + 2 rebounds, ~0.35 s). hitEnv: their max, for legacy callers.\nfloat hitFlash(float t, float hit, float dur) { float x = (t - hit) * max(dur, 0.05); return t < hit ? 0.0 : exp(-x * 60.0); }\nfloat hitSpring(float t, float hit, float dur) { float x = (t - hit) * max(dur, 0.05); return t < hit ? 0.0 : exp(-x * 10.0) * cos(x * 38.0); }\nfloat hitEnv(float t, float hit, float dur) { float x = (t - hit) * max(dur, 0.05); return t < hit ? 0.0 : exp(-x * 7.0); }\n// Camera shake: continuous (interpolated between 60 Hz random targets, so shutter taps never straddle a jump),\n// directional, damped with the spring. amt 0..1 -> up to ~0.06 height units at the hit.\nvec2 shakeOffset(float t, float hit, float dur, float amt) {\n  float s = max(t - hit, 0.0) * max(dur, 0.05) * 60.0;\n  float k = floor(s); float f = s - k; f = f * f * (3.0 - 2.0 * f);\n  vec2 r0 = hash22(vec2(k, 3.1)) - 0.5; vec2 r1 = hash22(vec2(k + 1.0, 3.1)) - 0.5;\n  vec2 r = mix(r0, r1, f);\n  float env = t < hit ? 0.0 : exp(-(t - hit) * max(dur, 0.05) * 9.0);\n  return r * vec2(1.0, 0.6) * amt * 0.12 * env;\n}\n\n// ---- effect ----\n// Portal tunnel: aperture opens, the spiral pulls in before the hit (z-speed x3, aperture -6%), the logo\n// erupts with a capped spin and a shockwave ring, holds at full size until ~25% of the out-phase, then\n// everything is sucked back. The white core fades behind the logo. Kick pumps the aperture, not the logo.\nvec4 stingerFrame(vec2 p, float t) {\n  float hit = uHitPoint;\n  float a = clamp(t / hit, 0.0, 1.0);\n  float b = clamp((t - hit) / (1.0 - hit), 0.0, 1.0);\n  float r = length(p);\n  float ang = atan(p.y, p.x);\n  float kick = kickN();\n  float open = easeOutExpo(a) * (1.0 - easeInExpo(holdRamp(b, 0.25, 1.0)));\n  float pull = smoothstep(0.78, 1.0, a) * (1.0 - step(hit, t));\n  float aperture = open * 1.1 * (1.0 - 0.06 * pull) * (1.0 + 0.08 * kick);\n  float zt = uDuration * (1.0 * t + 0.8 * hit * easeInExpo(a));\n  float z = 0.25 / max(r, 0.02) + zt + 0.7 * kick;\n  float edgeSoft = 1.0 - smoothstep(aperture - 0.08, aperture, r);\n  float stripes = 0.5 + 0.5 * sin(z * 10.0 + ang * 2.0);\n  vec3 tun = mix(uTint.rgb, uTint2.rgb, 0.5 + 0.5 * sin(ang * 3.0 + z * 0.8)) * (0.82 + 0.18 * stripes * stripes);\n  float ls = easeOutBack(clamp((t - hit) / (0.25 * (1.0 - hit)), 0.0, 1.0)) * (1.0 - easeInExpo(holdRamp(b, 0.25, 1.0)));\n  tun += mix(uTint2.rgb, vec3(1.0), 0.4) * exp(-r * 10.0) * 1.5 * (1.0 - 0.85 * ls);\n  tun *= edgeSoft;\n  float rim = exp(-abs(r - aperture) * 120.0) * step(0.01, open);\n  float spin = (1.0 - easeOutExpo(ls)) * 0.9;\n  vec2 q = rot2(spin) * p / max(ls, 0.001);\n  vec4 lg = logoRGBA(q);\n  float lm = lg.a * step(0.001, ls);\n  float shade = smoothstep(0.0, 0.45, logoField(q, 0.1).x) * step(0.001, ls);\n  vec3 col = tun * (1.0 - lm) * (1.0 - 0.8 * shade) + lg.rgb * lm;\n  col += uTint2.rgb * rim * (2.0 + 1.5 * kick);\n  float wave = (t - hit) * uDuration * 2.2;\n  float ring = exp(-abs(r - wave) * 70.0) * step(hit, t) * exp(-wave * 2.5);\n  col += mix(uTint2.rgb, vec3(1.0), 0.5) * ring * 1.5 * (1.0 - lm);\n  float bloom = min(hitFlash(t, hit, uDuration) * 1.2 + hitEnv(t, hit, uDuration) * 0.4, 1.0);\n  col += vec3(1.0) * bloom * exp(-r * 3.0) * (1.0 - lm) * 0.9;\n  return vec4(col, max(max(edgeSoft * open, lm), max(rim, ring)));\n}\n\n#ifndef STING_TAPS\n#define STING_TAPS 8\n#endif\nvoid main() {\n  vec2 p = uv2p(isf_FragNormCoord);\n  float t0 = stingerClock();\n  float dt = (TIMEDELTA > 0.0005 && TIMEDELTA < 0.1) ? TIMEDELTA : (1.0 / 60.0);\n  float expo = (uShutter / 360.0) * dt / max(uDuration, 0.05);\n  float jit = hash12(floor(isf_FragNormCoord * RENDERSIZE) + 0.37);\n  vec4 acc = vec4(0.0);\n  float n = 0.0;\n  for (int i = 0; i < STING_TAPS; i++) {\n    float t = t0 - expo * (float(i) + jit) / float(STING_TAPS);\n    if (t <= 0.0 || t >= 1.0) continue;\n    acc += stingerFrame(p + shakeOffset(t, uHitPoint, uDuration, uShake), t);\n    n += 1.0;\n  }\n  if (n > 0.0) acc /= float(STING_TAPS);\n  gl_FragColor = vjOutPM(acc);\n}\n"},{"id":"sting-laser","name":"Neon Laser Cutter","category":"sting","blurb":"A white-hot laser head traces the outline in neon, throwing sparks, then the fill ignites.","params":[{"name":"uProgress","label":"Cue Progress","type":"float","default":0.4,"min":0,"max":1,"driver":"cue","hint":"Driven by TAKE in the app; map to a clip timeline / BPM in the host."},{"name":"uLoop","label":"Self-Run Loop","type":"bool","default":true,"hint":"On: the stinger runs on TIME in any host. Off: follows Cue Progress."},{"name":"uDuration","label":"Transition Duration","type":"float","default":1.2,"min":0.3,"max":4,"unit":"s","hint":"Cue length. The self-run loop adds a gap of max(0.6\u00c3\u2014duration, 0.5 s) so cues never exceed ~2/s."},{"name":"uShutter","label":"Motion Blur Shutter","type":"float","default":180,"min":0,"max":360,"unit":"\u00c2\u00b0","hint":"Shutter angle: 180\u00c2\u00b0 = half-frame exposure (film look), 360\u00c2\u00b0 = full smear."},{"name":"uShake","label":"Impact Shake","type":"float","default":0.5,"min":0,"max":1,"hint":"Damped camera shake after the hit (0 = locked off)."},{"name":"uHitPoint","label":"Sound-Sync Hit Point","type":"float","default":0.35,"min":0.05,"max":0.95,"hint":"Where the impact lands, as a fraction of the duration (0.35 \u00c3\u2014 1.2 s = 0.42 s). Put it on the downbeat."},{"name":"uTint","label":"Brand Primary","type":"color","default":[0,0.9,1,1],"hint":"Main light / bar colour."},{"name":"uTint2","label":"Brand Accent","type":"color","default":[1,0.18,0.55,1],"hint":"Secondary colour: exit bar, rings, sparks, impact burst."},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Cyan Cutter","values":{}},{"name":"Hot Pink","values":{"uTint":[1,0.2,0.7,1],"uTint2":[1,0.85,0.3,1]}},{"name":"Slow Engrave","values":{"uDuration":3.2,"uHitPoint":0.6}}],"source":"/*{\n  \"DESCRIPTION\": \"Neon Laser Cutter \u00e2\u20ac\u201d A white-hot laser head traces the outline in neon, throwing sparks, then the fill ignites.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Stingers & Transitions\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uProgress\",\"TYPE\":\"float\",\"LABEL\":\"Cue Progress\",\"DEFAULT\":0.4,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uLoop\",\"TYPE\":\"bool\",\"LABEL\":\"Self-Run Loop\",\"DEFAULT\":true},\n    {\"NAME\":\"uDuration\",\"TYPE\":\"float\",\"LABEL\":\"Transition Duration\",\"DEFAULT\":1.2,\"MIN\":0.3,\"MAX\":4},\n    {\"NAME\":\"uShutter\",\"TYPE\":\"float\",\"LABEL\":\"Motion Blur Shutter\",\"DEFAULT\":180,\"MIN\":0,\"MAX\":360},\n    {\"NAME\":\"uShake\",\"TYPE\":\"float\",\"LABEL\":\"Impact Shake\",\"DEFAULT\":0.5,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHitPoint\",\"TYPE\":\"float\",\"LABEL\":\"Sound-Sync Hit Point\",\"DEFAULT\":0.35,\"MIN\":0.05,\"MAX\":0.95},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Brand Primary\",\"DEFAULT\":[0,0.9,1,1]},\n    {\"NAME\":\"uTint2\",\"TYPE\":\"color\",\"LABEL\":\"Brand Accent\",\"DEFAULT\":[1,0.18,0.55,1]},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Neon Laser Cutter \u00c2\u00b7 Stingers & Transitions\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// 25-tap disk coverage of the logo around p (radius r, height-normalized units).\n// x = coverage 0..1 (0.5 on the outline), yz = vector pointing into the logo.\nvec3 logoField(vec2 p, float r) {\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n// Approximate signed distance (positive outside) from a logoField sample of radius r.\nfloat fieldSD(vec3 f, float r) { return (0.5 - f.x) * 2.0 * r; }\n// Edge glow that falls to exactly zero at the field radius r (no full-frame haze floor).\nfloat edgeGlow(float sd, float k, float r) { float f = exp(-r * k); return max(exp(-abs(sd) * k) - f, 0.0) / (1.0 - f); }\n\n// logoField with the 12-direction ring rotated by a per-pixel hash: the polygonal iso-lines of the\n// fixed ring (the \"blocky banding\" and 12-ray stars seen in reviews) become fine, frame-stable noise.\n// Same cost as logoField; use it for anything that draws contours / distances, keep logoField for bevel normals.\nvec3 logoFieldJ(vec2 p, float r) {\n  float j = hash12(floor(isf_FragNormCoord * RENDERSIZE)) * 0.5235988;\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988 + j;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\n// Stinger timeline. Self-runs on TIME when uLoop is on, otherwise follows the host-driven uProgress.\n// Returns raw progress: outside 0..1 the stinger is idle (nothing drawn), so it never leaves remnants.\n// Loop period = duration + max(0.6*duration, 0.5 s): a fixed gap caps the cue rate at ~2/s (photosensitivity).\nfloat stingerClock() {\n  float dur = max(uDuration, 0.05);\n  if (bool(uLoop)) { float cyc = dur + max(0.6 * dur, 0.5); return mod(TIME, cyc) / dur; }\n  return uProgress;\n}\n// Impact envelope in seconds after the hit (t and hit are cue progress 0..1, dur in seconds).\n// hitFlash: 2-3 frame pop. hitSpring: damped spring (overshoot + 2 rebounds, ~0.35 s). hitEnv: their max, for legacy callers.\nfloat hitFlash(float t, float hit, float dur) { float x = (t - hit) * max(dur, 0.05); return t < hit ? 0.0 : exp(-x * 60.0); }\nfloat hitSpring(float t, float hit, float dur) { float x = (t - hit) * max(dur, 0.05); return t < hit ? 0.0 : exp(-x * 10.0) * cos(x * 38.0); }\nfloat hitEnv(float t, float hit, float dur) { float x = (t - hit) * max(dur, 0.05); return t < hit ? 0.0 : exp(-x * 7.0); }\n// Camera shake: continuous (interpolated between 60 Hz random targets, so shutter taps never straddle a jump),\n// directional, damped with the spring. amt 0..1 -> up to ~0.06 height units at the hit.\nvec2 shakeOffset(float t, float hit, float dur, float amt) {\n  float s = max(t - hit, 0.0) * max(dur, 0.05) * 60.0;\n  float k = floor(s); float f = s - k; f = f * f * (3.0 - 2.0 * f);\n  vec2 r0 = hash22(vec2(k, 3.1)) - 0.5; vec2 r1 = hash22(vec2(k + 1.0, 3.1)) - 0.5;\n  vec2 r = mix(r0, r1, f);\n  float env = t < hit ? 0.0 : exp(-(t - hit) * max(dur, 0.05) * 9.0);\n  return r * vec2(1.0, 0.6) * amt * 0.12 * env;\n}\n\n// ---- effect ----\n#define STING_TAPS 4\n// Laser cutter: the head sweeps left to right (x-sweep, linear pacing), hopping between the top and bottom\n// edge of the column it is cutting, leaving a two-tone neon outline (outer = primary, core = accent) and\n// sparks that stay where they were thrown. Ignition = 2-frame white overdrive on the hit; exit = at most\n// 3 soft dips (8 Hz, 40%) then an afterglow fade. Kick pushes the head faster and fattens the tube.\nvec4 stingerFrame(vec2 p, float t) {\n  float hit = uHitPoint;\n  float a = clamp(t / hit, 0.0, 1.0);\n  float b = clamp((t - hit) / (1.0 - hit), 0.0, 1.0);\n  float kick = kickN();\n  float px = 1.0 / RENDERSIZE.y;\n  float xmin = -0.68; float xmax = 0.68;\n  float sx = mix(xmin, xmax, a);\n  float drawn = smoothstep(sx + 0.012, sx, p.x);\n  vec3 F = logoFieldJ(p, 0.018);\n  float sd = fieldSD(F, 0.018);\n  float tube = pxMin(0.004 * (1.0 + 0.5 * kick));\n  float edge = exp(-abs(sd) / tube);\n  float core = exp(-abs(sd) / (tube * 0.55));\n  float halo = edgeGlow(sd, 110.0, 0.018);\n  float dips = step(0.6, hash11(floor(t * uDuration * 8.0) + 7.0)) * smoothstep(0.5, 0.6, b) * (1.0 - smoothstep(0.85, 1.0, b));\n  float on = (1.0 - 0.4 * dips) * (1.0 - smoothstep(0.72, 1.0, b));\n  float buzz = 0.9 + 0.1 * sin(t * uDuration * 120.0) + 0.4 * uHigh * uAudioReact;\n  float neon = edge * drawn * on;\n  vec3 col = (mix(uTint.rgb, uTint2.rgb, 0.25) * neon * 1.2 + mix(uTint2.rgb, vec3(1.0), 0.3) * core * drawn * on * 1.4 + mix(uTint.rgb, uTint2.rgb, 0.5) * halo * drawn * on * 0.7) * buzz;\n  float alpha = max(neon, halo * drawn * on * 0.6);\n  // head: topmost / bottommost logo row in the cutting column (12-tap march), alternating\n  float cutting = step(0.001, a) * step(a, 0.999);\n  float yTop = -9.0; float yBot = 9.0; float found = 0.0;\n  for (int k = 0; k < 12; k++) {\n    float y = mix(-0.2, 0.2, float(k) / 11.0);\n    if (logoP(vec2(sx, y)) > 0.5) { yTop = max(yTop, y); yBot = min(yBot, y); found = 1.0; }\n  }\n  float side = step(0.0, sin(a * 40.0));\n  vec2 hp = vec2(sx, mix(yBot, yTop, side));\n  float headOn = cutting * found;\n  vec2 emit = vec2(hp.x * 0.3, 0.75);\n  vec2 pa = p - emit; vec2 ba = hp - emit;\n  float hb = clamp(dot(pa, ba) / max(dot(ba, ba), 0.000001), 0.0, 1.0);\n  float bd = length(pa - ba * hb);\n  float beam = (exp(-bd / pxMin(0.004)) + 0.35 * exp(-bd / 0.025)) * headOn;\n  col += mix(uTint.rgb, vec3(1.0), 0.6) * beam * 1.2;\n  float hd = length(p - hp);\n  float hot = exp(-hd / pxMin(0.012)) * headOn;\n  col += vec3(1.0, 0.95, 0.8) * hot * 3.0 + uTint.rgb * exp(-hd * 25.0) * headOn * 0.7;\n  alpha = max(alpha, max(hot, beam));\n  // sparks: born at the head position of their birth time, left behind as the head moves on\n  float sw = pxMin(0.0035);\n  for (int i = 0; i < 10; i++) {\n    vec3 h = hash32(vec2(float(i), 11.0));\n    float rate = 2.0 + h.z * 2.0;\n    float life = fract(t * uDuration * rate + h.x);\n    float age = life / (uDuration * rate);\n    float ab = clamp(a - age / hit, 0.0, 1.0);\n    vec2 born = vec2(mix(xmin, xmax, ab), hp.y);\n    vec2 vel = vec2(cos(h.y * 6.2831853), sin(h.y * 6.2831853) * 0.6 + 0.5) * (0.2 + 0.25 * h.z);\n    vec2 sp = born + vel * life * 0.6 + vec2(0.0, -0.55) * life * life * 0.6;\n    vec2 tail = sp - (vel + vec2(0.0, -0.66) * life) * (0.03 + 0.1 * uShutter / 360.0);\n    vec2 qa = p - tail; vec2 qb = sp - tail;\n    float hs = clamp(dot(qa, qb) / max(dot(qb, qb), 0.000001), 0.0, 1.0);\n    float sdist = exp(-length(qa - qb * hs) / sw) * (1.0 - life) * headOn * step(0.02, ab);\n    col += mix(uTint2.rgb, vec3(1.0, 0.9, 0.6), 0.5 * (1.0 - life)) * sdist * 2.2;\n    alpha = max(alpha, sdist);\n  }\n  // fill ignites on the hit: 2-frame white overdrive, then a tinted hold that never desaturates\n  vec4 lg = logoRGBA(p);\n  float fill = smoothstep(hit, hit + 0.04, t) * on;\n  float ign = hitFlash(t, hit, uDuration) * 2.0 + hitEnv(t, hit, uDuration) * 0.6;\n  vec3 fillCol = mix(lg.rgb, uTint.rgb, 0.6 * b);\n  col += (fillCol + vec3(1.0) * ign) * lg.a * fill;\n  alpha = max(alpha, lg.a * fill);\n  return vec4(col, alpha);\n}\n\n#ifndef STING_TAPS\n#define STING_TAPS 8\n#endif\nvoid main() {\n  vec2 p = uv2p(isf_FragNormCoord);\n  float t0 = stingerClock();\n  float dt = (TIMEDELTA > 0.0005 && TIMEDELTA < 0.1) ? TIMEDELTA : (1.0 / 60.0);\n  float expo = (uShutter / 360.0) * dt / max(uDuration, 0.05);\n  float jit = hash12(floor(isf_FragNormCoord * RENDERSIZE) + 0.37);\n  vec4 acc = vec4(0.0);\n  float n = 0.0;\n  for (int i = 0; i < STING_TAPS; i++) {\n    float t = t0 - expo * (float(i) + jit) / float(STING_TAPS);\n    if (t <= 0.0 || t >= 1.0) continue;\n    acc += stingerFrame(p + shakeOffset(t, uHitPoint, uDuration, uShake), t);\n    n += 1.0;\n  }\n  if (n > 0.0) acc /= float(STING_TAPS);\n  gl_FragColor = vjOutPM(acc);\n}\n"},{"id":"sting-slam","name":"Typographic Kinetic Slam","category":"sting","blurb":"The logo slams in from huge scale, squashes on impact, throws echo outlines and kinetic bars.","params":[{"name":"uProgress","label":"Cue Progress","type":"float","default":0.4,"min":0,"max":1,"driver":"cue","hint":"Driven by TAKE in the app; map to a clip timeline / BPM in the host."},{"name":"uLoop","label":"Self-Run Loop","type":"bool","default":true,"hint":"On: the stinger runs on TIME in any host. Off: follows Cue Progress."},{"name":"uDuration","label":"Transition Duration","type":"float","default":1.2,"min":0.3,"max":4,"unit":"s","hint":"Cue length. The self-run loop adds a gap of max(0.6\u00c3\u2014duration, 0.5 s) so cues never exceed ~2/s."},{"name":"uShutter","label":"Motion Blur Shutter","type":"float","default":180,"min":0,"max":360,"unit":"\u00c2\u00b0","hint":"Shutter angle: 180\u00c2\u00b0 = half-frame exposure (film look), 360\u00c2\u00b0 = full smear."},{"name":"uShake","label":"Impact Shake","type":"float","default":0.5,"min":0,"max":1,"hint":"Damped camera shake after the hit (0 = locked off)."},{"name":"uHitPoint","label":"Sound-Sync Hit Point","type":"float","default":0.35,"min":0.05,"max":0.95,"hint":"Where the impact lands, as a fraction of the duration (0.35 \u00c3\u2014 1.2 s = 0.42 s). Put it on the downbeat."},{"name":"uTint","label":"Brand Primary","type":"color","default":[0,0.9,1,1],"hint":"Main light / bar colour."},{"name":"uTint2","label":"Brand Accent","type":"color","default":[1,0.18,0.55,1],"hint":"Secondary colour: exit bar, rings, sparks, impact burst."},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Heavy Slam","values":{}},{"name":"Punch Cut","values":{"uDuration":0.8,"uShake":0.9,"uHitPoint":0.3}},{"name":"Mono Slam","values":{"uTint":[1,1,1,1],"uTint2":[0.55,0.55,0.6,1]}}],"source":"/*{\n  \"DESCRIPTION\": \"Typographic Kinetic Slam \u00e2\u20ac\u201d The logo slams in from huge scale, squashes on impact, throws echo outlines and kinetic bars.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Stingers & Transitions\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uProgress\",\"TYPE\":\"float\",\"LABEL\":\"Cue Progress\",\"DEFAULT\":0.4,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uLoop\",\"TYPE\":\"bool\",\"LABEL\":\"Self-Run Loop\",\"DEFAULT\":true},\n    {\"NAME\":\"uDuration\",\"TYPE\":\"float\",\"LABEL\":\"Transition Duration\",\"DEFAULT\":1.2,\"MIN\":0.3,\"MAX\":4},\n    {\"NAME\":\"uShutter\",\"TYPE\":\"float\",\"LABEL\":\"Motion Blur Shutter\",\"DEFAULT\":180,\"MIN\":0,\"MAX\":360},\n    {\"NAME\":\"uShake\",\"TYPE\":\"float\",\"LABEL\":\"Impact Shake\",\"DEFAULT\":0.5,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHitPoint\",\"TYPE\":\"float\",\"LABEL\":\"Sound-Sync Hit Point\",\"DEFAULT\":0.35,\"MIN\":0.05,\"MAX\":0.95},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Brand Primary\",\"DEFAULT\":[0,0.9,1,1]},\n    {\"NAME\":\"uTint2\",\"TYPE\":\"color\",\"LABEL\":\"Brand Accent\",\"DEFAULT\":[1,0.18,0.55,1]},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Typographic Kinetic Slam \u00c2\u00b7 Stingers & Transitions\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nfloat vnoise(vec2 p) {\n  vec2 i = floor(p); vec2 f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x), mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nmat2 rot2(float a) { float c = cos(a); float s = sin(a); return mat2(c, -s, s, c); }\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\nfloat logoCov5(vec2 p, float r) {\n  return (logoP(p) + logoP(p + vec2(r, 0.0)) + logoP(p - vec2(r, 0.0)) + logoP(p + vec2(0.0, r)) + logoP(p - vec2(0.0, r))) * 0.2;\n}\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\nfloat easeOutExpo(float x) { x = clamp(x, 0.0, 1.0); return x >= 1.0 ? 1.0 : 1.0 - pow(2.0, -10.0 * x); }\nfloat easeInExpo(float x) { x = clamp(x, 0.0, 1.0); return x <= 0.0 ? 0.0 : pow(2.0, 10.0 * x - 10.0); }\nfloat easeInOutCubic(float x) { x = clamp(x, 0.0, 1.0); return x < 0.5 ? 4.0 * x * x * x : 1.0 - pow(-2.0 * x + 2.0, 3.0) * 0.5; }\nfloat easeOutBack(float x) { x = clamp(x, 0.0, 1.0); float y = x - 1.0; return 1.0 + 2.70158 * y * y * y + 1.70158 * y * y; }\n\n// Stinger timeline. Self-runs on TIME when uLoop is on, otherwise follows the host-driven uProgress.\n// Returns raw progress: outside 0..1 the stinger is idle (nothing drawn), so it never leaves remnants.\n// Loop period = duration + max(0.6*duration, 0.5 s): a fixed gap caps the cue rate at ~2/s (photosensitivity).\nfloat stingerClock() {\n  float dur = max(uDuration, 0.05);\n  if (bool(uLoop)) { float cyc = dur + max(0.6 * dur, 0.5); return mod(TIME, cyc) / dur; }\n  return uProgress;\n}\n// Impact envelope in seconds after the hit (t and hit are cue progress 0..1, dur in seconds).\n// hitFlash: 2-3 frame pop. hitSpring: damped spring (overshoot + 2 rebounds, ~0.35 s). hitEnv: their max, for legacy callers.\nfloat hitFlash(float t, float hit, float dur) { float x = (t - hit) * max(dur, 0.05); return t < hit ? 0.0 : exp(-x * 60.0); }\nfloat hitSpring(float t, float hit, float dur) { float x = (t - hit) * max(dur, 0.05); return t < hit ? 0.0 : exp(-x * 10.0) * cos(x * 38.0); }\nfloat hitEnv(float t, float hit, float dur) { float x = (t - hit) * max(dur, 0.05); return t < hit ? 0.0 : exp(-x * 7.0); }\n// Camera shake: continuous (interpolated between 60 Hz random targets, so shutter taps never straddle a jump),\n// directional, damped with the spring. amt 0..1 -> up to ~0.06 height units at the hit.\nvec2 shakeOffset(float t, float hit, float dur, float amt) {\n  float s = max(t - hit, 0.0) * max(dur, 0.05) * 60.0;\n  float k = floor(s); float f = s - k; f = f * f * (3.0 - 2.0 * f);\n  vec2 r0 = hash22(vec2(k, 3.1)) - 0.5; vec2 r1 = hash22(vec2(k + 1.0, 3.1)) - 0.5;\n  vec2 r = mix(r0, r1, f);\n  float env = t < hit ? 0.0 : exp(-(t - hit) * max(dur, 0.05) * 9.0);\n  return r * vec2(1.0, 0.6) * amt * 0.12 * env;\n}\n\n// ---- effect ----\n// Kinetic slam: the logo flies in from 3.2x on a visible exponential ramp (moving from frame 1), lands on\n// the hit with a spring squash (volume-preserving, rebounds), a tinted impact burst behind the mark, 4 px\n// echo outlines, a shock ring and kinetic bars that knock out around the logo. Kick pumps the held logo.\nvec4 stingerFrame(vec2 p, float t) {\n  float hit = uHitPoint;\n  float a = clamp(t / hit, 0.0, 1.0);\n  float b = clamp((t - hit) / (1.0 - hit), 0.0, 1.0);\n  float kick = kickN();\n  float s = exp(mix(log(3.2), 0.0, pow(a, 2.2)));\n  float rotA = mix(-0.3, 0.0, pow(a, 2.2));\n  float spring = hitSpring(t, hit, uDuration);\n  float imp = hitEnv(t, hit, uDuration);\n  float k = 0.1 * spring + 0.03 * kick * step(hit, t) * (1.0 - b);\n  vec2 sq = vec2(1.0 + k, 1.0 / (1.0 + k));\n  float ex = easeInExpo(holdRamp(b, 0.3, 1.0));\n  vec2 off = vec2(0.0, ex * 1.2);\n  vec2 q = rot2(rotA) * (p - off) / (s * sq);\n  vec4 lg = logoRGBA(q);\n  float vis = step(0.0001, t) * step(t, 0.9999) * smoothstep(0.0, 0.2, a);\n  float keyline = smoothstep(0.25, 0.5, 1.0 - abs(logoCov5(q, 0.004) * 2.0 - 1.0)) * (1.0 - smoothstep(0.85, 1.0, a));\n  vec3 flyCol = mix(uTint.rgb * (0.55 + 0.45 * smoothstep(-0.15, 0.15, q.y)), lg.rgb, smoothstep(0.85, 1.0, a));\n  vec3 col = flyCol * lg.a * vis + vec3(1.0) * keyline * lg.a * vis * 0.6;\n  float alpha = lg.a * vis;\n  // radial speed streaks during the fly-in\n  float rr = length(p);\n  float ang = atan(p.y, p.x);\n  float streak = pow(vnoise(vec2(ang * 24.0, rr * 2.0 - a * 14.0)), 5.0) * (1.0 - a) * step(0.001, a) * smoothstep(0.15, 0.5, rr);\n  col += uTint.rgb * streak * 0.8;\n  alpha = max(alpha, streak * 0.8);\n  // impact burst behind the logo\n  float burst = (hitFlash(t, hit, uDuration) + 0.4 * imp) * exp(-rr * 2.0);\n  col += uTint2.rgb * burst * 0.9 * (1.0 - lg.a * vis);\n  alpha = max(alpha, min(burst, 1.0));\n  for (int i = 1; i <= 3; i++) {\n    float fi = float(i);\n    float es = 1.0 + (0.06 + b * 0.5) * fi;\n    float e = smoothstep(0.2, 0.9, 1.0 - abs(logoCov5((p - off) / es, pxMin(0.005)) * 2.0 - 1.0));\n    e *= step(hit, t) * (1.0 - b) * (1.0 - fi * 0.22);\n    col += (mod(fi, 2.0) < 0.5 ? uTint.rgb : uTint2.rgb) * e * 1.1;\n    alpha = max(alpha, e);\n  }\n  float wave = (t - hit) / (1.0 - hit) * 1.4;\n  float ring = exp(-abs(rr - wave) / pxMin(0.012)) * step(hit, t) * (1.0 - b);\n  col += uTint2.rgb * ring;\n  alpha = max(alpha, ring);\n  // kinetic bars: 9 rows, staggered per row, knocked out around the logo\n  float rows = 9.0;\n  float row = floor(p.y * rows);\n  float sgn = mod(row, 2.0) * 2.0 - 1.0;\n  float delay = hash11(row + 3.0) * 0.1;\n  float slide = sgn * (1.0 - easeOutExpo(clamp((t - hit - delay) * 4.0 / (1.0 - hit), 0.0, 1.0))) * 2.0;\n  float slideOut = -sgn * easeInExpo(holdRamp(b, 0.3, 1.0)) * 2.4;\n  float barMask = step(abs(fract(p.y * rows) - 0.5), 0.2) * step(abs(p.x - slide - slideOut), 0.9) * step(hit + delay, t);\n  float knock = 1.0 - smoothstep(0.0, 0.5, logoCov5(p - off, 0.035));\n  barMask *= knock;\n  barMask *= 1.0 - 0.45 * b;\n  col += mix(uTint.rgb, uTint2.rgb, mod(row, 2.0)) * 0.75 * barMask;\n  alpha = max(alpha, barMask * 0.8);\n  return vec4(col, alpha);\n}\n\n#ifndef STING_TAPS\n#define STING_TAPS 8\n#endif\nvoid main() {\n  vec2 p = uv2p(isf_FragNormCoord);\n  float t0 = stingerClock();\n  float dt = (TIMEDELTA > 0.0005 && TIMEDELTA < 0.1) ? TIMEDELTA : (1.0 / 60.0);\n  float expo = (uShutter / 360.0) * dt / max(uDuration, 0.05);\n  float jit = hash12(floor(isf_FragNormCoord * RENDERSIZE) + 0.37);\n  vec4 acc = vec4(0.0);\n  float n = 0.0;\n  for (int i = 0; i < STING_TAPS; i++) {\n    float t = t0 - expo * (float(i) + jit) / float(STING_TAPS);\n    if (t <= 0.0 || t >= 1.0) continue;\n    acc += stingerFrame(p + shakeOffset(t, uHitPoint, uDuration, uShake), t);\n    n += 1.0;\n  }\n  if (n > 0.0) acc /= float(STING_TAPS);\n  gl_FragColor = vjOutPM(acc);\n}\n"},{"id":"flora-ivy","name":"Procedural Ivy & Vine Wrap","category":"flora","blurb":"Twin tube-shaded vines climb the outline from the ground up, budding wind-blown leaves before the logo fills in.","params":[{"name":"uGrowth","label":"Growth Progress","type":"float","default":100,"min":0,"max":100,"unit":"%","auto":{"on":true,"shape":"tri","rate":0.08,"lo":0,"hi":1},"hint":"Holds the finished logo above ~78%."},{"name":"uGrowthCurve","label":"Growth Curve","type":"long","default":1,"values":[0,1,2,3],"labels":["Linear","Ease Out","Organic S","Elastic"]},{"name":"uVineThickness","label":"Vine Thickness","type":"float","default":1,"min":0.2,"max":3,"hint":"Vine and leaf scale (sub-linear so max never swallows the letters)."},{"name":"uWindFreq","label":"Wind Flutter","type":"float","default":0.6,"min":0,"max":4,"unit":"Hz","hint":"Leaf flutter and vine sway rate."},{"name":"uSporeCount","label":"Spore Motes","type":"float","default":120,"min":0,"max":400},{"name":"uPalette","label":"Color Palette","type":"long","default":0,"values":[0,1,2],"labels":["Chlorophyll Green","Autumnal Gold","Bioluminescent Neon"]},{"name":"uTint","label":"Brand Tint","type":"color","default":[1,1,1,1],"hint":"Multiplies the palette so a sponsor can match its own green / gold."},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Climbing Ivy","values":{}},{"name":"Autumn Trellis","values":{"uPalette":1,"uVineThickness":1.6,"uSporeCount":60}},{"name":"Neon Jungle","values":{"uPalette":2,"uSporeCount":260,"uWindFreq":1.4}}],"source":"/*{\n  \"DESCRIPTION\": \"Procedural Ivy & Vine Wrap \u00e2\u20ac\u201d Twin tube-shaded vines climb the outline from the ground up, budding wind-blown leaves before the logo fills in.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Botanical & Flora\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uGrowth\",\"TYPE\":\"float\",\"LABEL\":\"Growth Progress\",\"DEFAULT\":100,\"MIN\":0,\"MAX\":100},\n    {\"NAME\":\"uGrowthCurve\",\"TYPE\":\"long\",\"LABEL\":\"Growth Curve\",\"DEFAULT\":1,\"VALUES\":[0,1,2,3],\"LABELS\":[\"Linear\",\"Ease Out\",\"Organic S\",\"Elastic\"]},\n    {\"NAME\":\"uVineThickness\",\"TYPE\":\"float\",\"LABEL\":\"Vine Thickness\",\"DEFAULT\":1,\"MIN\":0.2,\"MAX\":3},\n    {\"NAME\":\"uWindFreq\",\"TYPE\":\"float\",\"LABEL\":\"Wind Flutter\",\"DEFAULT\":0.6,\"MIN\":0,\"MAX\":4},\n    {\"NAME\":\"uSporeCount\",\"TYPE\":\"float\",\"LABEL\":\"Spore Motes\",\"DEFAULT\":120,\"MIN\":0,\"MAX\":400},\n    {\"NAME\":\"uPalette\",\"TYPE\":\"long\",\"LABEL\":\"Color Palette\",\"DEFAULT\":0,\"VALUES\":[0,1,2],\"LABELS\":[\"Chlorophyll Green\",\"Autumnal Gold\",\"Bioluminescent Neon\"]},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Brand Tint\",\"DEFAULT\":[1,1,1,1]},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Procedural Ivy & Vine Wrap \u00c2\u00b7 Botanical & Flora\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nfloat vnoise(vec2 p) {\n  vec2 i = floor(p); vec2 f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x), mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nfloat fbm(vec2 p) {\n  float a = 0.5; float s = 0.0;\n  for (int i = 0; i < 5; i++) { s += a * vnoise(p); p = p * 2.03 + vec2(17.1, 9.2); a *= 0.5; }\n  return s / 0.96875;\n}\n\nmat2 rot2(float a) { float c = cos(a); float s = sin(a); return mat2(c, -s, s, c); }\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// 25-tap disk coverage of the logo around p (radius r, height-normalized units).\n// x = coverage 0..1 (0.5 on the outline), yz = vector pointing into the logo.\nvec3 logoField(vec2 p, float r) {\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n// Approximate signed distance (positive outside) from a logoField sample of radius r.\nfloat fieldSD(vec3 f, float r) { return (0.5 - f.x) * 2.0 * r; }\n// Edge glow that falls to exactly zero at the field radius r (no full-frame haze floor).\nfloat edgeGlow(float sd, float k, float r) { float f = exp(-r * k); return max(exp(-abs(sd) * k) - f, 0.0) / (1.0 - f); }\n\n// logoField with the 12-direction ring rotated by a per-pixel hash: the polygonal iso-lines of the\n// fixed ring (the \"blocky banding\" and 12-ray stars seen in reviews) become fine, frame-stable noise.\n// Same cost as logoField; use it for anything that draws contours / distances, keep logoField for bevel normals.\nvec3 logoFieldJ(vec2 p, float r) {\n  float j = hash12(floor(isf_FragNormCoord * RENDERSIZE)) * 0.5235988;\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988 + j;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\nfloat logoCov5(vec2 p, float r) {\n  return (logoP(p) + logoP(p + vec2(r, 0.0)) + logoP(p - vec2(r, 0.0)) + logoP(p + vec2(0.0, r)) + logoP(p - vec2(0.0, r))) * 0.2;\n}\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\nvoid floraPal(int pal, out vec3 base, out vec3 hi, out vec3 glow) {\n  if (pal == 1) { base = vec3(0.42, 0.2, 0.04); hi = vec3(1.0, 0.7, 0.16); glow = vec3(1.0, 0.42, 0.08); }\n  else if (pal == 2) { base = vec3(0.0, 0.22, 0.3); hi = vec3(0.1, 1.0, 0.82); glow = vec3(0.65, 0.25, 1.0); }\n  else { base = vec3(0.06, 0.24, 0.07); hi = vec3(0.42, 0.78, 0.26); glow = vec3(0.7, 0.95, 0.4); }\n}\n\nfloat growthCurve(float g, int curve) {\n  if (curve == 1) return 1.0 - (1.0 - g) * (1.0 - g);\n  if (curve == 2) return g * g * (3.0 - 2.0 * g);\n  if (curve == 3) return clamp(1.0 - exp(-6.0 * g) * cos(10.0 * g), 0.0, 1.0);\n  return g;\n}\n\n// Rising, twinkling motes (spores / petals / dust) \u00e2\u20ac\u201d stateless cell particles with a soft halo.\nfloat spores(vec2 p, float density, float t) {\n  float acc = 0.0;\n  for (int k = 0; k < 3; k++) {\n    float fk = float(k);\n    float cs = 0.07 - fk * 0.018;\n    vec2 q = p + vec2(sin(t * 0.21 + fk * 2.0) * 0.04, -t * (0.025 + 0.018 * fk));\n    q += 0.025 * vec2(vnoise(q * 4.0 + t * 0.15), vnoise(q * 4.0 - t * 0.15 + 7.3));\n    vec2 cell = floor(q / cs);\n    vec2 f = (fract(q / cs) - 0.5) * cs;\n    vec3 h = hash32(cell + fk * 31.7);\n    if (h.z < density * 0.45) {\n      vec2 o = (h.xy - 0.5) * cs * 0.6;\n      float d = length(f - o);\n      float sz = max(0.0022 + 0.0032 * h.x, 1.4 / RENDERSIZE.y);\n      float tw = 0.5 + 0.5 * sin(t * (2.0 + 3.0 * h.y) + h.x * 40.0);\n      acc += tw * (exp(-d * d / (sz * sz)) + 0.22 * exp(-d * d / (sz * sz * 10.0)));\n    }\n  }\n  return acc;\n}\n\n// Pointed leaf (vesica) of half-length L along y; negative inside.\nfloat leafSD(vec2 q, float L) {\n  float R = L * 1.25; float o = L * 0.75;\n  return max(length(q - vec2(o, 0.0)), length(q + vec2(o, 0.0))) - R;\n}\n\n// ---- effect ----\nfloat ivyOrder(vec2 q) { return clamp((q.y + 0.16) / 0.32 * 0.8 + 0.2 * fbm(q * 5.0 + 2.0), 0.0, 1.0); }\n\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  int pal = int(float(uPalette) + 0.5);\n  vec3 cBase; vec3 cHi; vec3 cGlow;\n  floraPal(pal, cBase, cHi, cGlow);\n  cBase *= uTint.rgb; cHi *= uTint.rgb; cGlow *= uTint.rgb;\n  float kick = kickN();\n  float px = 1.0 / RENDERSIZE.y;\n  // the tri LFO spends ~45% of its cycle near the ends; the remap gives a real hold at the top\n  float g = growthCurve(holdRamp(clamp(uGrowth / 100.0, 0.0, 1.0), 0.03, 0.78), int(float(uGrowthCurve) + 0.5));\n  float wind = sin(t * uWindFreq * 6.2831853);\n  vec3 F = logoFieldJ(p, 0.016);\n  float sd = fieldSD(F, 0.016);\n  float la = logoP(p);\n  float gfront = g * 1.3 - 0.1;\n  float order = ivyOrder(p);\n  float grown = smoothstep(order, order + 0.05, gfront);\n  // twin tube-shaded vines winding along the outline (pixel-floored width, sub-linear thickness)\n  float thick = pow(uVineThickness, 0.6);\n  float th = max(0.0028 * thick * (1.0 + 0.25 * kick), px * 1.1);\n  float s = (p.x + p.y * 0.6) * 34.0 + fbm(p * 3.0) * 6.0;\n  float sway = wind * (0.004 + 0.003 * uWindFreq);\n  float amp = 0.009 + 0.004 * kick;\n  float v1 = abs(sd - amp * sin(s) - sway) / th;\n  float v2 = abs(sd - amp * sin(s + 3.14159) + sway) / th;\n  float vd = min(v1, v2);\n  float nearE = smoothstep(0.0, 0.08, F.x);\n  float vine = (1.0 - smoothstep(0.75, 1.0, vd)) * grown * nearE;\n  float tube = sqrt(clamp(1.0 - vd * vd, 0.0, 1.0));\n  float vineShadow = (1.0 - smoothstep(1.0, 2.2, vd)) * grown * 0.6 * nearE;\n  // leaves budding on the outline: fewer and smaller on thin strokes (the emblem), none inside the hex hole\n  vec3 leafCol = vec3(0.0); float leafM = 0.0; float leafShadow = 0.0;\n  float cs = 0.03;\n  vec2 cid = floor(p / cs);\n  for (int j = -1; j <= 1; j++) {\n    for (int i = -1; i <= 1; i++) {\n      vec2 id = cid + vec2(float(i), float(j));\n      vec3 h = hash32(id + 17.0);\n      vec2 c = (id + 0.5 + (h.xy - 0.5) * 0.6) * cs;\n      float e = logoCov5(c, 0.014);\n      if (1.0 - abs(e * 2.0 - 1.0) < 0.2) continue;\n      float thin = 1.0 - smoothstep(0.25, 0.5, logoCov5(c, 0.03));\n      if (h.z > 0.85 - 0.6 * thin) continue;\n      float oc = ivyOrder(c);\n      float pop = smoothstep(oc + 0.02, oc + 0.1, gfront);\n      if (pop <= 0.0) continue;\n      float ang = h.x * 6.2831853 + wind * (0.25 + 0.3 * h.y) + sin(t * uWindFreq * 9.0 + h.z * 20.0) * 0.1 + 0.3 * kick;\n      vec2 q = rot2(ang) * (p - c);\n      float L = cs * (0.55 + 0.3 * h.y) * pop * (0.85 + 0.15 * thick) * (1.0 - 0.4 * thin) * (1.0 + 0.2 * kick);\n      float d = leafSD(q, L);\n      leafShadow = max(leafShadow, (1.0 - smoothstep(-0.002, 0.004, leafSD(rot2(ang) * (p - c + vec2(-0.003, 0.004)), L))) * 0.5);\n      float m = 1.0 - smoothstep(-px, px, d);\n      if (m <= 0.0) continue;\n      float rim = smoothstep(-0.0035, -0.0004, d);\n      float rib = 1.0 - smoothstep(0.0, max(0.0011, px), abs(q.x));\n      float veinlets = 1.0 - smoothstep(0.0, max(0.0009, px), abs(fract((q.y - abs(q.x) * 0.9) / L * 3.0) - 0.5) * L * 0.6);\n      vec3 lc = mix(cBase, cHi, clamp(0.3 + 0.5 * h.y + 0.35 * q.x / L, 0.0, 1.0));\n      lc *= 0.7 + 0.45 * smoothstep(-L, L, q.y);\n      lc = mix(lc, cHi * 1.25, (rib + veinlets * 0.4) * 0.35);\n      lc *= 1.0 - rim * 0.45;\n      leafCol = mix(leafCol, lc, m);\n      leafM = max(leafM, m);\n    }\n  }\n  float fillAmt = smoothstep(order + 0.12, order + 0.3, gfront) * smoothstep(0.45, 0.8, g);\n  vec3 lcol = IMG_NORM_PIXEL(inputImage, uv).rgb;\n  vec3 col = lcol * la * fillAmt;\n  float solid = la * fillAmt;\n  col *= 1.0 - max(vineShadow, leafShadow) * (1.0 - leafM) * fillAmt;\n  solid = max(solid, max(vineShadow, leafShadow) * 0.5);\n  vec3 vineCol = mix(cBase * 0.55, cHi, 0.25 + 0.55 * tube) * (0.55 + 0.6 * tube);\n  col = mix(col, vineCol, vine); solid = max(solid, vine);\n  col = mix(col, leafCol, leafM); solid = max(solid, leafM);\n  float neon = pal == 2 ? 1.0 : 0.3;\n  col += cGlow * edgeGlow(sd, 110.0, 0.016) * grown * (0.2 + 0.4 * uHigh * aud) * neon;\n  float tip = exp(-abs(order - gfront) * 60.0) * edgeGlow(sd, 140.0, 0.016) * step(gfront, 1.05) * step(0.0, gfront);\n  col += cGlow * tip * 1.2;\n  float sporeMask = smoothstep(0.0, 0.3, logoField(p, 0.16).x);\n  col += cGlow * sporeMask * spores(p, uSporeCount / 400.0, t) * (1.2 + 0.6 * uMid * aud);\n  col = mix(1.0 - exp(-col * 1.3), col, la * fillAmt * (1.0 - vine) * (1.0 - leafM));\n  gl_FragColor = vjOut(col, solid);\n}\n"},{"id":"flora-moss","name":"Moss Dispersion Field","category":"flora","blurb":"Worley moss cushions grow out from seed colonies across the letterforms, creeping past the edges, with the brand mark reading through.","params":[{"name":"uGrowth","label":"Growth Progress","type":"float","default":100,"min":0,"max":100,"unit":"%","auto":{"on":true,"shape":"tri","rate":0.08,"lo":0,"hi":1},"hint":"Holds the finished logo above ~78%."},{"name":"uGrowthCurve","label":"Growth Curve","type":"long","default":1,"values":[0,1,2,3],"labels":["Linear","Ease Out","Organic S","Elastic"]},{"name":"uVineThickness","label":"Moss Relief","type":"float","default":1,"min":0.2,"max":3,"hint":"Bump strength and fibre scale."},{"name":"uWindFreq","label":"Wind Flutter","type":"float","default":0.6,"min":0,"max":4,"unit":"Hz","hint":"A height wave travelling through the cushions."},{"name":"uSporeCount","label":"Creep & Spores","type":"float","default":120,"min":0,"max":400,"hint":"How far the colonies creep past the edges, and the spore motes."},{"name":"uPalette","label":"Color Palette","type":"long","default":0,"values":[0,1,2],"labels":["Chlorophyll Green","Autumnal Gold","Bioluminescent Neon"]},{"name":"uTint","label":"Brand Tint","type":"color","default":[1,1,1,1],"hint":"Multiplies the palette so a sponsor can match its own green / gold."},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Forest Floor","values":{}},{"name":"Lichen Gold","values":{"uPalette":1,"uVineThickness":0.6}},{"name":"Bio Moss","values":{"uPalette":2,"uSporeCount":320}}],"source":"/*{\n  \"DESCRIPTION\": \"Moss Dispersion Field \u00e2\u20ac\u201d Worley moss cushions grow out from seed colonies across the letterforms, creeping past the edges, with the brand mark reading through.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Botanical & Flora\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uGrowth\",\"TYPE\":\"float\",\"LABEL\":\"Growth Progress\",\"DEFAULT\":100,\"MIN\":0,\"MAX\":100},\n    {\"NAME\":\"uGrowthCurve\",\"TYPE\":\"long\",\"LABEL\":\"Growth Curve\",\"DEFAULT\":1,\"VALUES\":[0,1,2,3],\"LABELS\":[\"Linear\",\"Ease Out\",\"Organic S\",\"Elastic\"]},\n    {\"NAME\":\"uVineThickness\",\"TYPE\":\"float\",\"LABEL\":\"Moss Relief\",\"DEFAULT\":1,\"MIN\":0.2,\"MAX\":3},\n    {\"NAME\":\"uWindFreq\",\"TYPE\":\"float\",\"LABEL\":\"Wind Flutter\",\"DEFAULT\":0.6,\"MIN\":0,\"MAX\":4},\n    {\"NAME\":\"uSporeCount\",\"TYPE\":\"float\",\"LABEL\":\"Creep & Spores\",\"DEFAULT\":120,\"MIN\":0,\"MAX\":400},\n    {\"NAME\":\"uPalette\",\"TYPE\":\"long\",\"LABEL\":\"Color Palette\",\"DEFAULT\":0,\"VALUES\":[0,1,2],\"LABELS\":[\"Chlorophyll Green\",\"Autumnal Gold\",\"Bioluminescent Neon\"]},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Brand Tint\",\"DEFAULT\":[1,1,1,1]},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Moss Dispersion Field \u00c2\u00b7 Botanical & Flora\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nfloat vnoise(vec2 p) {\n  vec2 i = floor(p); vec2 f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x), mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nfloat fbm(vec2 p) {\n  float a = 0.5; float s = 0.0;\n  for (int i = 0; i < 5; i++) { s += a * vnoise(p); p = p * 2.03 + vec2(17.1, 9.2); a *= 0.5; }\n  return s / 0.96875;\n}\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// 25-tap disk coverage of the logo around p (radius r, height-normalized units).\n// x = coverage 0..1 (0.5 on the outline), yz = vector pointing into the logo.\nvec3 logoField(vec2 p, float r) {\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n// Approximate signed distance (positive outside) from a logoField sample of radius r.\nfloat fieldSD(vec3 f, float r) { return (0.5 - f.x) * 2.0 * r; }\n// Edge glow that falls to exactly zero at the field radius r (no full-frame haze floor).\nfloat edgeGlow(float sd, float k, float r) { float f = exp(-r * k); return max(exp(-abs(sd) * k) - f, 0.0) / (1.0 - f); }\n\n// logoField with the 12-direction ring rotated by a per-pixel hash: the polygonal iso-lines of the\n// fixed ring (the \"blocky banding\" and 12-ray stars seen in reviews) become fine, frame-stable noise.\n// Same cost as logoField; use it for anything that draws contours / distances, keep logoField for bevel normals.\nvec3 logoFieldJ(vec2 p, float r) {\n  float j = hash12(floor(isf_FragNormCoord * RENDERSIZE)) * 0.5235988;\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988 + j;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\nvoid floraPal(int pal, out vec3 base, out vec3 hi, out vec3 glow) {\n  if (pal == 1) { base = vec3(0.42, 0.2, 0.04); hi = vec3(1.0, 0.7, 0.16); glow = vec3(1.0, 0.42, 0.08); }\n  else if (pal == 2) { base = vec3(0.0, 0.22, 0.3); hi = vec3(0.1, 1.0, 0.82); glow = vec3(0.65, 0.25, 1.0); }\n  else { base = vec3(0.06, 0.24, 0.07); hi = vec3(0.42, 0.78, 0.26); glow = vec3(0.7, 0.95, 0.4); }\n}\n\nfloat growthCurve(float g, int curve) {\n  if (curve == 1) return 1.0 - (1.0 - g) * (1.0 - g);\n  if (curve == 2) return g * g * (3.0 - 2.0 * g);\n  if (curve == 3) return clamp(1.0 - exp(-6.0 * g) * cos(10.0 * g), 0.0, 1.0);\n  return g;\n}\n\n// Rising, twinkling motes (spores / petals / dust) \u00e2\u20ac\u201d stateless cell particles with a soft halo.\nfloat spores(vec2 p, float density, float t) {\n  float acc = 0.0;\n  for (int k = 0; k < 3; k++) {\n    float fk = float(k);\n    float cs = 0.07 - fk * 0.018;\n    vec2 q = p + vec2(sin(t * 0.21 + fk * 2.0) * 0.04, -t * (0.025 + 0.018 * fk));\n    q += 0.025 * vec2(vnoise(q * 4.0 + t * 0.15), vnoise(q * 4.0 - t * 0.15 + 7.3));\n    vec2 cell = floor(q / cs);\n    vec2 f = (fract(q / cs) - 0.5) * cs;\n    vec3 h = hash32(cell + fk * 31.7);\n    if (h.z < density * 0.45) {\n      vec2 o = (h.xy - 0.5) * cs * 0.6;\n      float d = length(f - o);\n      float sz = max(0.0022 + 0.0032 * h.x, 1.4 / RENDERSIZE.y);\n      float tw = 0.5 + 0.5 * sin(t * (2.0 + 3.0 * h.y) + h.x * 40.0);\n      acc += tw * (exp(-d * d / (sz * sz)) + 0.22 * exp(-d * d / (sz * sz * 10.0)));\n    }\n  }\n  return acc;\n}\n\n// ---- effect ----\n// Worley moss: 3x3 cellular F1 on a domain-warped field (cushions with real gaps), two scales.\nfloat mossF1(vec2 q) {\n  vec2 ci = floor(q); vec2 cf = q - ci;\n  float f1 = 9.0;\n  for (int j = -1; j <= 1; j++) for (int i = -1; i <= 1; i++) {\n    vec2 o = vec2(float(i), float(j));\n    vec2 sp = o + hash22(ci + o);\n    f1 = min(f1, length(cf - sp));\n  }\n  return f1;\n}\nfloat mossHeight(vec2 q, float fscale, float wob) {\n  vec2 w = q + 0.02 * vec2(vnoise(q * 9.0), vnoise(q * 9.0 + 4.0));\n  float cushion = 44.0 - 7.0 * clamp(uVineThickness, 0.2, 3.0);\n  float c1 = 1.0 - smoothstep(0.1, 0.75, mossF1(w * cushion));\n  float c2 = 1.0 - smoothstep(0.1, 0.8, mossF1(w * cushion * 2.1 + 3.0));\n  float fib = vnoise((q + vec2(wob, 0.0)) * fscale) * 0.6 + vnoise((q + vec2(wob * 1.5, 0.0)) * fscale * 2.1 + 9.0) * 0.4;\n  return c1 * 0.55 + c2 * 0.25 + fib * 0.2;\n}\n// Colonies grow radially from Voronoi seeds (a real creep, not patches popping in).\nfloat mossCover(vec2 p, float g, float reach) {\n  vec2 q = p * 9.0;\n  vec2 ci = floor(q); vec2 cf = q - ci;\n  float cov = 0.0;\n  for (int j = -1; j <= 1; j++) for (int i = -1; i <= 1; i++) {\n    vec2 o = vec2(float(i), float(j));\n    vec2 h = hash22(ci + o);\n    vec2 sp = o + h;\n    float d = length(cf - sp);\n    float start = h.x * 0.6;\n    float R = max(g - start, 0.0) / (1.0 - start) * reach;\n    cov = max(cov, 1.0 - smoothstep(R - 0.25, R, d));\n  }\n  return cov;\n}\n\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  int pal = int(float(uPalette) + 0.5);\n  vec3 cBase; vec3 cHi; vec3 cGlow;\n  floraPal(pal, cBase, cHi, cGlow);\n  cBase *= uTint.rgb; cHi *= uTint.rgb; cGlow *= uTint.rgb;\n  float kick = kickN();\n  float px = 1.0 / RENDERSIZE.y;\n  // the tri LFO spends ~45% of its cycle near the ends; the remap gives a real hold at the top\n  float g = growthCurve(holdRamp(clamp(uGrowth / 100.0, 0.0, 1.0), 0.03, 0.78), int(float(uGrowthCurve) + 0.5));\n  float la = logoP(p);\n  vec3 F = logoFieldJ(p, 0.02);\n  float disp = clamp(uSporeCount / 250.0, 0.0, 1.6);\n  float creep = smoothstep(0.5 - 0.42 * disp, 0.5, F.x) * smoothstep(0.45, 0.75, fbm(p * 30.0 + 5.0) + F.x * 0.5);\n  float region = max(la, creep);\n  float feather = fbm(p * 90.0) * 0.3;\n  float cover = region * clamp(mossCover(p, g, 1.8 + 0.8 * kick) - feather + 0.15, 0.0, 1.0);\n  float wob = sin(t * uWindFreq * 6.2831853 + p.y * 30.0 + p.x * 12.0) * 0.007;\n  float fscale = 150.0 / max(uVineThickness, 0.2);\n  float e = 0.0025;\n  float travel = 0.12 * sin(p.x * 14.0 - t * uWindFreq * 6.2831853);\n  float h0 = mossHeight(p, fscale, wob) + travel;\n  float hx = mossHeight(p + vec2(e, 0.0), fscale, wob) + 0.12 * sin((p.x + e) * 14.0 - t * uWindFreq * 6.2831853);\n  float hy = mossHeight(p + vec2(0.0, e), fscale, wob) + travel;\n  float bump = (3.0 + 6.0 * uVineThickness) * (1.0 + 3.0 * kick);\n  vec3 n = normalize(vec3((h0 - hx) * bump, (h0 - hy) * bump, 1.0));\n  float lit = clamp(dot(n, normalize(vec3(-0.5, 0.6, 0.65))), 0.0, 1.0);\n  float rimL = pow(1.0 - clamp(dot(n, vec3(0.0, 0.0, 1.0)), 0.0, 1.0), 2.0);\n  float moss = clamp(smoothstep(0.0, 0.3, cover * (0.5 + 0.8 * h0) + (h0 - 0.5) * 0.2), 0.0, 1.0) * 0.85;\n  float tips = smoothstep(0.62, 0.85, h0);\n  vec3 cDeep = cBase * 0.3;\n  vec3 cMoss = cHi * vec3(0.8, 0.85, 0.6);\n  vec3 col = mix(cDeep, cMoss, smoothstep(0.2, 0.85, h0));\n  col *= 0.3 + 0.9 * lit;\n  col += cMoss * rimL * 0.35;\n  col += cMoss * pow(lit, 6.0) * kick * 1.2;\n  col = mix(col, cMoss * 1.15, tips * 0.3);\n  // lichen specks\n  float lichen = step(0.93, hash12(floor(p * 260.0))) * tips;\n  col = mix(col, mix(vec3(0.9, 0.9, 0.8), cGlow, 0.3), lichen * 0.6);\n  col *= moss;\n  float glowAmt = pal == 2 ? 1.0 : 0.15;\n  col += cGlow * tips * moss * glowAmt * (0.5 + uHigh * aud);\n  vec3 lcol = IMG_NORM_PIXEL(inputImage, uv).rgb;\n  // the un-mossed logo stays solid (never a ghost), and a thin rim of it shows through at the hold\n  float under = la * (1.0 - moss) * mix(1.0, 0.65, smoothstep(0.0, 0.5, g));\n  col += lcol * under;\n  float rimBand = smoothstep(0.3, 0.5, F.x) * (1.0 - smoothstep(0.55, 0.75, F.x));\n  col = mix(col, lcol, la * moss * (0.25 * smoothstep(0.8, 1.0, g) + 0.3 * rimBand));\n  float sporeMask = smoothstep(0.0, 0.3, logoField(p, 0.16).x);\n  col += cGlow * sporeMask * spores(p, uSporeCount / 400.0, t) * 1.2;\n  gl_FragColor = vjOut(col, max(moss, under));\n}\n"},{"id":"flora-bloom","name":"Flower Blooming Morph","category":"flora","blurb":"A lush bed of layered blossoms unfurls cell by cell across the logo, then settles into brand colors.","params":[{"name":"uGrowth","label":"Growth Progress","type":"float","default":100,"min":0,"max":100,"unit":"%","auto":{"on":true,"shape":"tri","rate":0.08,"lo":0,"hi":1},"hint":"Holds the finished logo above ~78%."},{"name":"uGrowthCurve","label":"Growth Curve","type":"long","default":1,"values":[0,1,2,3],"labels":["Linear","Ease Out","Organic S","Elastic"]},{"name":"uVineThickness","label":"Bloom Size","type":"float","default":1,"min":0.2,"max":3},{"name":"uWindFreq","label":"Wind Flutter","type":"float","default":0.6,"min":0,"max":4,"unit":"Hz","hint":"Petal sway rate."},{"name":"uSporeCount","label":"Pollen Motes","type":"float","default":120,"min":0,"max":400},{"name":"uPalette","label":"Color Palette","type":"long","default":0,"values":[0,1,2],"labels":["Chlorophyll Green","Autumnal Gold","Bioluminescent Neon"]},{"name":"uTint","label":"Brand Tint","type":"color","default":[1,1,1,1],"hint":"Multiplies the palette so a sponsor can match its own green / gold."},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Spring Bloom","values":{}},{"name":"Marigold","values":{"uPalette":1}},{"name":"Night Orchid","values":{"uPalette":2,"uSporeCount":200}}],"source":"/*{\n  \"DESCRIPTION\": \"Flower Blooming Morph \u00e2\u20ac\u201d A lush bed of layered blossoms unfurls cell by cell across the logo, then settles into brand colors.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Botanical & Flora\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uGrowth\",\"TYPE\":\"float\",\"LABEL\":\"Growth Progress\",\"DEFAULT\":100,\"MIN\":0,\"MAX\":100},\n    {\"NAME\":\"uGrowthCurve\",\"TYPE\":\"long\",\"LABEL\":\"Growth Curve\",\"DEFAULT\":1,\"VALUES\":[0,1,2,3],\"LABELS\":[\"Linear\",\"Ease Out\",\"Organic S\",\"Elastic\"]},\n    {\"NAME\":\"uVineThickness\",\"TYPE\":\"float\",\"LABEL\":\"Bloom Size\",\"DEFAULT\":1,\"MIN\":0.2,\"MAX\":3},\n    {\"NAME\":\"uWindFreq\",\"TYPE\":\"float\",\"LABEL\":\"Wind Flutter\",\"DEFAULT\":0.6,\"MIN\":0,\"MAX\":4},\n    {\"NAME\":\"uSporeCount\",\"TYPE\":\"float\",\"LABEL\":\"Pollen Motes\",\"DEFAULT\":120,\"MIN\":0,\"MAX\":400},\n    {\"NAME\":\"uPalette\",\"TYPE\":\"long\",\"LABEL\":\"Color Palette\",\"DEFAULT\":0,\"VALUES\":[0,1,2],\"LABELS\":[\"Chlorophyll Green\",\"Autumnal Gold\",\"Bioluminescent Neon\"]},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Brand Tint\",\"DEFAULT\":[1,1,1,1]},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Flower Blooming Morph \u00c2\u00b7 Botanical & Flora\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nfloat vnoise(vec2 p) {\n  vec2 i = floor(p); vec2 f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x), mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nfloat fbm(vec2 p) {\n  float a = 0.5; float s = 0.0;\n  for (int i = 0; i < 5; i++) { s += a * vnoise(p); p = p * 2.03 + vec2(17.1, 9.2); a *= 0.5; }\n  return s / 0.96875;\n}\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// 25-tap disk coverage of the logo around p (radius r, height-normalized units).\n// x = coverage 0..1 (0.5 on the outline), yz = vector pointing into the logo.\nvec3 logoField(vec2 p, float r) {\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n// Approximate signed distance (positive outside) from a logoField sample of radius r.\nfloat fieldSD(vec3 f, float r) { return (0.5 - f.x) * 2.0 * r; }\n// Edge glow that falls to exactly zero at the field radius r (no full-frame haze floor).\nfloat edgeGlow(float sd, float k, float r) { float f = exp(-r * k); return max(exp(-abs(sd) * k) - f, 0.0) / (1.0 - f); }\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\nfloat logoCov5(vec2 p, float r) {\n  return (logoP(p) + logoP(p + vec2(r, 0.0)) + logoP(p - vec2(r, 0.0)) + logoP(p + vec2(0.0, r)) + logoP(p - vec2(0.0, r))) * 0.2;\n}\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\nvoid floraPal(int pal, out vec3 base, out vec3 hi, out vec3 glow) {\n  if (pal == 1) { base = vec3(0.42, 0.2, 0.04); hi = vec3(1.0, 0.7, 0.16); glow = vec3(1.0, 0.42, 0.08); }\n  else if (pal == 2) { base = vec3(0.0, 0.22, 0.3); hi = vec3(0.1, 1.0, 0.82); glow = vec3(0.65, 0.25, 1.0); }\n  else { base = vec3(0.06, 0.24, 0.07); hi = vec3(0.42, 0.78, 0.26); glow = vec3(0.7, 0.95, 0.4); }\n}\n\nfloat growthCurve(float g, int curve) {\n  if (curve == 1) return 1.0 - (1.0 - g) * (1.0 - g);\n  if (curve == 2) return g * g * (3.0 - 2.0 * g);\n  if (curve == 3) return clamp(1.0 - exp(-6.0 * g) * cos(10.0 * g), 0.0, 1.0);\n  return g;\n}\n\n// Rising, twinkling motes (spores / petals / dust) \u00e2\u20ac\u201d stateless cell particles with a soft halo.\nfloat spores(vec2 p, float density, float t) {\n  float acc = 0.0;\n  for (int k = 0; k < 3; k++) {\n    float fk = float(k);\n    float cs = 0.07 - fk * 0.018;\n    vec2 q = p + vec2(sin(t * 0.21 + fk * 2.0) * 0.04, -t * (0.025 + 0.018 * fk));\n    q += 0.025 * vec2(vnoise(q * 4.0 + t * 0.15), vnoise(q * 4.0 - t * 0.15 + 7.3));\n    vec2 cell = floor(q / cs);\n    vec2 f = (fract(q / cs) - 0.5) * cs;\n    vec3 h = hash32(cell + fk * 31.7);\n    if (h.z < density * 0.45) {\n      vec2 o = (h.xy - 0.5) * cs * 0.6;\n      float d = length(f - o);\n      float sz = max(0.0022 + 0.0032 * h.x, 1.4 / RENDERSIZE.y);\n      float tw = 0.5 + 0.5 * sin(t * (2.0 + 3.0 * h.y) + h.x * 40.0);\n      acc += tw * (exp(-d * d / (sz * sz)) + 0.22 * exp(-d * d / (sz * sz * 10.0)));\n    }\n  }\n  return acc;\n}\n\n// ---- effect ----\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  int pal = int(float(uPalette) + 0.5);\n  vec3 cBase; vec3 cHi; vec3 cGlow;\n  floraPal(pal, cBase, cHi, cGlow);\n  cBase *= uTint.rgb; cHi *= uTint.rgb; cGlow *= uTint.rgb;\n  float kick = kickN();\n  float px = 1.0 / RENDERSIZE.y;\n  // the tri LFO spends ~45% of its cycle near the ends; the remap gives a real hold at the top\n  float g = growthCurve(holdRamp(clamp(uGrowth / 100.0, 0.0, 1.0), 0.03, 0.78), int(float(uGrowthCurve) + 0.5));\n  float la = logoP(p);\n  vec3 lcol = IMG_NORM_PIXEL(inputImage, uv).rgb;\n  float leafy = fbm(p * 55.0);\n  vec3 bedCol = mix(cBase * 0.45, cBase * 1.25, smoothstep(0.3, 0.75, leafy));\n  vec3 col = vec3(0.0);\n  float solid = 0.0;\n  float density = 0.0;\n  // petal palette derives from the chosen flora palette (no hard-coded pink under \"Chlorophyll Green\")\n  vec3 petA = mix(cHi, vec3(1.0), 0.6);\n  vec3 petB = mix(cGlow, cHi, 0.4);\n  if (pal == 1) { petA = vec3(1.0, 0.55, 0.12) * uTint.rgb; petB = vec3(0.85, 0.15, 0.06) * uTint.rgb; }\n  if (pal == 2) { petA = vec3(1.0, 0.25, 0.85) * uTint.rgb; petB = vec3(0.2, 0.9, 1.0) * uTint.rgb; }\n  for (int layer = 0; layer < 2; layer++) {\n    float fl = float(layer);\n    float cs = layer == 0 ? 0.036 : 0.024;\n    vec2 shift = vec2(0.5 * cs) * fl;\n    vec2 cid = floor((p + shift) / cs);\n    for (int j = -1; j <= 1; j++) {\n      for (int i = -1; i <= 1; i++) {\n        vec2 id = cid + vec2(float(i), float(j));\n        vec3 h = hash32(id * 1.17 + 3.0 + fl * 41.0);\n        vec2 c = (id + 0.5 + (h.xy - 0.5) * 0.7) * cs - shift;\n        if (logoCov5(c, 0.006) < 0.4) continue;\n        float thin = 1.0 - smoothstep(0.3, 0.6, logoCov5(c, 0.02));\n        float delay = h.z * 0.45 + clamp(c.y + 0.5, 0.0, 1.0) * 0.25 + fl * 0.1;\n        float bloomA = smoothstep(delay, delay + 0.3, g + 0.03);\n        if (bloomA <= 0.0) continue;\n        vec2 d = p - c;\n        float sway = sin(t * uWindFreq * 6.2831853 + h.x * 6.28) * 0.15;\n        float spin = (1.0 - bloomA) * 2.5 + h.y * 6.28 + sway;\n        float r = length(d);\n        float a = atan(d.y, d.x) + spin;\n        float N = 5.0 + floor(h.x * 3.0);\n        float R = cs * (0.9 + 0.25 * h.y) * bloomA * (0.92 + 0.2 * kick) * (0.85 + 0.08 * uVineThickness) * (1.0 - 0.45 * thin);\n        float petalShape = 0.45 + 0.55 * pow(abs(cos(a * N * 0.5)), 0.7);\n        float petal = R * petalShape;\n        float inner = R * 0.62 * (0.45 + 0.55 * abs(cos((a + 3.14159 / N) * N * 0.5)));\n        float mOuter = 1.0 - smoothstep(petal - px, petal + px * 0.5, r);\n        float mInner = 1.0 - smoothstep(inner - px, inner + px * 0.5, r);\n        float m = max(mOuter, mInner);\n        density = max(density, 1.0 - smoothstep(R, R * 1.6, r));\n        if (m <= 0.0) continue;\n        float core = 1.0 - smoothstep(R * 0.17, R * 0.17 + px, r);\n        float edgeO = smoothstep(petal - 0.004, petal - 0.0005, r) * mOuter;\n        float groove = pow(abs(sin(a * N * 0.5)), 8.0);\n        vec3 pc = mix(petA, petB, h.z);\n        // at the hold the petals take on the brand colour under them\n        pc = mix(pc, imgClamp(p2uv(c)).rgb, 0.6 * smoothstep(0.85, 1.0, g));\n        vec3 pc2 = mix(petB, vec3(1.0), 0.35);\n        vec3 fc = pc * (0.45 + 0.65 * r / max(petal, 0.0001));\n        fc *= 1.0 - groove * 0.3 - edgeO * 0.35;\n        fc = mix(fc, pc2 * (0.55 + 0.55 * r / max(inner, 0.0001)), mInner);\n        vec3 pollen = mix(vec3(1.0, 0.82, 0.25), cGlow, pal == 2 ? 0.6 : 0.1);\n        fc = mix(fc, pollen * (0.8 + 0.4 * hash12(floor(d * 900.0))), core);\n        fc += (edgeO * 0.5 + core) * cGlow * uHigh * aud * 0.35;\n        col = mix(col * (1.0 - 0.35 * mOuter), fc, m);\n        solid = max(solid, m);\n      }\n    }\n  }\n  // the bed only exists where flowers are (no olive slab), under them\n  float bed = la * density * smoothstep(0.03, 0.3, g);\n  col = mix(bedCol * bed, col, solid);\n  solid = max(solid, bed);\n  float sporeMask = smoothstep(0.0, 0.3, logoField(p, 0.16).x);\n  col += mix(cHi, cGlow, 0.5) * sporeMask * spores(p, uSporeCount / 400.0, t * 0.7) * 1.5;\n  gl_FragColor = vjOut(col, solid);\n}\n"},{"id":"flora-roots","name":"Root Fractal Extrusion","category":"flora","blurb":"Tapering roots hang from every stroke and grow downward, forking and swaying, with light pulses racing to their tips.","params":[{"name":"uGrowth","label":"Growth Progress","type":"float","default":100,"min":0,"max":100,"unit":"%","auto":{"on":true,"shape":"tri","rate":0.08,"lo":0,"hi":1},"hint":"Holds the finished logo above ~78%."},{"name":"uGrowthCurve","label":"Growth Curve","type":"long","default":1,"values":[0,1,2,3],"labels":["Linear","Ease Out","Organic S","Elastic"]},{"name":"uVineThickness","label":"Root Thickness","type":"float","default":1,"min":0.2,"max":3,"hint":"Trunk width and root length."},{"name":"uWindFreq","label":"Root Sway","type":"float","default":0.6,"min":0,"max":4,"unit":"Hz"},{"name":"uSporeCount","label":"Spore Motes","type":"float","default":120,"min":0,"max":400},{"name":"uPalette","label":"Color Palette","type":"long","default":0,"values":[0,1,2],"labels":["Chlorophyll Green","Autumnal Gold","Bioluminescent Neon"]},{"name":"uTint","label":"Brand Tint","type":"color","default":[1,1,1,1],"hint":"Multiplies the palette so a sponsor can match its own green / gold."},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Deep Roots","values":{}},{"name":"Copper Veins","values":{"uPalette":1,"uVineThickness":1.8}},{"name":"Mycelium Neon","values":{"uPalette":2,"uVineThickness":0.7,"uSporeCount":220}}],"source":"/*{\n  \"DESCRIPTION\": \"Root Fractal Extrusion \u00e2\u20ac\u201d Tapering roots hang from every stroke and grow downward, forking and swaying, with light pulses racing to their tips.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Botanical & Flora\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uGrowth\",\"TYPE\":\"float\",\"LABEL\":\"Growth Progress\",\"DEFAULT\":100,\"MIN\":0,\"MAX\":100},\n    {\"NAME\":\"uGrowthCurve\",\"TYPE\":\"long\",\"LABEL\":\"Growth Curve\",\"DEFAULT\":1,\"VALUES\":[0,1,2,3],\"LABELS\":[\"Linear\",\"Ease Out\",\"Organic S\",\"Elastic\"]},\n    {\"NAME\":\"uVineThickness\",\"TYPE\":\"float\",\"LABEL\":\"Root Thickness\",\"DEFAULT\":1,\"MIN\":0.2,\"MAX\":3},\n    {\"NAME\":\"uWindFreq\",\"TYPE\":\"float\",\"LABEL\":\"Root Sway\",\"DEFAULT\":0.6,\"MIN\":0,\"MAX\":4},\n    {\"NAME\":\"uSporeCount\",\"TYPE\":\"float\",\"LABEL\":\"Spore Motes\",\"DEFAULT\":120,\"MIN\":0,\"MAX\":400},\n    {\"NAME\":\"uPalette\",\"TYPE\":\"long\",\"LABEL\":\"Color Palette\",\"DEFAULT\":0,\"VALUES\":[0,1,2],\"LABELS\":[\"Chlorophyll Green\",\"Autumnal Gold\",\"Bioluminescent Neon\"]},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Brand Tint\",\"DEFAULT\":[1,1,1,1]},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Root Fractal Extrusion \u00c2\u00b7 Botanical & Flora\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nfloat vnoise(vec2 p) {\n  vec2 i = floor(p); vec2 f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x), mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// 25-tap disk coverage of the logo around p (radius r, height-normalized units).\n// x = coverage 0..1 (0.5 on the outline), yz = vector pointing into the logo.\nvec3 logoField(vec2 p, float r) {\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n// Approximate signed distance (positive outside) from a logoField sample of radius r.\nfloat fieldSD(vec3 f, float r) { return (0.5 - f.x) * 2.0 * r; }\n// Edge glow that falls to exactly zero at the field radius r (no full-frame haze floor).\nfloat edgeGlow(float sd, float k, float r) { float f = exp(-r * k); return max(exp(-abs(sd) * k) - f, 0.0) / (1.0 - f); }\n\n// logoField with the 12-direction ring rotated by a per-pixel hash: the polygonal iso-lines of the\n// fixed ring (the \"blocky banding\" and 12-ray stars seen in reviews) become fine, frame-stable noise.\n// Same cost as logoField; use it for anything that draws contours / distances, keep logoField for bevel normals.\nvec3 logoFieldJ(vec2 p, float r) {\n  float j = hash12(floor(isf_FragNormCoord * RENDERSIZE)) * 0.5235988;\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988 + j;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\nvoid floraPal(int pal, out vec3 base, out vec3 hi, out vec3 glow) {\n  if (pal == 1) { base = vec3(0.42, 0.2, 0.04); hi = vec3(1.0, 0.7, 0.16); glow = vec3(1.0, 0.42, 0.08); }\n  else if (pal == 2) { base = vec3(0.0, 0.22, 0.3); hi = vec3(0.1, 1.0, 0.82); glow = vec3(0.65, 0.25, 1.0); }\n  else { base = vec3(0.06, 0.24, 0.07); hi = vec3(0.42, 0.78, 0.26); glow = vec3(0.7, 0.95, 0.4); }\n}\n\nfloat growthCurve(float g, int curve) {\n  if (curve == 1) return 1.0 - (1.0 - g) * (1.0 - g);\n  if (curve == 2) return g * g * (3.0 - 2.0 * g);\n  if (curve == 3) return clamp(1.0 - exp(-6.0 * g) * cos(10.0 * g), 0.0, 1.0);\n  return g;\n}\n\n// Rising, twinkling motes (spores / petals / dust) \u00e2\u20ac\u201d stateless cell particles with a soft halo.\nfloat spores(vec2 p, float density, float t) {\n  float acc = 0.0;\n  for (int k = 0; k < 3; k++) {\n    float fk = float(k);\n    float cs = 0.07 - fk * 0.018;\n    vec2 q = p + vec2(sin(t * 0.21 + fk * 2.0) * 0.04, -t * (0.025 + 0.018 * fk));\n    q += 0.025 * vec2(vnoise(q * 4.0 + t * 0.15), vnoise(q * 4.0 - t * 0.15 + 7.3));\n    vec2 cell = floor(q / cs);\n    vec2 f = (fract(q / cs) - 0.5) * cs;\n    vec3 h = hash32(cell + fk * 31.7);\n    if (h.z < density * 0.45) {\n      vec2 o = (h.xy - 0.5) * cs * 0.6;\n      float d = length(f - o);\n      float sz = max(0.0022 + 0.0032 * h.x, 1.4 / RENDERSIZE.y);\n      float tw = 0.5 + 0.5 * sin(t * (2.0 + 3.0 * h.y) + h.x * 40.0);\n      acc += tw * (exp(-d * d / (sz * sz)) + 0.22 * exp(-d * d / (sz * sz * 10.0)));\n    }\n  }\n  return acc;\n}\n\n// ---- effect ----\n// Column-anchored roots: for the pixel's column find the glyph bottom directly above (10 taps), so every\n// root hangs from a letter, tapers with depth, sways and forks. Causal, confined, no neon rain.\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  int pal = int(float(uPalette) + 0.5);\n  vec3 cBase; vec3 cHi; vec3 cGlow;\n  floraPal(pal, cBase, cHi, cGlow);\n  cBase *= uTint.rgb; cHi *= uTint.rgb; cGlow *= uTint.rgb;\n  float kick = kickN();\n  float px = 1.0 / RENDERSIZE.y;\n  // the tri LFO spends ~45% of its cycle near the ends; the remap gives a real hold at the top\n  float g = growthCurve(holdRamp(clamp(uGrowth / 100.0, 0.0, 1.0), 0.03, 0.78), int(float(uGrowthCurve) + 0.5));\n  float la = logoP(p);\n  vec3 lcol = IMG_NORM_PIXEL(inputImage, uv).rgb;\n  float thick = clamp(uVineThickness / 3.0, 0.0, 1.0);\n  float colW = 0.018 * (0.7 + 0.6 * thick);\n  float cid = floor(p.x / colW);\n  float cx = (cid + 0.5) * colW;\n  vec3 hc = hash32(vec2(cid, 3.0));\n  // glyph bottom directly above this pixel\n  float yb = 9.0;\n  for (int i = 0; i < 10; i++) {\n    float y = p.y + 0.012 + float(i) * 0.03;\n    if (y > 0.2) break;\n    if (logoP(vec2(cx, y)) > 0.5) { yb = y; break; }\n  }\n  float hasRoot = step(yb, 8.0) * step(0.25, hc.z);\n  float len = (0.12 + 0.36 * hc.x) * (0.6 + 0.6 * thick);\n  float depth = (yb - p.y) / max(len, 0.001);\n  float reach = g * 1.05 + 0.05 * kick;\n  float grownR = 1.0 - smoothstep(reach - 0.08, reach, depth);\n  // sway centreline + fork at a hashed depth\n  float sway = (0.015 + 0.02 * hc.y) * sin(depth * 6.0 + hc.x * 6.28 + t * uWindFreq * 6.2831853 * 0.5) * depth;\n  float forkAt = 0.3 + 0.4 * hc.y;\n  float fork = smoothstep(forkAt, forkAt + 0.1, depth) * 0.6 * colW * (hc.x < 0.5 ? -1.0 : 1.0) * (depth - forkAt);\n  float w0 = colW * 0.45 * (1.0 + 0.5 * kick);\n  float width = w0 * pow(max(1.0 - depth, 0.0), 1.3);\n  float dxA = abs(p.x - cx - sway);\n  float dxB = abs(p.x - cx - sway - fork * 3.0);\n  float wB = width * 0.6 * smoothstep(forkAt, forkAt + 0.05, depth);\n  float rootA = 1.0 - smoothstep(width - px, width + px, dxA);\n  float rootB = 1.0 - smoothstep(wB - px, wB + px, dxB);\n  float inRoot = max(rootA, rootB) * step(0.0, depth) * step(depth, 1.0) * hasRoot * grownR * (1.0 - la);\n  float tubeA = sqrt(clamp(1.0 - dxA * dxA / max(width * width, 0.000001), 0.0, 1.0));\n  float ridge = 0.5 + 0.5 * sin(depth * 40.0 + hc.y * 10.0);\n  float pulse = pow(0.5 + 0.5 * sin(depth * 10.0 - t * 4.0 + hc.x * 6.0), 6.0);\n  float tip = exp(-abs(depth - reach + 0.04) * 30.0) * hasRoot * step(0.02, g);\n  float glowAmt = pal == 2 ? 1.0 : 0.4;\n  vec3 rootCol = mix(cBase * 0.8, cHi, 0.3 + 0.5 * tubeA) * (0.7 + 0.3 * ridge) + cGlow * (pulse * glowAmt * 0.6 + tip * 1.4) * (0.5 + 1.2 * kick);\n  // letters stay their own colour; veins only in a thin inside-edge band\n  float fill = la * smoothstep(0.25, 0.6, g);\n  vec3 Fe = logoFieldJ(p, 0.015);\n  float band = smoothstep(0.5, 0.7, Fe.x) * (1.0 - smoothstep(0.75, 0.95, Fe.x));\n  float veins = pow(1.0 - abs(2.0 * vnoise(p * 60.0 + 5.0) - 1.0), 6.0) * band * la;\n  vec3 col = lcol * fill + cGlow * veins * (0.3 + 0.4 * pulse + 0.8 * kick) * g * glowAmt;\n  col += cGlow * la * (1.0 - fill) * 0.25 * smoothstep(0.0, 0.3, g);\n  col += rootCol * inRoot;\n  float sporeMask = smoothstep(0.0, 0.3, logoField(p, 0.16).x);\n  col += cGlow * sporeMask * spores(p, uSporeCount / 400.0, t) * 1.3;\n  gl_FragColor = vjOut(col, max(fill, inRoot * 0.95));\n}\n"},{"id":"flora-swarm","name":"Leaf Particle Swarm","category":"flora","blurb":"A vortex of tumbling leaves spirals in and locks into the logo silhouette.","params":[{"name":"uGrowth","label":"Growth Progress","type":"float","default":100,"min":0,"max":100,"unit":"%","auto":{"on":true,"shape":"tri","rate":0.08,"lo":0,"hi":1},"hint":"Holds the finished logo above ~78%."},{"name":"uGrowthCurve","label":"Growth Curve","type":"long","default":1,"values":[0,1,2,3],"labels":["Linear","Ease Out","Organic S","Elastic"]},{"name":"uVineThickness","label":"Leaf Size","type":"float","default":1,"min":0.2,"max":3},{"name":"uWindFreq","label":"Flutter Rate","type":"float","default":0.6,"min":0,"max":4,"unit":"Hz"},{"name":"uSporeCount","label":"Glow Motes","type":"float","default":120,"min":0,"max":400},{"name":"uPalette","label":"Color Palette","type":"long","default":0,"values":[0,1,2],"labels":["Chlorophyll Green","Autumnal Gold","Bioluminescent Neon"]},{"name":"uTint","label":"Brand Tint","type":"color","default":[1,1,1,1],"hint":"Multiplies the palette so a sponsor can match its own green / gold."},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Green Gust","values":{}},{"name":"Fall Cyclone","values":{"uPalette":1,"uWindFreq":1.2}},{"name":"Glowfly Swarm","values":{"uPalette":2,"uSporeCount":300}}],"source":"/*{\n  \"DESCRIPTION\": \"Leaf Particle Swarm \u00e2\u20ac\u201d A vortex of tumbling leaves spirals in and locks into the logo silhouette.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Botanical & Flora\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uGrowth\",\"TYPE\":\"float\",\"LABEL\":\"Growth Progress\",\"DEFAULT\":100,\"MIN\":0,\"MAX\":100},\n    {\"NAME\":\"uGrowthCurve\",\"TYPE\":\"long\",\"LABEL\":\"Growth Curve\",\"DEFAULT\":1,\"VALUES\":[0,1,2,3],\"LABELS\":[\"Linear\",\"Ease Out\",\"Organic S\",\"Elastic\"]},\n    {\"NAME\":\"uVineThickness\",\"TYPE\":\"float\",\"LABEL\":\"Leaf Size\",\"DEFAULT\":1,\"MIN\":0.2,\"MAX\":3},\n    {\"NAME\":\"uWindFreq\",\"TYPE\":\"float\",\"LABEL\":\"Flutter Rate\",\"DEFAULT\":0.6,\"MIN\":0,\"MAX\":4},\n    {\"NAME\":\"uSporeCount\",\"TYPE\":\"float\",\"LABEL\":\"Glow Motes\",\"DEFAULT\":120,\"MIN\":0,\"MAX\":400},\n    {\"NAME\":\"uPalette\",\"TYPE\":\"long\",\"LABEL\":\"Color Palette\",\"DEFAULT\":0,\"VALUES\":[0,1,2],\"LABELS\":[\"Chlorophyll Green\",\"Autumnal Gold\",\"Bioluminescent Neon\"]},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Brand Tint\",\"DEFAULT\":[1,1,1,1]},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Leaf Particle Swarm \u00c2\u00b7 Botanical & Flora\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nfloat vnoise(vec2 p) {\n  vec2 i = floor(p); vec2 f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x), mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nmat2 rot2(float a) { float c = cos(a); float s = sin(a); return mat2(c, -s, s, c); }\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// 25-tap disk coverage of the logo around p (radius r, height-normalized units).\n// x = coverage 0..1 (0.5 on the outline), yz = vector pointing into the logo.\nvec3 logoField(vec2 p, float r) {\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n// Approximate signed distance (positive outside) from a logoField sample of radius r.\nfloat fieldSD(vec3 f, float r) { return (0.5 - f.x) * 2.0 * r; }\n// Edge glow that falls to exactly zero at the field radius r (no full-frame haze floor).\nfloat edgeGlow(float sd, float k, float r) { float f = exp(-r * k); return max(exp(-abs(sd) * k) - f, 0.0) / (1.0 - f); }\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\nvoid floraPal(int pal, out vec3 base, out vec3 hi, out vec3 glow) {\n  if (pal == 1) { base = vec3(0.42, 0.2, 0.04); hi = vec3(1.0, 0.7, 0.16); glow = vec3(1.0, 0.42, 0.08); }\n  else if (pal == 2) { base = vec3(0.0, 0.22, 0.3); hi = vec3(0.1, 1.0, 0.82); glow = vec3(0.65, 0.25, 1.0); }\n  else { base = vec3(0.06, 0.24, 0.07); hi = vec3(0.42, 0.78, 0.26); glow = vec3(0.7, 0.95, 0.4); }\n}\n\nfloat growthCurve(float g, int curve) {\n  if (curve == 1) return 1.0 - (1.0 - g) * (1.0 - g);\n  if (curve == 2) return g * g * (3.0 - 2.0 * g);\n  if (curve == 3) return clamp(1.0 - exp(-6.0 * g) * cos(10.0 * g), 0.0, 1.0);\n  return g;\n}\n\n// Rising, twinkling motes (spores / petals / dust) \u00e2\u20ac\u201d stateless cell particles with a soft halo.\nfloat spores(vec2 p, float density, float t) {\n  float acc = 0.0;\n  for (int k = 0; k < 3; k++) {\n    float fk = float(k);\n    float cs = 0.07 - fk * 0.018;\n    vec2 q = p + vec2(sin(t * 0.21 + fk * 2.0) * 0.04, -t * (0.025 + 0.018 * fk));\n    q += 0.025 * vec2(vnoise(q * 4.0 + t * 0.15), vnoise(q * 4.0 - t * 0.15 + 7.3));\n    vec2 cell = floor(q / cs);\n    vec2 f = (fract(q / cs) - 0.5) * cs;\n    vec3 h = hash32(cell + fk * 31.7);\n    if (h.z < density * 0.45) {\n      vec2 o = (h.xy - 0.5) * cs * 0.6;\n      float d = length(f - o);\n      float sz = max(0.0022 + 0.0032 * h.x, 1.4 / RENDERSIZE.y);\n      float tw = 0.5 + 0.5 * sin(t * (2.0 + 3.0 * h.y) + h.x * 40.0);\n      acc += tw * (exp(-d * d / (sz * sz)) + 0.22 * exp(-d * d / (sz * sz * 10.0)));\n    }\n  }\n  return acc;\n}\n\n// Pointed leaf (vesica) of half-length L along y; negative inside.\nfloat leafSD(vec2 q, float L) {\n  float R = L * 1.25; float o = L * 0.75;\n  return max(length(q - vec2(o, 0.0)), length(q + vec2(o, 0.0))) - R;\n}\n\n// ---- effect ----\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  int pal = int(float(uPalette) + 0.5);\n  vec3 cBase; vec3 cHi; vec3 cGlow;\n  floraPal(pal, cBase, cHi, cGlow);\n  cBase *= uTint.rgb; cHi *= uTint.rgb; cGlow *= uTint.rgb;\n  float kick = kickN();\n  float px = 1.0 / RENDERSIZE.y;\n  // the tri LFO spends ~45% of its cycle near the ends; the remap gives a real hold at the top\n  float g = growthCurve(holdRamp(clamp(uGrowth / 100.0, 0.0, 1.0), 0.03, 0.78), int(float(uGrowthCurve) + 0.5));\n  float freeA = pow(1.0 - g, 1.5);\n  float la = logoP(p);\n  vec3 lcol = IMG_NORM_PIXEL(inputImage, uv).rgb;\n  float base = la * smoothstep(0.55, 0.95, g);\n  float ghost = la * smoothstep(0.4, 0.7, g) * 0.25;\n  vec3 col = mix(lcol, cBase, 0.1) * max(base, ghost);\n  float solid = max(base, ghost);\n  float cs = 0.028;\n  float dens = mix(0.45, 0.8, smoothstep(0.7, 1.0, g));\n  for (int k = 0; k < 3; k++) {\n    float fk = float(k);\n    float depthK = fk / 2.0;\n    float spread = 1.0 + freeA * (1.2 + 0.6 * fk);\n    float rh = length(p) / spread;\n    float theta = freeA * (3.0 + 2.5 * fk + 7.0 * rh) + t * 0.6 * freeA * (1.0 + fk * 0.3) * (1.0 + kick * 0.5);\n    vec2 h = rot2(-theta) * p / spread;\n    vec2 cid = floor((h + fk * 0.37 * cs) / cs);\n    for (int j = -1; j <= 1; j++) {\n      for (int i = -1; i <= 1; i++) {\n        vec2 id = cid + vec2(float(i), float(j));\n        vec3 hh = hash32(id + fk * 57.0);\n        if (hh.z > dens) continue;\n        vec2 c = (id + 0.5 + (hh.xy - 0.5) * 0.8) * cs - fk * 0.37 * cs;\n        if (logoP(c) < 0.5) continue;\n        float flut = sin(t * uWindFreq * 6.2831853 + hh.x * 30.0);\n        vec2 off = vec2(flut, cos(t * uWindFreq * 5.0 + hh.y * 20.0)) * 0.006 * (freeA * 2.0 + 0.15) * (0.5 + 0.5 * uWindFreq);\n        vec2 q = rot2(hh.x * 6.28 + theta + flut * (0.3 + freeA)) * (h - c - off / spread);\n        float tumble = cos(t * (1.5 + hh.y * 2.0) + hh.z * 20.0);\n        float squash = mix(1.0, 0.45 + 0.55 * abs(tumble), clamp(freeA * 1.5, 0.0, 1.0));\n        q.x /= max(squash, 0.05);\n        // velocity stretch while airborne (motion blur along the orbit)\n        q.y /= 1.0 + 0.6 * freeA;\n        float L = cs * (0.55 + 0.3 * hh.y) * (0.6 + 0.25 * uVineThickness) * (1.0 + 0.25 * kick) * mix(1.3, 0.7, depthK);\n        float d = leafSD(q * spread, L);\n        float aaw = px * (1.0 + 2.0 * depthK);\n        float m = (1.0 - smoothstep(-aaw, aaw, d)) * mix(1.0, 0.6, smoothstep(0.5, 0.3, squash));\n        if (m <= 0.0) continue;\n        float shadow = 1.0 - smoothstep(-aaw, aaw * 3.0, leafSD((q - vec2(0.003, -0.004)) * spread, L));\n        float rib = 1.0 - smoothstep(0.0, max(0.001, px), abs(q.x * spread * squash));\n        vec3 lc = mix(cBase, cHi, 0.3 + 0.6 * hh.y) * (0.85 + 0.3 * hh.x);\n        if (pal == 1) lc = mix(lc, vec3(0.75, 0.18, 0.05) * uTint.rgb, hh.x * 0.6);\n        lc *= 0.7 + 0.4 * smoothstep(-L, L, q.y * spread);\n        lc *= mix(1.0, tumble < 0.0 ? 0.6 : 1.1, clamp(freeA * 1.5, 0.0, 1.0));\n        lc = mix(lc, cHi * 1.2, rib * 0.3);\n        lc *= mix(1.0, 0.55, depthK);\n        col *= 1.0 - shadow * 0.35 * (1.0 - m);\n        col = mix(col, lc, m);\n        solid = max(solid, max(m, shadow * 0.3));\n      }\n    }\n  }\n  float sporeMask = smoothstep(0.0, 0.3, logoField(p, 0.16).x);\n  col += cGlow * sporeMask * spores(p, uSporeCount / 400.0, t) * 1.3;\n  if (pal == 2) col += cGlow * 0.15 * solid * (0.5 + uHigh * aud);\n  gl_FragColor = vjOut(col, solid);\n}\n"},{"id":"flora-lotus","name":"Psy Lotus Mandala","category":"flora","blurb":"Golden-angle echo rings of the logo outline bloom outward like a psytrance lotus, stepping out on the beat around a knocked-out centre mark.","params":[{"name":"uGrowth","label":"Growth Progress","type":"float","default":100,"min":0,"max":100,"unit":"%","auto":{"on":true,"shape":"tri","rate":0.08,"lo":0,"hi":1},"hint":"Bloom: how far the echo rings open out from the logo."},{"name":"uGrowthCurve","label":"Growth Curve","type":"long","default":1,"values":[0,1,2,3],"labels":["Linear","Ease Out","Organic S","Elastic"]},{"name":"uVineThickness","label":"Vine Thickness","type":"float","default":1,"min":0.2,"max":3,"hint":"Stroke weight of the echo outlines."},{"name":"uWindFreq","label":"Wind Flutter","type":"float","default":0.6,"min":0,"max":4,"unit":"Hz","hint":"Counter-rotation of alternate rings (0.05 rev/s per Hz)."},{"name":"uSporeCount","label":"Spore Particles","type":"float","default":120,"min":0,"max":400,"hint":"Ring count: 2 rings at 0, 9 rings at 400."},{"name":"uPalette","label":"Color Palette","type":"long","default":0,"values":[0,1,2],"labels":["Chlorophyll Green","Autumnal Gold","Bioluminescent Neon"]},{"name":"uTint","label":"Brand Tint","type":"color","default":[1,1,1,1],"hint":"Multiplies the palette so a sponsor can match its own green / gold."},{"name":"uSwirl","label":"Lotus Swirl","type":"float","default":0.45,"min":0,"max":1,"hint":"Golden-angle turn per ring: each ring shows a different slice of the mark (0 = all rings alike)."},{"name":"uBeat","label":"Beat Phase","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"beat","hint":"Sawtooth 0\u00e2\u2020\u20191 per beat (app BPM clock). In Resolume, map to a BPM-synced parameter; in TD, a beat CHOP ramp."},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"UV Lotus","values":{"uPalette":2,"uSporeCount":280}},{"name":"Acid Mandala","values":{"uPalette":0,"uSporeCount":360,"uSwirl":0.72,"uWindFreq":1}},{"name":"Solar Bloom","values":{"uPalette":1,"uSporeCount":200,"uSwirl":0.22,"uVineThickness":1.6}}],"source":"/*{\n  \"DESCRIPTION\": \"Psy Lotus Mandala \u00e2\u20ac\u201d Golden-angle echo rings of the logo outline bloom outward like a psytrance lotus, stepping out on the beat around a knocked-out centre mark.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Botanical & Flora\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uGrowth\",\"TYPE\":\"float\",\"LABEL\":\"Growth Progress\",\"DEFAULT\":100,\"MIN\":0,\"MAX\":100},\n    {\"NAME\":\"uGrowthCurve\",\"TYPE\":\"long\",\"LABEL\":\"Growth Curve\",\"DEFAULT\":1,\"VALUES\":[0,1,2,3],\"LABELS\":[\"Linear\",\"Ease Out\",\"Organic S\",\"Elastic\"]},\n    {\"NAME\":\"uVineThickness\",\"TYPE\":\"float\",\"LABEL\":\"Vine Thickness\",\"DEFAULT\":1,\"MIN\":0.2,\"MAX\":3},\n    {\"NAME\":\"uWindFreq\",\"TYPE\":\"float\",\"LABEL\":\"Wind Flutter\",\"DEFAULT\":0.6,\"MIN\":0,\"MAX\":4},\n    {\"NAME\":\"uSporeCount\",\"TYPE\":\"float\",\"LABEL\":\"Spore Particles\",\"DEFAULT\":120,\"MIN\":0,\"MAX\":400},\n    {\"NAME\":\"uPalette\",\"TYPE\":\"long\",\"LABEL\":\"Color Palette\",\"DEFAULT\":0,\"VALUES\":[0,1,2],\"LABELS\":[\"Chlorophyll Green\",\"Autumnal Gold\",\"Bioluminescent Neon\"]},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Brand Tint\",\"DEFAULT\":[1,1,1,1]},\n    {\"NAME\":\"uSwirl\",\"TYPE\":\"float\",\"LABEL\":\"Lotus Swirl\",\"DEFAULT\":0.45,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uBeat\",\"TYPE\":\"float\",\"LABEL\":\"Beat Phase\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Psy Lotus Mandala \u00c2\u00b7 Botanical & Flora\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\n// Inigo Quilez cosine palette (iquilezles.org/articles/palettes).\nvec3 palCos(float t, vec3 a, vec3 b, vec3 c, vec3 d) { return a + b * cos(6.2831853 * (c * t + d)); }\n\n// Mirror-fold p into one of n angular segments (kaleidoscope). n is a float; continuous only for whole n \u00e2\u20ac\u201d crossfade between floor(n) and floor(n)+1.\nvec2 foldPolar(vec2 p, float n, float rot) {\n  float sp = 6.2831853 / max(n, 1.0);\n  float a = atan(p.y, p.x + 0.00001) + rot;\n  a = abs(mod(a, sp) - 0.5 * sp);\n  return length(p) * vec2(cos(a), sin(a));\n}\n\nmat2 rot2(float a) { float c = cos(a); float s = sin(a); return mat2(c, -s, s, c); }\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\nfloat logoCov5(vec2 p, float r) {\n  return (logoP(p) + logoP(p + vec2(r, 0.0)) + logoP(p - vec2(r, 0.0)) + logoP(p + vec2(0.0, r)) + logoP(p - vec2(0.0, r))) * 0.2;\n}\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\nvoid floraPal(int pal, out vec3 base, out vec3 hi, out vec3 glow) {\n  if (pal == 1) { base = vec3(0.42, 0.2, 0.04); hi = vec3(1.0, 0.7, 0.16); glow = vec3(1.0, 0.42, 0.08); }\n  else if (pal == 2) { base = vec3(0.0, 0.22, 0.3); hi = vec3(0.1, 1.0, 0.82); glow = vec3(0.65, 0.25, 1.0); }\n  else { base = vec3(0.06, 0.24, 0.07); hi = vec3(0.42, 0.78, 0.26); glow = vec3(0.7, 0.95, 0.4); }\n}\n\nfloat growthCurve(float g, int curve) {\n  if (curve == 1) return 1.0 - (1.0 - g) * (1.0 - g);\n  if (curve == 2) return g * g * (3.0 - 2.0 * g);\n  if (curve == 3) return clamp(1.0 - exp(-6.0 * g) * cos(10.0 * g), 0.0, 1.0);\n  return g;\n}\n\n// ---- effect ----\n// 5-tap plus kernel: x = centre alpha, y = mean coverage (0.5 on the outline).\nvec2 lotus_cov(vec2 q, float w) {\n  float c = logoP(q);\n  float s = c + logoP(q + vec2(w, 0.0)) + logoP(q - vec2(w, 0.0)) + logoP(q + vec2(0.0, w)) + logoP(q - vec2(0.0, w));\n  return vec2(c, s * 0.2);\n}\nvec3 lotus_pal(float x, int pal) {\n  if (pal == 1) return palCos(x, vec3(0.92, 0.42, 0.25), vec3(0.1, 0.36, 0.22), vec3(1.0, 1.0, 1.0), vec3(0.0, 0.0, 0.45));\n  if (pal == 2) return palCos(x, vec3(0.5, 0.42, 0.75), vec3(0.5, 0.45, 0.3), vec3(1.0, 1.0, 1.0), vec3(0.55, 0.3, 0.1));\n  return palCos(x, vec3(0.45, 0.62, 0.45), vec3(0.4, 0.38, 0.45), vec3(1.0, 1.0, 1.0), vec3(0.3, 0.12, 0.62));\n}\n\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  int pal = int(float(uPalette) + 0.5);\n  vec3 cBase; vec3 cHi; vec3 cGlow;\n  floraPal(pal, cBase, cHi, cGlow);\n  cBase *= uTint.rgb; cHi *= uTint.rgb; cGlow *= uTint.rgb;\n  float px = 1.0 / RENDERSIZE.y;\n  // hold at the top of the tri LFO (a legible finished logo instead of a scrub)\n  float g = growthCurve(holdRamp(clamp(uGrowth / 100.0, 0.0, 1.0), 0.03, 0.78), int(float(uGrowthCurve) + 0.5));\n  float kick = kickN();\n  // beat lock: a light cascade leaves the logo on every beat and runs out through the rings (zero at both ends of the beat, so no jump at the wrap)\n  float bp = clamp(uBeat, 0.0, 1.0);\n  float nR = 2.0 + clamp(uSporeCount / 400.0, 0.0, 1.0) * 7.0;\n  float gap = 0.13 * (1.0 + 0.6 * kick);\n  float spin = t * uWindFreq * 0.05 * 6.2831853;\n  float w = max(0.0045 * uVineThickness * (1.0 + 0.8 * kick), 1.6 * px);\n  float midTw = clamp(uMid * aud, 0.0, 1.5);\n  float shimmer = clamp(uHigh * aud, 0.0, 1.0);\n  float frameM = 1.0 - smoothstep(0.34, 0.49, length(p * vec2(0.56, 1.0)));\n  // the kick punches the whole mandala outward (structure, not only brightness)\n  vec2 pm = p / (1.0 + 0.14 * kick);\n  vec3 col = vec3(0.0); float solid = 0.0;\n  for (int k = 0; k < 10; k++) {\n    float x = float(k);\n    if (x > nR + 1.0) break;\n    float vis = clamp(nR + 1.0 - x, 0.0, 1.0) * smoothstep(0.0, 0.8, x);\n    vis *= smoothstep(0.0, 0.2, g * 1.3 - 0.11 * x);\n    if (vis <= 0.001) continue;\n    float s = 1.35 + x * gap * g;\n    float alt = cos(3.14159265 * x);\n    // ring k: 8-fold kaleidoscope of the logo, counter-rotating with its neighbours; the golden-angle\n    // turn picks a different slice of the mark for every ring (uSwirl = how far it turns per ring)\n    float ringRot = alt * (spin + 0.55 * midTw);\n    // fold first, rotate after: every ring keeps the same symmetry axes (a mandala, not polygon debris)\n    vec2 q = foldPolar(pm, 4.0, 0.0);\n    q = rot2(-(x * 2.39996323 * uSwirl + ringRot)) * q / s;\n    vec2 c = lotus_cov(q, w / s);\n    float band = 1.0 - abs(2.0 * c.y - 1.0);\n    float line = smoothstep(0.2, 0.75, band);\n    float dash = step(0.45, fract((q.x - q.y) * 70.0 - t * 4.0 + x * 0.37));\n    line *= mix(1.0, 0.2 + 0.8 * dash, shimmer * step(0.5, fract(x * 0.5)));\n    float petal = c.x * 0.04;\n    vec3 rc = lotus_pal(x / 9.0 + t * 0.04, pal) * uTint.rgb;\n    float fade = 1.0 - 0.5 * x / 10.0;\n    float cascade = exp(-abs(x - bp * (nR + 1.5)) * 1.4) * (1.0 - bp) * bp * 4.0;\n    col += rc * (line * (1.2 + 0.5 * kick + cascade) + petal) * vis * fade;\n    solid = max(solid, (line + petal) * vis * fade);\n  }\n  col *= frameM; solid *= frameM;\n  // centre logo on top over a dark knockout\n  float knock = smoothstep(0.0, 0.3, logoCov5(p, 0.02));\n  col *= 1.0 - 0.92 * knock;\n  solid = max(solid, knock * 0.85);\n  vec4 lg = logoRGBA(p / (1.0 + 0.04 * kick));\n  col = mix(col, lg.rgb, lg.a);\n  solid = max(solid, lg.a);\n  gl_FragColor = vjOut(col, solid);\n}\n"},{"id":"flora-coral","name":"Turing Coral Labyrinth","category":"flora","blurb":"Reaction-diffusion stripes and spots crawl out of the logo edge as a ragged coral reef, then keep slowly re-knotting.","params":[{"name":"uGrowth","label":"Growth Progress","type":"float","default":100,"min":0,"max":100,"unit":"%","auto":{"on":true,"shape":"tri","rate":0.08,"lo":0,"hi":1},"hint":"Reef reach out from the logo edge (ragged front)."},{"name":"uGrowthCurve","label":"Growth Curve","type":"long","default":1,"values":[0,1,2,3],"labels":["Linear","Ease Out","Organic S","Elastic"]},{"name":"uVineThickness","label":"Vine Thickness","type":"float","default":1,"min":0.2,"max":3,"hint":"Stripe thickness (Turing threshold): thin labyrinth to fat blobs."},{"name":"uWindFreq","label":"Wind Flutter","type":"float","default":0.6,"min":0,"max":4,"unit":"Hz","hint":"Crawl: how fast the pattern re-knots."},{"name":"uSporeCount","label":"Spore Particles","type":"float","default":120,"min":0,"max":400,"hint":"Stripes to spots blend (0 = labyrinth, 400 = spots)."},{"name":"uPalette","label":"Color Palette","type":"long","default":0,"values":[0,1,2],"labels":["Chlorophyll Green","Autumnal Gold","Bioluminescent Neon"]},{"name":"uTint","label":"Brand Tint","type":"color","default":[1,1,1,1],"hint":"Multiplies the palette so a sponsor can match its own green / gold."},{"name":"uStripeFreq","label":"Stripe Frequency","type":"float","default":26,"min":16,"max":60,"hint":"Turing wavelength: stripes per frame height."},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Brain Coral Calm","values":{"uPalette":0,"uWindFreq":0.25,"uAudioReact":0.4,"uSporeCount":40,"uVineThickness":0.7,"uTint":[0.8,0.85,0.75,1]}},{"name":"Living Coral","values":{"uPalette":1}},{"name":"Neon Reef","values":{"uPalette":2,"uSporeCount":220,"uWindFreq":1.4,"uAudioReact":1.4}}],"source":"/*{\n  \"DESCRIPTION\": \"Turing Coral Labyrinth \u00e2\u20ac\u201d Reaction-diffusion stripes and spots crawl out of the logo edge as a ragged coral reef, then keep slowly re-knotting.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Botanical & Flora\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uGrowth\",\"TYPE\":\"float\",\"LABEL\":\"Growth Progress\",\"DEFAULT\":100,\"MIN\":0,\"MAX\":100},\n    {\"NAME\":\"uGrowthCurve\",\"TYPE\":\"long\",\"LABEL\":\"Growth Curve\",\"DEFAULT\":1,\"VALUES\":[0,1,2,3],\"LABELS\":[\"Linear\",\"Ease Out\",\"Organic S\",\"Elastic\"]},\n    {\"NAME\":\"uVineThickness\",\"TYPE\":\"float\",\"LABEL\":\"Vine Thickness\",\"DEFAULT\":1,\"MIN\":0.2,\"MAX\":3},\n    {\"NAME\":\"uWindFreq\",\"TYPE\":\"float\",\"LABEL\":\"Wind Flutter\",\"DEFAULT\":0.6,\"MIN\":0,\"MAX\":4},\n    {\"NAME\":\"uSporeCount\",\"TYPE\":\"float\",\"LABEL\":\"Spore Particles\",\"DEFAULT\":120,\"MIN\":0,\"MAX\":400},\n    {\"NAME\":\"uPalette\",\"TYPE\":\"long\",\"LABEL\":\"Color Palette\",\"DEFAULT\":0,\"VALUES\":[0,1,2],\"LABELS\":[\"Chlorophyll Green\",\"Autumnal Gold\",\"Bioluminescent Neon\"]},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Brand Tint\",\"DEFAULT\":[1,1,1,1]},\n    {\"NAME\":\"uStripeFreq\",\"TYPE\":\"float\",\"LABEL\":\"Stripe Frequency\",\"DEFAULT\":26,\"MIN\":16,\"MAX\":60},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Turing Coral Labyrinth \u00c2\u00b7 Botanical & Flora\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nfloat vnoise(vec2 p) {\n  vec2 i = floor(p); vec2 f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x), mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nfloat fbm(vec2 p) {\n  float a = 0.5; float s = 0.0;\n  for (int i = 0; i < 5; i++) { s += a * vnoise(p); p = p * 2.03 + vec2(17.1, 9.2); a *= 0.5; }\n  return s / 0.96875;\n}\n\n// 3-octave fbm: cheaper sibling of fbm() for nested domain warps.\nfloat fbm3(vec2 p) {\n  float a = 0.5; float s = 0.0;\n  for (int i = 0; i < 3; i++) { s += a * vnoise(p); p = p * 2.03 + vec2(17.1, 9.2); a *= 0.5; }\n  return s / 0.875;\n}\n\n// Inigo Quilez double domain warp (iquilezles.org/articles/warp). Returns the warped field; q, r = intermediates for colouring.\nfloat warp2(vec2 p, out vec2 q, out vec2 r) {\n  q = vec2(fbm3(p), fbm3(p + vec2(5.2, 1.3)));\n  r = vec2(fbm3(p + 4.0 * q + vec2(1.7, 9.2)), fbm3(p + 4.0 * q + vec2(8.3, 2.8)));\n  return fbm3(p + 4.0 * r);\n}\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// 25-tap disk coverage of the logo around p (radius r, height-normalized units).\n// x = coverage 0..1 (0.5 on the outline), yz = vector pointing into the logo.\nvec3 logoField(vec2 p, float r) {\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n// Approximate signed distance (positive outside) from a logoField sample of radius r.\nfloat fieldSD(vec3 f, float r) { return (0.5 - f.x) * 2.0 * r; }\n// Edge glow that falls to exactly zero at the field radius r (no full-frame haze floor).\nfloat edgeGlow(float sd, float k, float r) { float f = exp(-r * k); return max(exp(-abs(sd) * k) - f, 0.0) / (1.0 - f); }\n\n// logoField with the 12-direction ring rotated by a per-pixel hash: the polygonal iso-lines of the\n// fixed ring (the \"blocky banding\" and 12-ray stars seen in reviews) become fine, frame-stable noise.\n// Same cost as logoField; use it for anything that draws contours / distances, keep logoField for bevel normals.\nvec3 logoFieldJ(vec2 p, float r) {\n  float j = hash12(floor(isf_FragNormCoord * RENDERSIZE)) * 0.5235988;\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988 + j;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\nvoid floraPal(int pal, out vec3 base, out vec3 hi, out vec3 glow) {\n  if (pal == 1) { base = vec3(0.42, 0.2, 0.04); hi = vec3(1.0, 0.7, 0.16); glow = vec3(1.0, 0.42, 0.08); }\n  else if (pal == 2) { base = vec3(0.0, 0.22, 0.3); hi = vec3(0.1, 1.0, 0.82); glow = vec3(0.65, 0.25, 1.0); }\n  else { base = vec3(0.06, 0.24, 0.07); hi = vec3(0.42, 0.78, 0.26); glow = vec3(0.7, 0.95, 0.4); }\n}\n\nfloat growthCurve(float g, int curve) {\n  if (curve == 1) return 1.0 - (1.0 - g) * (1.0 - g);\n  if (curve == 2) return g * g * (3.0 - 2.0 * g);\n  if (curve == 3) return clamp(1.0 - exp(-6.0 * g) * cos(10.0 * g), 0.0, 1.0);\n  return g;\n}\n\n// ---- effect ----\n// smooth signed distance (+ outside) to the logo edge: logoField + 6-step bisection along the field normal\nfloat coral_sd(vec2 p, float R) {\n  vec3 F = logoField(p, R);\n  float sd0 = fieldSD(F, R);\n  if (abs(sd0) > R * 0.96) return sd0;\n  vec2 n = length(F.yz) > 0.0001 ? normalize(F.yz) : vec2(0.0, 1.0);\n  bool inside = logoP(p) > 0.5;\n  vec2 dir = inside ? -n : n;\n  // march to the FIRST crossing along the normal (an endpoint test lands in the next letter), then bisect;\n  // no crossing at all (normal misses the ink between letters) keeps the coarse estimate\n  float lo = 0.0; float hi = -1.0;\n  for (int i = 1; i <= 8; i++) {\n    float st = R * float(i) * 0.125;\n    if (hi < 0.0) { if ((logoP(p + dir * st) > 0.5) != inside) hi = st; else lo = st; }\n  }\n  if (hi < 0.0) return sd0;\n  for (int i = 0; i < 5; i++) {\n    float mid = 0.5 * (lo + hi);\n    if ((logoP(p + dir * mid) > 0.5) != inside) hi = mid; else lo = mid;\n  }\n  // stay consistent with the coarse field: a missed thin feature must not make sd jump\n  float d = clamp(0.5 * (lo + hi), abs(sd0) - 0.02, abs(sd0) + 0.02);\n  return inside ? -d : d;\n}\n// fingerprint-style stripes: cell-local Gabor waves whose orientation follows a smooth field.\n// One wavelength everywhere; where neighbouring orientations clash the stripes fork and end, as RD labyrinths do.\nvec2 coral_gabor(vec2 q, float t, float gain) {\n  float C = 2.2;\n  vec2 ci = floor(q / C);\n  vec2 s = vec2(0.0); float wsum = 0.0;\n  for (int j = -1; j <= 1; j++) {\n    for (int i = -1; i <= 1; i++) {\n      vec2 id = ci + vec2(float(i), float(j));\n      vec3 h = hash32(id + 0.5);\n      vec2 c = (id + 0.5 + (h.xy - 0.5) * 0.6) * C;\n      float th = vnoise(id * 0.32 + vec2(t, -t * 0.6)) * 6.2831853 * gain;\n      vec2 d = vec2(cos(th), sin(th));\n      vec2 r = q - c;\n      float w = exp(-dot(r, r) / (C * C * 0.3));\n      // x: the stripe wave; y: the same wave turned 90 degrees (their product is the spot lattice)\n      s += w * vec2(cos(6.2831853 * dot(r, d) + h.z * 6.2831853), cos(6.2831853 * dot(r, vec2(-d.y, d.x)) + h.x * 6.2831853));\n      wsum += w * w;\n    }\n  }\n  return s / sqrt(wsum + 0.0001) * 0.7;\n}\nvoid coral_pal(int pal, out vec3 a, out vec3 b, out vec3 deep) {\n  if (pal == 1) { a = vec3(1.0, 0.36, 0.26); b = vec3(1.0, 0.74, 0.42); deep = vec3(0.55, 0.1, 0.12); }\n  else if (pal == 2) { a = vec3(0.1, 0.9, 1.0); b = vec3(0.86, 0.32, 1.0); deep = vec3(0.12, 0.08, 0.42); }\n  else { a = vec3(0.2, 0.78, 0.36); b = vec3(0.78, 1.0, 0.38); deep = vec3(0.06, 0.3, 0.14); }\n}\n\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  int pal = int(float(uPalette) + 0.5);\n  vec3 cBase; vec3 cHi; vec3 cGlow;\n  floraPal(pal, cBase, cHi, cGlow);\n  cBase *= uTint.rgb; cHi *= uTint.rgb; cGlow *= uTint.rgb;\n  float px = 1.0 / RENDERSIZE.y;\n  // hold at the top of the tri LFO (a legible finished logo instead of a scrub)\n  float g = growthCurve(holdRamp(clamp(uGrowth / 100.0, 0.0, 1.0), 0.03, 0.78), int(float(uGrowthCurve) + 0.5));\n  float kick = kickN();\n  float hi = clamp(uHigh * aud, 0.0, 1.0);\n  float R = 0.12;\n  float sd = coral_sd(p, R);\n  // continuous (unclamped) distance for the front: the bisected sd steps where it is clamped to the coarse field\n  float sdc = fieldSD(logoFieldJ(p, R), R);\n  vec4 lg = logoRGBA(p);\n  vec3 cA; vec3 cB; vec3 deep;\n  coral_pal(pal, cA, cB, deep);\n  float crawl = t * uWindFreq * 0.12;\n  vec2 q; vec2 r;\n  float n = warp2(p * 3.2 + vec2(crawl * 0.7, -crawl * 0.4), q, r);\n  // ragged organic front; the kick pops it outward. Always exactly 0 by sd = R.\n  float reach = g * R * (0.6 + 0.8 * n) * (1.0 + 0.3 * kick);\n  float cut = 1.0 - smoothstep(0.8 * R, R, sdc);\n  float grown = (1.0 - smoothstep(reach - 0.012, reach, sdc)) * cut;\n  // Turing field: bass raises the orientation gain (topology reshuffle)\n  float gain = 1.0;\n  vec2 tq = p * uStripeFreq + (q - 0.5) * 2.5;\n  vec2 gb = coral_gabor(tq, crawl * 0.8, gain);\n  float spotMix = clamp(smoothstep(0.2, 1.0, uSporeCount / 400.0) + 0.15 * hi, 0.0, 1.0);\n  float s = mix(gb.x, gb.x * gb.y * 2.2, spotMix);\n  // a dark moat against the ink, the first ridge half a wavelength out, then the free labyrinth\n  float edgeW = exp(-max(sd, 0.0) / 0.011);   // short reach: sd can jump mid-gap between letters (normal flips side)\n  s = mix(s, -cos(6.2831853 * sd * uStripeFreq) * 0.9, edgeW * 0.55 * (1.0 - spotMix));\n  s = mix(-1.0, s, smoothstep(0.006, 0.016, sd));\n  // the kick breathes the stripe threshold (fatter ridges) instead of re-rolling the whole pattern\n  float thr = mix((1.0 - uVineThickness) * 0.32, 0.3, spotMix) - 0.1 * kick;\n  float aaS = 6.2831853 * uStripeFreq * 0.6 / RENDERSIZE.y;\n  float stripe = smoothstep(thr - aaS, thr + aaS, s);\n  float ridge = clamp((s - thr) / 0.9, 0.0, 1.0);\n  vec3 coral = mix(cA, cB, smoothstep(0.25, 0.85, r.x + 0.35 * q.y)) * (0.55 + 0.65 * sqrt(ridge)) * uTint.rgb;\n  coral += mix(cB, vec3(1.0), 0.4) * pow(ridge, 3.0) * 0.45;\n  float outside = smoothstep(-0.002, 0.002, sd);\n  float body = grown * outside;\n  float gapA = 0.55 * (1.0 - smoothstep(reach * 0.7 - 0.012, reach * 0.7, sdc)) * outside * cut;\n  vec3 col = mix(deep * (0.55 + 0.45 * r.y) * gapA, coral * body, stripe);\n  float solid = mix(gapA, body, stripe);\n  // growing tips glow along the front\n  float tip = edgeGlow(sdc - reach, 140.0, 0.03) * stripe * outside * step(0.01, g) * cut;\n  col += mix(cB, vec3(1.0), 0.3) * tip * 0.8;\n  // logo inside: solid, a 0.1-0.3 palette tint carrying the same labyrinth\n  vec3 tint = mix(cA, cB, 0.5) * (0.5 + 0.5 * stripe);\n  vec3 inCol = mix(lg.rgb, tint, 0.1 + 0.2 * stripe);\n  col = mix(col, inCol, lg.a);\n  solid = max(solid, lg.a);\n  gl_FragColor = vjOut(col, solid);\n}\n"},{"id":"flora-engrave","name":"Botanical Engraving Draw-On","category":"flora","blurb":"Banknote hairline contours and cross-hatch trace the logo along an organic pen front, then fill to the exact lockup.","params":[{"name":"uGrowth","label":"Growth Progress","type":"float","default":100,"min":0,"max":100,"unit":"%","auto":{"on":true,"shape":"tri","rate":0.08,"lo":0,"hi":1},"hint":"Draw-on: the pen front sweeps across, then the solid logo fills in under the engraving."},{"name":"uGrowthCurve","label":"Growth Curve","type":"long","default":1,"values":[0,1,2,3],"labels":["Linear","Ease Out","Organic S","Elastic"]},{"name":"uVineThickness","label":"Vine Thickness","type":"float","default":1,"min":0.2,"max":3,"hint":"Hairline weight of the engraved lines."},{"name":"uWindFreq","label":"Wind Flutter","type":"float","default":0.6,"min":0,"max":4,"unit":"Hz","hint":"Sway of the drawing front, and a slow outward drift of the contour lines."},{"name":"uSporeCount","label":"Spore Particles","type":"float","default":120,"min":0,"max":400,"hint":"Stipple dot density in the engraved cast shadow."},{"name":"uPalette","label":"Color Palette","type":"long","default":0,"values":[0,1,2],"labels":["Chlorophyll Green","Autumnal Gold","Bioluminescent Neon"],"hint":"Ink pair: banknote green, gold leaf, neon cyan/violet."},{"name":"uTint","label":"Brand Tint","type":"color","default":[1,1,1,1],"hint":"Multiplies the palette so a sponsor can match its own green / gold."},{"name":"uLineDensity","label":"Line Density","type":"float","default":7,"min":4,"max":14,"hint":"Engraved lines per 0.1 frame height."},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Gold Leaf","values":{"uPalette":1,"uLineDensity":10,"uSporeCount":180}},{"name":"Banknote Green","values":{"uLineDensity":9}},{"name":"Neon Etch","values":{"uPalette":2,"uLineDensity":6,"uVineThickness":1.5}}],"source":"/*{\n  \"DESCRIPTION\": \"Botanical Engraving Draw-On \u00e2\u20ac\u201d Banknote hairline contours and cross-hatch trace the logo along an organic pen front, then fill to the exact lockup.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Botanical & Flora\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uGrowth\",\"TYPE\":\"float\",\"LABEL\":\"Growth Progress\",\"DEFAULT\":100,\"MIN\":0,\"MAX\":100},\n    {\"NAME\":\"uGrowthCurve\",\"TYPE\":\"long\",\"LABEL\":\"Growth Curve\",\"DEFAULT\":1,\"VALUES\":[0,1,2,3],\"LABELS\":[\"Linear\",\"Ease Out\",\"Organic S\",\"Elastic\"]},\n    {\"NAME\":\"uVineThickness\",\"TYPE\":\"float\",\"LABEL\":\"Vine Thickness\",\"DEFAULT\":1,\"MIN\":0.2,\"MAX\":3},\n    {\"NAME\":\"uWindFreq\",\"TYPE\":\"float\",\"LABEL\":\"Wind Flutter\",\"DEFAULT\":0.6,\"MIN\":0,\"MAX\":4},\n    {\"NAME\":\"uSporeCount\",\"TYPE\":\"float\",\"LABEL\":\"Spore Particles\",\"DEFAULT\":120,\"MIN\":0,\"MAX\":400},\n    {\"NAME\":\"uPalette\",\"TYPE\":\"long\",\"LABEL\":\"Color Palette\",\"DEFAULT\":0,\"VALUES\":[0,1,2],\"LABELS\":[\"Chlorophyll Green\",\"Autumnal Gold\",\"Bioluminescent Neon\"]},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Brand Tint\",\"DEFAULT\":[1,1,1,1]},\n    {\"NAME\":\"uLineDensity\",\"TYPE\":\"float\",\"LABEL\":\"Line Density\",\"DEFAULT\":7,\"MIN\":4,\"MAX\":14},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Botanical Engraving Draw-On \u00c2\u00b7 Botanical & Flora\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nfloat vnoise(vec2 p) {\n  vec2 i = floor(p); vec2 f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x), mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nfloat fbm(vec2 p) {\n  float a = 0.5; float s = 0.0;\n  for (int i = 0; i < 5; i++) { s += a * vnoise(p); p = p * 2.03 + vec2(17.1, 9.2); a *= 0.5; }\n  return s / 0.96875;\n}\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// 25-tap disk coverage of the logo around p (radius r, height-normalized units).\n// x = coverage 0..1 (0.5 on the outline), yz = vector pointing into the logo.\nvec3 logoField(vec2 p, float r) {\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n// Approximate signed distance (positive outside) from a logoField sample of radius r.\nfloat fieldSD(vec3 f, float r) { return (0.5 - f.x) * 2.0 * r; }\n// Edge glow that falls to exactly zero at the field radius r (no full-frame haze floor).\nfloat edgeGlow(float sd, float k, float r) { float f = exp(-r * k); return max(exp(-abs(sd) * k) - f, 0.0) / (1.0 - f); }\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\nvoid floraPal(int pal, out vec3 base, out vec3 hi, out vec3 glow) {\n  if (pal == 1) { base = vec3(0.42, 0.2, 0.04); hi = vec3(1.0, 0.7, 0.16); glow = vec3(1.0, 0.42, 0.08); }\n  else if (pal == 2) { base = vec3(0.0, 0.22, 0.3); hi = vec3(0.1, 1.0, 0.82); glow = vec3(0.65, 0.25, 1.0); }\n  else { base = vec3(0.06, 0.24, 0.07); hi = vec3(0.42, 0.78, 0.26); glow = vec3(0.7, 0.95, 0.4); }\n}\n\nfloat growthCurve(float g, int curve) {\n  if (curve == 1) return 1.0 - (1.0 - g) * (1.0 - g);\n  if (curve == 2) return g * g * (3.0 - 2.0 * g);\n  if (curve == 3) return clamp(1.0 - exp(-6.0 * g) * cos(10.0 * g), 0.0, 1.0);\n  return g;\n}\n\n// ---- effect ----\n// smooth signed distance (+ outside) and the inward field normal (for the engraving light)\nvec3 engr_sd(vec2 p, float R) {\n  vec3 F = logoField(p, R);\n  float sd0 = fieldSD(F, R);\n  float gl2 = length(F.yz);\n  vec2 n = gl2 > 0.0001 ? F.yz / gl2 : vec2(0.0, 1.0);\n  if (abs(sd0) > R * 0.96) return vec3(sd0, n * smoothstep(0.0, 0.5, gl2));\n  bool inside = logoP(p) > 0.5;\n  vec2 dir = inside ? -n : n;\n  // march to the FIRST crossing along the normal (an endpoint test lands in the next letter), then bisect;\n  // no crossing at all (normal misses the ink between letters) keeps the coarse estimate\n  float lo = 0.0; float hi = -1.0;\n  for (int i = 1; i <= 8; i++) {\n    float st = R * float(i) * 0.125;\n    if (hi < 0.0) { if ((logoP(p + dir * st) > 0.5) != inside) hi = st; else lo = st; }\n  }\n  if (hi < 0.0) return vec3(sd0, n);\n  for (int i = 0; i < 5; i++) {\n    float mid = 0.5 * (lo + hi);\n    if ((logoP(p + dir * mid) > 0.5) != inside) hi = mid; else lo = mid;\n  }\n  // stay consistent with the coarse field: a missed thin feature must not make sd jump\n  float d = clamp(0.5 * (lo + hi), abs(sd0) - 0.02, abs(sd0) + 0.02);\n  return vec3(inside ? -d : d, n);\n}\nvoid engr_ink(int pal, out vec3 ink, out vec3 acc) {\n  if (pal == 1) { ink = vec3(1.0, 0.8, 0.38); acc = vec3(1.0, 0.5, 0.18); }\n  else if (pal == 2) { ink = vec3(0.25, 0.95, 1.0); acc = vec3(0.78, 0.4, 1.0); }\n  else { ink = vec3(0.45, 0.88, 0.55); acc = vec3(0.86, 1.0, 0.6); }\n}\nfloat engr_line(float d, float hw, float px) { return 1.0 - smoothstep(hw, hw + px, d); }\n\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  int pal = int(float(uPalette) + 0.5);\n  vec3 cBase; vec3 cHi; vec3 cGlow;\n  floraPal(pal, cBase, cHi, cGlow);\n  cBase *= uTint.rgb; cHi *= uTint.rgb; cGlow *= uTint.rgb;\n  float px = 1.0 / RENDERSIZE.y;\n  // hold at the top of the tri LFO (a legible finished logo instead of a scrub)\n  float g = growthCurve(holdRamp(clamp(uGrowth / 100.0, 0.0, 1.0), 0.03, 0.78), int(float(uGrowthCurve) + 0.5));\n  float kick = kickN();\n  float hi = clamp(uHigh * aud, 0.0, 1.5);\n  vec3 E = engr_sd(p, 0.05);\n  float sd = E.x;\n  vec2 outN = -E.yz;\n  vec4 lg = logoRGBA(p);\n  vec3 ink; vec3 acc;\n  engr_ink(pal, ink, acc);\n  ink *= uTint.rgb; acc *= uTint.rgb;\n  // light from the upper left: faces turned away engrave heavier (banknote line swell)\n  float shadow = clamp(0.5 - 0.6 * dot(outN, normalize(vec2(-0.55, 0.85))), 0.0, 1.0);\n  float sp = 0.1 / max(uLineDensity, 2.0);\n  float hw = max((0.0006 + 0.0022 * shadow * shadow) * uVineThickness * (1.0 + 0.7 * kick), 0.75 * px);\n  // contour hairlines: iso-distance bands inside, two fading echoes outside\n  // wind: the contour lines drift slowly outward from the core (a living guilloche)\n  float flow = t * uWindFreq * 0.25;\n  float dc = abs(fract(sd / sp + 0.5 - flow) - 0.5) * sp;\n  float depth = 1.55 * sp;\n  float cIn = 1.0 - smoothstep(depth - 0.3 * sp, depth + 0.05 * sp, -sd);\n  float cOut = 1.0 - smoothstep(0.6 * sp, 1.3 * sp, sd);\n  float contour = engr_line(dc, hw * (sd > 0.0 ? 0.7 : 1.0), px) * cIn * cOut;\n  // deep inside thick strokes: 45-degree hatch, cross-hatched where the stroke is in shadow\n  float hs = sp * 0.62;\n  float h1 = abs(fract((p.x + p.y) * 0.7071 / hs) - 0.5) * hs;\n  float h2 = abs(fract((p.x - p.y) * 0.7071 / hs) - 0.5) * hs;\n  float hReg = smoothstep(depth - 0.05 * sp, depth + 0.35 * sp, -sd);\n  float hatch = max(engr_line(h1, hw * 0.8, px), engr_line(h2, hw * 0.8, px) * smoothstep(0.4, 0.7, shadow)) * hReg;\n  float lines = max(contour, hatch);\n  // organic pen front sweeping left to right; the kick steps it forward\n  float sway = sin(t * uWindFreq * 6.2831853 + p.y * 7.0) * 0.045;\n  float fr = (p.x + 0.72) / 1.44 + 0.24 * (fbm(p * 3.0 + vec2(4.0, 4.0 + t * uWindFreq * 0.15)) - 0.5) + sway;\n  float drawP = g * 1.45 - 0.15;\n  float drawn = 1.0 - smoothstep(drawP - 0.005, drawP, fr);\n  // then a second pass of the same front floods the exact logo in under the engraving; lines retire at full growth\n  float fillP = (g - 0.82) / 0.15 * 1.3 - 0.15;\n  float fill = (1.0 - smoothstep(fillP - 0.06, fillP, fr)) * step(0.82, g);\n  fill = max(fill, smoothstep(0.985, 1.0, g));\n  float lineFade = 1.0 - smoothstep(0.9, 0.97, g);\n  float lum = dot(lg.rgb, vec3(0.299, 0.587, 0.114));\n  vec3 inkOn = mix(ink, ink * 0.25, fill * smoothstep(0.45, 0.8, lum));\n  float inkM = lines * drawn * lineFade;\n  vec3 col = lg.rgb * lg.a * fill;\n  float solid = lg.a * fill;\n  col += ink * 0.05 * lg.a * drawn * (1.0 - fill);\n  col = mix(col, inkOn, inkM);\n  solid = max(solid, inkM);\n  // pen tip\n  float tipG = exp(-abs(fr - drawP) * 90.0) * max(lines, 0.25 * smoothstep(0.3, 0.7, lg.a)) * (1.0 - fill) * step(0.01, g);\n  col += acc * tipG * 1.8;\n  solid = max(solid, tipG * 0.8);\n  // stipple in the engraved cast shadow (down-right); highs add dots\n  float cs = 0.0055;\n  vec2 cid = floor(p / cs);\n  vec3 hh = hash32(cid + 5.0);\n  vec2 cc = (cid + 0.5 + (hh.xy - 0.5) * 0.5) * cs;\n  // thresholded: the logo plate can carry a faint alpha floor, which would sprinkle dots over the whole frame\n  float castS = smoothstep(0.3, 0.7, logoP(cc + vec2(-0.02, 0.026))) * (1.0 - smoothstep(0.2, 0.5, logoP(cc)));\n  float dens = clamp(uSporeCount / 400.0, 0.0, 1.0) * 1.2 + 0.45 * hi;\n  float dotOn = hh.z < dens * castS ? 1.0 : 0.0;   // strict: step() lights cells whose hash is exactly 0\n  float dotR = max(0.0013 * (0.7 + 0.3 * uVineThickness), 1.2 * px);\n  float stip = engr_line(length(p - cc), dotR, px) * dotOn * drawn * lineFade;\n  col = mix(col, acc * 0.9, stip);\n  solid = max(solid, stip);\n  gl_FragColor = vjOut(col, solid);\n}\n"},{"id":"flora-watercolor","name":"Watercolor Wash Bloom","category":"flora","blurb":"A wet pigment wash blooms through the logo with pooled edges and paper granulation, then sharpens to the crisp lockup.","params":[{"name":"uGrowth","label":"Growth Progress","type":"float","default":100,"min":0,"max":100,"unit":"%","auto":{"on":true,"shape":"tri","rate":0.08,"lo":0,"hi":1},"hint":"Wash bloom: pigment spreads, then the wet edge tightens to the exact logo at 100 %."},{"name":"uGrowthCurve","label":"Growth Curve","type":"long","default":1,"values":[0,1,2,3],"labels":["Linear","Ease Out","Organic S","Elastic"]},{"name":"uVineThickness","label":"Vine Thickness","type":"float","default":1,"min":0.2,"max":3,"hint":"Width of the darker pooled wet edge."},{"name":"uWindFreq","label":"Wind Flutter","type":"float","default":0.6,"min":0,"max":4,"unit":"Hz","hint":"Pigment flow speed inside the wash."},{"name":"uSporeCount","label":"Spore Particles","type":"float","default":120,"min":0,"max":400,"hint":"Drops: spatter around the mark, blossoms (pale centre, dark ring) where they land in the wet wash."},{"name":"uPalette","label":"Color Palette","type":"long","default":0,"values":[0,1,2],"labels":["Chlorophyll Green","Autumnal Gold","Bioluminescent Neon"],"hint":"Pigment set: sap green, burnt sienna, ultramarine/magenta."},{"name":"uTint","label":"Brand Tint","type":"color","default":[1,1,1,1],"hint":"Multiplies the palette so a sponsor can match its own green / gold."},{"name":"uPaperGrain","label":"Paper Grain","type":"float","default":0.35,"min":0,"max":1,"hint":"Granulation: pigment settling into the paper tooth."},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Ultramarine Ink","values":{"uPalette":2,"uVineThickness":1.8,"uWindFreq":1.2}},{"name":"Sienna Bloom","values":{"uPalette":1,"uPaperGrain":0.7,"uSporeCount":200}},{"name":"Sap Green Wash","values":{}}],"source":"/*{\n  \"DESCRIPTION\": \"Watercolor Wash Bloom \u00e2\u20ac\u201d A wet pigment wash blooms through the logo with pooled edges and paper granulation, then sharpens to the crisp lockup.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Botanical & Flora\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uGrowth\",\"TYPE\":\"float\",\"LABEL\":\"Growth Progress\",\"DEFAULT\":100,\"MIN\":0,\"MAX\":100},\n    {\"NAME\":\"uGrowthCurve\",\"TYPE\":\"long\",\"LABEL\":\"Growth Curve\",\"DEFAULT\":1,\"VALUES\":[0,1,2,3],\"LABELS\":[\"Linear\",\"Ease Out\",\"Organic S\",\"Elastic\"]},\n    {\"NAME\":\"uVineThickness\",\"TYPE\":\"float\",\"LABEL\":\"Vine Thickness\",\"DEFAULT\":1,\"MIN\":0.2,\"MAX\":3},\n    {\"NAME\":\"uWindFreq\",\"TYPE\":\"float\",\"LABEL\":\"Wind Flutter\",\"DEFAULT\":0.6,\"MIN\":0,\"MAX\":4},\n    {\"NAME\":\"uSporeCount\",\"TYPE\":\"float\",\"LABEL\":\"Spore Particles\",\"DEFAULT\":120,\"MIN\":0,\"MAX\":400},\n    {\"NAME\":\"uPalette\",\"TYPE\":\"long\",\"LABEL\":\"Color Palette\",\"DEFAULT\":0,\"VALUES\":[0,1,2],\"LABELS\":[\"Chlorophyll Green\",\"Autumnal Gold\",\"Bioluminescent Neon\"]},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Brand Tint\",\"DEFAULT\":[1,1,1,1]},\n    {\"NAME\":\"uPaperGrain\",\"TYPE\":\"float\",\"LABEL\":\"Paper Grain\",\"DEFAULT\":0.35,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Watercolor Wash Bloom \u00c2\u00b7 Botanical & Flora\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nfloat vnoise(vec2 p) {\n  vec2 i = floor(p); vec2 f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x), mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nfloat fbm(vec2 p) {\n  float a = 0.5; float s = 0.0;\n  for (int i = 0; i < 5; i++) { s += a * vnoise(p); p = p * 2.03 + vec2(17.1, 9.2); a *= 0.5; }\n  return s / 0.96875;\n}\n\n// 3-octave fbm: cheaper sibling of fbm() for nested domain warps.\nfloat fbm3(vec2 p) {\n  float a = 0.5; float s = 0.0;\n  for (int i = 0; i < 3; i++) { s += a * vnoise(p); p = p * 2.03 + vec2(17.1, 9.2); a *= 0.5; }\n  return s / 0.875;\n}\n\n// Inigo Quilez double domain warp (iquilezles.org/articles/warp). Returns the warped field; q, r = intermediates for colouring.\nfloat warp2(vec2 p, out vec2 q, out vec2 r) {\n  q = vec2(fbm3(p), fbm3(p + vec2(5.2, 1.3)));\n  r = vec2(fbm3(p + 4.0 * q + vec2(1.7, 9.2)), fbm3(p + 4.0 * q + vec2(8.3, 2.8)));\n  return fbm3(p + 4.0 * r);\n}\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// 25-tap disk coverage of the logo around p (radius r, height-normalized units).\n// x = coverage 0..1 (0.5 on the outline), yz = vector pointing into the logo.\nvec3 logoField(vec2 p, float r) {\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n// Approximate signed distance (positive outside) from a logoField sample of radius r.\nfloat fieldSD(vec3 f, float r) { return (0.5 - f.x) * 2.0 * r; }\n// Edge glow that falls to exactly zero at the field radius r (no full-frame haze floor).\nfloat edgeGlow(float sd, float k, float r) { float f = exp(-r * k); return max(exp(-abs(sd) * k) - f, 0.0) / (1.0 - f); }\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\nfloat logoCov5(vec2 p, float r) {\n  return (logoP(p) + logoP(p + vec2(r, 0.0)) + logoP(p - vec2(r, 0.0)) + logoP(p + vec2(0.0, r)) + logoP(p - vec2(0.0, r))) * 0.2;\n}\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\nvoid floraPal(int pal, out vec3 base, out vec3 hi, out vec3 glow) {\n  if (pal == 1) { base = vec3(0.42, 0.2, 0.04); hi = vec3(1.0, 0.7, 0.16); glow = vec3(1.0, 0.42, 0.08); }\n  else if (pal == 2) { base = vec3(0.0, 0.22, 0.3); hi = vec3(0.1, 1.0, 0.82); glow = vec3(0.65, 0.25, 1.0); }\n  else { base = vec3(0.06, 0.24, 0.07); hi = vec3(0.42, 0.78, 0.26); glow = vec3(0.7, 0.95, 0.4); }\n}\n\nfloat growthCurve(float g, int curve) {\n  if (curve == 1) return 1.0 - (1.0 - g) * (1.0 - g);\n  if (curve == 2) return g * g * (3.0 - 2.0 * g);\n  if (curve == 3) return clamp(1.0 - exp(-6.0 * g) * cos(10.0 * g), 0.0, 1.0);\n  return g;\n}\n\n// ---- effect ----\n// wet map from a smooth signed distance (logoField + march/bisection along the normal, 39 taps).\n// A 12-tap Vogel disc was tried first: its per-pixel rotation turned the wash edge into a ragged sponge at 3-6 px.\nfloat wc_sd(vec2 p, float R) {\n  vec3 F = logoField(p, R);\n  float sd0 = fieldSD(F, R);\n  if (abs(sd0) > R * 0.96) return sd0;\n  vec2 n = length(F.yz) > 0.0001 ? normalize(F.yz) : vec2(0.0, 1.0);\n  bool inside = logoP(p) > 0.5;\n  vec2 dir = inside ? -n : n;\n  // march to the FIRST crossing along the normal (an endpoint test lands in the next letter), then bisect;\n  // no crossing at all (normal misses the ink between letters) keeps the coarse estimate\n  float lo = 0.0; float hi = -1.0;\n  for (int i = 1; i <= 8; i++) {\n    float st = R * float(i) * 0.125;\n    if (hi < 0.0) { if ((logoP(p + dir * st) > 0.5) != inside) hi = st; else lo = st; }\n  }\n  if (hi < 0.0) return sd0;\n  for (int i = 0; i < 5; i++) {\n    float mid = 0.5 * (lo + hi);\n    if ((logoP(p + dir * mid) > 0.5) != inside) hi = mid; else lo = mid;\n  }\n  // stay consistent with the coarse field: a missed thin feature must not make sd jump\n  float d = clamp(0.5 * (lo + hi), abs(sd0) - 0.02, abs(sd0) + 0.02);\n  return inside ? -d : d;\n}\nvoid wc_pig(int pal, out vec3 a, out vec3 b, out vec3 c) {\n  if (pal == 1) { a = vec3(0.95, 0.42, 0.16); b = vec3(1.0, 0.72, 0.3); c = vec3(0.7, 0.16, 0.12); }\n  else if (pal == 2) { a = vec3(0.2, 0.36, 1.0); b = vec3(0.2, 0.85, 1.0); c = vec3(0.95, 0.25, 0.8); }\n  else { a = vec3(0.3, 0.86, 0.42); b = vec3(0.82, 0.96, 0.3); c = vec3(0.08, 0.6, 0.6); }\n}\n\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  int pal = int(float(uPalette) + 0.5);\n  vec3 cBase; vec3 cHi; vec3 cGlow;\n  floraPal(pal, cBase, cHi, cGlow);\n  cBase *= uTint.rgb; cHi *= uTint.rgb; cGlow *= uTint.rgb;\n  float px = 1.0 / RENDERSIZE.y;\n  // hold at the top of the tri LFO (a legible finished logo instead of a scrub)\n  float g = growthCurve(holdRamp(clamp(uGrowth / 100.0, 0.0, 1.0), 0.03, 0.78), int(float(uGrowthCurve) + 0.5));\n  float kick = kickN();\n  vec4 lg = logoRGBA(p);\n  // timeline: bloom (thr falls) -> wash holds -> wet edge tightens to the exact lockup\n  float rest = smoothstep(0.9, 1.0, g);\n  float sd = wc_sd(p, 0.06);\n  // wet map = the logo alpha blurred over Rw (a ramp of the smooth distance); Rw -> 0 at rest\n  float Rw = (0.034 + 0.01 * kick) * (1.0 - rest) + 0.0005;\n  // hard reach limit: the wet map is exactly 0 by 0.055 from the ink, so no audio setting can paint the frame\n  float wet = clamp(0.5 - sd / (2.0 * Rw), 0.0, 1.0) * (1.0 - smoothstep(0.035, 0.055, sd));\n  vec2 q; vec2 r;\n  float flow = t * uWindFreq * 0.06;\n  float n = warp2(p * 3.4 + vec2(flow, flow * 0.35), q, r);\n  // front: wet + warped noise beats a threshold that falls with growth; bass injects bloom pulses\n  float thr = mix(1.2, 0.44, smoothstep(0.0, 0.6, g)) - 0.07 * kick * (1.0 - rest);\n  thr = mix(thr, 0.5, rest);\n  float F = wet + (n - 0.5) * 0.34 * (1.0 - rest);\n  float soft = mix(0.018, 0.003, rest);\n  float paint = smoothstep(thr - soft, thr + soft, F);\n  // pooled wet edge = difference of two thresholds (pigment carried to the rim as the wash dries)\n  float wE = 0.14 * uVineThickness;\n  float ridge = smoothstep(thr - 0.01, thr + 0.01, F) * (1.0 - smoothstep(thr + wE * 0.35, thr + wE, F));\n  // backrun blooms: lighter pools inside the wash with a soft darker margin (cauliflower edge)\n  float inner = smoothstep(thr + 0.08, thr + 0.25, F);\n  float bloomL = smoothstep(0.5, 0.62, r.x) * inner;\n  float backrun = (smoothstep(0.44, 0.52, r.x) - smoothstep(0.52, 0.6, r.x)) * inner;\n  // drops (uSporeCount): outside the wash they are spatter; inside the wet wash they become blossoms\n  // (pigment pushed out to a darker ring around a paler centre). Gone at rest.\n  float near = smoothstep(0.0, 0.25, logoCov5(p, 0.085));\n  float cs = 0.022;\n  vec2 cid = floor(p / cs);\n  vec3 hh = hash32(cid + 3.0);\n  vec2 cc = (cid + 0.5 + (hh.xy - 0.5) * 0.5) * cs;\n  float rad = 0.0024 + 0.008 * hh.x * hh.x * hh.x;\n  float dd = length(p - cc);\n  float dropOn = (hh.z < clamp(uSporeCount / 400.0, 0.0, 1.0) * 0.95 ? 1.0 : 0.0) * step(0.1 + 0.5 * hh.y, g) * (1.0 - rest) * near;\n  // blossoms live on their own coarser grid, radius and jitter kept inside the cell (no clipped squares)\n  float bcs = 0.09;\n  vec2 bid = floor(p / bcs);\n  vec3 bh = hash32(bid + 41.0);\n  float bR = bcs * (0.22 + 0.18 * bh.x);\n  vec2 bc = (bid + 0.5) * bcs + (bh.yz - 0.5) * (bcs - 2.0 * bR);\n  float bD = length(p - bc) / bR;\n  float bOn = (hash12(bid + 9.0) < clamp(uSporeCount / 400.0, 0.0, 1.0) * 0.8 ? 1.0 : 0.0) * step(0.15 + 0.4 * bh.y, g) * (1.0 - rest);\n  float bEdge = bD + 0.3 * (vnoise(p * 45.0 + bh.xy * 9.0) - 0.5) + 0.2 * (vnoise(p * 150.0) - 0.5);   // cauliflower edge\n  float blossom = bOn * paint * (1.0 - smoothstep(0.85, 1.0, bEdge));\n  float bRing = blossom * smoothstep(0.62, 0.9, bEdge);\n  // granulation: pigment settling into the paper tooth (two octaves, not pixel noise)\n  mat2 gr = mat2(0.8, 0.6, -0.6, 0.8);\n  float grain = vnoise(gr * p * 100.0) * 0.45 + vnoise(p * 38.0 + 7.0) * 0.35 + vnoise(gr * gr * p * 220.0 + 3.0) * 0.2;\n  float gran = (grain - 0.5) * uPaperGrain * (1.0 + 0.8 * kick);\n  vec3 pA; vec3 pB; vec3 pC;\n  wc_pig(pal, pA, pB, pC);\n  vec3 pig = mix(pA, pB, smoothstep(0.3, 0.7, q.x));\n  pig = mix(pig, pC, smoothstep(0.5, 0.85, r.y) * 0.55);\n  pig *= uTint.rgb;\n  // the pigment keeps the logo's own hue where there is ink, so the brand colours survive the wash\n  pig = mix(pig, lg.rgb * (0.5 + 0.5 * pig), lg.a * 0.6);\n  // luminous interior. On a dark backdrop diluted pigment must read LIGHTER (towards a pale tint), not more\n  // transparent: lower alpha would read as a dark hole.\n  float body = clamp(0.8 + 0.15 * (q.y - 0.5) + gran * 0.8, 0.35, 0.97);\n  float dilute = clamp(0.35 * bloomL + 0.7 * (blossom - bRing), 0.0, 1.0);\n  vec3 interior = mix(pig * (1.0 + 1.25 * gran), mix(pig, vec3(1.0), 0.5), dilute);\n  // pooled rim, backruns and blossom rings: denser, darker pigment, fully opaque\n  float pool = clamp(ridge * (0.85 + 0.3 * gran) + backrun * 0.3 + bRing * 0.7, 0.0, 1.0);\n  vec3 pooled = pig * pig * 0.55;\n  vec3 wcol = mix(interior, pooled, pool);\n  float wa = paint * mix(body, 1.0, pool);\n  vec3 wash = wcol * wa;\n  // spatter outside the wash\n  float drop = (1.0 - smoothstep(rad - 0.0009, rad, dd)) * dropOn * (1.0 - paint);\n  float dropRim = smoothstep(rad * 0.4, rad, dd);\n  vec3 dropC = mix(mix(pA, pB, hh.y), pig * pig * 0.55, dropRim * 0.7);\n  float dropA = drop * (0.78 + 0.22 * dropRim);\n  wash = mix(wash, dropC * dropA, drop);\n  wa = max(wa, dropA);\n  // the wash settles into the exact lockup\n  vec3 col = mix(wash, lg.rgb * lg.a, rest);\n  float solid = mix(wa, lg.a, rest);\n  gl_FragColor = vjOut(col, solid);\n}\n"},{"id":"flora-circuit","name":"Truchet Circuit Vine","category":"flora","blurb":"A quarter-arc Truchet weave grows through the letterforms like a living circuit board, with pulsing traces and node pads.","params":[{"name":"uGrowth","label":"Growth Progress","type":"float","default":100,"min":0,"max":100,"unit":"%","auto":{"on":true,"shape":"tri","rate":0.08,"lo":0,"hi":1},"hint":"Signal front: traces snake in cell by cell, then the logo colours come up under them."},{"name":"uGrowthCurve","label":"Growth Curve","type":"long","default":1,"values":[0,1,2,3],"labels":["Linear","Ease Out","Organic S","Elastic"]},{"name":"uVineThickness","label":"Vine Thickness","type":"float","default":1,"min":0.2,"max":3,"hint":"Trace width."},{"name":"uWindFreq","label":"Wind Flutter","type":"float","default":0.6,"min":0,"max":4,"unit":"Hz","hint":"Re-wiring rate: a fraction of tiles flips (crossfaded) at this rate; also the current pulse speed."},{"name":"uSporeCount","label":"Spore Particles","type":"float","default":120,"min":0,"max":400,"hint":"Node pad density at the trace junctions."},{"name":"uPalette","label":"Color Palette","type":"long","default":0,"values":[0,1,2],"labels":["Chlorophyll Green","Autumnal Gold","Bioluminescent Neon"]},{"name":"uTint","label":"Brand Tint","type":"color","default":[1,1,1,1],"hint":"Multiplies the palette so a sponsor can match its own green / gold."},{"name":"uCellCount","label":"Cell Count","type":"float","default":40,"min":16,"max":64,"hint":"Truchet cells per frame height."},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Gold Trace Calm","values":{"uPalette":1,"uWindFreq":0.25,"uAudioReact":0.5,"uSporeCount":80}},{"name":"Bioluminescent Board","values":{"uPalette":2,"uSporeCount":110,"uWindFreq":1.2,"uAudioReact":1.4}},{"name":"Green PCB","values":{"uPalette":0,"uCellCount":46,"uSporeCount":170}}],"source":"/*{\n  \"DESCRIPTION\": \"Truchet Circuit Vine \u00e2\u20ac\u201d A quarter-arc Truchet weave grows through the letterforms like a living circuit board, with pulsing traces and node pads.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Botanical & Flora\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uGrowth\",\"TYPE\":\"float\",\"LABEL\":\"Growth Progress\",\"DEFAULT\":100,\"MIN\":0,\"MAX\":100},\n    {\"NAME\":\"uGrowthCurve\",\"TYPE\":\"long\",\"LABEL\":\"Growth Curve\",\"DEFAULT\":1,\"VALUES\":[0,1,2,3],\"LABELS\":[\"Linear\",\"Ease Out\",\"Organic S\",\"Elastic\"]},\n    {\"NAME\":\"uVineThickness\",\"TYPE\":\"float\",\"LABEL\":\"Vine Thickness\",\"DEFAULT\":1,\"MIN\":0.2,\"MAX\":3},\n    {\"NAME\":\"uWindFreq\",\"TYPE\":\"float\",\"LABEL\":\"Wind Flutter\",\"DEFAULT\":0.6,\"MIN\":0,\"MAX\":4},\n    {\"NAME\":\"uSporeCount\",\"TYPE\":\"float\",\"LABEL\":\"Spore Particles\",\"DEFAULT\":120,\"MIN\":0,\"MAX\":400},\n    {\"NAME\":\"uPalette\",\"TYPE\":\"long\",\"LABEL\":\"Color Palette\",\"DEFAULT\":0,\"VALUES\":[0,1,2],\"LABELS\":[\"Chlorophyll Green\",\"Autumnal Gold\",\"Bioluminescent Neon\"]},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Brand Tint\",\"DEFAULT\":[1,1,1,1]},\n    {\"NAME\":\"uCellCount\",\"TYPE\":\"float\",\"LABEL\":\"Cell Count\",\"DEFAULT\":40,\"MIN\":16,\"MAX\":64},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Truchet Circuit Vine \u00c2\u00b7 Botanical & Flora\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nfloat vnoise(vec2 p) {\n  vec2 i = floor(p); vec2 f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x), mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\nfloat logoCov5(vec2 p, float r) {\n  return (logoP(p) + logoP(p + vec2(r, 0.0)) + logoP(p - vec2(r, 0.0)) + logoP(p + vec2(0.0, r)) + logoP(p - vec2(0.0, r))) * 0.2;\n}\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\nvoid floraPal(int pal, out vec3 base, out vec3 hi, out vec3 glow) {\n  if (pal == 1) { base = vec3(0.42, 0.2, 0.04); hi = vec3(1.0, 0.7, 0.16); glow = vec3(1.0, 0.42, 0.08); }\n  else if (pal == 2) { base = vec3(0.0, 0.22, 0.3); hi = vec3(0.1, 1.0, 0.82); glow = vec3(0.65, 0.25, 1.0); }\n  else { base = vec3(0.06, 0.24, 0.07); hi = vec3(0.42, 0.78, 0.26); glow = vec3(0.7, 0.95, 0.4); }\n}\n\nfloat growthCurve(float g, int curve) {\n  if (curve == 1) return 1.0 - (1.0 - g) * (1.0 - g);\n  if (curve == 2) return g * g * (3.0 - 2.0 * g);\n  if (curve == 3) return clamp(1.0 - exp(-6.0 * g) * cos(10.0 * g), 0.0, 1.0);\n  return g;\n}\n\n// ---- effect ----\n// quarter-arc Truchet cell: x = distance to the nearer arc (cell units), y = position along that arc (0..1)\nvec2 circ_arc(vec2 f) {\n  float d1 = abs(length(f) - 0.5);\n  vec2 f2 = 1.0 - f;\n  float d2 = abs(length(f2) - 0.5);\n  float s1 = atan(f.y, f.x + 0.00001) / 1.5707963;\n  float s2 = atan(f2.y, f2.x + 0.00001) / 1.5707963;\n  return d1 < d2 ? vec2(d1, s1) : vec2(d2, s2);\n}\nvoid circ_pal(int pal, out vec3 sub, out vec3 tr, out vec3 nd) {\n  if (pal == 1) { sub = vec3(0.13, 0.06, 0.015); tr = vec3(1.0, 0.74, 0.28); nd = vec3(1.0, 0.95, 0.75); }\n  else if (pal == 2) { sub = vec3(0.01, 0.045, 0.1); tr = vec3(0.1, 1.0, 0.85); nd = vec3(0.78, 0.38, 1.0); }\n  else { sub = vec3(0.02, 0.13, 0.05); tr = vec3(0.55, 1.0, 0.45); nd = vec3(1.0, 0.84, 0.35); }\n}\n\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  int pal = int(float(uPalette) + 0.5);\n  vec3 cBase; vec3 cHi; vec3 cGlow;\n  floraPal(pal, cBase, cHi, cGlow);\n  cBase *= uTint.rgb; cHi *= uTint.rgb; cGlow *= uTint.rgb;\n  float px = 1.0 / RENDERSIZE.y;\n  // hold at the top of the tri LFO (a legible finished logo instead of a scrub)\n  float g = growthCurve(holdRamp(clamp(uGrowth / 100.0, 0.0, 1.0), 0.03, 0.78), int(float(uGrowthCurve) + 0.5));\n  float kick = kickN();\n  float hi = clamp(uHigh * aud, 0.0, 1.5);\n  vec4 lg = logoRGBA(p);\n  float cov = logoCov5(p, 0.0045);\n  float mask = smoothstep(0.1, 0.5, cov);\n  float rim = 1.0 - abs(2.0 * cov - 1.0);\n  vec3 subC; vec3 trC; vec3 ndC;\n  circ_pal(pal, subC, trC, ndC);\n  subC *= uTint.rgb; trC *= uTint.rgb; ndC *= uTint.rgb;\n  float cells = uCellCount;\n  vec2 cp = p * cells + vec2(0.37, 0.11);\n  vec2 id = floor(cp);\n  vec2 f = fract(cp);\n  float h0 = hash12(id + 7.13);\n  float base = step(0.5, h0);\n  // timed re-wiring: each epoch a random fraction of tiles is flipped; the bass flips more (topology on the kick)\n  float ep = t * uWindFreq * 0.5;\n  float e0 = floor(ep);\n  float xf = smoothstep(0.6, 1.0, fract(ep));\n  float fracF = clamp(0.34 + 0.45 * kick, 0.0, 0.9);\n  float fA = 1.0 - smoothstep(fracF - 0.05, fracF + 0.05, hash12(id + e0 * 17.31));\n  float fB = 1.0 - smoothstep(fracF - 0.05, fracF + 0.05, hash12(id + (e0 + 1.0) * 17.31));\n  float oA = mix(base, 1.0 - base, fA);\n  float oB = mix(base, 1.0 - base, fB);\n  float o = mix(oA, oB, xf);\n  float rewire = abs(oB - oA) * sin(3.14159265 * xf);   // a re-wired tile sparks while it crossfades\n  vec2 a0 = circ_arc(f);\n  vec2 a1 = circ_arc(vec2(1.0 - f.x, f.y));\n  // reveal: left-to-right signal front with per-cell jitter; arcs snake in along their own length\n  float order = 0.8 * clamp((id.x / cells + 0.78) / 1.56, 0.0, 1.0) + 0.2 * hash12(id * 1.37 + 3.1);\n  float grow = clamp((g * 1.3 - order) / 0.12, 0.0, 1.0);\n  float lw = 0.07 * uVineThickness;\n  float aaC = cells * 1.2 / RENDERSIZE.y;\n  float L0 = (1.0 - smoothstep(lw - aaC, lw + aaC, a0.x)) * smoothstep(a0.y - 0.04, a0.y, grow);\n  float L1 = (1.0 - smoothstep(lw - aaC, lw + aaC, a1.x)) * smoothstep(a1.y - 0.04, a1.y, grow);\n  float G0 = exp(-a0.x * a0.x / (lw * lw * 12.0)) * smoothstep(a0.y - 0.04, a0.y, grow);\n  float G1 = exp(-a1.x * a1.x / (lw * lw * 12.0)) * smoothstep(a1.y - 0.04, a1.y, grow);\n  float trace = mix(L0, L1, o) * mask;\n  float glow = mix(G0, G1, o) * mask;\n  float spark = max(G0, G1) * rewire * mask;\n  float sAl = o > 0.5 ? a1.y : a0.y;\n  float pp = fract(sAl * 0.5 + h0 - t * (0.4 + 0.6 * uWindFreq));\n  float pulse = smoothstep(0.55, 0.95, pp) * (1.0 - smoothstep(0.95, 1.0, pp)) * mix(L0, L1, o) * mask;\n  // node pads at the edge midpoints (shared by both neighbours, so the hash is keyed on the midpoint)\n  float dens = clamp(uSporeCount / 400.0, 0.0, 1.0);\n  float node = 0.0; float pad = 0.0;\n  for (int i = 0; i < 4; i++) {\n    float fi = float(i);\n    vec2 m = i == 0 ? vec2(0.5, 0.0) : i == 1 ? vec2(0.0, 0.5) : i == 2 ? vec2(1.0, 0.5) : vec2(0.5, 1.0);\n    vec2 key = id * 2.0 + m * 2.0;\n    if (hash12(key + 11.0) > dens) continue;\n    float ordN = 0.8 * clamp(((id.x + m.x) / cells + 0.78) / 1.56, 0.0, 1.0) + 0.2 * hash12(key * 0.71 + 5.3);\n    float on = smoothstep(0.0, 0.08, g * 1.3 - ordN - 0.08);\n    float dn = length(f - m);\n    // via: copper annulus around a dark drill hole\n    pad = max(pad, (1.0 - smoothstep(0.2, 0.2 + aaC, dn)) * smoothstep(0.085, 0.085 + aaC, dn) * on);\n    node = max(node, (1.0 - smoothstep(0.085, 0.085 + aaC, dn)) * on);\n  }\n  pad *= mask; node *= mask;\n  // composite: the dark board grows in with the signal front, logo colours come up near full growth\n  float logoFill = smoothstep(0.9, 1.0, g);\n  // the hold is the exact logo: every board element fades out over the last 6%\n  float restK = 1.0 - smoothstep(0.94, 1.0, g);\n  trace *= restK; glow *= restK; spark *= restK; pulse *= restK; pad *= restK; node *= restK; rim *= restK;\n  float ordP = 0.62 * clamp((p.x + 0.78) / 1.56, 0.0, 1.0) + 0.38 * vnoise(p * cells * 0.35);\n  float subA = lg.a * smoothstep(ordP - 0.1, ordP + 0.05, g * 1.3);\n  vec3 sub = mix(subC + lg.rgb * 0.1, lg.rgb, logoFill);\n  vec3 col = sub * subA;\n  float solid = subA;\n  float lum = dot(lg.rgb, vec3(0.299, 0.587, 0.114));\n  vec3 tc = mix(trC, lg.rgb * 0.55, logoFill * smoothstep(0.5, 0.85, lum));\n  float tA = trace * (1.0 - 0.45 * logoFill);\n  col = mix(col, tc, tA);\n  col += mix(trC, vec3(1.0), 0.5) * spark * 0.9 * (1.0 - 0.6 * logoFill);\n  col += trC * glow * (0.35 + 0.4 * kick) * (1.0 - 0.7 * logoFill) + mix(trC, vec3(1.0), 0.7) * pulse * (1.3 + 0.8 * kick) * (1.0 - 0.5 * logoFill);\n  float rimOn = smoothstep(0.0, 0.3, g * 1.3 - 0.62 * clamp((p.x + 0.78) / 1.56, 0.0, 1.0));\n  col += trC * rim * rimOn * 0.45 * (1.0 - 0.6 * logoFill);\n  // pads: bright on the board, etched like the traces once the logo colours are up; highs light them\n  vec3 nc = mix(mix(ndC, vec3(1.0), 0.15) * (0.75 + 0.9 * hi), tc, logoFill * 0.75);\n  col = mix(col, nc, pad * (1.0 - 0.3 * logoFill));\n  col = mix(col, subC * 0.4, node * (1.0 - logoFill));   // drill hole\n  col += ndC * (pad + node * 0.6) * hi * 0.5;\n  solid = max(solid, max(max(tA, max(glow, spark) * 0.5), max(pad, node)));\n  solid = max(solid, rim * rimOn * 0.45);\n  gl_FragColor = vjOut(col, solid);\n}\n"},{"id":"fluid-vortex","name":"GPU Compute Particle Vortex","category":"fluid","blurb":"Sparks erode off the logo edges and spiral out on log-polar orbits through a swirling haze; bass breathes the gravity well.","params":[{"name":"uTurbScale","label":"Turbulence Noise Scale","type":"float","default":3,"min":0.5,"max":12},{"name":"uLifespan","label":"Particle Lifespan","type":"float","default":1.8,"min":0.2,"max":6,"unit":"s"},{"name":"uBounce","label":"Collision Bounce","type":"float","default":0.4,"min":0,"max":1,"hint":"How hard particles are deflected around the logo silhouette."},{"name":"uDamping","label":"Velocity Damping","type":"float","default":0.35,"min":0,"max":1},{"name":"uGravityWell","label":"Audio Gravity Well","type":"float","default":0.6,"min":0,"max":2},{"name":"uTint","label":"Particle Tint","type":"color","default":[0.2,0.75,1,1]},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Ion Storm","values":{}},{"name":"Solar Flare","values":{"uTint":[1,0.45,0.1,1],"uLifespan":2.6,"uDamping":0.1}},{"name":"Tight Orbit","values":{"uDamping":0.8,"uTurbScale":6,"uLifespan":1.1}}],"source":"/*{\n  \"DESCRIPTION\": \"GPU Compute Particle Vortex \u00e2\u20ac\u201d Sparks erode off the logo edges and spiral out on log-polar orbits through a swirling haze; bass breathes the gravity well.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Particle & Fluid\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uTurbScale\",\"TYPE\":\"float\",\"LABEL\":\"Turbulence Noise Scale\",\"DEFAULT\":3,\"MIN\":0.5,\"MAX\":12},\n    {\"NAME\":\"uLifespan\",\"TYPE\":\"float\",\"LABEL\":\"Particle Lifespan\",\"DEFAULT\":1.8,\"MIN\":0.2,\"MAX\":6},\n    {\"NAME\":\"uBounce\",\"TYPE\":\"float\",\"LABEL\":\"Collision Bounce\",\"DEFAULT\":0.4,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uDamping\",\"TYPE\":\"float\",\"LABEL\":\"Velocity Damping\",\"DEFAULT\":0.35,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uGravityWell\",\"TYPE\":\"float\",\"LABEL\":\"Audio Gravity Well\",\"DEFAULT\":0.6,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Particle Tint\",\"DEFAULT\":[0.2,0.75,1,1]},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// GPU Compute Particle Vortex \u00c2\u00b7 Particle & Fluid\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nfloat vnoise(vec2 p) {\n  vec2 i = floor(p); vec2 f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x), mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nfloat fbm(vec2 p) {\n  float a = 0.5; float s = 0.0;\n  for (int i = 0; i < 5; i++) { s += a * vnoise(p); p = p * 2.03 + vec2(17.1, 9.2); a *= 0.5; }\n  return s / 0.96875;\n}\n\nvec2 curl2(vec2 p) {\n  float e = 0.05;\n  float a = vnoise(p + vec2(0.0, e)); float b = vnoise(p - vec2(0.0, e));\n  float c = vnoise(p + vec2(e, 0.0)); float d = vnoise(p - vec2(e, 0.0));\n  return vec2(a - b, -(c - d)) / (2.0 * e);\n}\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// 25-tap disk coverage of the logo around p (radius r, height-normalized units).\n// x = coverage 0..1 (0.5 on the outline), yz = vector pointing into the logo.\nvec3 logoField(vec2 p, float r) {\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n// Approximate signed distance (positive outside) from a logoField sample of radius r.\nfloat fieldSD(vec3 f, float r) { return (0.5 - f.x) * 2.0 * r; }\n// Edge glow that falls to exactly zero at the field radius r (no full-frame haze floor).\nfloat edgeGlow(float sd, float k, float r) { float f = exp(-r * k); return max(exp(-abs(sd) * k) - f, 0.0) / (1.0 - f); }\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\n// ---- effect ----\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  float kick = kickN();\n  float la = logoP(p);\n  vec3 lcol = IMG_NORM_PIXEL(inputImage, uv).rgb;\n  vec3 F = logoField(p, 0.035);\n  vec2 nrm = length(F.yz) > 0.0001 ? normalize(F.yz) : vec2(0.0);\n  float sd = fieldSD(F, 0.035);\n  vec2 pp = p - nrm * uBounce * 0.06 * exp(-abs(sd) * 40.0);\n  float well = 1.0 + uGravityWell * (0.1 + 0.45 * kick);\n  pp *= well;\n  pp += curl2(pp * uTurbScale + t * 0.15) * 0.0045;\n  float r = max(length(pp), 0.001);\n  float u = log(r);\n  float v = atan(pp.y, pp.x) / 6.2831853;\n  float life = max(uLifespan, 0.2);\n  float omega = 0.24 * (1.0 - 0.7 * uDamping);\n  float outward = 0.3;\n  // macro arc: the shed density breathes over ~15 s and a kick fires a denser ring\n  float breathe = 0.5 + 0.5 * sin(t * 0.4);\n  float density = 0.5 + 0.3 * breathe + 0.2 * kick;\n  float core = smoothstep(0.02, 0.09, r);\n  float px = 1.2 / RENDERSIZE.y;\n  vec3 acc = vec3(0.0);\n  for (int k = 0; k < 6; k++) {\n    float fk = float(k);\n    float depth = fk / 5.0;\n    float rows = 60.0 + fk * 19.0;\n    float du = 0.045 + 0.01 * fk;\n    float sp = 0.8 + 0.12 * fk;\n    float sw = 1.0 + 0.18 * fk;\n    vec2 q = vec2(u - outward * t * sp, v - omega * t * sw + u * 0.25);\n    vec2 cell = floor(vec2(q.x / du, q.y * rows));\n    vec2 f = vec2(fract(q.x / du), fract(q.y * rows)) - 0.5;\n    vec3 h = hash32(cell + fk * 91.0);\n    if (h.z > density) continue;\n    float age = fract((t + h.x * life) / life) * life;\n    vec2 fo = (hash22(cell + 7.0 + fk) - 0.5) * 0.35;\n    vec2 cq = vec2((cell.x + 0.5 + fo.x) * du, (cell.y + 0.5 + fo.y) / rows);\n    float ub = cq.x + outward * (t - age) * sp;\n    float vb = cq.y + omega * (t - age) * sw - ub * 0.25;\n    vec2 pb = exp(ub) * vec2(cos(vb * 6.2831853), sin(vb * 6.2831853)) / well;\n    if (logoP(pb) < 0.5) continue;\n    float fade = (1.0 - age / life) * smoothstep(0.0, 0.08, age);\n    vec2 dl = f - fo;\n    vec2 ds = vec2(dl.x * du * r, dl.y / rows * 6.2831853 * r);\n    // depth: far layers are larger, softer, dimmer dots; near layers small, sharp and long-streaked\n    float streak = 1.0 + 5.0 * (1.0 - uDamping) * mix(0.4, 1.0, depth);\n    float sz0 = (0.0022 + 0.0016 * h.y) * mix(1.8, 1.0, depth);\n    float sz = max(sz0, px);\n    float d2 = ds.x * ds.x + ds.y * ds.y / (streak * streak);\n    float ageN = age / life;\n    vec3 pc = mix(vec3(1.0, 0.95, 0.85), mix(uTint.rgb, mix(uTint.rgb, vec3(1.0), 0.5), smoothstep(0.15, 0.6, r)), smoothstep(0.0, 0.5, ageN));\n    float e = (exp(-d2 / (sz * sz)) * 1.6 + exp(-d2 / (sz * sz * 12.0)) * 0.25) * (sz0 * sz0) / (sz * sz);\n    acc += pc * e * fade * mix(0.45, 1.0, depth) * core;\n  }\n  float near = logoField(p, 0.22).x;\n  float haze = fbm(vec2(u * 3.0 - t * 0.5, (v + u * 0.25 - t * omega) * 6.0) + 3.0);\n  float hazeMask = smoothstep(0.02, 0.45, near) * (1.0 - la);\n  vec3 col = uTint.rgb * pow(haze, 3.0) * hazeMask * (0.6 + 1.0 * kick) * 1.3;\n  // accretion glow fills the spiral's eye instead of a dark pupil\n  col += uTint.rgb * exp(-r * r / 0.004) * (0.25 + 0.8 * kick) * (1.0 - la);\n  col += acc * (1.0 - la * 0.85);\n  float band = edgeGlow(sd, 260.0, 0.035);\n  float erode = smoothstep(0.55, 0.8, vnoise(p * 90.0 + vec2(t * 3.0, 0.0))) * band;\n  col = mix(col, lcol, la * (1.0 - erode * 0.7));\n  col += uTint.rgb * edgeGlow(sd, 70.0, 0.035) * (0.6 + 1.2 * uHigh * aud);\n  gl_FragColor = vjOut(col, la);\n}\n"},{"id":"fluid-mercury","name":"Liquid Mercury Melt & Dissolve","category":"fluid","blurb":"The logo turns to liquid chrome: tapered rivulets hang from every stroke, bulb and shed beads, then pull back up.","params":[{"name":"uMelt","label":"Melt Amount","type":"float","default":0.45,"min":0,"max":1,"auto":{"on":true,"shape":"tri","rate":0.07,"lo":0,"hi":1},"hint":"How far the drips hang. Under ~0.35 the mark stays sponsor-safe."},{"name":"uTurbScale","label":"Drip Variation","type":"float","default":3,"min":0.5,"max":12,"hint":"Noise scale for which columns drip longest."},{"name":"uLifespan","label":"Bead Interval","type":"float","default":1.8,"min":0.2,"max":6,"unit":"s","hint":"Seconds between beads falling from each drip."},{"name":"uBounce","label":"Surface Tension","type":"float","default":0.4,"min":0,"max":1,"hint":"Capillary wave that moves the silhouette."},{"name":"uDamping","label":"Viscosity","type":"float","default":0.35,"min":0,"max":1,"hint":"Higher = shorter, stiller drips."},{"name":"uGravityWell","label":"Bass Melt","type":"float","default":0.6,"min":0,"max":2,"hint":"Kick adds melt."},{"name":"uTint","label":"Metal Tint","type":"color","default":[0.85,0.9,1,1]},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Quicksilver","values":{}},{"name":"Molten Gold","values":{"uTint":[1,0.75,0.3,1],"uTurbScale":2}},{"name":"Sponsor Sag","values":{"uMelt":0.3,"uDamping":0.5,"uBounce":0.2},"auto":{"uMelt":{"hi":0.35}}}],"source":"/*{\n  \"DESCRIPTION\": \"Liquid Mercury Melt & Dissolve \u00e2\u20ac\u201d The logo turns to liquid chrome: tapered rivulets hang from every stroke, bulb and shed beads, then pull back up.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Particle & Fluid\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uMelt\",\"TYPE\":\"float\",\"LABEL\":\"Melt Amount\",\"DEFAULT\":0.45,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uTurbScale\",\"TYPE\":\"float\",\"LABEL\":\"Drip Variation\",\"DEFAULT\":3,\"MIN\":0.5,\"MAX\":12},\n    {\"NAME\":\"uLifespan\",\"TYPE\":\"float\",\"LABEL\":\"Bead Interval\",\"DEFAULT\":1.8,\"MIN\":0.2,\"MAX\":6},\n    {\"NAME\":\"uBounce\",\"TYPE\":\"float\",\"LABEL\":\"Surface Tension\",\"DEFAULT\":0.4,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uDamping\",\"TYPE\":\"float\",\"LABEL\":\"Viscosity\",\"DEFAULT\":0.35,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uGravityWell\",\"TYPE\":\"float\",\"LABEL\":\"Bass Melt\",\"DEFAULT\":0.6,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Metal Tint\",\"DEFAULT\":[0.85,0.9,1,1]},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Liquid Mercury Melt & Dissolve \u00c2\u00b7 Particle & Fluid\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nfloat vnoise(vec2 p) {\n  vec2 i = floor(p); vec2 f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x), mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nmat2 rot2(float a) { float c = cos(a); float s = sin(a); return mat2(c, -s, s, c); }\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// 25-tap disk coverage of the logo around p (radius r, height-normalized units).\n// x = coverage 0..1 (0.5 on the outline), yz = vector pointing into the logo.\nvec3 logoField(vec2 p, float r) {\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n// Approximate signed distance (positive outside) from a logoField sample of radius r.\nfloat fieldSD(vec3 f, float r) { return (0.5 - f.x) * 2.0 * r; }\n// Edge glow that falls to exactly zero at the field radius r (no full-frame haze floor).\nfloat edgeGlow(float sd, float k, float r) { float f = exp(-r * k); return max(exp(-abs(sd) * k) - f, 0.0) / (1.0 - f); }\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\n// Procedural studio environment for chrome / glass / crystal: four off-axis strip lights at mixed elevations\n// (a flat face sees a horizon split instead of one value that flips dark/bright), energy-normalised roughness\n// (rougher = wider lobes, not brighter), top key, horizon line, dark floor. Peaks ~2.0; callers tonemap.\nvec3 studioEnv(vec3 d, float rough, float spin) {\n  d = normalize(d);\n  d.xz = rot2(spin) * d.xz;\n  float y = d.y;\n  float az = atan(d.x, d.z);\n  float k = mix(40.0, 3.0, rough);\n  float norm = (k + 1.0) / 41.0;\n  vec3 sky = mix(vec3(0.08, 0.09, 0.11), vec3(0.75, 0.8, 0.88), smoothstep(-0.1, 0.8, y));\n  float l1 = pow(max(cos(az - 0.3) * cos((y - 0.15) * 1.6), 0.0), k);\n  float l2 = pow(max(cos(az - 2.4) * cos((y - 0.35) * 1.6), 0.0), k * 0.7);\n  float l3 = pow(max(cos(az + 1.9) * cos((y + 0.05) * 1.6), 0.0), k * 1.3);\n  float l4 = pow(max(cos(az + 3.0) * cos((y - 0.5) * 1.6), 0.0), k * 0.5);\n  float strips = norm * (1.6 * l1 + 1.25 * l2 + 1.1 * l3 + 0.8 * l4);\n  float top = pow(max(y, 0.0), mix(24.0, 2.0, rough)) * mix(1.0, 0.35, rough);\n  float hor = exp(-abs(y) * mix(40.0, 6.0, rough));\n  vec3 col = sky * 0.5 + vec3(1.0, 0.98, 0.95) * strips * 1.5 + vec3(2.0, 1.9, 1.75) * top + vec3(0.7, 0.8, 0.95) * hor;\n  float ground = 1.0 - smoothstep(-0.25, 0.0, y);\n  return mix(col, vec3(0.025, 0.025, 0.03) + hor * 0.2, ground);\n}\n\n// ---- effect ----\n// Column-hang drips: the glyph body stays in place (the bolt and the ring survive); each narrow column below a\n// glyph grows a tapered chrome rivulet from the glyph's lowest pixel, bulbs at the tip and sheds a bead.\n// A capillary wave (Surface Tension) moves the silhouette; Viscosity shortens and stills the drips.\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  float kick = kickN();\n  float m = clamp(uMelt + uGravityWell * 0.45 * kick, 0.0, 1.0);\n  float colW = 0.012;\n  float cid = floor(p.x / colW);\n  float cx = (cid + 0.5) * colW;\n  float fx = (p.x - cx) / colW;\n  float n1 = vnoise(vec2(cx * uTurbScale * 2.0, 3.0));\n  float L = min(m * (0.05 + 0.3 * pow(0.6 * hash11(cid) + 0.4 * n1, 1.6)) * mix(1.0, 0.35, uDamping), 0.26);\n  // lowest glyph pixel in this column (12 taps, top to bottom)\n  float yb = 9.0;\n  for (int i = 0; i < 12; i++) {\n    float y = 0.17 - float(i) * 0.03;\n    if (logoP(vec2(cx, y)) > 0.5) yb = y;\n  }\n  float hasCol = step(yb, 8.0) * step(0.001, L);\n  // capillary wave on the body, surface tension ripple\n  float wob = 0.011 * sin(p.y * 120.0 - t * 5.0) * uBounce * (0.3 + m) + 0.003 * sin(p.y * 28.0 + t * 3.5 + n1 * 6.0) * (1.0 - uDamping) * m;\n  vec2 pb = vec2(p.x + wob, p.y);\n  float la = logoP(pb);\n  vec3 F = logoField(pb, 0.03);\n  vec3 Fw = logoField(pb, 0.06);\n  vec2 dir = length(F.yz) > 0.0001 ? normalize(F.yz) : vec2(0.0);\n  float slope = 4.0 * F.x * (1.0 - F.x);\n  vec3 n = normalize(vec3(-dir * slope * 2.2 - Fw.yz * 0.04, 1.0));\n  // rivulet below the glyph\n  float s0 = (yb - p.y) / max(L, 0.0001);\n  float bulb = smoothstep(0.7, 0.95, s0) * (1.0 - smoothstep(0.97, 1.0, s0));\n  float hw = 0.5 * (1.0 - 0.55 * s0) + 0.45 * bulb;\n  float sway = 0.004 * sin(s0 * L * 60.0 + t * 3.0 * (1.0 - uDamping)) / colW;\n  float rx = fx - sway;\n  float aaw = 1.2 / (RENDERSIZE.y * colW);\n  float riv = hasCol * step(0.0, s0) * step(s0, 1.0) * (1.0 - smoothstep(hw - aaw, hw + aaw, abs(rx)));\n  vec3 nr = normalize(vec3(rx / max(hw, 0.05) * 0.9, 0.3 * (1.0 - s0), 1.0));\n  float inside = max(la, riv);\n  n = normalize(mix(n, nr, riv * (1.0 - la)));\n  // bead falling from the tip\n  vec3 hc = hash32(vec2(cid, 9.0));\n  float life = max(uLifespan, 0.2);\n  float age = fract(t / life + hc.x) * life;\n  float dropY = yb - L - 0.6 * age * age - 0.01;\n  vec2 dp = p - vec2(cx + (hc.y - 0.5) * 0.004, dropY);\n  float dr = 0.005 + 0.004 * hc.z;\n  float dropOn = hasCol * step(0.05, L) * step(0.25, m) * step(0.3, hc.z + n1 * 0.5);\n  float drop = (1.0 - smoothstep(dr - 0.0012, dr, length(dp))) * dropOn;\n  vec3 dn = normalize(vec3(dp / dr, sqrt(max(0.0, 1.0 - dot(dp, dp) / (dr * dr)))));\n  n = normalize(mix(n, dn, drop));\n  inside = max(inside, drop);\n  vec3 V = normalize(vec3(-p * 0.6, 1.0));\n  vec3 R = reflect(-V, n);\n  vec3 env = studioEnv(R, 0.08, t * 0.2);\n  float fres = pow(1.0 - clamp(dot(n, V), 0.0, 1.0), 3.0);\n  float body = 0.35 + 0.45 * smoothstep(-0.3, 0.6, R.y);\n  vec3 col = (env + body * vec3(0.55, 0.6, 0.68)) * mix(vec3(0.85), uTint.rgb, 0.5) + uTint.rgb * fres * 1.2;\n  col = 1.0 - exp(-col * 1.7);\n  col *= 1.0 + 0.3 * uHigh * aud;\n  gl_FragColor = vjOut(col * inside, inside);\n}\n"},{"id":"fluid-magnet","name":"Magnetic Point-Grid Attraction","category":"fluid","blurb":"A halftone dot matrix is pulled onto the logo in magnetic pulses, trailing field lines and overshooting on the spring.","params":[{"name":"uTurbScale","label":"Lattice Jitter","type":"float","default":3,"min":0.5,"max":12,"hint":"Curl noise wobbling the dot lattice."},{"name":"uLifespan","label":"Pulse Period","type":"float","default":1.8,"min":0.2,"max":6,"unit":"s","hint":"Seconds per magnetic pulse (dots fly in, lock into the logo, release)."},{"name":"uBounce","label":"Spring Overshoot","type":"float","default":0.4,"min":0,"max":1,"hint":"Overshoot when the lattice snaps to the logo."},{"name":"uDamping","label":"Damping","type":"float","default":0.35,"min":0,"max":1,"hint":"Settles jitter and overshoot."},{"name":"uGravityWell","label":"Pull Strength","type":"float","default":0.6,"min":0,"max":2,"hint":"How far the lattice is compressed toward the mark; kick pulls harder."},{"name":"uTint","label":"Dot Tint","type":"color","default":[0.35,0.95,0.75,1]},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Field Lines","values":{}},{"name":"Hot Plate","values":{"uTint":[1,0.3,0.2,1],"uGravityWell":1.4}},{"name":"Calm Matrix","values":{"uDamping":0.9,"uTurbScale":1,"uGravityWell":0.2}}],"source":"/*{\n  \"DESCRIPTION\": \"Magnetic Point-Grid Attraction \u00e2\u20ac\u201d A halftone dot matrix is pulled onto the logo in magnetic pulses, trailing field lines and overshooting on the spring.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Particle & Fluid\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uTurbScale\",\"TYPE\":\"float\",\"LABEL\":\"Lattice Jitter\",\"DEFAULT\":3,\"MIN\":0.5,\"MAX\":12},\n    {\"NAME\":\"uLifespan\",\"TYPE\":\"float\",\"LABEL\":\"Pulse Period\",\"DEFAULT\":1.8,\"MIN\":0.2,\"MAX\":6},\n    {\"NAME\":\"uBounce\",\"TYPE\":\"float\",\"LABEL\":\"Spring Overshoot\",\"DEFAULT\":0.4,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uDamping\",\"TYPE\":\"float\",\"LABEL\":\"Damping\",\"DEFAULT\":0.35,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uGravityWell\",\"TYPE\":\"float\",\"LABEL\":\"Pull Strength\",\"DEFAULT\":0.6,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Dot Tint\",\"DEFAULT\":[0.35,0.95,0.75,1]},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Magnetic Point-Grid Attraction \u00c2\u00b7 Particle & Fluid\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nfloat vnoise(vec2 p) {\n  vec2 i = floor(p); vec2 f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x), mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nvec2 curl2(vec2 p) {\n  float e = 0.05;\n  float a = vnoise(p + vec2(0.0, e)); float b = vnoise(p - vec2(0.0, e));\n  float c = vnoise(p + vec2(e, 0.0)); float d = vnoise(p - vec2(e, 0.0));\n  return vec2(a - b, -(c - d)) / (2.0 * e);\n}\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// 25-tap disk coverage of the logo around p (radius r, height-normalized units).\n// x = coverage 0..1 (0.5 on the outline), yz = vector pointing into the logo.\nvec3 logoField(vec2 p, float r) {\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n// Approximate signed distance (positive outside) from a logoField sample of radius r.\nfloat fieldSD(vec3 f, float r) { return (0.5 - f.x) * 2.0 * r; }\n// Edge glow that falls to exactly zero at the field radius r (no full-frame haze floor).\nfloat edgeGlow(float sd, float k, float r) { float f = exp(-r * k); return max(exp(-abs(sd) * k) - f, 0.0) / (1.0 - f); }\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\n// ---- effect ----\n// Warped-lattice attraction: the dot lattice itself is pulled along the logo's field (3-5 pitches of visible\n// compression), dots resolve into the exact logo at the pulse peak (lock-in moment), streaks trail the pull.\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  float kick = kickN();\n  float sp = 0.015;\n  float life = max(uLifespan, 0.2);\n  float phase = t / life;\n  float pulse = 0.5 - 0.5 * cos(phase * 6.2831853);\n  float well = uGravityWell * (0.3 + 1.4 * kick);\n  vec3 F = logoField(p, 0.14);\n  float gl = length(F.yz);\n  vec2 g = gl > 0.001 ? F.yz / gl * smoothstep(0.0, 0.3, gl) : vec2(0.0);\n  float over = 1.0 + uBounce * 0.9 * sin(phase * 6.2831853 * 3.0) * exp(-uDamping * 3.0);\n  vec2 warp = g * (0.05 * well * (0.4 + 0.6 * pulse)) * over;\n  warp += curl2(p * uTurbScale + t * 0.4) * 0.004 * (1.0 - uDamping * 0.8);\n  vec2 pw = p - warp;\n  vec2 cid = floor(pw / sp);\n  float near = smoothstep(0.0, 0.06, F.x);\n  float px = 1.2 / RENDERSIZE.y;\n  vec3 col = vec3(0.0); float solid = 0.0;\n  for (int j = -1; j <= 1; j++) {\n    for (int i = -1; i <= 1; i++) {\n      vec2 id = cid + vec2(float(i), float(j));\n      vec2 home = (id + 0.5) * sp;\n      vec3 h = hash32(id);\n      float a0 = logoP(home + warp * 0.5);\n      float rad = min(mix(0.0028, 0.0062, a0) * (0.75 + 0.5 * pulse) * (1.0 + 0.4 * uBounce * pulse * a0), 0.42 * sp);\n      rad = max(rad, px);\n      float d = length(pw - home);\n      float mk = 1.0 - smoothstep(rad - px * 0.7, rad + px * 0.5, d);\n      vec3 lc = IMG_NORM_PIXEL(inputImage, p2uv(home + warp * 0.5)).rgb;\n      vec3 dc = mix(uTint.rgb * (0.2 + 0.6 * pulse * near) * (0.5 + 0.5 * near), lc, a0);\n      col = max(col, dc * mk);\n      solid = max(solid, mk * mix(0.45, 1.0, a0) * mix(0.15, 1.0, near * near));\n      // streak trailing the pull direction (the field line the dot rode in on)\n      vec2 ba = g * 0.03 * well * (0.3 + pulse);\n      vec2 pa = pw - home;\n      float hseg = clamp(dot(pa, -ba) / max(dot(ba, ba), 0.0000001), 0.0, 1.0);\n      float line = exp(-length(pa + ba * hseg) / max(0.0012, px)) * step(0.002, length(ba)) * (1.0 - hseg) * near;\n      col += uTint.rgb * line * 0.7;\n      solid = max(solid, line * 0.5);\n    }\n  }\n  // lock-in: at the pulse peak the dots resolve into the real logo (bolt, ring and colours come back)\n  vec4 lg = logoRGBA(p);\n  float lock = smoothstep(0.75, 1.0, pulse);\n  col = mix(col, lg.rgb * lg.a, lock * lg.a);\n  solid = mix(solid, max(solid, lg.a), lock);\n  gl_FragColor = vjOut(col, solid);\n}\n"},{"id":"fluid-ash","name":"Ash & Dust Wind Drift","category":"fluid","blurb":"A white-hot seam sweeps across the logo; the mark crumbles behind it into pale flakes that stream away downwind, then snaps back.","params":[{"name":"uDissolve","label":"Dissolve Front","type":"float","default":0,"min":0,"max":1,"auto":{"on":true,"shape":"burn","rate":0.06,"lo":0,"hi":1},"hint":"0 = intact, 1 = fully blown away. The app runs it as a burn LFO: sweep, fast re-form, hold."},{"name":"uTurbScale","label":"Wind Turbulence","type":"float","default":3,"min":0.5,"max":12,"hint":"Curl noise bending the flake paths."},{"name":"uLifespan","label":"Flake Lifespan","type":"float","default":1.8,"min":0.2,"max":6,"unit":"s"},{"name":"uBounce","label":"Updraft","type":"float","default":0.4,"min":0,"max":1,"hint":"Thermal lift on the ash."},{"name":"uDamping","label":"Drag","type":"float","default":0.35,"min":0,"max":1,"hint":"Straightens the flake paths."},{"name":"uGravityWell","label":"Bass Lift","type":"float","default":0.6,"min":0,"max":2,"hint":"Kick lofts the flakes."},{"name":"uTint","label":"Ember Tint","type":"color","default":[1,0.45,0.12,1]},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Snap Away","values":{}},{"name":"Grey Dust","values":{"uTint":[0.75,0.75,0.8,1],"uTurbScale":5}},{"name":"Updraft","values":{"uBounce":1,"uLifespan":3.5,"uDamping":0.6}}],"source":"/*{\n  \"DESCRIPTION\": \"Ash & Dust Wind Drift \u00e2\u20ac\u201d A white-hot seam sweeps across the logo; the mark crumbles behind it into pale flakes that stream away downwind, then snaps back.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Particle & Fluid\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uDissolve\",\"TYPE\":\"float\",\"LABEL\":\"Dissolve Front\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uTurbScale\",\"TYPE\":\"float\",\"LABEL\":\"Wind Turbulence\",\"DEFAULT\":3,\"MIN\":0.5,\"MAX\":12},\n    {\"NAME\":\"uLifespan\",\"TYPE\":\"float\",\"LABEL\":\"Flake Lifespan\",\"DEFAULT\":1.8,\"MIN\":0.2,\"MAX\":6},\n    {\"NAME\":\"uBounce\",\"TYPE\":\"float\",\"LABEL\":\"Updraft\",\"DEFAULT\":0.4,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uDamping\",\"TYPE\":\"float\",\"LABEL\":\"Drag\",\"DEFAULT\":0.35,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uGravityWell\",\"TYPE\":\"float\",\"LABEL\":\"Bass Lift\",\"DEFAULT\":0.6,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Ember Tint\",\"DEFAULT\":[1,0.45,0.12,1]},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Ash & Dust Wind Drift \u00c2\u00b7 Particle & Fluid\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nfloat vnoise(vec2 p) {\n  vec2 i = floor(p); vec2 f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x), mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nvec2 curl2(vec2 p) {\n  float e = 0.05;\n  float a = vnoise(p + vec2(0.0, e)); float b = vnoise(p - vec2(0.0, e));\n  float c = vnoise(p + vec2(e, 0.0)); float d = vnoise(p - vec2(e, 0.0));\n  return vec2(a - b, -(c - d)) / (2.0 * e);\n}\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\n// Front position for a 0..1 burn slider: 0 = intact (front just off the mark), 1 = fully gone. The app's 'burn'\n// LFO shape supplies the asymmetric sweep / fast re-form / hold; hosts drive the slider directly.\nfloat burnTimeline(float x) { return mix(0.12, 0.92, clamp(x, 0.0, 1.0)); }\n\n// ---- effect ----\nfloat ashFront(vec2 h) { return clamp((h.x + 0.95) / 1.9, 0.0, 1.0) * 0.8 + (vnoise(h * 6.0) * 0.65 + vnoise(h * 17.0) * 0.35) * 0.25 - 0.05; }\n\n// Scrolling-grid shed: 8 layers of flakes with their own rigid velocity, each flake born on the burnt glyph just\n// behind the front and streaming downwind (constant-velocity layers with a birth test: particles, not an image warp).\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  float kick = kickN();\n  float prog = burnTimeline(uDissolve);\n  float T = 3.0;\n  float W = 1.4;\n  float life = max(uLifespan, 0.2);\n  float la = logoP(p);\n  float fr = ashFront(p + curl2(p * uTurbScale + t * 0.2) * 0.03);\n  vec3 lcol = IMG_NORM_PIXEL(inputImage, uv).rgb;\n  // body: intact ahead of the front; a hash-cell crumble zone right behind it; ash-pale near the line\n  float ahead = smoothstep(prog - 0.005, prog + 0.02, fr);\n  float crumbleZone = smoothstep(prog - 0.07, prog, fr) * (1.0 - ahead);\n  float crumble = step(hash12(floor(p * 220.0)), smoothstep(prog - 0.07, prog + 0.02, fr)) * crumbleZone;\n  float body = la * max(ahead, crumble);\n  vec3 pale = vec3(0.68, 0.64, 0.6);\n  vec3 bcol = mix(lcol, mix(pale, uTint.rgb, 0.6), smoothstep(0.14, 0.0, fr - prog));\n  vec3 col = bcol * body;\n  float line = exp(-abs(fr - prog) / pxMin(0.003)) * la * step(0.13, prog);\n  col += mix(vec3(1.0, 0.98, 0.9), uTint.rgb, 0.35) * line * (1.6 + 1.0 * kick);\n  float solid = max(body, line);\n  vec2 wind = vec2(0.17, 0.03);\n  for (int k = 0; k < 8; k++) {\n    float fk = float(k);\n    vec2 vel = (wind * (0.6 + 0.25 * fk) + vec2(0.0, 0.15 * uBounce) + vec2(0.12 * kick, 0.03 + 0.1 * kick) * uGravityWell) * (1.0 - 0.55 * uDamping);\n    float cs = 0.014 + 0.003 * fk;\n    vec2 sway = vec2(sin(t * 0.8 + fk), 0.0) * 0.01;\n    vec2 q = (p - vel * t - sway) / cs;\n    vec2 cell = floor(q);\n    vec3 h = hash32(cell + fk * 37.0);\n    if (h.z > 0.45) continue;\n    float age = fract(t / life + h.x) * life;\n    vec2 cc = (cell + 0.5 + (h.xy - 0.5) * 0.6) * cs + vel * t + sway;\n    cc += curl2(cc * uTurbScale + t * 0.3) * 0.012 * min(age, 1.5);\n    vec2 b = cc - vel * age - curl2(cc * uTurbScale) * 0.02 * age;\n    if (logoP(b) < 0.5) continue;\n    float a = (prog - ashFront(b)) * T;\n    if (a - age < 0.0 || a - age > W) continue;\n    float ageN = age / life;\n    float sz = max(0.0055 * (0.5 + h.y), 1.2 / RENDERSIZE.y) * mix(1.6, 1.0, fk / 7.0);\n    vec2 d = p - cc;\n    float mk = exp(-dot(d, d) / (sz * sz));\n    float hot = (1.0 - smoothstep(0.0, 0.3, age)) * (0.6 + 0.4 * kick);\n    float fade = 1.0 - ageN;\n    vec3 ac = mix(mix(pale * 0.95, uTint.rgb, 0.3), uTint.rgb * 2.0, hot);\n    col += ac * mk * fade * mix(0.6, 1.2, fk / 7.0);\n    solid = max(solid, mk * fade * 0.9);\n  }\n  gl_FragColor = vjOut(col, solid);\n}\n"},{"id":"fluid-ember","name":"Ember Combustion","category":"fluid","blurb":"Flames lick up from the burn line, char the logo with glowing cracks and loft swarms of embers on heat haze.","params":[{"name":"uBurn","label":"Burn Progress","type":"float","default":0,"min":0,"max":1,"auto":{"on":true,"shape":"burn","rate":0.06,"lo":0,"hi":1},"hint":"0 = intact, 1 = burnt out. The app runs it as a burn LFO: fire climbs, fast re-form, hold."},{"name":"uTurbScale","label":"Flame Turbulence","type":"float","default":3,"min":0.5,"max":12},{"name":"uLifespan","label":"Ember Lifespan","type":"float","default":1.8,"min":0.2,"max":6,"unit":"s","hint":"How long embers glow (and how high they rise)."},{"name":"uBounce","label":"Flame Height","type":"float","default":0.4,"min":0,"max":1},{"name":"uDamping","label":"Ember Drag","type":"float","default":0.35,"min":0,"max":1},{"name":"uGravityWell","label":"Bass Surge","type":"float","default":0.6,"min":0,"max":2,"hint":"Kick surges the flames and lofts the embers."},{"name":"uTint","label":"Fire Tint","type":"color","default":[1,0.5,0.1,1],"hint":"Tint-aware: blue gives a real blue flame."},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Wildfire","values":{}},{"name":"Blue Flame","values":{"uTint":[0.25,0.55,1,1]}},{"name":"Slow Smoulder","values":{"uTurbScale":1.5,"uLifespan":4,"uDamping":0.7}}],"source":"/*{\n  \"DESCRIPTION\": \"Ember Combustion \u00e2\u20ac\u201d Flames lick up from the burn line, char the logo with glowing cracks and loft swarms of embers on heat haze.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Particle & Fluid\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uBurn\",\"TYPE\":\"float\",\"LABEL\":\"Burn Progress\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uTurbScale\",\"TYPE\":\"float\",\"LABEL\":\"Flame Turbulence\",\"DEFAULT\":3,\"MIN\":0.5,\"MAX\":12},\n    {\"NAME\":\"uLifespan\",\"TYPE\":\"float\",\"LABEL\":\"Ember Lifespan\",\"DEFAULT\":1.8,\"MIN\":0.2,\"MAX\":6},\n    {\"NAME\":\"uBounce\",\"TYPE\":\"float\",\"LABEL\":\"Flame Height\",\"DEFAULT\":0.4,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uDamping\",\"TYPE\":\"float\",\"LABEL\":\"Ember Drag\",\"DEFAULT\":0.35,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uGravityWell\",\"TYPE\":\"float\",\"LABEL\":\"Bass Surge\",\"DEFAULT\":0.6,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Fire Tint\",\"DEFAULT\":[1,0.5,0.1,1]},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Ember Combustion \u00c2\u00b7 Particle & Fluid\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nfloat vnoise(vec2 p) {\n  vec2 i = floor(p); vec2 f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x), mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nfloat fbm(vec2 p) {\n  float a = 0.5; float s = 0.0;\n  for (int i = 0; i < 5; i++) { s += a * vnoise(p); p = p * 2.03 + vec2(17.1, 9.2); a *= 0.5; }\n  return s / 0.96875;\n}\n\nvec2 curl2(vec2 p) {\n  float e = 0.05;\n  float a = vnoise(p + vec2(0.0, e)); float b = vnoise(p - vec2(0.0, e));\n  float c = vnoise(p + vec2(e, 0.0)); float d = vnoise(p - vec2(e, 0.0));\n  return vec2(a - b, -(c - d)) / (2.0 * e);\n}\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// 25-tap disk coverage of the logo around p (radius r, height-normalized units).\n// x = coverage 0..1 (0.5 on the outline), yz = vector pointing into the logo.\nvec3 logoField(vec2 p, float r) {\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n// Approximate signed distance (positive outside) from a logoField sample of radius r.\nfloat fieldSD(vec3 f, float r) { return (0.5 - f.x) * 2.0 * r; }\n// Edge glow that falls to exactly zero at the field radius r (no full-frame haze floor).\nfloat edgeGlow(float sd, float k, float r) { float f = exp(-r * k); return max(exp(-abs(sd) * k) - f, 0.0) / (1.0 - f); }\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\n// Tint-aware heat ramp (0 = cold, 1 = white hot). Goes dark tint -> tint -> near white, so a blue tint gives\n// a blue flame instead of the olive you get from multiplying a warm blackbody ramp by a cool colour.\nvec3 heatRamp(float x, vec3 tint) {\n  x = clamp(x, 0.0, 1.0);\n  vec3 dark = tint * 0.12;\n  return mix(mix(dark, tint, smoothstep(0.0, 0.5, x)), vec3(1.0, 0.96, 0.85), smoothstep(0.55, 1.0, x));\n}\n\n// Front position for a 0..1 burn slider: 0 = intact (front just off the mark), 1 = fully gone. The app's 'burn'\n// LFO shape supplies the asymmetric sweep / fast re-form / hold; hosts drive the slider directly.\nfloat burnTimeline(float x) { return mix(0.12, 0.92, clamp(x, 0.0, 1.0)); }\n\n// ---- effect ----\nfloat burnFront(vec2 h) { return clamp(h.y + 0.5, 0.0, 1.0) * 0.75 + (vnoise(h * 7.0) * 0.6 + vnoise(h * 19.0) * 0.4) * 0.3; }\n\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  float kick = kickN();\n  float prog = burnTimeline(uBurn);\n  float life = max(uLifespan, 0.2);\n  float T = 3.0;\n  float surge = 1.0 + uGravityWell * (0.2 + 0.8 * kick);\n  float fr0 = burnFront(p);\n  float hz = exp(-abs(fr0 - prog) * 10.0);\n  vec2 p2 = p + vec2(vnoise(p * 30.0 - vec2(0.0, t * 3.0)) - 0.5, 0.0) * 0.014 * hz;\n  float fr = burnFront(p2);\n  float diff = fr - prog;\n  float la = logoP(p2);\n  vec3 lcol = IMG_NORM_PIXEL(inputImage, p2uv(p2)).rgb;\n  float unburned = smoothstep(0.0, 0.015, diff);\n  vec3 col = lcol * la * unburned;\n  // char that survives on a dark stage: lifted albedo, rim glow, Voronoi cracks cooling yellow -> red -> dark\n  vec3 charCol = vec3(0.11, 0.05, 0.025);\n  col = mix(col, charCol * la, (1.0 - smoothstep(0.0, 0.07, diff)) * unburned * 0.85);\n  float line = exp(-abs(diff) / pxMin(0.0045));\n  col += la * line * heatRamp(0.85 + 0.15 * sin(t * 13.0 + p.x * 40.0), uTint.rgb) * (1.0 + kick);\n  float charred = la * (1.0 - unburned) * smoothstep(-0.5, -0.02, diff);\n  vec2 vc = p * 40.0;\n  vec2 vi = floor(vc);\n  float f1 = 9.0; float f2 = 9.0;\n  for (int j = -1; j <= 1; j++) for (int i = -1; i <= 1; i++) {\n    vec2 o = vec2(float(i), float(j));\n    vec2 sp = vi + o + hash22(vi + o);\n    float dd = length(vc - sp);\n    if (dd < f1) { f2 = f1; f1 = dd; } else if (dd < f2) { f2 = dd; }\n  }\n  float crack = 1.0 - smoothstep(0.0, 0.12, f2 - f1);\n  float cool = clamp(-diff / 0.25, 0.0, 1.0);\n  vec3 crackCol = heatRamp(0.8 - 0.7 * cool, uTint.rgb) * (1.0 - 0.8 * cool);\n  float rim = edgeGlow(fieldSD(logoField(p2, 0.02), 0.02), 90.0, 0.02) * (1.0 - cool * 0.7);\n  col += charred * (charCol + crack * crackCol * 1.2 + uTint.rgb * rim * 0.25);\n  // flames rise into the air above the burn line (no longer masked to the letters)\n  float flameH = (0.08 + 0.17 * uBounce) * surge * (1.0 - 0.4 * uDamping);\n  float nearF = logoField(p, 0.1).x;\n  float flame = 0.0;\n  for (int i = 0; i < 4; i++) {\n    float off = (float(i) + 0.5) / 4.0 * flameH;\n    vec2 q = p2 - vec2(0.0, off);\n    float l2 = exp(-abs(burnFront(q) - prog) * 40.0) * smoothstep(0.0, 0.25, nearF);\n    float tongue = fbm(vec2(p.x * (6.0 + uTurbScale * 5.0), p.y * (2.0 + uTurbScale * 0.5) - t * 3.2));\n    flame = max(flame, l2 * smoothstep(off / flameH, off / flameH + 0.35, tongue * 1.25) * (1.0 - off / flameH * 0.6));\n  }\n  col += heatRamp(0.45 + 0.5 * flame, uTint.rgb) * flame * 1.4;\n  float solid = max(max(la * unburned, charred * 0.9), flame * 0.8);\n  // ember swarm: 3 scrolling layers (small/medium/large) rising at their own speed, born on the burnt glyph\n  for (int k = 0; k < 3; k++) {\n    float fk = float(k);\n    vec2 vel = vec2(0.02 * sin(t * 0.7 + fk), 0.10 + 0.07 * fk) * (1.0 - 0.75 * uDamping) + vec2(0.0, uGravityWell * (0.02 + 0.08 * kick));\n    float cs = 0.012 + 0.006 * fk;\n    vec2 q = (p - vel * t) / cs;\n    vec2 cell = floor(q);\n    vec3 h = hash32(cell + fk * 53.0);\n    if (h.z > 0.7) continue;\n    float age = fract(t / life + h.x) * life;\n    vec2 cc = (cell + 0.5 + (h.xy - 0.5) * 0.6) * cs + vel * t;\n    vec2 b = cc - vel * age - curl2(cc * uTurbScale - vec2(0.0, t * 0.5)) * 0.03 * age;\n    if (logoP(b) < 0.5) continue;\n    float a = (prog - burnFront(b)) * T;\n    if (a - age < 0.0 || a - age > 1.8) continue;\n    float ageN = age / life;\n    float sz = max(0.003 + 0.003 * fk, 1.2 / RENDERSIZE.y) * (0.6 + 0.6 * h.y) * (1.0 + 0.3 * min(life, 4.0) / 4.0);\n    vec2 d = p - cc;\n    vec2 dt2 = vec2(d.x, d.y < 0.0 ? d.y * 0.4 : d.y);\n    float mk = exp(-dot(dt2, dt2) / (sz * sz)) + 0.2 * exp(-dot(d, d) / (sz * sz * 8.0));\n    float fade = 1.0 - ageN;\n    col += heatRamp(0.95 - 0.7 * ageN, uTint.rgb) * mk * fade * (1.6 + 0.6 * sin(t * 20.0 + h.y * 50.0)) * (1.0 + 0.4 * uHigh * aud) * (1.0 + 0.5 * uDamping);\n    solid = max(solid, mk * fade * 0.9);\n  }\n  gl_FragColor = vjOut(col, solid);\n}\n"},{"id":"fluid-shockwave","name":"Bass Shockwave Refraction","category":"fluid","blurb":"Every beat fires a pressure ring out of the logo centre; the letterforms bend and spring back with overshoot as the refracting front passes.","params":[{"name":"uTurbScale","label":"Ring Wavelength","type":"float","default":3,"min":0.5,"max":12,"hint":"Ring wavelength \u00e2\u20ac\u201d higher packs the pressure front into tighter ripples."},{"name":"uLifespan","label":"Ring Crossing (beats)","type":"float","default":1.8,"min":0.2,"max":6,"unit":"s","hint":"Ring crossing time: each ring takes 0.4 + 0.7 \u00c3\u2014 this many beats to cross the logo. Long = overlapping rings."},{"name":"uBounce","label":"Spring Overshoot","type":"float","default":0.4,"min":0,"max":1,"hint":"Spring overshoot: how many times the letterforms ring back after the front passes."},{"name":"uDamping","label":"Ring Decay","type":"float","default":0.35,"min":0,"max":1,"hint":"How fast each ring loses its push as it expands."},{"name":"uGravityWell","label":"Ring Push","type":"float","default":0.6,"min":0,"max":2,"hint":"Ring push strength; the kick multiplies it and punches the logo toward the viewer."},{"name":"uTint","label":"Ring Tint","type":"color","default":[0.3,0.8,1,1]},{"name":"uBeat","label":"Beat Phase","type":"float","default":0.9,"min":0,"max":1,"group":"Audio","driver":"beat","hint":"Sawtooth 0\u00e2\u2020\u20191 per beat (app BPM clock). In Resolume, map to a BPM-synced parameter; in TD, a beat CHOP ramp."},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Sub Drop","values":{}},{"name":"Hardstyle Slam","values":{"uTint":[1,0.12,0.08,1],"uGravityWell":1.4,"uBounce":0.15,"uDamping":0.55,"uTurbScale":2}},{"name":"Psy Ripple","values":{"uTint":[0.7,0.3,1,1],"uTurbScale":7,"uBounce":0.9,"uLifespan":3.2,"uDamping":0.2}}],"source":"/*{\n  \"DESCRIPTION\": \"Bass Shockwave Refraction \u00e2\u20ac\u201d Every beat fires a pressure ring out of the logo centre; the letterforms bend and spring back with overshoot as the refracting front passes.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Particle & Fluid\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uTurbScale\",\"TYPE\":\"float\",\"LABEL\":\"Ring Wavelength\",\"DEFAULT\":3,\"MIN\":0.5,\"MAX\":12},\n    {\"NAME\":\"uLifespan\",\"TYPE\":\"float\",\"LABEL\":\"Ring Crossing (beats)\",\"DEFAULT\":1.8,\"MIN\":0.2,\"MAX\":6},\n    {\"NAME\":\"uBounce\",\"TYPE\":\"float\",\"LABEL\":\"Spring Overshoot\",\"DEFAULT\":0.4,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uDamping\",\"TYPE\":\"float\",\"LABEL\":\"Ring Decay\",\"DEFAULT\":0.35,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uGravityWell\",\"TYPE\":\"float\",\"LABEL\":\"Ring Push\",\"DEFAULT\":0.6,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Ring Tint\",\"DEFAULT\":[0.3,0.8,1,1]},\n    {\"NAME\":\"uBeat\",\"TYPE\":\"float\",\"LABEL\":\"Beat Phase\",\"DEFAULT\":0.9,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Bass Shockwave Refraction \u00c2\u00b7 Particle & Fluid\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// 25-tap disk coverage of the logo around p (radius r, height-normalized units).\n// x = coverage 0..1 (0.5 on the outline), yz = vector pointing into the logo.\nvec3 logoField(vec2 p, float r) {\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n// Approximate signed distance (positive outside) from a logoField sample of radius r.\nfloat fieldSD(vec3 f, float r) { return (0.5 - f.x) * 2.0 * r; }\n// Edge glow that falls to exactly zero at the field radius r (no full-frame haze floor).\nfloat edgeGlow(float sd, float k, float r) { float f = exp(-r * k); return max(exp(-abs(sd) * k) - f, 0.0) / (1.0 - f); }\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\nfloat logoCov5(vec2 p, float r) {\n  return (logoP(p) + logoP(p + vec2(r, 0.0)) + logoP(p - vec2(r, 0.0)) + logoP(p + vec2(0.0, r)) + logoP(p - vec2(0.0, r))) * 0.2;\n}\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\n// ---- effect ----\n// Ring profile: a sharp leading compression front, then a spring-overshoot tail (uBounce = ringing length).\nfloat swProfile(float x, float lam) {\n  float lead = lam * 0.3;\n  float tail = lam * (0.2 + 2.4 * uBounce);\n  float env = x > 0.0 ? exp(-x * x / (lead * lead)) : exp(x / tail);\n  return cos(6.2831853 * x / lam) * env;\n}\n\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  float kick = kickN();\n  float beat = clamp(uBeat, 0.0, 1.0);\n  float cross = min(0.4 + max(uLifespan, 0.2) * 0.7, 1.05 + 0.6 * step(3.0, uLifespan));\n  // hold gate: the last fifth of every beat is the clean logo, whatever the ring count\n  float hold = 1.0 - smoothstep(0.78, 0.97, beat);\n  float Rmax = 0.82;\n  float lam = 0.03 + 0.3 / max(uTurbScale, 0.5);\n  float dampE = 0.25 + 2.2 * uDamping;\n  float A = min(0.008 + 0.032 * uGravityWell * (0.3 + kick), 0.03) * hold;\n  // the kick punches the whole mark toward the viewer, then it relaxes over the beat\n  float punch = 0.07 * uGravityWell * kick * exp(-beat * 5.0);\n  vec2 q = p / (1.0 + punch);\n  float d = length(q);\n  vec2 dir = q / max(d, 0.0001);\n  float disp = 0.0; float slope = 0.0; float line = 0.0; float band = 0.0;\n  for (int k = 0; k < 3; k++) {\n    float ph = (beat + 0.06 + float(k)) / cross;\n    if (ph < 1.0) {\n      float R = Rmax * pow(ph, 0.6);\n      float amp = A * pow(1.0 - ph, dampE);\n      float x = d - R;\n      disp += amp * swProfile(x, lam);\n      slope += amp * (swProfile(x + 0.0015, lam) - swProfile(x - 0.0015, lam)) / 0.003;\n      float lw = 0.006 + 0.004 * kick;\n      float life = pow(1.0 - ph, 0.4 + dampE * 0.4) * hold;\n      line += exp(-x * x / (lw * lw)) * life;\n      float bw = lam * 0.45;\n      band += exp(-x * x / (bw * bw)) * life;\n    }\n  }\n  // refraction: sample the logo along the ring normal, with a spectral split that grows with the kick\n  float ca = 0.15 + 0.35 * kick;\n  vec2 qs = q - dir * disp;\n  vec4 cR = logoRGBA(q - dir * disp * (1.0 + ca));\n  vec4 cG = logoRGBA(qs);\n  vec4 cB = logoRGBA(q - dir * disp * (1.0 - ca));\n  vec3 lc = vec3(cR.r * cR.a, cG.g * cG.a, cB.b * cB.a);\n  float la = max(cG.a, max(cR.a, cB.a));\n  // compression brightens, rarefaction darkens (caustic of the bent letterforms)\n  float shade = clamp(1.0 - slope * 0.9, 0.7, 1.7);\n  vec3 col = mix(lc * shade, lc * uTint.rgb * 1.6, clamp(-slope * 0.5, 0.0, 0.5));\n  // tint rim light on the (bent) letter edges: idles low, flares where a front crosses an edge\n  float c5 = logoCov5(qs, 0.0035);\n  float rim = 4.0 * c5 * (1.0 - c5);\n  vec3 rimC = mix(lc / max(la, 0.001), uTint.rgb, 0.4);\n  col += rimC * rim * (0.04 + 2.0 * band + 0.5 * kick * hold);\n  // ring highlight only near ink: no ring is ever drawn in empty space\n  float near = logoField(p, 0.16).x;\n  float gate = smoothstep(0.02, 0.3, near);\n  vec3 hot = mix(uTint.rgb, vec3(1.0), 0.45);\n  col += uTint.rgb * (line * (0.7 + 1.1 * kick) + band * 0.18) * gate * (1.0 - la);\n  col += hot * line * la * (0.5 + 0.7 * kick);\n  col *= 1.0 + 0.35 * kick * exp(-beat * 8.0);\n  float solid = max(la, max(line * 0.85, band * 0.2) * gate);\n  solid = max(solid, rim * (0.25 + 0.6 * min(band, 1.0)));\n  gl_FragColor = vjOut(col, solid);\n}\n"},{"id":"fluid-cymatic","name":"Cymatic Sand Plate","category":"fluid","blurb":"The logo is poured in sand on a vibrating plate: every kick throws the grains into a Chladni figure that settles back into the letterforms over the beat.","params":[{"name":"uTurbScale","label":"Plate Mode Frequency","type":"float","default":3,"min":0.5,"max":12,"hint":"Plate mode frequency \u00e2\u20ac\u201d higher = finer Chladni figure."},{"name":"uLifespan","label":"Settle Time","type":"float","default":1.8,"min":0.2,"max":6,"unit":"s","hint":"Settle time: how much of the beat the sand takes to fall back into the logo."},{"name":"uBounce","label":"Grain Hop","type":"float","default":0.4,"min":0,"max":1,"hint":"Grain hop: how high the sand dances while the plate rings."},{"name":"uDamping","label":"Plate Decay","type":"float","default":0.35,"min":0,"max":1,"hint":"Excitation decay: how fast the plate stops ringing after each kick."},{"name":"uGravityWell","label":"Plate Excitation","type":"float","default":0.6,"min":0,"max":2,"hint":"Plate excitation: how far the kick throws the sand into the figure (and how far it shifts the mode)."},{"name":"uTint","label":"Sand Tint","type":"color","default":[0.85,0.92,1,1]},{"name":"uBeat","label":"Beat Phase","type":"float","default":0.9,"min":0,"max":1,"group":"Audio","driver":"beat","hint":"Sawtooth 0\u00e2\u2020\u20191 per beat (app BPM clock). In Resolume, map to a BPM-synced parameter; in TD, a beat CHOP ramp."},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Salt Plate","values":{}},{"name":"Gold Dust","values":{"uTint":[1,0.72,0.3,1],"uTurbScale":2,"uBounce":0.25}},{"name":"Acid Resonance","values":{"uTint":[0.55,1,0.2,1],"uTurbScale":7,"uGravityWell":1.4,"uDamping":0.3}}],"source":"/*{\n  \"DESCRIPTION\": \"Cymatic Sand Plate \u00e2\u20ac\u201d The logo is poured in sand on a vibrating plate: every kick throws the grains into a Chladni figure that settles back into the letterforms over the beat.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Particle & Fluid\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uTurbScale\",\"TYPE\":\"float\",\"LABEL\":\"Plate Mode Frequency\",\"DEFAULT\":3,\"MIN\":0.5,\"MAX\":12},\n    {\"NAME\":\"uLifespan\",\"TYPE\":\"float\",\"LABEL\":\"Settle Time\",\"DEFAULT\":1.8,\"MIN\":0.2,\"MAX\":6},\n    {\"NAME\":\"uBounce\",\"TYPE\":\"float\",\"LABEL\":\"Grain Hop\",\"DEFAULT\":0.4,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uDamping\",\"TYPE\":\"float\",\"LABEL\":\"Plate Decay\",\"DEFAULT\":0.35,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uGravityWell\",\"TYPE\":\"float\",\"LABEL\":\"Plate Excitation\",\"DEFAULT\":0.6,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Sand Tint\",\"DEFAULT\":[0.85,0.92,1,1]},\n    {\"NAME\":\"uBeat\",\"TYPE\":\"float\",\"LABEL\":\"Beat Phase\",\"DEFAULT\":0.9,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Cymatic Sand Plate \u00c2\u00b7 Particle & Fluid\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// 25-tap disk coverage of the logo around p (radius r, height-normalized units).\n// x = coverage 0..1 (0.5 on the outline), yz = vector pointing into the logo.\nvec3 logoField(vec2 p, float r) {\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n// Approximate signed distance (positive outside) from a logoField sample of radius r.\nfloat fieldSD(vec3 f, float r) { return (0.5 - f.x) * 2.0 * r; }\n// Edge glow that falls to exactly zero at the field radius r (no full-frame haze floor).\nfloat edgeGlow(float sd, float k, float r) { float f = exp(-r * k); return max(exp(-abs(sd) * k) - f, 0.0) / (1.0 - f); }\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\n// ---- effect ----\n// Chladni plate mode (n, m) for a float index; returns C and its gradient (plate coords X).\n// Pairs: (2,3) (3,6) (4,5) (5,8) (6,7) (7,10) \u00e2\u20ac\u201d never n = m (that mode is identically zero).\nfloat cyMode(vec2 X, float i, out vec2 g) {\n  float n = 2.0 + i;\n  float m = n + 1.0 + 2.0 * mod(i, 2.0);\n  float a = n * 3.14159265; float b = m * 3.14159265;\n  float cnx = cos(a * X.x); float snx = sin(a * X.x);\n  float cmx = cos(b * X.x); float smx = sin(b * X.x);\n  float cny = cos(a * X.y); float sny = sin(a * X.y);\n  float cmy = cos(b * X.y); float smy = sin(b * X.y);\n  g = vec2(-a * snx * cmy + b * smx * cny, -b * cnx * smy + a * cmx * sny);\n  return cnx * cmy - cmx * cny;\n}\n\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  float kick = kickN();\n  float beat = clamp(uBeat, 0.0, 1.0);\n  // plate excitation: kicked on every beat, decays with uDamping\n  float excN = exp(-beat * (0.5 + 6.0 * uDamping));\n  float exc = uGravityWell * (0.45 + 0.9 * kick) * excN;\n  // how far the sand is thrown into the figure, then settles back into the logo over uLifespan\n  float settleB = clamp(0.15 + max(uLifespan, 0.2) * 0.28, 0.15, 1.0);\n  float depth = clamp(uGravityWell * (0.75 + 0.9 * kick), 0.0, 0.95);\n  float fig = depth * max(1.0 - smoothstep(0.0, settleB, beat), 0.7 * excN);\n  // the throw takes ~20 ms: at the exact downbeat only about half the sand is airborne\n  fig *= smoothstep(0.0, 0.09, beat);\n  // the hold: by 85% of the beat every grain is back in the letters\n  fig *= 1.0 - smoothstep(0.55, 0.85, beat);\n  fig = max(fig, 0.02 * clamp(uGravityWell, 0.0, 1.0));\n  // mode: slow drift, the kick jumps it; adjacent modes crossfade (superposed vibration)\n  float mi = 1.0 + t * 0.06 + uGravityWell * kick * 0.8;\n  float i0 = mod(floor(mi), 6.0);\n  float i1 = mod(floor(mi) + 1.0, 6.0);\n  float mf = smoothstep(0.2, 0.8, fract(mi));\n  float s = 0.55 + 0.17 * uTurbScale;\n  vec2 sx = vec2(s, s * 1.7);\n  float plate = smoothstep(0.0, 0.2, logoField(p, 0.16).x);\n  vec4 lgp = logoRGBA(p);\n  float gs = 0.011;\n  vec2 cid = floor(p / gs);\n  // sand bed: a faint fill under the settled grains keeps the letterforms solid at rest\n  float thin = 1.0 - smoothstep(0.3, 0.6, logoField(p, 0.012).x);\n  float bed = lgp.a * (1.0 - fig) * mix(0.22, 0.4, thin);\n  vec3 col = lgp.rgb * bed; float solid = bed;\n  for (int j = -1; j <= 1; j++) {\n    for (int i = -1; i <= 1; i++) {\n      vec2 id = cid + vec2(float(i), float(j));\n      vec3 h = hash32(id);\n      vec3 h2 = hash32(id + 71.3);\n      vec2 gp = (id + 0.5 + (h.xy - 0.5) * 0.55) * gs;\n      bool isFig = h.z < fig;\n      float exist = 0.0;\n      vec3 gc = uTint.rgb;\n      if (isFig) {\n        vec2 g0; vec2 g1;\n        float c0 = cyMode(gp * sx, i0, g0);\n        float c1 = cyMode(gp * sx, i1, g1);\n        float C = mix(c0, c1, mf);\n        vec2 G = mix(g0, g1, mf) * sx;\n        float gl = max(length(G), 0.001);\n        float dn = abs(C) / gl;\n        // grains slide (up to one cell) down the plate gradient onto the nodal line\n        gp -= sign(C) * G / gl * min(dn, gs * 0.9);\n        exist = (1.0 - smoothstep(0.004, 0.013, dn)) * plate;\n      } else {\n        vec4 lg = logoRGBA(gp);\n        exist = step(0.5, lg.a) * step(h2.x, 0.95);\n        gc = mix(lg.rgb, uTint.rgb, 0.2);\n      }\n      if (exist < 0.01) continue;\n      // grains that just changed state land with a hop and a glint (sand raining back into the letters)\n      float land = exp(-abs(fig - h.z) * 18.0) * step(0.1, fig);\n      // hop: grains dance while the plate rings\n      float hop = uBounce * (1.3 * exc + 0.2 * float(isFig)) * abs(sin(t * 29.0 + h2.y * 40.0)) + uBounce * land * 0.8;\n      vec2 hopOff = (h2.yz - 0.5) * gs * 2.0 * hop + vec2(0.0, gs * (0.8 * land * uBounce + 1.2 * hop));\n      gp += clamp(hopOff, vec2(-0.55 * gs), vec2(0.55 * gs));\n      vec2 f = p - gp;\n      float sz = gs * (0.22 + 0.22 * h2.x) * (1.0 + 0.4 * land);\n      float m = (1.0 - smoothstep(sz * 0.7, sz * 1.1, length(f))) * exist;\n      // hard-edged grain with a dark underside and a top-left glint\n      m *= 0.75 + 0.35 * clamp(dot(normalize(f + 0.0001), vec2(-0.6, 0.8)), -1.0, 1.0);\n      float br = isFig ? 1.25 + 0.9 * exc : 1.3;\n      col += gc * m * (br + 0.5 * hop) + mix(uTint.rgb, vec3(1.0), 0.5) * m * land * 0.6;\n      solid = max(solid, m);\n    }\n  }\n  gl_FragColor = vjOut(col, solid);\n}\n"},{"id":"fluid-goldfill","name":"Liquid Gold Fill","category":"fluid","blurb":"Molten gold rises inside the logo like a pour into a mould \u00e2\u20ac\u201d the meniscus sloshes, specular streaks flow \u00e2\u20ac\u201d then it settles into polished, stable gold.","params":[{"name":"uFill","label":"Fill Level","type":"float","default":1,"min":0,"max":1,"auto":{"on":true,"shape":"pour","rate":0.05,"lo":0,"hi":1},"hint":"Pour progress. 0 = empty mould, 0.8 = full, \u00e2\u2030\u00a5 0.92 = settled polished gold (rest state). The app runs it as a pour LFO (hold, fast drain, slow pour)."},{"name":"uTurbScale","label":"Swirl Scale","type":"float","default":3,"min":0.5,"max":12,"hint":"Scale of the flowing swirls in the molten surface."},{"name":"uLifespan","label":"Slosh Period","type":"float","default":1.8,"min":0.2,"max":6,"unit":"s","hint":"Slosh period (seconds) of the meniscus wave."},{"name":"uBounce","label":"Slosh Overshoot","type":"float","default":0.4,"min":0,"max":1,"hint":"Slosh overshoot: crest height of the meniscus wave."},{"name":"uDamping","label":"Slosh Damping","type":"float","default":0.35,"min":0,"max":1,"hint":"How quickly the slosh dies down as the mould fills."},{"name":"uGravityWell","label":"Kick Slosh","type":"float","default":0.6,"min":0,"max":2,"hint":"Kick slosh: the bass throws a wave across the surface."},{"name":"uTint","label":"Gold Tint","type":"color","default":[1,0.76,0.34,1]},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"24K Pour","values":{}},{"name":"Rose Gold","values":{"uTint":[1,0.62,0.52,1],"uTurbScale":2}},{"name":"Platinum","values":{"uTint":[0.86,0.9,0.96,1],"uBounce":0.2,"uDamping":0.6}}],"source":"/*{\n  \"DESCRIPTION\": \"Liquid Gold Fill \u00e2\u20ac\u201d Molten gold rises inside the logo like a pour into a mould \u00e2\u20ac\u201d the meniscus sloshes, specular streaks flow \u00e2\u20ac\u201d then it settles into polished, stable gold.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Particle & Fluid\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uFill\",\"TYPE\":\"float\",\"LABEL\":\"Fill Level\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uTurbScale\",\"TYPE\":\"float\",\"LABEL\":\"Swirl Scale\",\"DEFAULT\":3,\"MIN\":0.5,\"MAX\":12},\n    {\"NAME\":\"uLifespan\",\"TYPE\":\"float\",\"LABEL\":\"Slosh Period\",\"DEFAULT\":1.8,\"MIN\":0.2,\"MAX\":6},\n    {\"NAME\":\"uBounce\",\"TYPE\":\"float\",\"LABEL\":\"Slosh Overshoot\",\"DEFAULT\":0.4,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uDamping\",\"TYPE\":\"float\",\"LABEL\":\"Slosh Damping\",\"DEFAULT\":0.35,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uGravityWell\",\"TYPE\":\"float\",\"LABEL\":\"Kick Slosh\",\"DEFAULT\":0.6,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Gold Tint\",\"DEFAULT\":[1,0.76,0.34,1]},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Liquid Gold Fill \u00c2\u00b7 Particle & Fluid\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nfloat vnoise(vec2 p) {\n  vec2 i = floor(p); vec2 f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x), mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nfloat fbm(vec2 p) {\n  float a = 0.5; float s = 0.0;\n  for (int i = 0; i < 5; i++) { s += a * vnoise(p); p = p * 2.03 + vec2(17.1, 9.2); a *= 0.5; }\n  return s / 0.96875;\n}\n\n// 3-octave fbm: cheaper sibling of fbm() for nested domain warps.\nfloat fbm3(vec2 p) {\n  float a = 0.5; float s = 0.0;\n  for (int i = 0; i < 3; i++) { s += a * vnoise(p); p = p * 2.03 + vec2(17.1, 9.2); a *= 0.5; }\n  return s / 0.875;\n}\n\n// Inigo Quilez double domain warp (iquilezles.org/articles/warp). Returns the warped field; q, r = intermediates for colouring.\nfloat warp2(vec2 p, out vec2 q, out vec2 r) {\n  q = vec2(fbm3(p), fbm3(p + vec2(5.2, 1.3)));\n  r = vec2(fbm3(p + 4.0 * q + vec2(1.7, 9.2)), fbm3(p + 4.0 * q + vec2(8.3, 2.8)));\n  return fbm3(p + 4.0 * r);\n}\n\nmat2 rot2(float a) { float c = cos(a); float s = sin(a); return mat2(c, -s, s, c); }\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// 25-tap disk coverage of the logo around p (radius r, height-normalized units).\n// x = coverage 0..1 (0.5 on the outline), yz = vector pointing into the logo.\nvec3 logoField(vec2 p, float r) {\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n// Approximate signed distance (positive outside) from a logoField sample of radius r.\nfloat fieldSD(vec3 f, float r) { return (0.5 - f.x) * 2.0 * r; }\n// Edge glow that falls to exactly zero at the field radius r (no full-frame haze floor).\nfloat edgeGlow(float sd, float k, float r) { float f = exp(-r * k); return max(exp(-abs(sd) * k) - f, 0.0) / (1.0 - f); }\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\n// Procedural studio environment for chrome / glass / crystal: four off-axis strip lights at mixed elevations\n// (a flat face sees a horizon split instead of one value that flips dark/bright), energy-normalised roughness\n// (rougher = wider lobes, not brighter), top key, horizon line, dark floor. Peaks ~2.0; callers tonemap.\nvec3 studioEnv(vec3 d, float rough, float spin) {\n  d = normalize(d);\n  d.xz = rot2(spin) * d.xz;\n  float y = d.y;\n  float az = atan(d.x, d.z);\n  float k = mix(40.0, 3.0, rough);\n  float norm = (k + 1.0) / 41.0;\n  vec3 sky = mix(vec3(0.08, 0.09, 0.11), vec3(0.75, 0.8, 0.88), smoothstep(-0.1, 0.8, y));\n  float l1 = pow(max(cos(az - 0.3) * cos((y - 0.15) * 1.6), 0.0), k);\n  float l2 = pow(max(cos(az - 2.4) * cos((y - 0.35) * 1.6), 0.0), k * 0.7);\n  float l3 = pow(max(cos(az + 1.9) * cos((y + 0.05) * 1.6), 0.0), k * 1.3);\n  float l4 = pow(max(cos(az + 3.0) * cos((y - 0.5) * 1.6), 0.0), k * 0.5);\n  float strips = norm * (1.6 * l1 + 1.25 * l2 + 1.1 * l3 + 0.8 * l4);\n  float top = pow(max(y, 0.0), mix(24.0, 2.0, rough)) * mix(1.0, 0.35, rough);\n  float hor = exp(-abs(y) * mix(40.0, 6.0, rough));\n  vec3 col = sky * 0.5 + vec3(1.0, 0.98, 0.95) * strips * 1.5 + vec3(2.0, 1.9, 1.75) * top + vec3(0.7, 0.8, 0.95) * hor;\n  float ground = 1.0 - smoothstep(-0.25, 0.0, y);\n  return mix(col, vec3(0.025, 0.025, 0.03) + hor * 0.2, ground);\n}\n\n// ---- effect ----\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  float kick = uBass * aud;\n  float f = clamp(uFill, 0.0, 1.0);\n  float fe = clamp(f / 0.7, 0.0, 1.0);\n  float settle = smoothstep(0.68, 0.82, f);\n  float L = -0.15 + 0.32 * pow(fe, 1.8);\n  // damped slosh: big as the gold slams in, dying away as the mould fills; the kick throws a new wave\n  float per = max(uLifespan, 0.2);\n  float om = 6.2831853 / per;\n  float A0 = (0.012 + 0.045 * uBounce) * exp(-(0.05 + 2.8 * uDamping) * fe);\n  float A = A0 * (1.0 - settle) + 0.04 * uGravityWell * (0.3 + kick) * (1.0 - 0.85 * settle);\n  float ph = p.x * 6.0 - t * om;\n  // travelling crest (with overshoot harmonic) + the tank's fundamental tilt mode\n  float surf = L + A * (sin(ph) + 0.5 * uBounce * sin(2.0 * ph + 1.1)) + A * 3.0 * p.x * sin(t * om * 0.5 + 0.7);\n  float dy = surf - p.y;\n  float below = smoothstep(-0.0015, 0.0015, dy);\n  vec4 lg = logoRGBA(p);\n  float la = lg.a;\n  // bevel (cast-metal edges) from the logo field\n  vec3 F = logoField(p, 0.016);\n  vec3 Fr = logoField(p, 0.008);\n  vec2 gdir = length(F.yz) > 0.0001 ? normalize(F.yz) : vec2(0.0);\n  float slope = 4.0 * F.x * (1.0 - F.x);\n  float slopeR = 4.0 * Fr.x * (1.0 - Fr.x);\n  // molten flow normals from a domain warp that calms to a mirror polish as it settles\n  float flow = mix(1.0, 0.06, settle) * (1.0 + 0.5 * kick);\n  vec2 wq; vec2 wr;\n  float wv = warp2(p * uTurbScale * 1.4 + vec2(-t * 0.1, t * 0.06), wq, wr);\n  // meniscus climbs the mould walls\n  float climb = 0.012 * slope * (1.0 - settle);\n  dy += climb; below = smoothstep(-0.0015, 0.0015, dy);\n  float men = exp(-max(dy, 0.0) / 0.01) * (1.0 - settle);\n  vec3 n = normalize(vec3(-gdir * slope * 2.2 + (wr - 0.5) * 1.5 * flow + vec2(0.0, 1.0) * men * 0.9 + vec2(0.0, 0.3), 1.0));\n  vec3 V = normalize(vec3(-p * 0.5, 1.0));\n  vec3 R = reflect(-V, n);\n  vec3 gold = uTint.rgb;\n  vec3 env = studioEnv(R, 0.1, 0.6 + t * 0.12);\n  vec3 col = env * gold * 1.05 + gold * gold * 0.1;\n  float strip = pow(0.5 + 0.5 * sin((p.x * 0.5 + p.y * 1.3) * 26.0 + wv * 9.0 - t * 1.6 * flow), 18.0);\n  vec3 hiC = mix(gold, vec3(1.0), 0.55);\n  col += hiC * strip * 0.5 * flow;\n  col += hiC * pow(1.0 - n.z, 1.6) * 0.7;\n  col += hiC * men * 1.2;\n  // polished sweep once settled\n  float sw = mix(-1.4, 1.4, fract(t * 0.18));\n  col += hiC * exp(-pow(dot(p, vec2(0.86, 0.5)) - sw, 2.0) / 0.004) * 0.7 * settle;\n  // empty mould: dark cavity with a faint rim so the letterforms read during the pour\n  // the molten metal lights the empty mould walls above it (fades upward, gone once settled)\n  float heat = exp(-max(-dy, 0.0) / 0.045) * (1.0 - settle);\n  vec3 mould = gold * (0.04 + 0.5 * pow(slopeR, 1.2)) + mix(gold, vec3(1.0), 0.4) * heat * 0.42;\n  vec3 outc = mix(mould, col, below) * la;\n  float solid = la * mix(0.5, 1.0, below);\n  gl_FragColor = vjOut(outc, solid);\n}\n"},{"id":"fluid-soapfilm","name":"Soap-Film Iridescence","category":"fluid","blurb":"A thin-film oil-slick swirls inside the letters and in a halo just outside; the bass sends ripples along the outline and drains the film in a vortex.","params":[{"name":"uTurbScale","label":"Swirl Scale","type":"float","default":3,"min":0.5,"max":12,"hint":"Scale of the film swirls (thickness noise)."},{"name":"uLifespan","label":"Flow Period","type":"float","default":1.8,"min":0.2,"max":6,"unit":"s","hint":"Flow period: seconds for the film to drift one swirl."},{"name":"uBounce","label":"Ripple Height","type":"float","default":0.4,"min":0,"max":1,"hint":"Surface-tension ripple height along the outline."},{"name":"uDamping","label":"Ripple Decay","type":"float","default":0.35,"min":0,"max":1,"hint":"How quickly ripples die away from the outline."},{"name":"uGravityWell","label":"Vortex Drain","type":"float","default":0.6,"min":0,"max":2,"hint":"Vortex drain: pre-rotates the film into a spiral; the kick winds it tighter."},{"name":"uTint","label":"Palette Hue","type":"color","default":[0.55,0.35,1,1]},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Soap Bubble","values":{}},{"name":"Brand Calm","values":{"uGravityWell":0.15,"uBounce":0.15,"uTurbScale":1.6,"uLifespan":4.5,"uTint":[0.4,0.75,1,1]}},{"name":"Oil Slick Drop","values":{"uGravityWell":1.6,"uBounce":0.9,"uDamping":0.15,"uTurbScale":4.5,"uLifespan":1,"uTint":[1,0.3,0.6,1]}}],"source":"/*{\n  \"DESCRIPTION\": \"Soap-Film Iridescence \u00e2\u20ac\u201d A thin-film oil-slick swirls inside the letters and in a halo just outside; the bass sends ripples along the outline and drains the film in a vortex.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Particle & Fluid\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uTurbScale\",\"TYPE\":\"float\",\"LABEL\":\"Swirl Scale\",\"DEFAULT\":3,\"MIN\":0.5,\"MAX\":12},\n    {\"NAME\":\"uLifespan\",\"TYPE\":\"float\",\"LABEL\":\"Flow Period\",\"DEFAULT\":1.8,\"MIN\":0.2,\"MAX\":6},\n    {\"NAME\":\"uBounce\",\"TYPE\":\"float\",\"LABEL\":\"Ripple Height\",\"DEFAULT\":0.4,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uDamping\",\"TYPE\":\"float\",\"LABEL\":\"Ripple Decay\",\"DEFAULT\":0.35,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uGravityWell\",\"TYPE\":\"float\",\"LABEL\":\"Vortex Drain\",\"DEFAULT\":0.6,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Palette Hue\",\"DEFAULT\":[0.55,0.35,1,1]},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Soap-Film Iridescence \u00c2\u00b7 Particle & Fluid\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nfloat vnoise(vec2 p) {\n  vec2 i = floor(p); vec2 f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x), mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nfloat fbm(vec2 p) {\n  float a = 0.5; float s = 0.0;\n  for (int i = 0; i < 5; i++) { s += a * vnoise(p); p = p * 2.03 + vec2(17.1, 9.2); a *= 0.5; }\n  return s / 0.96875;\n}\n\n// 3-octave fbm: cheaper sibling of fbm() for nested domain warps.\nfloat fbm3(vec2 p) {\n  float a = 0.5; float s = 0.0;\n  for (int i = 0; i < 3; i++) { s += a * vnoise(p); p = p * 2.03 + vec2(17.1, 9.2); a *= 0.5; }\n  return s / 0.875;\n}\n\n// Inigo Quilez double domain warp (iquilezles.org/articles/warp). Returns the warped field; q, r = intermediates for colouring.\nfloat warp2(vec2 p, out vec2 q, out vec2 r) {\n  q = vec2(fbm3(p), fbm3(p + vec2(5.2, 1.3)));\n  r = vec2(fbm3(p + 4.0 * q + vec2(1.7, 9.2)), fbm3(p + 4.0 * q + vec2(8.3, 2.8)));\n  return fbm3(p + 4.0 * r);\n}\n\n// Inigo Quilez cosine palette (iquilezles.org/articles/palettes).\nvec3 palCos(float t, vec3 a, vec3 b, vec3 c, vec3 d) { return a + b * cos(6.2831853 * (c * t + d)); }\n\nmat2 rot2(float a) { float c = cos(a); float s = sin(a); return mat2(c, -s, s, c); }\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// 25-tap disk coverage of the logo around p (radius r, height-normalized units).\n// x = coverage 0..1 (0.5 on the outline), yz = vector pointing into the logo.\nvec3 logoField(vec2 p, float r) {\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n// Approximate signed distance (positive outside) from a logoField sample of radius r.\nfloat fieldSD(vec3 f, float r) { return (0.5 - f.x) * 2.0 * r; }\n// Edge glow that falls to exactly zero at the field radius r (no full-frame haze floor).\nfloat edgeGlow(float sd, float k, float r) { float f = exp(-r * k); return max(exp(-abs(sd) * k) - f, 0.0) / (1.0 - f); }\n\n// logoField with the 12-direction ring rotated by a per-pixel hash: the polygonal iso-lines of the\n// fixed ring (the \"blocky banding\" and 12-ray stars seen in reviews) become fine, frame-stable noise.\n// Same cost as logoField; use it for anything that draws contours / distances, keep logoField for bevel normals.\nvec3 logoFieldJ(vec2 p, float r) {\n  float j = hash12(floor(isf_FragNormCoord * RENDERSIZE)) * 0.5235988;\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988 + j;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\n// ---- effect ----\nfloat sfHue(vec3 c) {\n  float y = 1.7320508 * (c.g - c.b); float x = 2.0 * c.r - c.g - c.b;\n  return abs(x) + abs(y) < 0.0001 ? 0.0 : atan(y, x) / 6.2831853;\n}\n\n// Two-scale signed distance to the outline (+ outside). The near field (25 taps, radius 0.02) is local, so it\n// is accurate at the edge and cannot see across a gap; beyond 0.02 the far field (radius R) takes over, never\n// closer than 0.02. (A normal-march refinement either overshot at concave corners or, clamped to the far\n// coverage, collapsed to ~0 in narrow gaps between letters and lit the rim there.) 50 taps.\nfloat sfSD(vec2 p, float R, out float cov) {\n  vec3 Ff = logoFieldJ(p, R);\n  cov = Ff.x;\n  float sdF = fieldSD(Ff, R);\n  float sdN = fieldSD(logoFieldJ(p, 0.02), 0.02);\n  float far = (sdN >= 0.0 ? 1.0 : -1.0) * max(abs(sdF), 0.02);\n  return mix(sdN, far, smoothstep(0.014, 0.019, abs(sdN)));\n}\n\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  float kick = kickN();\n  float Rf = 0.07;\n  float cov;\n  float sd = sfSD(p, Rf, cov);\n  vec4 lg = logoRGBA(p);\n  float la = lg.a;\n  // vortex drain: pre-rotate the film domain, strongest at the centre; the kick winds it tighter\n  float r = length(p);\n  float swirl = uGravityWell * (1.4 + 0.5 * kick) * exp(-r * 3.0);\n  vec2 q = rot2(swirl) * p;\n  float sp = 1.0 / max(uLifespan, 0.2);\n  vec2 wq; vec2 wr;\n  float h = warp2(q * uTurbScale * 0.45 + vec2(t * 0.5, -t * 0.3) * sp, wq, wr);\n  // bass ripple running along the outline, decaying away from it\n  float rip = sin(110.0 * sd - t * 30.0) * exp(-abs(sd) * (12.0 + 110.0 * uDamping)) * uBounce * (0.38 + 0.6 * kick);\n  // film thickness: swirled warp + fine flow striations + gravity drainage (thinner at the top)\n  float stri = fbm3(vec2(wq.x * 9.0, wr.y * 9.0) + q * uTurbScale * 2.2 + t * 0.2 * sp);\n  float thick = 0.28 + h * 1.7 + wr.y * 0.45 + stri * 0.18 - p.y * 0.8 + rip;\n  // thin-film interference: reflectance ~ sin^2(2*pi*n*d/lambda) per channel (lambda 650/530/450 nm),\n  // palette phase rotated by the tint hue\n  float hue = sfHue(uTint.rgb);\n  vec3 film = palCos(thick * 1.5, vec3(0.5), vec3(-0.5), vec3(1.0, 1.23, 1.45), vec3(0.0, 0.33, 0.67) + hue);\n  film = mix(film, vec3(dot(film, vec3(0.333))), 0.15 + smoothstep(1.4, 2.4, thick) * 0.4);\n  float luma = dot(lg.rgb, vec3(0.299, 0.587, 0.114));\n  // inside: the film sits over the logo; the logo's own luma modulates it so letterforms stay readable\n  // reflectance floor: the thinnest (black) film reads as dim silver, never as a hole in the letters\n  float floorR = mix(0.22, 0.08, smoothstep(0.8, 1.6, uGravityWell));\n  vec3 filmL = film + (1.0 - film) * floorR;\n  vec3 inside = lg.rgb * 0.18 + filmL * (0.5 + 0.6 * luma);\n  // soft window reflection drifting over the film (the bubble sheen)\n  float sheen = smoothstep(0.55, 0.95, wq.x) * smoothstep(0.2, 0.6, wr.x);\n  inside += vec3(0.9, 0.95, 1.0) * sheen * 0.3;\n  float rim = edgeGlow(sd, 380.0, Rf);\n  // halo: light only (alpha follows its brightness), so thin black film never paints a dark smudge.\n  // Kept tight (~0.035): coverage-driven halos ghost the 12-tap ring, wide exp() halos expose far-field errors.\n  float halo = edgeGlow(max(sd, 0.0), 70.0, Rf) * (1.0 - la);\n  // halo colour from the smooth thickness only (no striations / ripple): a clean iridescent glow\n  vec3 filmH = palCos((0.28 + h * 1.7 + wr.y * 0.45 - p.y * 0.8) * 1.5, vec3(0.5), vec3(-0.5), vec3(1.0, 1.23, 1.45), vec3(0.0, 0.33, 0.67) + hue);\n  vec3 hc = (0.3 + 0.7 * filmH) * halo * (0.6 + 0.6 * kick);\n  vec3 col = inside * la + hc + mix(film, vec3(1.0), 0.6) * rim * 0.55;\n  float solid = max(la, rim * 0.6);\n  gl_FragColor = vjOutPM(vec4(col, solid));\n}\n"},{"id":"fluid-frost","name":"Frosted Pane Clear-Run","category":"fluid","blurb":"The logo starts as a frosted-glass slab; droplets run down it leaving clear trails that sharpen the mark, until it stands fully clear with a glassy rim.","params":[{"name":"uClear","label":"Clear Progress","type":"float","default":1,"min":0,"max":1,"auto":{"on":true,"shape":"pour","rate":0.05,"lo":0,"hi":1},"hint":"0 = fully frosted, 1 = fully clear (rest state). The app runs it as a pour LFO: hold clear, frost over fast, droplets clear it."},{"name":"uFrost","label":"Frost Blur","type":"float","default":0.7,"min":0,"max":1,"hint":"Maximum frost blur radius."},{"name":"uTurbScale","label":"Crystal Size","type":"float","default":3,"min":0.5,"max":12,"hint":"Frost crystal size: scale of the ice veins and of the scatter grain."},{"name":"uLifespan","label":"Run Time","type":"float","default":1.8,"min":0.2,"max":6,"unit":"s","hint":"Droplet run time: how much of the clear cycle each droplet takes to run down."},{"name":"uBounce","label":"Stick-Slip","type":"float","default":0.4,"min":0,"max":1,"hint":"Stick-slip: how much droplets hesitate, lurch and meander as they run."},{"name":"uDamping","label":"Trail Spread","type":"float","default":0.35,"min":0,"max":1,"hint":"Trail spread: higher keeps trails narrow (slower clearing between drops)."},{"name":"uGravityWell","label":"Droplet Gravity","type":"float","default":0.6,"min":0,"max":2,"hint":"Gravity: pulls the droplets down faster and streams extra fast droplets while frost remains; the kick spatters beads and bursts more."},{"name":"uTint","label":"Frost Tint","type":"color","default":[0.82,0.92,1,1]},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Winter Glass","values":{}},{"name":"Steam Mirror","values":{"uTint":[1,0.9,0.8,1],"uFrost":1,"uTurbScale":1.5}},{"name":"Rain Burst","values":{"uGravityWell":1.6,"uLifespan":0.8,"uBounce":0.8,"uDamping":0.1}}],"source":"/*{\n  \"DESCRIPTION\": \"Frosted Pane Clear-Run \u00e2\u20ac\u201d The logo starts as a frosted-glass slab; droplets run down it leaving clear trails that sharpen the mark, until it stands fully clear with a glassy rim.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Particle & Fluid\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uClear\",\"TYPE\":\"float\",\"LABEL\":\"Clear Progress\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uFrost\",\"TYPE\":\"float\",\"LABEL\":\"Frost Blur\",\"DEFAULT\":0.7,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uTurbScale\",\"TYPE\":\"float\",\"LABEL\":\"Crystal Size\",\"DEFAULT\":3,\"MIN\":0.5,\"MAX\":12},\n    {\"NAME\":\"uLifespan\",\"TYPE\":\"float\",\"LABEL\":\"Run Time\",\"DEFAULT\":1.8,\"MIN\":0.2,\"MAX\":6},\n    {\"NAME\":\"uBounce\",\"TYPE\":\"float\",\"LABEL\":\"Stick-Slip\",\"DEFAULT\":0.4,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uDamping\",\"TYPE\":\"float\",\"LABEL\":\"Trail Spread\",\"DEFAULT\":0.35,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uGravityWell\",\"TYPE\":\"float\",\"LABEL\":\"Droplet Gravity\",\"DEFAULT\":0.6,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Frost Tint\",\"DEFAULT\":[0.82,0.92,1,1]},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Frosted Pane Clear-Run \u00c2\u00b7 Particle & Fluid\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nfloat vnoise(vec2 p) {\n  vec2 i = floor(p); vec2 f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x), mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// 25-tap disk coverage of the logo around p (radius r, height-normalized units).\n// x = coverage 0..1 (0.5 on the outline), yz = vector pointing into the logo.\nvec3 logoField(vec2 p, float r) {\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n// Approximate signed distance (positive outside) from a logoField sample of radius r.\nfloat fieldSD(vec3 f, float r) { return (0.5 - f.x) * 2.0 * r; }\n// Edge glow that falls to exactly zero at the field radius r (no full-frame haze floor).\nfloat edgeGlow(float sd, float k, float r) { float f = exp(-r * k); return max(exp(-abs(sd) * k) - f, 0.0) / (1.0 - f); }\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\n// ---- effect ----\n// Vogel-disc frost blur of the logo (12 taps), rotated per frost grain cell for a grainy scatter. Premultiplied.\nvec4 frBlur(vec2 p, float rad, float rot) {\n  vec4 acc = vec4(0.0);\n  for (int i = 0; i < 12; i++) {\n    float fi = float(i);\n    float rr = sqrt((fi + 0.5) / 12.0) * rad;\n    float a = fi * 2.3999632 + rot;\n    vec4 s = logoRGBA(p + vec2(cos(a), sin(a)) * rr);\n    acc += vec4(s.rgb * s.a, s.a);\n  }\n  return acc / 12.0;\n}\n\nfloat frWob(float y, float h) { return (0.3 + 1.7 * uBounce) * 0.006 * (vnoise(vec2(y * 18.0 + h * 40.0, h * 7.0)) - 0.5); }\n\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  float kick = kickN();\n  float P = min(clamp(uClear, 0.0, 1.0) / 0.85, 1.0);\n  // gravity pulls droplets down faster (parameter only, never the bass, so droplets never run backwards)\n  float runP = (0.1 + 0.06 * max(uLifespan, 0.2)) / (0.75 + 0.4 * uGravityWell);\n  float yTop = 0.27; float yBot = -0.29; float H = yTop - yBot;\n  float colW = 0.04;\n  float c0 = floor(p.x / colW);\n  // whatever frost the trails missed evaporates at the end: the rest state is always fully clear\n  float clear = smoothstep(0.86, 0.97, P);\n  float dropM = 0.0; vec2 dOff = vec2(0.0); float spec = 0.0; float dEdge = 0.0; float ridge = 0.0;\n  for (int i = -1; i <= 1; i++) {\n    float ci = c0 + float(i);\n    for (int j = 0; j < 3; j++) {\n      vec3 hj = hash32(vec2(ci * 1.7 + 3.1, float(j) * 5.3 + 1.0));\n      if (j < 2 && hj.x > 0.6) continue;   // skip some columns: no picket fence\n      float burst = float(j == 2);\n      float bvis = 1.0;\n      float u;\n      float dr = (0.012 + 0.008 * hj.z) * mix(0.7, 1.4, uTurbScale / 12.0);\n      if (j < 2) {\n        float s = 0.04 + (float(j) * 0.4 + hj.x * 0.36) * (1.0 - runP) * 0.92;\n        u = (P - s) / runP;\n      } else {\n        // droplet load (Gravity Well): fast droplets stream down while frost remains; the kick bursts more\n        float load = uGravityWell * 0.45 * (1.0 - smoothstep(0.85, 0.97, P));\n        float kv = smoothstep(0.05, 0.35, kick * uGravityWell);\n        if (hj.x > max(load, uGravityWell * 0.5 * kv)) continue;\n        bvis = hj.x < load ? 1.0 : kv;\n        u = fract(t * 0.8 + hj.y);\n        dr *= 0.8;\n      }\n      if (u <= 0.0) continue;\n      float uc = min(u, 1.0);\n      // stick-slip: the droplet hesitates and lurches (uBounce)\n      float lurch = uBounce * 0.3 * sin(uc * 24.0 + hj.y * 6.2831853) * uc;\n      float stopH = burst > 0.5 ? 1.0 : 0.45 + 0.55 * hj.x;\n      float yy = yTop - H * clamp(uc * uc * 0.35 + uc * 0.65 + lurch, 0.0, 1.0) * stopH;\n      float cx = (ci + 0.2 + 0.6 * hj.y) * colW;\n      float dx = p.x - cx - frWob(p.y, hj.z);\n      float vis = bvis;\n      // trail from the top of the pane down to the droplet, widening as it ages\n      float passU = clamp((yTop - p.y) / H, 0.0, 1.0);\n      float age = max(u - passU, 0.0) * runP;\n      float tw = dr * (0.35 + (1.0 - uDamping) * 1.6 * min(age / 0.6, 1.0)) * (1.0 + 0.3 * uGravityWell);\n      float inTrail = step(yy, p.y) * step(p.y, yTop) * vis;\n      float trail = (1.0 - smoothstep(tw * 0.75, tw, abs(dx))) * inTrail;\n      clear = max(clear, trail * (burst > 0.5 ? 0.8 : 1.0));\n      ridge = max(ridge, exp(-pow((abs(dx) - tw * 0.85) / 0.0018, 2.0)) * inTrail);\n      if (u < 1.0) {\n        vec2 dp = p - vec2(cx + frWob(yy, hj.z), yy);\n        dp.y *= dp.y > 0.0 ? 0.6 : 1.0;\n        float dd = length(dp) / dr;\n        float m = (1.0 - smoothstep(0.8, 1.0, dd)) * vis;\n        if (m > dropM) {\n          dropM = m;\n          dOff = -dp * 0.7;\n          vec2 sq = dp / dr - vec2(-0.32, 0.38);\n          spec = exp(-dot(sq, sq) * 16.0);\n          dEdge = smoothstep(0.5, 0.97, dd);\n        }\n      }\n    }\n  }\n  // kick spray: a burst of small beads spatters the pane while the bass is up (Gravity Well)\n  float spray = clamp(kick * uGravityWell, 0.0, 1.5);\n  vec2 bc = floor(p / 0.034);\n  vec3 bh = hash32(bc + 17.0);\n  vec2 bp = (bc + 0.25 + 0.5 * bh.xy) * 0.034;\n  // beads land on the ink only: off the letters they would read as dark specks of dirt\n  if (bh.z < spray * 0.6 && logoP(bp) > 0.5) {\n    vec2 dp = p - bp;\n    float dd = length(dp) / (0.0045 + 0.0035 * bh.x);\n    float m = 1.0 - smoothstep(0.75, 1.0, dd);\n    clear = max(clear, m * 0.9);\n    if (m > dropM) {\n      dropM = m; dOff = -dp * 0.9;\n      vec2 sq = dp / (0.0045 + 0.0035 * bh.x) - vec2(-0.3, 0.35);\n      spec = exp(-dot(sq, sq) * 10.0);\n      dEdge = smoothstep(0.4, 0.95, dd);\n    }\n  }\n  clear = clamp(clear, 0.0, 1.0);\n  float rot = hash12(floor(isf_FragNormCoord * RENDERSIZE)) * 6.2831853;\n  // the kick shivers the pane: frost scatter swells for a moment\n  float rad = uFrost * 0.055 * (1.0 - clear) * (1.0 + 0.45 * kick);\n  vec4 bl = frBlur(p, rad, rot);\n  vec4 sh = logoRGBA(p + dOff * dropM);\n  vec4 shp = vec4(sh.rgb * sh.a, sh.a);\n  // frost: scattering lifts the logo toward the tint, with ridged ice veins that glint on the kick\n  float cs = 16.0 + 26.0 * uTurbScale;\n  vec2 pv = vec2(p.x * cs * 0.6, p.y * cs * 1.4) + vec2(sin(p.y * 40.0) * 0.3, 0.0);\n  float vein = pow(1.0 - abs(2.0 * vnoise(pv) - 1.0), 5.0) * 0.65 + pow(1.0 - abs(2.0 * vnoise(pv * 2.3 + 7.1) - 1.0), 7.0) * 0.35;\n  float crys = vein * 0.7 + vnoise(p * cs * 4.0) * 0.3;\n  vec3 frostC = mix(vec3(0.92, 0.95, 1.0), uTint.rgb, 0.72);\n  vec4 frosted = vec4(bl.rgb * 0.5 + frostC * bl.a * (0.28 + 0.34 * crys), bl.a * (0.66 + 0.24 * crys));\n  frosted.rgb += frostC * bl.a * vein * 0.38 * (1.0 + 2.0 * kick);\n  float fr = (1.0 - clear) * smoothstep(0.0, 0.08, uFrost);\n  vec4 col = mix(shp, frosted, fr);\n  // water ridge along the trail edges (catches light where the trail meets the frost)\n  col.rgb += frostC * ridge * fr * bl.a * 0.55;\n  // droplets: a clear lens onto the sharp logo + water body + specular + refraction-dark rim\n  float pane = max(bl.a, sh.a);\n  float dm = dropM * smoothstep(0.05, 0.3, pane);\n  vec3 water = shp.rgb * 1.1 + frostC * (1.0 - sh.a) * 0.22 * pane;\n  col.rgb = mix(col.rgb, water, dm);\n  col.rgb *= 1.0 - dEdge * dm * 0.6 * sh.a;\n  col.rgb += frostC * dEdge * dm * 0.25 * (1.0 - sh.a) * pane;\n  col.rgb += vec3(1.0) * spec * dm;\n  col.a = mix(col.a, max(sh.a, 0.3 * pane), dm);\n  col.a = max(col.a, spec * dm);\n  // glassy rim on the cleared letterforms: lit top-left edge, shaded bottom-right edge\n  vec3 Fr = logoField(p, 0.012);\n  vec2 gdir = length(Fr.yz) > 0.0001 ? normalize(Fr.yz) : vec2(0.0);\n  float bev = 4.0 * Fr.x * (1.0 - Fr.x);\n  float lit = dot(-gdir, normalize(vec2(-0.6, 0.8)));\n  float sweep = exp(-pow(dot(p, vec2(0.8, 0.6)) - mix(-1.2, 1.2, fract(t * 0.15)), 2.0) / 0.006);\n  vec3 rimC = mix(vec3(1.0), uTint.rgb, 0.6);\n  float cl = clear * sh.a;\n  col.rgb *= 1.0 - 0.45 * pow(bev, 1.2) * max(-lit, 0.0) * cl;\n  col.rgb += rimC * pow(bev, 1.3) * max(lit, 0.0) * (1.1 + 0.8 * kick) * cl;\n  col.rgb += rimC * sweep * 0.22 * cl;\n  gl_FragColor = vjOutPM(col);\n}\n"},{"id":"metal-chrome","name":"Raymarching Chrome Extrusion","category":"metal","blurb":"Ray-marches the logo as an extruded solid with rounded bevels and studio reflections.","params":[{"name":"uDepth","label":"Extrusion Depth","type":"float","default":0.08,"min":0,"max":0.25,"hint":"Extrusion depth; the kick deepens it."},{"name":"uRoughness","label":"Metallic Roughness","type":"float","default":0.15,"min":0,"max":1},{"name":"uFresnel","label":"Fresnel Rim Light","type":"float","default":1.2,"min":0,"max":3},{"name":"uBevel","label":"Bevel Radius","type":"float","default":0.012,"min":0.002,"max":0.04},{"name":"uOrbit","label":"Camera Orbit Speed","type":"float","default":0.4,"min":0,"max":2,"hint":"Camera rock speed (and the light band / env spin)."},{"name":"uTint","label":"Material Tint","type":"color","default":[0.92,0.95,1,1]},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Mirror Chrome","values":{}},{"name":"Brushed Gold","values":{"uTint":[1,0.8,0.45,1],"uRoughness":0.35}},{"name":"Deep Gunmetal","values":{"uTint":[0.45,0.5,0.58,1],"uDepth":0.16,"uFresnel":2.2}}],"source":"/*{\n  \"DESCRIPTION\": \"Raymarching Chrome Extrusion \u00e2\u20ac\u201d Ray-marches the logo as an extruded solid with rounded bevels and studio reflections.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"3D Volumetric & Metallurgic\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uDepth\",\"TYPE\":\"float\",\"LABEL\":\"Extrusion Depth\",\"DEFAULT\":0.08,\"MIN\":0,\"MAX\":0.25},\n    {\"NAME\":\"uRoughness\",\"TYPE\":\"float\",\"LABEL\":\"Metallic Roughness\",\"DEFAULT\":0.15,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uFresnel\",\"TYPE\":\"float\",\"LABEL\":\"Fresnel Rim Light\",\"DEFAULT\":1.2,\"MIN\":0,\"MAX\":3},\n    {\"NAME\":\"uBevel\",\"TYPE\":\"float\",\"LABEL\":\"Bevel Radius\",\"DEFAULT\":0.012,\"MIN\":0.002,\"MAX\":0.04},\n    {\"NAME\":\"uOrbit\",\"TYPE\":\"float\",\"LABEL\":\"Camera Orbit Speed\",\"DEFAULT\":0.4,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Material Tint\",\"DEFAULT\":[0.92,0.95,1,1]},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Raymarching Chrome Extrusion \u00c2\u00b7 3D Volumetric & Metallurgic\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nmat2 rot2(float a) { float c = cos(a); float s = sin(a); return mat2(c, -s, s, c); }\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// 25-tap disk coverage of the logo around p (radius r, height-normalized units).\n// x = coverage 0..1 (0.5 on the outline), yz = vector pointing into the logo.\nvec3 logoField(vec2 p, float r) {\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n// Approximate signed distance (positive outside) from a logoField sample of radius r.\nfloat fieldSD(vec3 f, float r) { return (0.5 - f.x) * 2.0 * r; }\n// Edge glow that falls to exactly zero at the field radius r (no full-frame haze floor).\nfloat edgeGlow(float sd, float k, float r) { float f = exp(-r * k); return max(exp(-abs(sd) * k) - f, 0.0) / (1.0 - f); }\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\nfloat logoCov5(vec2 p, float r) {\n  return (logoP(p) + logoP(p + vec2(r, 0.0)) + logoP(p - vec2(r, 0.0)) + logoP(p + vec2(0.0, r)) + logoP(p - vec2(0.0, r))) * 0.2;\n}\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\n// Procedural studio environment for chrome / glass / crystal: four off-axis strip lights at mixed elevations\n// (a flat face sees a horizon split instead of one value that flips dark/bright), energy-normalised roughness\n// (rougher = wider lobes, not brighter), top key, horizon line, dark floor. Peaks ~2.0; callers tonemap.\nvec3 studioEnv(vec3 d, float rough, float spin) {\n  d = normalize(d);\n  d.xz = rot2(spin) * d.xz;\n  float y = d.y;\n  float az = atan(d.x, d.z);\n  float k = mix(40.0, 3.0, rough);\n  float norm = (k + 1.0) / 41.0;\n  vec3 sky = mix(vec3(0.08, 0.09, 0.11), vec3(0.75, 0.8, 0.88), smoothstep(-0.1, 0.8, y));\n  float l1 = pow(max(cos(az - 0.3) * cos((y - 0.15) * 1.6), 0.0), k);\n  float l2 = pow(max(cos(az - 2.4) * cos((y - 0.35) * 1.6), 0.0), k * 0.7);\n  float l3 = pow(max(cos(az + 1.9) * cos((y + 0.05) * 1.6), 0.0), k * 1.3);\n  float l4 = pow(max(cos(az + 3.0) * cos((y - 0.5) * 1.6), 0.0), k * 0.5);\n  float strips = norm * (1.6 * l1 + 1.25 * l2 + 1.1 * l3 + 0.8 * l4);\n  float top = pow(max(y, 0.0), mix(24.0, 2.0, rough)) * mix(1.0, 0.35, rough);\n  float hor = exp(-abs(y) * mix(40.0, 6.0, rough));\n  vec3 col = sky * 0.5 + vec3(1.0, 0.98, 0.95) * strips * 1.5 + vec3(2.0, 1.9, 1.75) * top + vec3(0.7, 0.8, 0.95) * hor;\n  float ground = 1.0 - smoothstep(-0.25, 0.0, y);\n  return mix(col, vec3(0.025, 0.025, 0.03) + hor * 0.2, ground);\n}\n\n// ---- effect ----\n// Extruded chrome: front faces get wide convexity (so a stem shows a horizon split instead of one env value),\n// walls take their direction from a 10-tap field instead of a 1 px finite difference (no stipple), the brand\n// colour survives as an anodised accent on saturated regions, a light band travels across, kick deepens the\n// extrusion and pumps the scale, and a soft shoulder keeps highlights from clipping to paper white.\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  float kick = kickN();\n  float px = 1.0 / RENDERSIZE.y;\n  float ang = t * uOrbit;\n  vec2 tilt = vec2(sin(ang) * 0.4, 0.25 + sin(ang * 0.63) * 0.2);\n  float depth = uDepth * (1.0 + 0.8 * kick);\n  vec2 ps = p / (1.0 + 0.03 * kick);\n  vec2 base = ps + tilt * depth * 0.5;\n  float stepZ = depth / 47.0;\n  float hitZ = -1.0;\n  float near = logoCov5(ps, 0.12);\n  vec3 col = vec3(0.0);\n  float solid = 0.0;\n  if (near > 0.001) {\n    for (int i = 0; i < 48; i++) {\n      float z = stepZ * float(i);\n      if (logoP(base - tilt * z) > 0.5) { hitZ = z; break; }\n    }\n  }\n  if (hitZ >= 0.0) {\n    vec3 V = normalize(vec3(-tilt * 0.6 - ps * 0.9, 1.0));\n    vec2 hp = base - tilt * hitZ;\n    vec3 n;\n    bool front = hitZ < stepZ * 0.5;\n    if (front) {\n      vec3 F = logoField(hp, uBevel);\n      vec3 Fw = logoField(hp, 0.045);\n      vec2 dir = length(F.yz) > 0.0001 ? normalize(F.yz) : vec2(0.0);\n      float slope = 4.0 * F.x * (1.0 - F.x);\n      n = normalize(vec3(-dir * slope * 1.5 - Fw.yz * 0.05, 1.0));\n      solid = smoothstep(0.35, 0.65, logoP(base));\n    } else {\n      vec3 Fw = logoField(hp, 0.01);\n      vec2 dir = length(Fw.yz) > 0.0001 ? -normalize(Fw.yz) : -normalize(tilt);\n      dir = normalize(mix(dir, -normalize(tilt), 0.3));\n      n = normalize(vec3(dir, 0.2));\n      solid = 1.0;\n    }\n    vec3 R = reflect(-V, n);\n    vec3 env = studioEnv(R, uRoughness, ang * 0.5);\n    float fres = pow(1.0 - clamp(dot(n, V), 0.0, 1.0), 5.0);\n    col = env * mix(vec3(1.0), uTint.rgb, 0.65);\n    vec3 L = normalize(vec3(-0.5 + sin(ang) * 0.4, 0.7, 0.6));\n    float spec = pow(max(dot(reflect(-L, n), V), 0.0), mix(120.0, 8.0, uRoughness));\n    if (!front) spec = min(spec, 0.5);\n    col += vec3(1.0) * spec * (1.0 - uRoughness * 0.6) * (1.0 + uHigh * aud);\n    if (!front) col *= 0.55 + 0.45 * (1.0 - hitZ / max(depth, 0.0001));\n    col += uTint.rgb * fres * uFresnel * 0.6;\n    // travelling light band\n    float band = exp(-pow((hp.x * 0.8 + hp.y * 0.5 - (fract(t * 0.22) * 2.4 - 1.2)) * 9.0, 2.0));\n    col += band * (0.5 + 0.8 * fres) * mix(vec3(1.0), uTint.rgb, 0.3);\n    // brand colour as an anodised accent on saturated logo regions (the emblem keeps its gradient)\n    vec4 lg = logoRGBA(hp);\n    float sat = max(lg.r, max(lg.g, lg.b)) - min(lg.r, min(lg.g, lg.b));\n    col = mix(col, col * (0.4 + 1.6 * lg.rgb), smoothstep(0.15, 0.5, sat) * lg.a);\n    col = 1.0 - exp(-col * 1.25);\n  }\n  gl_FragColor = vjOut(col * solid, solid);\n}\n"},{"id":"metal-glass","name":"Glass Refraction Bevels","category":"metal","blurb":"A beveled glass slab refracts a moving light field with chromatic dispersion and caustics.","params":[{"name":"uDepth","label":"Glass Thickness","type":"float","default":0.08,"min":0,"max":0.25,"hint":"Refraction strength (ior); the kick pumps it."},{"name":"uRoughness","label":"Frost","type":"float","default":0.15,"min":0,"max":1,"hint":"Softens the refracted stripes."},{"name":"uFresnel","label":"Fresnel Rim Light","type":"float","default":1.2,"min":0,"max":3},{"name":"uBevel","label":"Bevel Radius","type":"float","default":0.012,"min":0.002,"max":0.04},{"name":"uOrbit","label":"Backdrop Drift","type":"float","default":0.4,"min":0,"max":2},{"name":"uTint","label":"Material Tint","type":"color","default":[0.55,0.85,1,1]},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Crystal Clear","values":{}},{"name":"Rose Glass","values":{"uTint":[1,0.5,0.75,1],"uDepth":0.14}},{"name":"Frosted","values":{"uRoughness":0.75,"uBevel":0.03}}],"source":"/*{\n  \"DESCRIPTION\": \"Glass Refraction Bevels \u00e2\u20ac\u201d A beveled glass slab refracts a moving light field with chromatic dispersion and caustics.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"3D Volumetric & Metallurgic\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uDepth\",\"TYPE\":\"float\",\"LABEL\":\"Glass Thickness\",\"DEFAULT\":0.08,\"MIN\":0,\"MAX\":0.25},\n    {\"NAME\":\"uRoughness\",\"TYPE\":\"float\",\"LABEL\":\"Frost\",\"DEFAULT\":0.15,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uFresnel\",\"TYPE\":\"float\",\"LABEL\":\"Fresnel Rim Light\",\"DEFAULT\":1.2,\"MIN\":0,\"MAX\":3},\n    {\"NAME\":\"uBevel\",\"TYPE\":\"float\",\"LABEL\":\"Bevel Radius\",\"DEFAULT\":0.012,\"MIN\":0.002,\"MAX\":0.04},\n    {\"NAME\":\"uOrbit\",\"TYPE\":\"float\",\"LABEL\":\"Backdrop Drift\",\"DEFAULT\":0.4,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Material Tint\",\"DEFAULT\":[0.55,0.85,1,1]},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Glass Refraction Bevels \u00c2\u00b7 3D Volumetric & Metallurgic\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nfloat vnoise(vec2 p) {\n  vec2 i = floor(p); vec2 f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x), mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nfloat fbm(vec2 p) {\n  float a = 0.5; float s = 0.0;\n  for (int i = 0; i < 5; i++) { s += a * vnoise(p); p = p * 2.03 + vec2(17.1, 9.2); a *= 0.5; }\n  return s / 0.96875;\n}\n\n// 3-octave fbm: cheaper sibling of fbm() for nested domain warps.\nfloat fbm3(vec2 p) {\n  float a = 0.5; float s = 0.0;\n  for (int i = 0; i < 3; i++) { s += a * vnoise(p); p = p * 2.03 + vec2(17.1, 9.2); a *= 0.5; }\n  return s / 0.875;\n}\n\nmat2 rot2(float a) { float c = cos(a); float s = sin(a); return mat2(c, -s, s, c); }\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// 25-tap disk coverage of the logo around p (radius r, height-normalized units).\n// x = coverage 0..1 (0.5 on the outline), yz = vector pointing into the logo.\nvec3 logoField(vec2 p, float r) {\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n// Approximate signed distance (positive outside) from a logoField sample of radius r.\nfloat fieldSD(vec3 f, float r) { return (0.5 - f.x) * 2.0 * r; }\n// Edge glow that falls to exactly zero at the field radius r (no full-frame haze floor).\nfloat edgeGlow(float sd, float k, float r) { float f = exp(-r * k); return max(exp(-abs(sd) * k) - f, 0.0) / (1.0 - f); }\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\n// Procedural studio environment for chrome / glass / crystal: four off-axis strip lights at mixed elevations\n// (a flat face sees a horizon split instead of one value that flips dark/bright), energy-normalised roughness\n// (rougher = wider lobes, not brighter), top key, horizon line, dark floor. Peaks ~2.0; callers tonemap.\nvec3 studioEnv(vec3 d, float rough, float spin) {\n  d = normalize(d);\n  d.xz = rot2(spin) * d.xz;\n  float y = d.y;\n  float az = atan(d.x, d.z);\n  float k = mix(40.0, 3.0, rough);\n  float norm = (k + 1.0) / 41.0;\n  vec3 sky = mix(vec3(0.08, 0.09, 0.11), vec3(0.75, 0.8, 0.88), smoothstep(-0.1, 0.8, y));\n  float l1 = pow(max(cos(az - 0.3) * cos((y - 0.15) * 1.6), 0.0), k);\n  float l2 = pow(max(cos(az - 2.4) * cos((y - 0.35) * 1.6), 0.0), k * 0.7);\n  float l3 = pow(max(cos(az + 1.9) * cos((y + 0.05) * 1.6), 0.0), k * 1.3);\n  float l4 = pow(max(cos(az + 3.0) * cos((y - 0.5) * 1.6), 0.0), k * 0.5);\n  float strips = norm * (1.6 * l1 + 1.25 * l2 + 1.1 * l3 + 0.8 * l4);\n  float top = pow(max(y, 0.0), mix(24.0, 2.0, rough)) * mix(1.0, 0.35, rough);\n  float hor = exp(-abs(y) * mix(40.0, 6.0, rough));\n  vec3 col = sky * 0.5 + vec3(1.0, 0.98, 0.95) * strips * 1.5 + vec3(2.0, 1.9, 1.75) * top + vec3(0.7, 0.8, 0.95) * hor;\n  float ground = 1.0 - smoothstep(-0.25, 0.0, y);\n  return mix(col, vec3(0.025, 0.025, 0.03) + hor * 0.2, ground);\n}\n\n// ---- effect ----\n// Beveled glass slab: a wide thickness normal makes the whole stroke refract the backdrop (stroke-scale stripes),\n// a bright caustic network instead of posterised rings, a desaturated second tint stop (no channel-rotation hues),\n// real translucency through premultiplied output, dispersion wide enough to see, and the kick drives ior / stripe speed.\nvec3 glassBackdrop(vec2 q, float t, float rough, float kick) {\n  float bars = pow(0.5 + 0.5 * sin(q.x * 10.0 + q.y * 3.0 + t * 2.4 + kick * 1.5), mix(16.0, 3.0, rough));\n  float dots = 1.0 - smoothstep(0.0, 0.35, length(fract(q * 14.0) - 0.5));\n  vec3 t2 = mix(uTint.rgb, vec3(dot(uTint.rgb, vec3(0.333))), 0.6);\n  vec3 grad = mix(uTint.rgb * 0.45, t2 * 0.42 + 0.04, 0.5 + 0.5 * sin(q.y * 3.0 + t * 0.3));\n  return grad + vec3(1.0) * bars * 0.9 + uTint.rgb * dots * 0.25 * (1.0 - rough);\n}\n\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  float kick = kickN();\n  float px = 1.0 / RENDERSIZE.y;\n  float r = uBevel * 2.0 + 0.004;\n  vec3 F = logoField(p, r);\n  vec3 Fw = logoField(p, 0.05);\n  float la = logoP(p);\n  vec2 dir = length(F.yz) > 0.0001 ? normalize(F.yz) : vec2(0.0);\n  float slope = 4.0 * F.x * (1.0 - F.x);\n  vec3 n = normalize(vec3(-dir * slope * (1.0 + uDepth * 10.0) - Fw.yz * 0.05 * (1.0 + uDepth * 8.0), 1.0));\n  vec2 q = p + vec2(t * 0.15 * uOrbit, 0.0);\n  float ior = (0.24 + uDepth * 1.8) * (1.0 + 0.8 * kick);\n  float disp = 0.35;\n  vec3 refr = vec3(\n    glassBackdrop(q + n.xy * ior * (1.0 + disp), t, uRoughness, kick).r,\n    glassBackdrop(q + n.xy * ior, t, uRoughness, kick).g,\n    glassBackdrop(q + n.xy * ior * (1.0 - disp), t, uRoughness, kick).b);\n  vec3 R = reflect(vec3(0.0, 0.0, -1.0), n);\n  vec3 env = studioEnv(R, uRoughness, t * uOrbit * 0.3);\n  float fres = pow(1.0 - n.z, 2.0) * uFresnel;\n  vec3 glass = refr * mix(vec3(1.0), uTint.rgb, 0.35) + env * (0.08 + fres * 1.4);\n  glass += mix(vec3(1.0), uTint.rgb, 0.4) * pow(slope, 3.0) * 0.5 * uFresnel * (1.0 + uHigh * aud);\n  // diagonal sheen sweeping every ~5 s\n  float sw = fract(t * 0.2) * 2.6 - 1.3;\n  glass += vec3(1.0) * exp(-pow((dot(p, vec2(0.8, 0.6)) - sw) * 10.0, 2.0)) * 0.35;\n  glass = 1.0 - exp(-glass * 1.3);\n  float a = la * (0.3 + 0.7 * clamp(fres + slope, 0.0, 1.0));\n  vec3 col = glass * a;\n  // caustic: a bright network cast down-right (not contour rings)\n  vec3 Fs = logoField(p + vec2(-0.012, 0.02), 0.035);\n  float caus = pow(1.0 - abs(2.0 * Fs.x - 1.0), 2.0) * (0.5 + 0.5 * fbm3(q * 9.0 + t)) * (1.0 - la) * 0.6 * (1.0 + 0.6 * kick);\n  col += uTint.rgb * caus;\n  gl_FragColor = vjOutPM(vec4(col, max(a, caus)));\n}\n"},{"id":"metal-holo","name":"Holographic Wireframe CAD","category":"metal","blurb":"Contour-stacked wireframe of the extruded logo with a depth scan, CAD brackets and floor grid.","params":[{"name":"uDepth","label":"Slice Depth","type":"float","default":0.08,"min":0,"max":0.25,"hint":"Spacing of the stacked wireframe slices; the kick deepens it."},{"name":"uRoughness","label":"Line Softness","type":"float","default":0.15,"min":0,"max":1},{"name":"uFresnel","label":"Brightness","type":"float","default":1.2,"min":0,"max":3},{"name":"uBevel","label":"Line Weight","type":"float","default":0.012,"min":0.002,"max":0.04},{"name":"uOrbit","label":"Camera Orbit Speed","type":"float","default":0.4,"min":0,"max":2},{"name":"uTint","label":"Material Tint","type":"color","default":[0.25,0.95,1,1]},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Blueprint Holo","values":{}},{"name":"Amber Terminal","values":{"uTint":[1,0.7,0.2,1],"uOrbit":0.2}},{"name":"Deep Scan","values":{"uDepth":0.22,"uFresnel":2.4,"uOrbit":0.8}}],"source":"/*{\n  \"DESCRIPTION\": \"Holographic Wireframe CAD \u00e2\u20ac\u201d Contour-stacked wireframe of the extruded logo with a depth scan, CAD brackets and floor grid.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"3D Volumetric & Metallurgic\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uDepth\",\"TYPE\":\"float\",\"LABEL\":\"Slice Depth\",\"DEFAULT\":0.08,\"MIN\":0,\"MAX\":0.25},\n    {\"NAME\":\"uRoughness\",\"TYPE\":\"float\",\"LABEL\":\"Line Softness\",\"DEFAULT\":0.15,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uFresnel\",\"TYPE\":\"float\",\"LABEL\":\"Brightness\",\"DEFAULT\":1.2,\"MIN\":0,\"MAX\":3},\n    {\"NAME\":\"uBevel\",\"TYPE\":\"float\",\"LABEL\":\"Line Weight\",\"DEFAULT\":0.012,\"MIN\":0.002,\"MAX\":0.04},\n    {\"NAME\":\"uOrbit\",\"TYPE\":\"float\",\"LABEL\":\"Camera Orbit Speed\",\"DEFAULT\":0.4,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Material Tint\",\"DEFAULT\":[0.25,0.95,1,1]},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Holographic Wireframe CAD \u00c2\u00b7 3D Volumetric & Metallurgic\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\nfloat logoCov5(vec2 p, float r) {\n  return (logoP(p) + logoP(p + vec2(r, 0.0)) + logoP(p - vec2(r, 0.0)) + logoP(p + vec2(0.0, r)) + logoP(p - vec2(0.0, r))) * 0.2;\n}\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\n// ---- effect ----\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  float kick = kickN();\n  float px = 1.0 / RENDERSIZE.y;\n  float ang = t * uOrbit;\n  vec2 tilt = vec2(clamp(sin(ang) * 0.7, -0.4, 0.4), 0.3 + 0.15 * sin(ang * 0.7));\n  float depth = (uDepth * 1.2 + 0.02) * (1.0 + 0.8 * kick);\n  vec3 tint = uTint.rgb;\n  float lw = max(0.0022 + uBevel * 0.12, 1.2 * px);\n  float soft = mix(0.9, 0.5, uRoughness);\n  vec3 col = vec3(0.0);\n  float scanZ = fract(t * 0.35);\n  for (int k = 0; k < 10; k++) {\n    float fk = float(k) / 9.0;\n    vec2 q = p + tilt * depth * (fk - 0.5);\n    float edge = smoothstep(0.1, soft, 1.0 - abs(logoCov5(q, lw) * 2.0 - 1.0));\n    // one readable front face (weight 1.5), faint stacked slices behind it with a depth cue\n    float w = (k == 0) ? 1.5 : 0.15 * mix(1.0, 0.45, fk);\n    w += exp(-abs(fk - scanZ) * 25.0) * 1.0;\n    col += tint * edge * w;\n  }\n  // front slice: slight R/B dispersion on the edges + a bloom\n  vec2 qf = p - tilt * depth * 0.5;\n  float eR = 1.0 - abs(logoCov5(qf + vec2(0.0012, 0.0), lw) * 2.0 - 1.0);\n  float eB = 1.0 - abs(logoCov5(qf - vec2(0.0012, 0.0), lw) * 2.0 - 1.0);\n  col += vec3(smoothstep(0.1, soft, eR), 0.0, smoothstep(0.1, soft, eB)) * 0.25;\n  col += tint * logoCov5(qf, 0.01) * 0.2;\n  float hatch = smoothstep(0.6, 0.9, abs(fract((p.x + p.y) * 90.0) - 0.5) * 2.0);\n  col += tint * logoP(qf) * hatch * 0.12;\n  // brand colour accent on saturated regions (the emblem)\n  vec4 lg = logoRGBA(qf);\n  float sat = max(lg.r, max(lg.g, lg.b)) - min(lg.r, min(lg.g, lg.b));\n  col = mix(col, col * (0.3 + 1.7 * lg.rgb), smoothstep(0.15, 0.5, sat) * lg.a * 0.8);\n  float hy = -0.33;\n  if (p.y < hy) {\n    float zf = 0.12 / (hy - p.y + 0.002);\n    vec2 gp = vec2(p.x * zf, zf + t * 0.5 * uOrbit);\n    vec2 gq = abs(fract(gp * 2.0) - 0.5);\n    float line = 1.0 - smoothstep(0.0, 0.03 * zf, min(gq.x, gq.y));\n    float foot = zf * zf * 16.7 * px;\n    line *= 1.0 - smoothstep(0.3, 0.7, foot);\n    col += tint * line * 0.35 * exp(-zf * 0.12);\n  }\n  vec2 b = vec2(0.62, 0.36);\n  vec2 dc = b - abs(p);\n  if (dc.x > -0.002 && dc.y > -0.002 && dc.x < 0.06 && dc.y < 0.06) {\n    float br = max(1.0 - smoothstep(0.0015, 0.003, abs(dc.x)), 1.0 - smoothstep(0.0015, 0.003, abs(dc.y)));\n    col += tint * br * 0.8;\n  }\n  float tick = step(abs(fract(p.x * 25.0) - 0.5), 0.04) * step(abs(p.y + b.y + 0.025), 0.006) * step(abs(p.x), b.x);\n  col += tint * tick * 0.5;\n  float scan = 0.84 + 0.16 * sin(uv.y * RENDERSIZE.y * 1.5707963);\n  float flick = 0.92 + 0.08 * hash11(floor(t * 24.0));\n  col *= scan * flick * (0.75 + uFresnel * 0.25);\n  gl_FragColor = vjOut(col, 0.0);\n}\n"},{"id":"metal-crystal","name":"Crystal Growth Matrix","category":"metal","blurb":"Faceted gem cells nucleate across the logo, catching glints in a rotating studio light.","params":[{"name":"uCrystal","label":"Growth Progress","type":"float","default":1,"min":0,"max":1,"auto":{"on":true,"shape":"tri","rate":0.07,"lo":0,"hi":1}},{"name":"uDepth","label":"Facet Tilt","type":"float","default":0.08,"min":0,"max":0.25},{"name":"uRoughness","label":"Facet Frost","type":"float","default":0.15,"min":0,"max":1},{"name":"uFresnel","label":"Facet Rim","type":"float","default":1.2,"min":0,"max":3},{"name":"uBevel","label":"Facet Border","type":"float","default":0.012,"min":0.002,"max":0.04,"hint":"Border line and dark crease width."},{"name":"uOrbit","label":"Facet Spin","type":"float","default":0.4,"min":0,"max":2,"hint":"Rotates every facet (the glints wander)."},{"name":"uTint","label":"Gem Tint","type":"color","default":[0.7,0.85,1,1]},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Diamond","values":{}},{"name":"Amethyst","values":{"uTint":[0.75,0.45,1,1],"uDepth":0.12}},{"name":"Emerald Frost","values":{"uTint":[0.3,1,0.6,1],"uRoughness":0.5}}],"source":"/*{\n  \"DESCRIPTION\": \"Crystal Growth Matrix \u00e2\u20ac\u201d Faceted gem cells nucleate across the logo, catching glints in a rotating studio light.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"3D Volumetric & Metallurgic\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uCrystal\",\"TYPE\":\"float\",\"LABEL\":\"Growth Progress\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uDepth\",\"TYPE\":\"float\",\"LABEL\":\"Facet Tilt\",\"DEFAULT\":0.08,\"MIN\":0,\"MAX\":0.25},\n    {\"NAME\":\"uRoughness\",\"TYPE\":\"float\",\"LABEL\":\"Facet Frost\",\"DEFAULT\":0.15,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uFresnel\",\"TYPE\":\"float\",\"LABEL\":\"Facet Rim\",\"DEFAULT\":1.2,\"MIN\":0,\"MAX\":3},\n    {\"NAME\":\"uBevel\",\"TYPE\":\"float\",\"LABEL\":\"Facet Border\",\"DEFAULT\":0.012,\"MIN\":0.002,\"MAX\":0.04},\n    {\"NAME\":\"uOrbit\",\"TYPE\":\"float\",\"LABEL\":\"Facet Spin\",\"DEFAULT\":0.4,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Gem Tint\",\"DEFAULT\":[0.7,0.85,1,1]},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Crystal Growth Matrix \u00c2\u00b7 3D Volumetric & Metallurgic\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nmat2 rot2(float a) { float c = cos(a); float s = sin(a); return mat2(c, -s, s, c); }\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\n// Procedural studio environment for chrome / glass / crystal: four off-axis strip lights at mixed elevations\n// (a flat face sees a horizon split instead of one value that flips dark/bright), energy-normalised roughness\n// (rougher = wider lobes, not brighter), top key, horizon line, dark floor. Peaks ~2.0; callers tonemap.\nvec3 studioEnv(vec3 d, float rough, float spin) {\n  d = normalize(d);\n  d.xz = rot2(spin) * d.xz;\n  float y = d.y;\n  float az = atan(d.x, d.z);\n  float k = mix(40.0, 3.0, rough);\n  float norm = (k + 1.0) / 41.0;\n  vec3 sky = mix(vec3(0.08, 0.09, 0.11), vec3(0.75, 0.8, 0.88), smoothstep(-0.1, 0.8, y));\n  float l1 = pow(max(cos(az - 0.3) * cos((y - 0.15) * 1.6), 0.0), k);\n  float l2 = pow(max(cos(az - 2.4) * cos((y - 0.35) * 1.6), 0.0), k * 0.7);\n  float l3 = pow(max(cos(az + 1.9) * cos((y + 0.05) * 1.6), 0.0), k * 1.3);\n  float l4 = pow(max(cos(az + 3.0) * cos((y - 0.5) * 1.6), 0.0), k * 0.5);\n  float strips = norm * (1.6 * l1 + 1.25 * l2 + 1.1 * l3 + 0.8 * l4);\n  float top = pow(max(y, 0.0), mix(24.0, 2.0, rough)) * mix(1.0, 0.35, rough);\n  float hor = exp(-abs(y) * mix(40.0, 6.0, rough));\n  vec3 col = sky * 0.5 + vec3(1.0, 0.98, 0.95) * strips * 1.5 + vec3(2.0, 1.9, 1.75) * top + vec3(0.7, 0.8, 0.95) * hor;\n  float ground = 1.0 - smoothstep(-0.25, 0.0, y);\n  return mix(col, vec3(0.025, 0.025, 0.03) + hor * 0.2, ground);\n}\n\n// ---- effect ----\nvec4 voro(vec2 x, out vec2 second) {\n  vec2 n = floor(x); vec2 f = fract(x);\n  float d1 = 8.0; float d2 = 8.0; vec2 best = vec2(0.0); second = vec2(0.0);\n  for (int j = -1; j <= 1; j++) {\n    for (int i = -1; i <= 1; i++) {\n      vec2 g = vec2(float(i), float(j));\n      vec2 o = hash22(n + g);\n      vec2 rr = g + o - f;\n      float d = dot(rr, rr);\n      if (d < d1) { d2 = d1; second = best; d1 = d; best = n + g + o; }\n      else if (d < d2) { d2 = d; second = n + g + o; }\n    }\n  }\n  return vec4(best, sqrt(d1), sqrt(d2));\n}\n\n// Faceted crystal: each cell is a facet tilted toward its nearest neighbour (real relief), lit by a 3-sample\n// spectral dispersion of the studio env (physical colour fringes, not a per-cell hash hue), with a tone curve\n// so a few facets go hot while others stay dark. Cells grow from a nucleus front and shrink toward their seed.\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  float kick = kickN();\n  float px = 1.0 / RENDERSIZE.y;\n  float sc = 28.0;\n  vec2 seed2;\n  vec4 v = voro(p * sc, seed2);\n  vec2 cc = v.xy / sc;\n  float edgeD = (v.w - v.z) / sc;\n  vec3 h = hash32(floor(v.xy * 7.0));\n  float inCell = logoP(cc);\n  float la = logoP(p);\n  float g = clamp(uCrystal, 0.0, 1.0);\n  // growth front from a nucleus (left-bottom) with a little randomness; cells shrink toward their seed before that\n  float order = 0.8 * clamp((cc.x + 0.7) / 1.4 * 0.7 + (cc.y + 0.5) * 0.3, 0.0, 1.0) + 0.2 * h.z;\n  float k = smoothstep(order, order + 0.35, g * 1.35);\n  float cellMask = smoothstep((1.0 - k) * 0.045 - 0.002, (1.0 - k) * 0.045, edgeD);\n  float shard = step(0.5, inCell) * step(0.7, h.y) * (1.0 - la) * (1.0 - smoothstep(0.0, 0.5 / sc, v.z / sc));\n  float mask = max(smoothstep(0.35, 0.65, la), shard) * cellMask;\n  vec2 toC = p - cc;\n  vec2 fd = normalize(seed2 - v.xy + 0.0001);\n  float facetRot = t * uOrbit * 0.6 + h.x * 6.28;\n  vec2 fdr = rot2(facetRot) * fd;\n  vec3 n = normalize(vec3(fdr * (0.35 + uDepth * 5.0) + (h.xy - 0.5) * 0.3, 1.0));\n  n.xy += (h.xy - 0.5) * 0.4 * kick;\n  n = normalize(n);\n  vec3 V = normalize(vec3(-p * 0.7, 1.0));\n  vec3 R = reflect(-V, n);\n  float dlt = 0.12;\n  vec3 env = vec3(studioEnv(vec3(rot2(dlt) * R.xy, R.z), uRoughness, h.y * 2.0).r,\n                  studioEnv(R, uRoughness, h.y * 2.0).g,\n                  studioEnv(vec3(rot2(-dlt) * R.xy, R.z), uRoughness, h.y * 2.0).b);\n  float fres = pow(1.0 - clamp(dot(n, V), 0.0, 1.0), 2.0) * uFresnel;\n  vec3 refl = env * mix(vec3(1.0), uTint.rgb, 0.5);\n  vec3 refr = uTint.rgb * (0.25 + 0.35 * h.x);\n  vec3 col = mix(refr, refl, clamp(fres * 0.6 + 0.35, 0.0, 1.0));\n  col = max(col, uTint.rgb * 0.22);\n  float crease = 1.0 - smoothstep(0.0, uBevel * 1.2, edgeD);\n  float edgeLine = 1.0 - smoothstep(0.0, uBevel * 0.6 + px, edgeD);\n  col *= 1.0 - crease * 0.35;\n  col += vec3(1.0) * edgeLine * (0.3 + 0.3 * uFresnel);\n  float sw = max(0.7 * px, 0.0008);\n  float star = max(exp(-abs(toC.x) / sw) * exp(-abs(toC.y) * 90.0), exp(-abs(toC.y) / sw) * exp(-abs(toC.x) * 90.0));\n  float glint = pow(max(sin(t * (2.0 + uOrbit * 2.0) + h.x * 30.0 + kick * 3.0), 0.0), 30.0) * (1.0 + uHigh * aud * 3.0);\n  col += vec3(1.0) * star * glint * 2.0;\n  col = pow(col, vec3(1.3)) * 1.25;\n  col = 1.0 - exp(-col * 1.2);\n  vec3 lcol = IMG_NORM_PIXEL(inputImage, uv).rgb;\n  vec3 seedCol = lcol * 0.18 * la * (1.0 - mask);\n  gl_FragColor = vjOut(col * mask + seedCol, max(mask, la * 0.3 * (1.0 - mask)));\n}\n"},{"id":"metal-forge","name":"Forged Heat-Front Steel","category":"metal","blurb":"Black forged-steel slab with a molten edge; every kick drives a white-hot front inward that cools red to black.","params":[{"name":"uCool","label":"Cooling Rate","type":"float","default":0.45,"min":0,"max":1,"hint":"How fast the heat trail behind the front cools from white through red to black (per beat)."},{"name":"uBeat","label":"Beat Phase","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"beat","hint":"Sawtooth 0\u00e2\u2020\u20191 per beat (app BPM clock). In Resolume, map to a BPM-synced parameter; in TD, a beat CHOP ramp."},{"name":"uDepth","label":"Extrusion Depth","type":"float","default":0.08,"min":0,"max":0.25,"hint":"Depth of the extruded steel slab (side walls); the kick punches it deeper."},{"name":"uRoughness","label":"Metallic Roughness","type":"float","default":0.15,"min":0,"max":1,"hint":"Steel finish: polished bevels \u00e2\u2020\u2019 hammered, mill-scaled forging."},{"name":"uFresnel","label":"Fresnel Rim Light","type":"float","default":1.2,"min":0,"max":3,"hint":"Cold rim light on the steel bevels and side walls."},{"name":"uBevel","label":"Bevel Radius","type":"float","default":0.012,"min":0.002,"max":0.04,"hint":"Width of the rounded bevel that catches the rim light."},{"name":"uOrbit","label":"Camera Orbit Speed","type":"float","default":0.4,"min":0,"max":2,"hint":"Speed the camera swings around the slab."},{"name":"uTint","label":"Material Tint","type":"color","default":[1,0.3,0.06,1],"hint":"Heat colour. The ramp runs black \u00e2\u2020\u2019 tint \u00e2\u2020\u2019 white-hot, so red-orange reads as forge steel."},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Hardstyle Forge","values":{}},{"name":"Plasma Weld","values":{"uTint":[0.3,0.55,1,1],"uCool":0.7,"uRoughness":0.3}},{"name":"Slow Quench","values":{"uCool":0.12,"uDepth":0.16,"uFresnel":2,"uOrbit":0.2}}],"source":"/*{\n  \"DESCRIPTION\": \"Forged Heat-Front Steel \u00e2\u20ac\u201d Black forged-steel slab with a molten edge; every kick drives a white-hot front inward that cools red to black.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"3D Volumetric & Metallurgic\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uCool\",\"TYPE\":\"float\",\"LABEL\":\"Cooling Rate\",\"DEFAULT\":0.45,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uBeat\",\"TYPE\":\"float\",\"LABEL\":\"Beat Phase\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uDepth\",\"TYPE\":\"float\",\"LABEL\":\"Extrusion Depth\",\"DEFAULT\":0.08,\"MIN\":0,\"MAX\":0.25},\n    {\"NAME\":\"uRoughness\",\"TYPE\":\"float\",\"LABEL\":\"Metallic Roughness\",\"DEFAULT\":0.15,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uFresnel\",\"TYPE\":\"float\",\"LABEL\":\"Fresnel Rim Light\",\"DEFAULT\":1.2,\"MIN\":0,\"MAX\":3},\n    {\"NAME\":\"uBevel\",\"TYPE\":\"float\",\"LABEL\":\"Bevel Radius\",\"DEFAULT\":0.012,\"MIN\":0.002,\"MAX\":0.04},\n    {\"NAME\":\"uOrbit\",\"TYPE\":\"float\",\"LABEL\":\"Camera Orbit Speed\",\"DEFAULT\":0.4,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Material Tint\",\"DEFAULT\":[1,0.3,0.06,1]},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Forged Heat-Front Steel \u00c2\u00b7 3D Volumetric & Metallurgic\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nfloat vnoise(vec2 p) {\n  vec2 i = floor(p); vec2 f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x), mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nmat2 rot2(float a) { float c = cos(a); float s = sin(a); return mat2(c, -s, s, c); }\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// 25-tap disk coverage of the logo around p (radius r, height-normalized units).\n// x = coverage 0..1 (0.5 on the outline), yz = vector pointing into the logo.\nvec3 logoField(vec2 p, float r) {\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n// Approximate signed distance (positive outside) from a logoField sample of radius r.\nfloat fieldSD(vec3 f, float r) { return (0.5 - f.x) * 2.0 * r; }\n// Edge glow that falls to exactly zero at the field radius r (no full-frame haze floor).\nfloat edgeGlow(float sd, float k, float r) { float f = exp(-r * k); return max(exp(-abs(sd) * k) - f, 0.0) / (1.0 - f); }\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\n// Procedural studio environment for chrome / glass / crystal: four off-axis strip lights at mixed elevations\n// (a flat face sees a horizon split instead of one value that flips dark/bright), energy-normalised roughness\n// (rougher = wider lobes, not brighter), top key, horizon line, dark floor. Peaks ~2.0; callers tonemap.\nvec3 studioEnv(vec3 d, float rough, float spin) {\n  d = normalize(d);\n  d.xz = rot2(spin) * d.xz;\n  float y = d.y;\n  float az = atan(d.x, d.z);\n  float k = mix(40.0, 3.0, rough);\n  float norm = (k + 1.0) / 41.0;\n  vec3 sky = mix(vec3(0.08, 0.09, 0.11), vec3(0.75, 0.8, 0.88), smoothstep(-0.1, 0.8, y));\n  float l1 = pow(max(cos(az - 0.3) * cos((y - 0.15) * 1.6), 0.0), k);\n  float l2 = pow(max(cos(az - 2.4) * cos((y - 0.35) * 1.6), 0.0), k * 0.7);\n  float l3 = pow(max(cos(az + 1.9) * cos((y + 0.05) * 1.6), 0.0), k * 1.3);\n  float l4 = pow(max(cos(az + 3.0) * cos((y - 0.5) * 1.6), 0.0), k * 0.5);\n  float strips = norm * (1.6 * l1 + 1.25 * l2 + 1.1 * l3 + 0.8 * l4);\n  float top = pow(max(y, 0.0), mix(24.0, 2.0, rough)) * mix(1.0, 0.35, rough);\n  float hor = exp(-abs(y) * mix(40.0, 6.0, rough));\n  vec3 col = sky * 0.5 + vec3(1.0, 0.98, 0.95) * strips * 1.5 + vec3(2.0, 1.9, 1.75) * top + vec3(0.7, 0.8, 0.95) * hor;\n  float ground = 1.0 - smoothstep(-0.25, 0.0, y);\n  return mix(col, vec3(0.025, 0.025, 0.03) + hor * 0.2, ground);\n}\n\n// ---- effect ----\nfloat fgSD(vec2 p, float R, out vec2 nIn) {\n  vec3 F = logoField(p, R);\n  float sd0 = fieldSD(F, R);\n  nIn = length(F.yz) > 0.0001 ? normalize(F.yz) : vec2(0.0, 1.0);\n  if (abs(sd0) > R * 0.96) return sd0;\n  bool inside = logoP(p) > 0.5;\n  vec2 dir = inside ? -nIn : nIn;\n  float lo = 0.0;\n  float hi = R;\n  for (int i = 0; i < 6; i++) {\n    float mid = 0.5 * (lo + hi);\n    bool crossed = (logoP(p + dir * mid) > 0.5) != inside;\n    if (crossed) hi = mid; else lo = mid;\n  }\n  float d = 0.5 * (lo + hi);\n  return inside ? -d : d;\n}\n\n// Temperature ramp derived from the tint: pow(tint, k) with k falling as it heats walks the hue\n// toward the tint's brightest channel and then white (black -> deep tint -> tint -> white-hot).\nvec3 fgHeat(float T, vec3 tint) {\n  T = max(T, 0.0);\n  vec3 c = pow(max(tint, vec3(0.002)), vec3(mix(3.4, 0.1, clamp(T, 0.0, 1.0))));\n  return c * smoothstep(0.02, 0.4, T) * (0.25 + 2.0 * T);\n}\n\n// Heat at interior depth d for beat phase ph. x = the white-hot front line racing in from the edge\n// (decelerating), y = the trail behind it cooling at 'cool' per beat (+ the previous beat's residue, so\n// the wrap is continuous). The front line is thin, so it can run hot without flattening the letterform.\nvec2 fgFront(float d, float ph, float W, float cool) {\n  float e = 1.0 - ph;\n  float front = W * (1.0 - e * e * e);\n  float off = (d - front) / (d > front ? 0.0045 : 0.006);\n  float line = exp(-off * off) * (1.0 - 0.4 * ph) * (1.0 - smoothstep(0.45, 0.95, ph));\n  float pass = 1.0 - pow(max(1.0 - d / W, 0.0), 0.3333);\n  float s = ph - pass;\n  float trail = d <= front ? exp(-s * cool) : 0.0;\n  float prev = d < W ? exp(-(s + 1.0) * cool) : 0.0;\n  return vec2(line, trail + prev);\n}\n\n// Sparse rising sparks: bright points with a short tail, twinkling; caller masks them to the edge.\nfloat fgSparks(vec2 p, float t) {\n  float acc = 0.0;\n  for (int k = 0; k < 2; k++) {\n    float fk = float(k);\n    float cs = 0.03 - fk * 0.009;\n    vec2 g = p + vec2(sin(t * 0.7 + fk) * 0.012, -t * (0.2 + 0.08 * fk));\n    vec2 cell = floor(g / cs);\n    vec3 h = hash32(cell + fk * 19.1);\n    if (h.z > 0.3) continue;\n    vec2 c = (cell + 0.2 + 0.6 * h.xy) * cs;\n    vec2 f = g - c;\n    f.y = f.y < 0.0 ? f.y * 0.35 : f.y;\n    float e = dot(f, f) / (0.0016 * 0.0016);\n    acc += exp(-e) * (0.5 + 0.5 * h.x) * smoothstep(0.2, 1.0, sin(t * (5.0 + 5.0 * h.y) + h.x * 40.0) * 0.5 + 0.5);\n  }\n  return acc;\n}\n\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  float kick = clamp(uBass * aud, 0.0, 1.5);\n  float ph = fract(uBeat);\n  vec2 q = p / (1.0 + 0.05 * kick);\n  float ang = t * uOrbit;\n  vec2 tilt = vec2(sin(ang) * 0.5, -0.42 - 0.12 * sin(ang * 0.7));\n  float depth = uDepth * (0.6 + 0.4 * kick);\n  float R = 0.045;\n  vec2 nIn;\n  float sd = fgSD(q, R, nIn);\n  float la = logoP(q);\n  float faceA = smoothstep(0.25, 0.75, la);\n  float dIn = max(-sd, 0.0);\n\n  // heat: beat-locked front + persistent molten seam. The strike strength is a compressed bass level, so the\n  // front keeps its heat as the kick envelope decays; the trail is capped so letter interiors keep their shading.\n  float cool = mix(1.2, 9.0, uCool);\n  float A = 0.32 + 0.9 * pow(kick, 0.4);\n  vec2 hf = fgFront(dIn, ph, 0.03, cool);\n  float Tcap = mix(1.0, 0.62, smoothstep(0.003, 0.016, dIn));\n  float seam = 0.6 + 0.2 * vnoise(q * 30.0 + vec2(0.0, t * 2.0)) + 0.25 * kick;\n  float Te = exp(-dIn / 0.0032) * seam;\n  float T = max(max(A * hf.x * 1.2, min(A * hf.y * 0.62, Tcap)), Te);\n\n  // front face: black steel with a rounded bevel and hammered texture\n  float bw = uBevel * 1.2 + 0.002;\n  float xb = clamp(dIn / bw, 0.0, 1.0);\n  float slope = (1.0 - xb) * (1.0 - xb) * 2.6;\n  vec2 hq = q * 26.0;\n  float h0 = vnoise(hq);\n  vec2 hg = vec2(vnoise(hq + vec2(0.35, 0.0)) - h0, vnoise(hq + vec2(0.0, 0.35)) - h0) / 0.35;\n  vec3 n = normalize(vec3(-nIn * slope + hg * (0.02 + 0.3 * uRoughness), 1.0));\n  vec3 V = normalize(vec3(tilt * 0.35 - q * 0.5, 1.0));\n  vec3 env = studioEnv(reflect(-V, n), 0.2 + uRoughness * 0.8, ang * 0.4 + 0.6);\n  float fres = pow(1.0 - clamp(dot(n, V), 0.0, 1.0), 4.0);\n  float scale = 0.7 + 0.6 * vnoise(q * 9.0 + 3.0);\n  vec3 Lk = normalize(vec3(-0.5 + 0.3 * sin(ang), 0.6, 0.65));\n  float keySpec = pow(max(dot(reflect(-Lk, n), V), 0.0), mix(90.0, 10.0, uRoughness)) * (1.0 - 0.5 * uRoughness);\n  vec3 steel = env * vec3(0.27, 0.28, 0.3) * mix(1.0, scale, uRoughness) + vec3(0.9, 0.93, 1.0) * keySpec * 0.6;\n  vec2 Lr = normalize(vec2(-0.6, 0.8));\n  float rimF = max(dot(normalize(n.xy + vec2(0.0001)), Lr), 0.0) * (1.0 - n.z) * 2.2 + fres;\n  steel += mix(env, vec3(0.75, 0.85, 1.0), 0.6) * rimF * uFresnel * 0.55;\n  vec3 face = steel * (1.0 - 0.6 * smoothstep(0.3, 0.9, T)) + fgHeat(T, uTint.rgb) * (0.7 + 0.3 * n.z);\n\n  // side walls of the extruded slab (16-step march + 3-step bisection)\n  vec3 col = vec3(0.0);\n  float alpha = 0.0;\n  if (la < 0.99 && depth > 0.0005) {\n    float hitZ = -1.0;\n    float zPrev = 0.0;\n    for (int i = 1; i <= 16; i++) {\n      float z = depth * float(i) / 16.0;\n      if (logoP(q - tilt * z) > 0.5) { hitZ = z; break; }\n      zPrev = z;\n    }\n    if (hitZ > 0.0) {\n      float lo = zPrev;\n      float hi = hitZ;\n      for (int j = 0; j < 3; j++) {\n        float mid = 0.5 * (lo + hi);\n        if (logoP(q - tilt * mid) > 0.5) hi = mid; else lo = mid;\n      }\n      hitZ = hi;\n      vec2 hp = q - tilt * hitZ;\n      float e = 0.004;\n      vec2 gr = vec2(logoP(hp + vec2(e, 0.0)) - logoP(hp - vec2(e, 0.0)), logoP(hp + vec2(0.0, e)) - logoP(hp - vec2(0.0, e)));\n      vec2 od = length(gr) > 0.0001 ? -normalize(gr) : -normalize(tilt);\n      vec3 nw = normalize(vec3(od, 0.2));\n      vec3 envw = studioEnv(reflect(-V, nw), 0.3 + 0.7 * uRoughness, ang * 0.4 + 0.6);\n      float zf = hitZ / max(depth, 0.0001);\n      // walls face down into the dark floor of the env, so light them like a forge: a warm bounce from the\n      // fire below plus the cold rim light from above on the wall edges\n      vec3 wall = (envw * vec3(0.2, 0.205, 0.22) + vec3(0.03)) * (1.0 - 0.55 * zf);\n      float up = max(dot(nw, normalize(vec3(0.25, -0.85, 0.45))), 0.0);\n      wall += fgHeat(0.5 + 0.3 * kick, uTint.rgb) * up * 0.3 * (1.0 - 0.4 * zf);\n      wall += vec3(0.75, 0.85, 1.0) * max(dot(od, Lr), 0.0) * 0.35 * uFresnel * (1.0 - zf);\n      float Tw = (0.45 + 0.6 * A * exp(-ph * cool)) * exp(-hitZ / 0.009);\n      wall += fgHeat(Tw, uTint.rgb) * 0.9;\n      col = wall;\n      alpha = 1.0;\n    }\n  }\n  col = mix(col, face, faceA);\n  alpha = max(alpha, faceA);\n\n  // heat bloom just outside the edge + sparks riding the edge on the highs (both fall to zero by R)\n  float edgeT = 0.5 + A * exp(-ph * cool);\n  vec3 bloom = fgHeat(edgeT * 0.55, uTint.rgb) * edgeGlow(max(sd, 0.0), 90.0, R) * 0.55 * step(0.0, sd);\n  float sparkMask = edgeGlow(sd, 40.0, R) * step(-0.004, sd);\n  vec3 sparks = fgHeat(0.95, uTint.rgb) * fgSparks(q, t) * sparkMask * (0.15 + 1.6 * uHigh * aud);\n  col += (bloom + sparks) * (1.0 - faceA * 0.7);\n  gl_FragColor = vjOut(col, alpha);\n}\n"},{"id":"metal-pillars","name":"LED Pillar Extrusion","category":"metal","blurb":"The logo rebuilt from square LED pillars, a 3D equaliser skyline: bass lifts the core, highs the rim, a wave rolls across.","params":[{"name":"uCell","label":"Pillar Pitch","type":"float","default":0.016,"min":0.006,"max":0.04,"hint":"Size of one square LED pillar (height units). Smaller = finer skyline."},{"name":"uDepth","label":"Extrusion Depth","type":"float","default":0.08,"min":0,"max":0.25,"hint":"Resting pillar height. At 0 the skyline crossfades back to the flat logo."},{"name":"uRoughness","label":"Metallic Roughness","type":"float","default":0.15,"min":0,"max":1,"hint":"Gloss of the pillar side walls (studio reflections) vs matte."},{"name":"uFresnel","label":"Fresnel Rim Light","type":"float","default":1.2,"min":0,"max":3,"hint":"Catch-light on the top-face chamfers."},{"name":"uBevel","label":"Bevel Radius","type":"float","default":0.012,"min":0.002,"max":0.04,"hint":"Gap between pillars (bevel gap), as a share of the pitch."},{"name":"uOrbit","label":"Camera Orbit Speed","type":"float","default":0.4,"min":0,"max":2,"hint":"Speed the camera swings around the skyline."},{"name":"uTint","label":"Material Tint","type":"color","default":[0.35,0.6,1,1],"hint":"Side-wall metal colour; the top faces keep the logo colours."},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"LED Skyline","values":{}},{"name":"Techno Monolith","values":{"uCell":0.02,"uDepth":0.09,"uTint":[0.55,0.6,0.7,1],"uRoughness":0.35,"uOrbit":0.25,"uFresnel":2}},{"name":"Micro Grid","values":{"uCell":0.009,"uOrbit":0.9,"uTint":[1,0.3,0.6,1]}}],"source":"/*{\n  \"DESCRIPTION\": \"LED Pillar Extrusion \u00e2\u20ac\u201d The logo rebuilt from square LED pillars, a 3D equaliser skyline: bass lifts the core, highs the rim, a wave rolls across.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"3D Volumetric & Metallurgic\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uCell\",\"TYPE\":\"float\",\"LABEL\":\"Pillar Pitch\",\"DEFAULT\":0.016,\"MIN\":0.006,\"MAX\":0.04},\n    {\"NAME\":\"uDepth\",\"TYPE\":\"float\",\"LABEL\":\"Extrusion Depth\",\"DEFAULT\":0.08,\"MIN\":0,\"MAX\":0.25},\n    {\"NAME\":\"uRoughness\",\"TYPE\":\"float\",\"LABEL\":\"Metallic Roughness\",\"DEFAULT\":0.15,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uFresnel\",\"TYPE\":\"float\",\"LABEL\":\"Fresnel Rim Light\",\"DEFAULT\":1.2,\"MIN\":0,\"MAX\":3},\n    {\"NAME\":\"uBevel\",\"TYPE\":\"float\",\"LABEL\":\"Bevel Radius\",\"DEFAULT\":0.012,\"MIN\":0.002,\"MAX\":0.04},\n    {\"NAME\":\"uOrbit\",\"TYPE\":\"float\",\"LABEL\":\"Camera Orbit Speed\",\"DEFAULT\":0.4,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Material Tint\",\"DEFAULT\":[0.35,0.6,1,1]},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// LED Pillar Extrusion \u00c2\u00b7 3D Volumetric & Metallurgic\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nmat2 rot2(float a) { float c = cos(a); float s = sin(a); return mat2(c, -s, s, c); }\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\n// Procedural studio environment for chrome / glass / crystal: four off-axis strip lights at mixed elevations\n// (a flat face sees a horizon split instead of one value that flips dark/bright), energy-normalised roughness\n// (rougher = wider lobes, not brighter), top key, horizon line, dark floor. Peaks ~2.0; callers tonemap.\nvec3 studioEnv(vec3 d, float rough, float spin) {\n  d = normalize(d);\n  d.xz = rot2(spin) * d.xz;\n  float y = d.y;\n  float az = atan(d.x, d.z);\n  float k = mix(40.0, 3.0, rough);\n  float norm = (k + 1.0) / 41.0;\n  vec3 sky = mix(vec3(0.08, 0.09, 0.11), vec3(0.75, 0.8, 0.88), smoothstep(-0.1, 0.8, y));\n  float l1 = pow(max(cos(az - 0.3) * cos((y - 0.15) * 1.6), 0.0), k);\n  float l2 = pow(max(cos(az - 2.4) * cos((y - 0.35) * 1.6), 0.0), k * 0.7);\n  float l3 = pow(max(cos(az + 1.9) * cos((y + 0.05) * 1.6), 0.0), k * 1.3);\n  float l4 = pow(max(cos(az + 3.0) * cos((y - 0.5) * 1.6), 0.0), k * 0.5);\n  float strips = norm * (1.6 * l1 + 1.25 * l2 + 1.1 * l3 + 0.8 * l4);\n  float top = pow(max(y, 0.0), mix(24.0, 2.0, rough)) * mix(1.0, 0.35, rough);\n  float hor = exp(-abs(y) * mix(40.0, 6.0, rough));\n  vec3 col = sky * 0.5 + vec3(1.0, 0.98, 0.95) * strips * 1.5 + vec3(2.0, 1.9, 1.75) * top + vec3(0.7, 0.8, 0.95) * hor;\n  float ground = 1.0 - smoothstep(-0.25, 0.0, y);\n  return mix(col, vec3(0.025, 0.025, 0.03) + hor * 0.2, ground);\n}\n\n// ---- effect ----\n// 3-band \"spectrum\" by radius: bass at the centre, mid in the middle, highs at the rim.\nfloat plBand(float x) {\n  x = clamp(x, 0.0, 1.0);\n  return x < 0.5 ? mix(uBass, uMid, x * 2.0) : mix(uMid, uHigh, x * 2.0 - 1.0);\n}\n\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  float c = max(uCell, 0.004);\n  float ang = t * uOrbit;\n  vec2 tilt = vec2(sin(ang) * 0.5, 0.55 + 0.12 * cos(ang * 0.7));\n  float base = uDepth;\n  float lvlMax = max(uBass, max(uMid, uHigh)) * aud;\n  float ridge = base * 0.6;\n  float zmax = base * (1.0 + 1.25 * lvlMax) + ridge + 0.0005;\n  // orthographic view: a pillar top at height h over ground g shows at screen g + tilt*h. Walk the eye ray's\n  // ground trace cell by cell (exact DDA, <= 40 cells = 40 taps) from the top of the volume down to the floor;\n  // each column is an inset box, so the hit is exact (top face or the x/y side face it entered through).\n  float span = (abs(tilt.x) + abs(tilt.y)) * zmax / c;\n  tilt *= min(1.0, 38.0 / max(span, 0.001));\n  vec2 d = tilt;\n  d.x = abs(d.x) < 0.0001 ? 0.0001 : d.x;\n  d.y = abs(d.y) < 0.0001 ? 0.0001 : d.y;\n  vec2 pc = p + d * base;\n  vec2 A = pc - d * zmax;\n  vec2 cell = floor(A / c);\n  vec2 stp = vec2(d.x > 0.0 ? 1.0 : -1.0, d.y > 0.0 ? 1.0 : -1.0);\n  vec2 tMax = ((cell + max(stp, vec2(0.0))) * c - A) / d;\n  vec2 tDel = c / abs(d);\n  float gap = c * clamp(0.04 + uBevel * 5.0, 0.0, 0.4);\n  float face = -1.0;\n  float hitH = 0.0;\n  float hitZ = 0.0;\n  float hitLvl = 0.0;\n  vec3 hitRGB = vec3(0.0);\n  vec2 hitMin = vec2(0.0);\n  vec2 hitMax = vec2(0.0);\n  float lastA = 0.0;\n  for (int i = 0; i < 40; i++) {\n    vec2 cc = (cell + 0.5) * c;\n    vec4 lg = logoRGBA(cc);\n    lastA = lg.a;\n    if (lg.a > 0.5) {\n      float lvl = plBand(length(cc) / 0.8) * aud * (0.75 + 0.5 * hash11(cell.x * 1.37 + 0.5));\n      float wave = pow(0.5 + 0.5 * sin(cc.x * 9.0 + cc.y * 3.0 - t * 4.0), 3.0);\n      float h = base * (1.0 + 1.0 * lvl) + ridge * wave;\n      vec2 bmin = cell * c + gap;\n      vec2 bmax = (cell + 1.0) * c - gap;\n      vec2 t1 = (bmin - A) / d;\n      vec2 t2 = (bmax - A) / d;\n      vec2 tn = min(t1, t2);\n      vec2 tf = max(t1, t2);\n      float u0 = max(max(tn.x, tn.y), 0.0);\n      float u1 = min(min(tf.x, tf.y), zmax);\n      if (u1 > u0) {\n        float zIn = zmax - u0;\n        float zOut = zmax - u1;\n        if (h >= zIn) { face = tn.x > tn.y ? 1.0 : 2.0; hitZ = zIn; }\n        else if (h >= zOut) { face = 0.0; hitZ = h; }\n        if (face >= 0.0) { hitH = h; hitLvl = lvl; hitRGB = lg.rgb; hitMin = bmin; hitMax = bmax; break; }\n      }\n    }\n    if (tMax.x < tMax.y) {\n      if (tMax.x > zmax) break;\n      cell.x += stp.x;\n      tMax.x += tDel.x;\n    } else {\n      if (tMax.y > zmax) break;\n      cell.y += stp.y;\n      tMax.y += tDel.y;\n    }\n  }\n\n  vec3 V = normalize(vec3(-d, 1.0));\n  vec3 L = normalize(vec3(-0.35, -0.45, 0.8));\n  vec3 col = vec3(0.0);\n  float alpha = 0.0;\n  if (face == 0.0) {\n    // top face = an LED diffuser: bright centre, soft falloff, chamfer catch-light on the light-facing edges\n    float hn = clamp((hitH - base * 0.8) / (base * 1.5 + 0.0001), 0.0, 1.0);\n    vec2 g = pc - d * hitH;\n    vec2 u = (g - hitMin) / max(hitMax - hitMin, vec2(0.0001)) - 0.5;\n    float diffuser = 0.72 + 0.28 * (1.0 - smoothstep(0.05, 0.5, max(abs(u.x), abs(u.y))));\n    vec2 e2 = min(g - hitMin, hitMax - g);\n    float rimW = max(c * 0.1, 1.5 / RENDERSIZE.y);\n    float rim = (1.0 - smoothstep(0.0, rimW, min(e2.x, e2.y))) * (0.35 + 0.65 * smoothstep(-0.2, 0.3, -u.x - u.y));\n    vec3 top = hitRGB * diffuser * (0.66 + 0.5 * hn + 0.3 * hitLvl);\n    // glossy lens over each LED (normal jittered per pillar): sparkling reflections when polished, none when matte\n    vec2 jit = (hash22(floor(g / c) + 7.7) - 0.5) * 0.5;\n    vec3 envT = studioEnv(reflect(-V, normalize(vec3(jit, 1.0))), uRoughness, ang * 0.5);\n    top = mix(top, top * 0.75 + envT * 0.4, 1.0 - uRoughness);\n    top += mix(vec3(1.0), hitRGB, 0.35) * rim * uFresnel * 0.45;\n    col = top;\n    alpha = 1.0;\n  } else if (face > 0.0) {\n    // side wall: tinted metal, lit per face, occluded toward the floor, with the LED bleeding down from the top\n    vec3 n = face == 1.0 ? vec3(-stp.x, 0.0, 0.0) : vec3(0.0, -stp.y, 0.0);\n    float diff = max(dot(n, L), 0.0);\n    float zt = clamp(hitZ / max(hitH, 0.0001), 0.0, 1.0);\n    float ao = mix(0.25, 1.0, smoothstep(0.0, 0.7, zt));\n    vec3 side = uTint.rgb * (0.07 + 0.55 * diff) * ao;\n    side += hitRGB * (0.1 + 0.55 * smoothstep(0.8, 1.0, zt)) * ao;\n    side += studioEnv(reflect(-V, n), uRoughness, ang * 0.5) * mix(vec3(1.0), uTint.rgb, 0.5) * 0.4 * (1.0 - 0.85 * uRoughness);\n    col = side;\n    alpha = 1.0;\n  } else if (lastA > 0.5) {\n    col = uTint.rgb * 0.03;\n    alpha = 1.0;\n  }\n  // at zero depth the skyline crossfades to the untouched flat logo\n  float fx = smoothstep(0.0, 0.025, uDepth);\n  vec4 lgp = logoRGBA(p);\n  col = mix(lgp.rgb * lgp.a, col, fx);\n  alpha = mix(lgp.a, alpha, fx);\n  gl_FragColor = vjOut(col, alpha);\n}\n"},{"id":"metal-anodized","name":"Anodized Brushed Sweep","category":"metal","blurb":"Satin brushed titanium plate with an anodized hue shift; an anisotropic light streak sweeps across the grain.","params":[{"name":"uBrushAngle","label":"Brush Direction","type":"float","default":0,"min":0,"max":2.3562,"unit":"rad","hint":"Direction of the brushed grain, 0\u00c2\u00b0 (horizontal) to 135\u00c2\u00b0. The highlight streak runs across it and sweeps along it."},{"name":"uAnisotropy","label":"Anisotropy","type":"float","default":0.85,"min":0,"max":1,"hint":"Round satin highlight (0) \u00e2\u2020\u2019 long Kajiya-Kay streak across the grain (1)."},{"name":"uDepth","label":"Extrusion Depth","type":"float","default":0.08,"min":0,"max":0.25,"hint":"Plate thickness and bevel height; the bass pulses the bevel."},{"name":"uRoughness","label":"Metallic Roughness","type":"float","default":0.15,"min":0,"max":1,"hint":"Satin roughness: tight hairline streak \u00e2\u2020\u2019 soft bead-blasted sheen."},{"name":"uFresnel","label":"Fresnel Rim Light","type":"float","default":1.2,"min":0,"max":3,"hint":"Rim light on the bevels."},{"name":"uBevel","label":"Bevel Radius","type":"float","default":0.012,"min":0.002,"max":0.04,"hint":"Width of the edge bevel (the face stays flat)."},{"name":"uOrbit","label":"Camera Orbit Speed","type":"float","default":0.4,"min":0,"max":2,"hint":"Light sweep speed (and a slow camera drift)."},{"name":"uTint","label":"Material Tint","type":"color","default":[0.78,0.8,0.84,1],"hint":"Anodize colour; the oxide film shifts hue around it on the bevels."},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Satin Titanium","values":{}},{"name":"Anodized Cobalt","values":{"uTint":[0.32,0.46,1,1],"uAnisotropy":0.95,"uRoughness":0.1}},{"name":"Bronze Hairline","values":{"uTint":[0.95,0.64,0.38,1],"uBrushAngle":1.5708,"uRoughness":0.45}}],"source":"/*{\n  \"DESCRIPTION\": \"Anodized Brushed Sweep \u00e2\u20ac\u201d Satin brushed titanium plate with an anodized hue shift; an anisotropic light streak sweeps across the grain.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"3D Volumetric & Metallurgic\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uBrushAngle\",\"TYPE\":\"float\",\"LABEL\":\"Brush Direction\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":2.3562},\n    {\"NAME\":\"uAnisotropy\",\"TYPE\":\"float\",\"LABEL\":\"Anisotropy\",\"DEFAULT\":0.85,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uDepth\",\"TYPE\":\"float\",\"LABEL\":\"Extrusion Depth\",\"DEFAULT\":0.08,\"MIN\":0,\"MAX\":0.25},\n    {\"NAME\":\"uRoughness\",\"TYPE\":\"float\",\"LABEL\":\"Metallic Roughness\",\"DEFAULT\":0.15,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uFresnel\",\"TYPE\":\"float\",\"LABEL\":\"Fresnel Rim Light\",\"DEFAULT\":1.2,\"MIN\":0,\"MAX\":3},\n    {\"NAME\":\"uBevel\",\"TYPE\":\"float\",\"LABEL\":\"Bevel Radius\",\"DEFAULT\":0.012,\"MIN\":0.002,\"MAX\":0.04},\n    {\"NAME\":\"uOrbit\",\"TYPE\":\"float\",\"LABEL\":\"Camera Orbit Speed\",\"DEFAULT\":0.4,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Material Tint\",\"DEFAULT\":[0.78,0.8,0.84,1]},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Anodized Brushed Sweep \u00c2\u00b7 3D Volumetric & Metallurgic\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nfloat vnoise(vec2 p) {\n  vec2 i = floor(p); vec2 f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x), mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\n// Inigo Quilez cosine palette (iquilezles.org/articles/palettes).\nvec3 palCos(float t, vec3 a, vec3 b, vec3 c, vec3 d) { return a + b * cos(6.2831853 * (c * t + d)); }\n\nmat2 rot2(float a) { float c = cos(a); float s = sin(a); return mat2(c, -s, s, c); }\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// 25-tap disk coverage of the logo around p (radius r, height-normalized units).\n// x = coverage 0..1 (0.5 on the outline), yz = vector pointing into the logo.\nvec3 logoField(vec2 p, float r) {\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n// Approximate signed distance (positive outside) from a logoField sample of radius r.\nfloat fieldSD(vec3 f, float r) { return (0.5 - f.x) * 2.0 * r; }\n// Edge glow that falls to exactly zero at the field radius r (no full-frame haze floor).\nfloat edgeGlow(float sd, float k, float r) { float f = exp(-r * k); return max(exp(-abs(sd) * k) - f, 0.0) / (1.0 - f); }\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\n// Procedural studio environment for chrome / glass / crystal: four off-axis strip lights at mixed elevations\n// (a flat face sees a horizon split instead of one value that flips dark/bright), energy-normalised roughness\n// (rougher = wider lobes, not brighter), top key, horizon line, dark floor. Peaks ~2.0; callers tonemap.\nvec3 studioEnv(vec3 d, float rough, float spin) {\n  d = normalize(d);\n  d.xz = rot2(spin) * d.xz;\n  float y = d.y;\n  float az = atan(d.x, d.z);\n  float k = mix(40.0, 3.0, rough);\n  float norm = (k + 1.0) / 41.0;\n  vec3 sky = mix(vec3(0.08, 0.09, 0.11), vec3(0.75, 0.8, 0.88), smoothstep(-0.1, 0.8, y));\n  float l1 = pow(max(cos(az - 0.3) * cos((y - 0.15) * 1.6), 0.0), k);\n  float l2 = pow(max(cos(az - 2.4) * cos((y - 0.35) * 1.6), 0.0), k * 0.7);\n  float l3 = pow(max(cos(az + 1.9) * cos((y + 0.05) * 1.6), 0.0), k * 1.3);\n  float l4 = pow(max(cos(az + 3.0) * cos((y - 0.5) * 1.6), 0.0), k * 0.5);\n  float strips = norm * (1.6 * l1 + 1.25 * l2 + 1.1 * l3 + 0.8 * l4);\n  float top = pow(max(y, 0.0), mix(24.0, 2.0, rough)) * mix(1.0, 0.35, rough);\n  float hor = exp(-abs(y) * mix(40.0, 6.0, rough));\n  vec3 col = sky * 0.5 + vec3(1.0, 0.98, 0.95) * strips * 1.5 + vec3(2.0, 1.9, 1.75) * top + vec3(0.7, 0.8, 0.95) * hor;\n  float ground = 1.0 - smoothstep(-0.25, 0.0, y);\n  return mix(col, vec3(0.025, 0.025, 0.03) + hor * 0.2, ground);\n}\n\nfloat easeOutExpo(float x) { x = clamp(x, 0.0, 1.0); return x >= 1.0 ? 1.0 : 1.0 - pow(2.0, -10.0 * x); }\nfloat easeInExpo(float x) { x = clamp(x, 0.0, 1.0); return x <= 0.0 ? 0.0 : pow(2.0, 10.0 * x - 10.0); }\nfloat easeInOutCubic(float x) { x = clamp(x, 0.0, 1.0); return x < 0.5 ? 4.0 * x * x * x : 1.0 - pow(-2.0 * x + 2.0, 3.0) * 0.5; }\nfloat easeOutBack(float x) { x = clamp(x, 0.0, 1.0); float y = x - 1.0; return 1.0 + 2.70158 * y * y * y + 1.70158 * y * y; }\n\n// ---- effect ----\nfloat anKK(vec3 T, vec3 H, float shin) {\n  float th = dot(T, H);\n  return pow(sqrt(max(1.0 - th * th, 0.0)), shin);\n}\n\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  float kick = clamp(uBass * aud, 0.0, 1.5);\n  vec2 bd = vec2(cos(uBrushAngle), sin(uBrushAngle));\n  vec2 bn = vec2(-bd.y, bd.x);\n  float ang = t * uOrbit * 0.8;\n  vec2 tilt = vec2(sin(ang) * 0.45, -0.5);\n  float la = logoP(p);\n  float faceA = smoothstep(0.3, 0.7, la);\n\n  // bevel normal from the logo field: tilts only at the edges, the face stays flat\n  vec3 F = logoField(p, uBevel);\n  vec2 dir = length(F.yz) > 0.0001 ? normalize(F.yz) : vec2(0.0);\n  float slope = 4.0 * F.x * (1.0 - F.x);\n  float bh = (0.5 + uDepth * 8.0) * (1.0 + 1.4 * kick);\n\n  // brushed grain: value noise stretched along the brush axis, ~2 px across at any resolution\n  vec2 bp = vec2(dot(p, bd), dot(p, bn));\n  float gy = RENDERSIZE.y * 0.42;\n  float grain = vnoise(vec2(bp.x * 5.0, bp.y * gy)) * 0.6 + vnoise(vec2(bp.x * 13.0 + 7.1, bp.y * gy * 0.37)) * 0.4;\n  vec3 N = normalize(vec3(-dir * slope * bh + bn * (grain - 0.5) * 0.08, 1.0));\n  vec3 T = normalize(vec3(bd, 0.0));\n  T = normalize(T - N * dot(T, N));\n  vec3 V = normalize(vec3(-p * 0.35 + tilt * 0.15, 1.0));\n\n  // light sweep: a low light travels along the brush axis -> the anisotropic streak crosses the logo\n  float sw = fract(t * (0.1 + 0.15 * uOrbit));\n  float pos = mix(-1.25, 1.25, easeInOutCubic(clamp(sw * 1.35, 0.0, 1.0)));\n  float shin = mix(300.0, 40.0, uRoughness);\n  vec3 Lp = vec3(bd * pos + bn * 0.12, 0.24);\n  vec3 L = normalize(Lp - vec3(p, 0.0));\n  vec3 H = normalize(L + V);\n  float att = 1.0 / (1.0 + 4.0 * dot(Lp.xy - p, Lp.xy - p));\n  float spec = mix(pow(max(dot(N, H), 0.0), shin), anKK(T, H, shin), uAnisotropy) * att;\n  // kick sweep: the bass envelope is the clock, so each kick launches a fresh streak that fades as it crosses\n  float kp = 1.0 - sqrt(clamp(uBass, 0.0, 1.0));\n  vec3 Lk = vec3(bd * mix(-0.55, 1.3, kp) - bn * 0.1, 0.24);\n  vec3 Hk = normalize(normalize(Lk - vec3(p, 0.0)) + V);\n  float spk = mix(pow(max(dot(N, Hk), 0.0), shin), anKK(T, Hk, shin), uAnisotropy) / (1.0 + 4.0 * dot(Lk.xy - p, Lk.xy - p));\n  spec += spk * smoothstep(0.02, 0.3, uBass) * clamp(aud, 0.0, 1.5) * 1.4;\n\n  // anodized oxide: hue walks around the tint with film thickness (view angle on the bevel, slow drift);\n  // the shift is zero-mean, so flat faces keep the exact tint\n  float film = min(1.0 - N.z, 0.35) * 1.4 + 0.05 * bp.x + 0.03 * sin(t * 0.3) + (grain - 0.5) * 0.04;\n  vec3 dph = vec3(0.0, 0.33, 0.67);\n  vec3 ano = clamp(palCos(film, uTint.rgb - 0.14 * cos(6.2831853 * dph), vec3(0.14), vec3(1.0), dph), 0.0, 1.0);\n  vec3 env = studioEnv(reflect(-V, N), 0.55 + 0.45 * uRoughness, ang * 1.6 + 0.4);\n  float fres = pow(1.0 - clamp(dot(N, V), 0.0, 1.0), 3.0);\n  // satin base: soft broad reflection + a gentle vertical gradient, grain-modulated\n  float grad = 0.82 + 0.3 * smoothstep(-0.35, 0.3, p.y + 0.15 * p.x);\n  vec3 envN = mix(vec3(dot(env, vec3(0.3, 0.5, 0.2))), env, 0.35);\n  vec3 face = ano * (0.34 + envN * 0.62) * grad * (0.82 + 0.36 * grain);\n  // broad static key light through the same iso <-> Kajiya-Kay mix: a soft sheen band across the grain\n  vec3 Hs = normalize(normalize(vec3(-0.45 + 0.55 * sin(ang * 1.3), 0.55, 0.7)) + V);\n  float keyS = mix(pow(max(dot(N, Hs), 0.0), 30.0), anKK(T, Hs, 14.0), uAnisotropy);\n  face += ano * keyS * (0.6 + 0.6 * grain) * 0.38;\n  face += mix(vec3(1.0), ano, 0.45) * spec * (0.3 + 1.3 * grain) * 1.5;\n  // rim light on the bevels (Fresnel control)\n  float rimB = (1.0 - N.z) * 1.6 + fres;\n  face += mix(env, vec3(1.0), 0.5) * mix(vec3(1.0), ano, 0.4) * rimB * uFresnel * 0.45;\n\n  // plate thickness: short extruded side below the letters\n  vec3 col = vec3(0.0);\n  float alpha = 0.0;\n  float depth = uDepth * 0.35;\n  if (la < 0.99 && depth > 0.0005) {\n    float hitZ = -1.0;\n    for (int i = 1; i <= 10; i++) {\n      float z = depth * float(i) / 10.0;\n      if (logoP(p - tilt * z) > 0.5) { hitZ = z; break; }\n    }\n    if (hitZ > 0.0) {\n      float zf = hitZ / depth;\n      vec3 ns = normalize(vec3(-normalize(tilt), 0.35));\n      vec3 envs = studioEnv(reflect(-V, ns), 0.6 + 0.4 * uRoughness, ang + 0.4);\n      col = ano * (0.08 + envs * 0.32) * (1.0 - 0.5 * zf) * (0.9 + 0.2 * vnoise(vec2(dot(p, bd) * 40.0, hitZ * 900.0)));\n      alpha = 1.0;\n    }\n  }\n  col = mix(col, face, faceA);\n  alpha = max(alpha, faceA);\n  gl_FragColor = vjOut(col, alpha);\n}\n"},{"id":"metal-acrylic","name":"Acrylic Layer Stack","category":"metal","blurb":"The logo splits into floating stepped acrylic layers with parallax and soft shadows, then settles into a flat hero lockup.","params":[{"name":"uSettle","label":"Settle (1 = flat lockup)","type":"float","default":1,"min":0,"max":1,"auto":{"on":true,"shape":"sine","rate":0.1,"lo":0,"hi":1},"hint":"Below ~0.65 the layers float fully racked; above ~0.95 they land as the exact flat logo."},{"name":"uLayers","label":"Layer Count","type":"long","default":3,"values":[0,1,2,3,4],"labels":["2","3","4","5","6"]},{"name":"uDepth","label":"Extrusion Depth","type":"float","default":0.08,"min":0,"max":0.25,"hint":"Gap between acrylic layers: parallax travel and shadow offset."},{"name":"uRoughness","label":"Metallic Roughness","type":"float","default":0.15,"min":0,"max":1,"hint":"Clear (see-through layers, gloss sheen) \u00e2\u2020\u2019 frosted (milky, matte)."},{"name":"uFresnel","label":"Fresnel Rim Light","type":"float","default":1.2,"min":0,"max":3,"hint":"Brightness of the polished, light-piping layer edges."},{"name":"uBevel","label":"Bevel Radius","type":"float","default":0.012,"min":0.002,"max":0.04,"hint":"Terrace step: how much each upper layer is inset from the one below."},{"name":"uOrbit","label":"Camera Orbit Speed","type":"float","default":0.4,"min":0,"max":2,"hint":"Speed of the parallax orbit."},{"name":"uTint","label":"Material Tint","type":"color","default":[0.55,0.85,1,1],"hint":"Acrylic tint; layers ramp dark \u00e2\u2020\u2019 light toward the top, which carries the logo print."},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Clear Acrylic Stack","values":{}},{"name":"Smoked Amber","values":{"uTint":[1,0.62,0.22,1],"uRoughness":0.45,"uDepth":0.12}},{"name":"Frosted Six","values":{"uLayers":4,"uRoughness":0.8,"uTint":[0.86,0.9,1,1],"uBevel":0.02}}],"source":"/*{\n  \"DESCRIPTION\": \"Acrylic Layer Stack \u00e2\u20ac\u201d The logo splits into floating stepped acrylic layers with parallax and soft shadows, then settles into a flat hero lockup.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"3D Volumetric & Metallurgic\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uSettle\",\"TYPE\":\"float\",\"LABEL\":\"Settle (1 = flat lockup)\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uLayers\",\"TYPE\":\"long\",\"LABEL\":\"Layer Count\",\"DEFAULT\":3,\"VALUES\":[0,1,2,3,4],\"LABELS\":[\"2\",\"3\",\"4\",\"5\",\"6\"]},\n    {\"NAME\":\"uDepth\",\"TYPE\":\"float\",\"LABEL\":\"Extrusion Depth\",\"DEFAULT\":0.08,\"MIN\":0,\"MAX\":0.25},\n    {\"NAME\":\"uRoughness\",\"TYPE\":\"float\",\"LABEL\":\"Metallic Roughness\",\"DEFAULT\":0.15,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uFresnel\",\"TYPE\":\"float\",\"LABEL\":\"Fresnel Rim Light\",\"DEFAULT\":1.2,\"MIN\":0,\"MAX\":3},\n    {\"NAME\":\"uBevel\",\"TYPE\":\"float\",\"LABEL\":\"Bevel Radius\",\"DEFAULT\":0.012,\"MIN\":0.002,\"MAX\":0.04},\n    {\"NAME\":\"uOrbit\",\"TYPE\":\"float\",\"LABEL\":\"Camera Orbit Speed\",\"DEFAULT\":0.4,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Material Tint\",\"DEFAULT\":[0.55,0.85,1,1]},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Acrylic Layer Stack \u00c2\u00b7 3D Volumetric & Metallurgic\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\n// ---- effect ----\n// Hex-ring erosion of the logo at q, radius R: x = min tap (eroded mask), y = mean (soft), zw = inward gradient.\nvec4 acRing(vec2 q, float R) {\n  float c0 = logoP(q);\n  if (c0 < 0.01) return vec4(0.0);\n  float mn = c0;\n  float sm = c0;\n  vec2 g = vec2(0.0);\n  for (int i = 0; i < 6; i++) {\n    float a = float(i) * 1.0471976 + 0.2617994;\n    vec2 dv = vec2(cos(a), sin(a));\n    float s = logoP(q + dv * R);\n    mn = min(mn, s);\n    sm += s;\n    g += dv * s;\n  }\n  return vec4(mn, sm / 7.0, g);\n}\n\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  float kick = clamp(uBass * aud, 0.0, 1.5);\n  float s = clamp(uSettle, 0.0, 1.0);\n  float rack = 1.0 - smoothstep(0.62, 0.95, s);\n  float rest = 1.0 - rack;\n  int N = int(float(uLayers) + 0.5) + 2;\n  float Nf = float(N);\n  float gaps = max(Nf - 1.0, 1.0);\n  float a = t * uOrbit * 1.2 + 0.6 + sin(t * 0.9) * 0.25 * uMid * aud;\n  vec2 odir = vec2(cos(a), 0.6 * sin(a));\n  // stack height (parallax travel top<->bottom); the kick pushes the layers apart\n  float stackH = uDepth * 0.7 * (1.0 + 0.3 * kick) * rack;\n  float gapH = stackH / gaps;\n  float inset = (0.0012 + uBevel * 0.08) * rack;\n  vec2 Ld = normalize(vec2(-0.55, 0.8));\n  float opac = mix(0.5, 0.93, uRoughness);\n  float sweep = mix(-1.2, 1.2, fract(t * 0.11));\n\n  // composite the sheets front-to-back (top sheet first; equivalent to back-to-front \"over\") so the loop can\n  // stop once the pixel is opaque. Sheet k sits at p - orbitDir*stackH*(k/(N-1) - 0.5).\n  vec3 col = vec3(0.0);\n  float alpha = 0.0;\n  vec2 qb = p;\n  for (int i = 0; i < 6; i++) {\n    if (i >= N) break;\n    float k = Nf - 1.0 - float(i);\n    float fk = k / gaps;\n    float off = fk - 0.5;\n    vec2 q = (p - odir * stackH * off) / (1.0 + 0.05 * off * rack);\n    qb = q;\n    float R = inset * k;\n    // face of the sheet (eroded by its terrace inset) and its side: the same outline one sheet-thickness lower\n    float m = smoothstep(0.3, 0.7, acRing(q, R).x);\n    vec4 rs = acRing(q + odir * gapH * 0.55, R);\n    float mT = smoothstep(0.3, 0.7, rs.x) * rack;\n    float side = max(mT - m, 0.0);\n    float cov = max(m, mT);\n    if (cov > 0.001) {\n      vec3 tl = uTint.rgb * mix(0.42, 1.0, fk) + vec3(0.06) * fk;\n      // soft shadow from the sheet above (two taps toward the light), fades out as the stack settles\n      float sh = 0.0;\n      if (i > 0) sh = (logoP(q + Ld * gapH * 0.7) + logoP(q + Ld * gapH * 1.4)) * 0.5 * rack;\n      // frosted acrylic scatters: milky, desaturated, brighter faces\n      float lum = dot(tl, vec3(0.299, 0.587, 0.114));\n      tl = mix(tl, mix(vec3(lum), tl, 0.45) * 0.75 + 0.22, uRoughness * 0.75 * rack);\n      vec3 faceC = tl * (1.0 - 0.7 * sh);\n      float gx = (dot(q, normalize(vec2(1.0, 0.45))) - sweep) / 0.09;\n      faceC += vec3(exp(-gx * gx) * (1.0 - uRoughness) * 0.35) * mix(0.6, 1.0, fk) * rack;\n      if (i == 0) {\n        vec4 lg = logoRGBA(q);\n        faceC = mix(faceC, lg.rgb * (1.0 - 0.35 * sh), mix(0.85, 1.0, rest));\n      }\n      // polished sheet edge: light-piping glow, brighter on the side facing the light\n      vec2 gi = length(rs.zw) > 0.0001 ? normalize(rs.zw) : vec2(0.0);\n      float lit = 0.5 + 0.5 * max(dot(-gi, Ld), 0.0);\n      vec3 edgeC = mix(tl, vec3(1.0), 0.3) * (0.45 + 0.7 * lit * (1.0 - 0.6 * uRoughness)) * (0.5 + 0.55 * uFresnel) * (1.0 + 0.6 * uHigh * aud);\n      vec3 c = faceC * m + edgeC * side;\n      float op = mix(m * (i == 0 ? 0.95 : opac) + side * 0.95, cov, rest);\n      col += (1.0 - alpha) * c / max(cov, 0.0001) * op;\n      alpha += (1.0 - alpha) * op;\n    }\n    if (alpha > 0.985) break;\n  }\n  // soft contact shadow of the whole stack, offset away from the light\n  float dropA = 0.0;\n  if (rack > 0.001) {\n    float hd = gapH * 0.9 + 0.006 * rack;\n    dropA = (logoP(qb + Ld * hd) + logoP(qb + Ld * hd * 1.8) + logoP(qb + Ld * hd * 2.6)) / 3.0 * 0.45 * rack;\n  }\n  alpha += (1.0 - alpha) * dropA;\n  gl_FragColor = vjOutPM(vec4(col, alpha));\n}\n"},{"id":"metal-guilloche","name":"Guilloche Moire Mint","category":"metal","blurb":"Banknote engine-turned linework fills the logo: two ring gratings beat into drifting moir\u00c3\u00a9 fringes inside an engraved contour frame.","params":[{"name":"uLineFreq","label":"Line Frequency","type":"float","default":64,"min":24,"max":135,"unit":"lines/height","hint":"Engraved lines per frame height. Capped so a line period stays \u00e2\u2030\u00a5 8 px at 1080p; finer than ~3 px at the render size fades to tone instead of aliasing."},{"name":"uDepth","label":"Extrusion Depth","type":"float","default":0.08,"min":0,"max":0.25,"hint":"Engraving depth: relief of the grooves and how dark they print."},{"name":"uRoughness","label":"Metallic Roughness","type":"float","default":0.15,"min":0,"max":1,"hint":"Polish of the metal between the grooves."},{"name":"uFresnel","label":"Fresnel Rim Light","type":"float","default":1.2,"min":0,"max":3,"hint":"Grazing sheen on the relief and brightness of the contour frame."},{"name":"uBevel","label":"Bevel Radius","type":"float","default":0.012,"min":0.002,"max":0.04,"hint":"Burin width: line weight of the engraving and the frame."},{"name":"uOrbit","label":"Camera Orbit Speed","type":"float","default":0.4,"min":0,"max":2,"hint":"Drift speed of the two grating centres (moir\u00c3\u00a9 motion)."},{"name":"uTint","label":"Material Tint","type":"color","default":[1,0.78,0.36,1],"hint":"Metal: gold, silver, copper\u00e2\u20ac\u00a6"},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Gold Note","values":{}},{"name":"Sterling Silver","values":{"uTint":[0.86,0.89,0.94,1],"uRoughness":0.1}},{"name":"Copper Plate Fine","values":{"uTint":[1,0.55,0.4,1],"uLineFreq":100,"uDepth":0.14}}],"source":"/*{\n  \"DESCRIPTION\": \"Guilloche Moire Mint \u00e2\u20ac\u201d Banknote engine-turned linework fills the logo: two ring gratings beat into drifting moir\u00c3\u00a9 fringes inside an engraved contour frame.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"3D Volumetric & Metallurgic\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uLineFreq\",\"TYPE\":\"float\",\"LABEL\":\"Line Frequency\",\"DEFAULT\":64,\"MIN\":24,\"MAX\":135},\n    {\"NAME\":\"uDepth\",\"TYPE\":\"float\",\"LABEL\":\"Extrusion Depth\",\"DEFAULT\":0.08,\"MIN\":0,\"MAX\":0.25},\n    {\"NAME\":\"uRoughness\",\"TYPE\":\"float\",\"LABEL\":\"Metallic Roughness\",\"DEFAULT\":0.15,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uFresnel\",\"TYPE\":\"float\",\"LABEL\":\"Fresnel Rim Light\",\"DEFAULT\":1.2,\"MIN\":0,\"MAX\":3},\n    {\"NAME\":\"uBevel\",\"TYPE\":\"float\",\"LABEL\":\"Bevel Radius\",\"DEFAULT\":0.012,\"MIN\":0.002,\"MAX\":0.04},\n    {\"NAME\":\"uOrbit\",\"TYPE\":\"float\",\"LABEL\":\"Camera Orbit Speed\",\"DEFAULT\":0.4,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uTint\",\"TYPE\":\"color\",\"LABEL\":\"Material Tint\",\"DEFAULT\":[1,0.78,0.36,1]},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Guilloche Moire Mint \u00c2\u00b7 3D Volumetric & Metallurgic\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nmat2 rot2(float a) { float c = cos(a); float s = sin(a); return mat2(c, -s, s, c); }\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// 25-tap disk coverage of the logo around p (radius r, height-normalized units).\n// x = coverage 0..1 (0.5 on the outline), yz = vector pointing into the logo.\nvec3 logoField(vec2 p, float r) {\n  float sum = logoP(p); vec2 g = vec2(0.0);\n  for (int i = 0; i < 12; i++) {\n    float a = float(i) * 0.5235988;\n    vec2 d1 = vec2(cos(a), sin(a));\n    vec2 d2 = vec2(cos(a + 0.2617994), sin(a + 0.2617994));\n    float s1 = logoP(p + d1 * r);\n    float s2 = logoP(p + d2 * r * 0.5);\n    sum += s1 + s2;\n    g += d1 * s1 + d2 * s2 * 0.5;\n  }\n  return vec3(sum / 25.0, g);\n}\n// Approximate signed distance (positive outside) from a logoField sample of radius r.\nfloat fieldSD(vec3 f, float r) { return (0.5 - f.x) * 2.0 * r; }\n// Edge glow that falls to exactly zero at the field radius r (no full-frame haze floor).\nfloat edgeGlow(float sd, float k, float r) { float f = exp(-r * k); return max(exp(-abs(sd) * k) - f, 0.0) / (1.0 - f); }\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\n// Procedural studio environment for chrome / glass / crystal: four off-axis strip lights at mixed elevations\n// (a flat face sees a horizon split instead of one value that flips dark/bright), energy-normalised roughness\n// (rougher = wider lobes, not brighter), top key, horizon line, dark floor. Peaks ~2.0; callers tonemap.\nvec3 studioEnv(vec3 d, float rough, float spin) {\n  d = normalize(d);\n  d.xz = rot2(spin) * d.xz;\n  float y = d.y;\n  float az = atan(d.x, d.z);\n  float k = mix(40.0, 3.0, rough);\n  float norm = (k + 1.0) / 41.0;\n  vec3 sky = mix(vec3(0.08, 0.09, 0.11), vec3(0.75, 0.8, 0.88), smoothstep(-0.1, 0.8, y));\n  float l1 = pow(max(cos(az - 0.3) * cos((y - 0.15) * 1.6), 0.0), k);\n  float l2 = pow(max(cos(az - 2.4) * cos((y - 0.35) * 1.6), 0.0), k * 0.7);\n  float l3 = pow(max(cos(az + 1.9) * cos((y + 0.05) * 1.6), 0.0), k * 1.3);\n  float l4 = pow(max(cos(az + 3.0) * cos((y - 0.5) * 1.6), 0.0), k * 0.5);\n  float strips = norm * (1.6 * l1 + 1.25 * l2 + 1.1 * l3 + 0.8 * l4);\n  float top = pow(max(y, 0.0), mix(24.0, 2.0, rough)) * mix(1.0, 0.35, rough);\n  float hor = exp(-abs(y) * mix(40.0, 6.0, rough));\n  vec3 col = sky * 0.5 + vec3(1.0, 0.98, 0.95) * strips * 1.5 + vec3(2.0, 1.9, 1.75) * top + vec3(0.7, 0.8, 0.95) * hor;\n  float ground = 1.0 - smoothstep(-0.25, 0.0, y);\n  return mix(col, vec3(0.025, 0.025, 0.03) + hor * 0.2, ground);\n}\n\n// ---- effect ----\nfloat gqSD(vec2 p, float R, out vec2 nIn) {\n  vec3 F = logoField(p, R);\n  float sd0 = fieldSD(F, R);\n  nIn = length(F.yz) > 0.0001 ? normalize(F.yz) : vec2(0.0, 1.0);\n  if (abs(sd0) > R * 0.96) return sd0;\n  bool inside = logoP(p) > 0.5;\n  vec2 dir = inside ? -nIn : nIn;\n  float lo = 0.0;\n  float hi = R;\n  for (int i = 0; i < 6; i++) {\n    float mid = 0.5 * (lo + hi);\n    bool crossed = (logoP(p + dir * mid) > 0.5) != inside;\n    if (crossed) hi = mid; else lo = mid;\n  }\n  float d = 0.5 * (lo + hi);\n  return inside ? -d : d;\n}\n\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  float kick = clamp(uBass * aud, 0.0, 1.5);\n  vec2 nIn;\n  float R = 0.05;\n  float sd = gqSD(p, R, nIn);\n  float la = logoP(p);\n  float px = 1.0 / RENDERSIZE.y;\n  float Lf = clamp(uLineFreq, 16.0, 135.0);\n  float Fq = Lf * 0.5;\n  // two ring gratings whose centres orbit; G = cos(A1)*cos(A2) = 1/2[cos(A1-A2) + cos(A1+A2)]:\n  // the sum term is a fine family of confocal ellipses (the engraved lines), the difference term the\n  // slow hyperbolic moire fringes, which set the line weight (the banknote tone).\n  float a = t * uOrbit * 0.3;\n  vec2 c1 = vec2(-0.3 + 0.14 * cos(a), 0.04 + 0.1 * sin(a * 1.3));\n  vec2 c2 = vec2(0.28 + 0.14 * cos(a * 0.8 + 2.1), -0.05 + 0.1 * sin(a * 0.9 + 0.7));\n  float ratio = 1.03 + 0.035 * kick;\n  vec2 v1 = p - c1;\n  vec2 v2 = p - c2;\n  float r1 = max(length(v1), 0.0001);\n  float r2 = max(length(v2), 0.0001);\n  vec2 u1 = v1 / r1;\n  vec2 u2 = v2 / r2;\n  float A1 = 6.2831853 * Fq * r1;\n  float A2 = 6.2831853 * Fq * ratio * r2;\n  float G = cos(A1) * cos(A2);\n  vec2 gG = -6.2831853 * Fq * (sin(A1) * cos(A2) * u1 + ratio * cos(A1) * sin(A2) * u2);\n  float S = (A1 + A2) / 6.2831853;\n  float gS = max(length(Fq * (u1 + ratio * u2)), 0.5);\n  float spacing = 1.0 / gS;\n  float dl = abs(fract(S + 0.5) - 0.5) * spacing;\n  float fringe = 0.5 + 0.5 * cos(A1 - A2);\n  float wf = 0.45 + uBevel * 28.0;\n  float w = spacing * mix(0.035, 0.36, fringe * fringe) * wf;\n  float line = 1.0 - smoothstep(w - px * 0.75, w + px * 0.75, dl);\n  // aliasing guard: lines closer than ~3 px fade to their mean tone instead of shimmering\n  float guard = smoothstep(2.5, 4.5, spacing * RENDERSIZE.y);\n  float ink = mix(clamp(2.0 * w / spacing, 0.0, 1.0), line, guard);\n\n  // engraved relief, all analytic: each groove is a rounded cut across the line family (gradient =\n  // profile slope x unit grad S, so one wall catches the light and the other falls dark), plus a faint\n  // undulation from grad G so the moire also reads in the sheen\n  vec2 dirS = (u1 + ratio * u2) * Fq / gS;\n  float side = fract(S + 0.5) - 0.5;\n  float xg = dl / max(w, px);\n  float cut = uDepth * 6.0 * guard;\n  vec2 gH = (xg < 1.0 ? xg : 0.0) * sign(side) * dirS * cut;\n  gH += gG / (6.2831853 * Fq) * uDepth * 1.2 * guard;\n  vec3 n = normalize(vec3(-gH, 1.0));\n  vec3 V = normalize(vec3(-p * 0.3, 1.0));\n  vec3 env = studioEnv(reflect(-V, n), uRoughness, t * uOrbit * 0.25 + 0.8);\n  float fres = pow(1.0 - clamp(dot(n, V), 0.0, 1.0), 2.0);\n  float sheen = 0.85 + 0.3 * smoothstep(-0.4, 0.4, p.x * 0.6 + p.y);\n  vec3 metal = uTint.rgb * (0.32 + 0.75 * env) * sheen * (1.0 + 0.35 * uHigh * aud);\n  metal += env * fres * uFresnel * 0.6 * mix(vec3(1.0), uTint.rgb, 0.4);\n  vec3 groove = uTint.rgb * 0.14;\n  vec3 fill = mix(metal, groove, ink * (0.45 + 0.4 * min(uDepth * 7.0, 1.0)));\n  // polished border just inside the outline (keeps the silhouette crisp)\n  float border = smoothstep(-0.006, -0.0035, sd) * (1.0 - smoothstep(-0.0012, 0.0, sd));\n  fill = mix(fill, uTint.rgb * (0.45 + 0.8 * env) * (0.65 + 0.35 * uFresnel), border * 0.9);\n\n  // engraved contour frame: 3 hairline onion lines outside the outline, fading outward, zero before R\n  float fs = max(0.0055 + uBevel * 0.05, 3.2 * px);\n  float lw = 0.0004 + uBevel * 0.02 + px * 0.25;\n  float frame = 0.0;\n  for (int i = 1; i <= 3; i++) {\n    float dd = abs(sd - fs * float(i));\n    frame += (1.0 - smoothstep(lw, lw + px * 1.1, dd)) * (1.05 - float(i) * 0.3);\n  }\n  frame *= step(0.0, sd) * (1.0 - smoothstep(R * 0.8, R * 0.96, sd));\n  vec3 frameC = uTint.rgb * (0.4 + 0.45 * uFresnel) * (0.75 + 0.4 * env.y);\n  vec3 col = fill * la + frameC * frame * (1.0 - la);\n  gl_FragColor = vjOutPM(vec4(col, max(la, frame * (1.0 - la))));\n}\n"},{"id":"glitch-datamosh","name":"Datamosh Block Displacement","category":"glitch","blurb":"Macroblocks lose their I-frames and smear the logo along stale motion vectors.","params":[{"name":"uGlitch","label":"Glitch Burst Intensity","type":"float","default":0.55,"min":0,"max":1,"hint":"Burst strength and how often ticks fire (duty 12% + 30% \u00c3\u2014 intensity)."},{"name":"uGlitchFreq","label":"Frequency Interval","type":"float","default":0.35,"min":0.25,"max":2,"unit":"s","hint":"Length of one burst tick. Minimum 0.25 s keeps full-frame changes under 4/s."},{"name":"uScanDensity","label":"Block Density","type":"float","default":420,"min":50,"max":1200,"unit":"lines","hint":"Higher = smaller macroblocks (6-64 px)."},{"name":"uChannelOffset","label":"Chroma Drag","type":"float","default":0.012,"min":0,"max":0.06,"hint":"How far the red channel lags the moshed blocks."},{"name":"uSeed","label":"Seed Randomization","type":"float","default":7,"min":0,"max":999},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"P-Frame Bleed","values":{}},{"name":"Total Mosh","values":{"uGlitch":0.95,"uGlitchFreq":0.6}},{"name":"Micro Hits","values":{"uGlitch":0.35,"uGlitchFreq":0.25,"uSeed":211}}],"source":"/*{\n  \"DESCRIPTION\": \"Datamosh Block Displacement \u00e2\u20ac\u201d Macroblocks lose their I-frames and smear the logo along stale motion vectors.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Glitch & Cyber\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uGlitch\",\"TYPE\":\"float\",\"LABEL\":\"Glitch Burst Intensity\",\"DEFAULT\":0.55,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uGlitchFreq\",\"TYPE\":\"float\",\"LABEL\":\"Frequency Interval\",\"DEFAULT\":0.35,\"MIN\":0.25,\"MAX\":2},\n    {\"NAME\":\"uScanDensity\",\"TYPE\":\"float\",\"LABEL\":\"Block Density\",\"DEFAULT\":420,\"MIN\":50,\"MAX\":1200},\n    {\"NAME\":\"uChannelOffset\",\"TYPE\":\"float\",\"LABEL\":\"Chroma Drag\",\"DEFAULT\":0.012,\"MIN\":0,\"MAX\":0.06},\n    {\"NAME\":\"uSeed\",\"TYPE\":\"float\",\"LABEL\":\"Seed Randomization\",\"DEFAULT\":7,\"MIN\":0,\"MAX\":999},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Datamosh Block Displacement \u00c2\u00b7 Glitch & Cyber\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nfloat vnoise(vec2 p) {\n  vec2 i = floor(p); vec2 f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x), mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\nfloat glitchClock() { return floor(TIME / max(uGlitchFreq, 0.02)); }\nfloat glitchBurst(float gt) {\n  float b = step(1.0 - uGlitch * 0.85, hash11(gt * 1.371 + uSeed * 0.173));\n  return max(b, step(0.65, uBass * uAudioReact));\n}\n\n// Burst envelope 0..1 for the glitch family. A tick is on for 12% + 30%*uGlitch of the time (capped duty: rare\n// but heavy hits stay possible), decays through the tick, and a kick (uBass*uAudioReact crossing 0.45..0.8,\n// with the analyser's own decay as hysteresis) forces a hit. Ticks never shorter than 0.25 s (photosensitivity).\nfloat glitchGate(float gt) { return step(1.0 - (0.12 + 0.3 * uGlitch), hash11(gt * 1.371 + uSeed * 0.173)); }\nfloat glitchEnv(float gt) {\n  float ph = fract(TIME / max(uGlitchFreq, 0.25));\n  float env = glitchGate(gt) * (1.0 - smoothstep(0.55, 1.0, ph));\n  float hit = smoothstep(0.45, 0.8, uBass * uAudioReact);\n  return max(env, hit);\n}\n// Pose id that re-rolls at 10 Hz independently of the gate (frozen poses read as a slideshow).\nfloat glitchPose() { return mod(floor(TIME * 10.0), 4096.0); }\n// How many consecutive ticks the current run has been on (0..7): lets a smear grow until the run ends.\nfloat glitchRunAge(float gt) {\n  float age = 0.0;\n  for (int k = 1; k < 8; k++) { if (glitchGate(gt - float(k)) < 0.5) break; age += 1.0; }\n  return age;\n}\n// Bounded frame counter for per-frame noise (an unbounded TIME*13.7 hash loses precision after hours).\nfloat glitchFrame(float fps) { return mod(floor(TIME * fps), 4096.0); }\n\n// ---- effect ----\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  float kick = kickN();\n  float gt = glitchClock();\n  float burst = glitchEnv(gt);\n  float pose = glitchPose();\n  // one run = consecutive on-ticks; everything (vectors, which blocks, smear length) is seeded from the run onset\n  float age = glitchRunAge(gt);\n  float onset = gt - age;\n  float ph = fract(t / max(uGlitchFreq, 0.25));\n  float run = min(age + ph, 4.0);\n  float bsPx = clamp(7200.0 / max(uScanDensity, 50.0), 6.0, 64.0);\n  float bs = bsPx / RENDERSIZE.y;\n  vec2 bgrid = vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0) / bs;\n  vec2 bid = floor(uv * bgrid);\n  vec3 h = hash32(bid * 0.37 + onset * 7.31 + uSeed);\n  // coherent motion: a global pan per run plus a low-frequency field, like stale P-frame vectors\n  vec2 pan = hash22(vec2(onset * 1.7, uSeed)) - 0.5;\n  vec2 field = vec2(vnoise(bid * 0.15 + onset), vnoise(bid * 0.15 + 7.3 + onset)) - 0.5;\n  vec2 mv = (pan * 0.1 + field * 0.06) * (0.4 + 0.6 * uGlitch) * (1.0 + 0.7 * kick);\n  float moshed = step(h.z, 0.3 + 0.55 * uGlitch) * step(0.02, burst);\n  vec4 acc = imgClamp(uv); acc.a = keyed(acc);\n  if (moshed > 0.5) {\n    // the smear grows with the run age: the block keeps \"predicting\" from the last keyframe\n    float len = 0.25 + 0.75 * run / 4.0;\n    vec4 smear = vec4(0.0);\n    for (int k = 0; k < 8; k++) {\n      float fk = float(k);\n      vec4 sm = imgClamp(uv - mv * fk * 0.3 * len);\n      sm.a = keyed(sm);\n      smear = max(smear, sm * (1.0 - fk * 0.07));\n    }\n    // chroma drag + 8 px chroma quantisation inside moshed blocks (codec-style, not CRT-style)\n    vec2 cq = floor(uv * RENDERSIZE / 8.0) * 8.0 / RENDERSIZE + 4.0 / RENDERSIZE;\n    vec4 cs = imgClamp(cq - mv * 0.6 * len + vec2(uChannelOffset * (1.0 + kick), 0.0)); cs.a = keyed(cs);\n    vec3 c = smear.rgb;\n    c.rb = mix(c.rb, cs.rb, 0.6 * step(0.001, uChannelOffset));\n    smear.a = max(smear.a, cs.a * 0.85 * step(0.001, uChannelOffset));\n    float q = 6.0 + floor(h.x * 5.0);\n    c = floor(c * q + 0.5) / q;\n    acc = mix(acc, vec4(c, max(smear.a, acc.a)), burst);\n  }\n  vec3 col = acc.rgb * acc.a;\n  gl_FragColor = vjOut(col, acc.a);\n}\n"},{"id":"glitch-rgb","name":"RGB Split Chromatic Aberration","category":"glitch","blurb":"Red/blue channels tear apart along a burst vector with radial fringing and slice shifts.","params":[{"name":"uGlitch","label":"Glitch Burst Intensity","type":"float","default":0.55,"min":0,"max":1,"hint":"Burst strength and how often ticks fire (duty 12% + 30% \u00c3\u2014 intensity)."},{"name":"uGlitchFreq","label":"Frequency Interval","type":"float","default":0.35,"min":0.25,"max":2,"unit":"s","hint":"Length of one burst tick. Minimum 0.25 s keeps full-frame changes under 4/s."},{"name":"uScanDensity","label":"Slice Count","type":"float","default":420,"min":50,"max":1200,"unit":"lines","hint":"How many horizontal slices can shift on a burst (density / 30)."},{"name":"uChannelOffset","label":"Channel Split","type":"float","default":0.012,"min":0,"max":0.06,"hint":"Red/blue separation at rest; bursts and kicks push it up to 1.6x."},{"name":"uSeed","label":"Seed Randomization","type":"float","default":23,"min":0,"max":999},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Prism Hit","values":{}},{"name":"Wide Fringe","values":{"uChannelOffset":0.04,"uGlitch":0.4}},{"name":"Slice Storm","values":{"uGlitch":0.9,"uGlitchFreq":0.25,"uSeed":42}}],"source":"/*{\n  \"DESCRIPTION\": \"RGB Split Chromatic Aberration \u00e2\u20ac\u201d Red/blue channels tear apart along a burst vector with radial fringing and slice shifts.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Glitch & Cyber\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uGlitch\",\"TYPE\":\"float\",\"LABEL\":\"Glitch Burst Intensity\",\"DEFAULT\":0.55,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uGlitchFreq\",\"TYPE\":\"float\",\"LABEL\":\"Frequency Interval\",\"DEFAULT\":0.35,\"MIN\":0.25,\"MAX\":2},\n    {\"NAME\":\"uScanDensity\",\"TYPE\":\"float\",\"LABEL\":\"Slice Count\",\"DEFAULT\":420,\"MIN\":50,\"MAX\":1200},\n    {\"NAME\":\"uChannelOffset\",\"TYPE\":\"float\",\"LABEL\":\"Channel Split\",\"DEFAULT\":0.012,\"MIN\":0,\"MAX\":0.06},\n    {\"NAME\":\"uSeed\",\"TYPE\":\"float\",\"LABEL\":\"Seed Randomization\",\"DEFAULT\":23,\"MIN\":0,\"MAX\":999},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// RGB Split Chromatic Aberration \u00c2\u00b7 Glitch & Cyber\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\nfloat glitchClock() { return floor(TIME / max(uGlitchFreq, 0.02)); }\nfloat glitchBurst(float gt) {\n  float b = step(1.0 - uGlitch * 0.85, hash11(gt * 1.371 + uSeed * 0.173));\n  return max(b, step(0.65, uBass * uAudioReact));\n}\n\n// Burst envelope 0..1 for the glitch family. A tick is on for 12% + 30%*uGlitch of the time (capped duty: rare\n// but heavy hits stay possible), decays through the tick, and a kick (uBass*uAudioReact crossing 0.45..0.8,\n// with the analyser's own decay as hysteresis) forces a hit. Ticks never shorter than 0.25 s (photosensitivity).\nfloat glitchGate(float gt) { return step(1.0 - (0.12 + 0.3 * uGlitch), hash11(gt * 1.371 + uSeed * 0.173)); }\nfloat glitchEnv(float gt) {\n  float ph = fract(TIME / max(uGlitchFreq, 0.25));\n  float env = glitchGate(gt) * (1.0 - smoothstep(0.55, 1.0, ph));\n  float hit = smoothstep(0.45, 0.8, uBass * uAudioReact);\n  return max(env, hit);\n}\n// Pose id that re-rolls at 10 Hz independently of the gate (frozen poses read as a slideshow).\nfloat glitchPose() { return mod(floor(TIME * 10.0), 4096.0); }\n// How many consecutive ticks the current run has been on (0..7): lets a smear grow until the run ends.\nfloat glitchRunAge(float gt) {\n  float age = 0.0;\n  for (int k = 1; k < 8; k++) { if (glitchGate(gt - float(k)) < 0.5) break; age += 1.0; }\n  return age;\n}\n// Bounded frame counter for per-frame noise (an unbounded TIME*13.7 hash loses precision after hours).\nfloat glitchFrame(float fps) { return mod(floor(TIME * fps), 4096.0); }\n\n// ---- effect ----\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  float kick = kickN();\n  float gt = glitchClock();\n  float burst = glitchEnv(gt);\n  float pose = glitchPose();\n  vec3 h = hash32(vec2(pose, uSeed));\n  float amtRest = uChannelOffset * 0.35 * (1.0 + 0.8 * kick);\n  float amt = min(amtRest + uChannelOffset * burst * 2.5 * uGlitch, uChannelOffset * 1.6);\n  float ang = h.x * 6.2831853;\n  vec2 dir = vec2(cos(ang), sin(ang));\n  vec2 radial = (uv - 0.5) * amt * 2.0;\n  float n = 6.0 + floor(uScanDensity / 30.0);\n  float slice = floor(uv.y * n);\n  float sh = (hash11(slice + pose * 3.1 + uSeed) - 0.5) * 0.12 * uGlitch * burst * step(0.55, hash11(slice * 1.7 + gt));\n  vec2 su = uv + vec2(sh, 0.0);\n  vec4 r = imgClamp(su + dir * amt + radial); r.a = keyed(r);\n  vec4 g = imgClamp(su); g.a = keyed(g);\n  vec4 b = imgClamp(su - dir * amt - radial); b.a = keyed(b);\n  vec4 o = imgClamp(uv); o.a = keyed(o);\n  vec3 split = vec3(r.r * r.a, g.g * g.a, b.b * b.a);\n  // luma anchor keeps the mark readable through the split; the pure R/B ghosts only tint outside the silhouette\n  vec3 col = mix(split, o.rgb * o.a, 0.4 * burst);\n  col += vec3(r.a, 0.0, b.a) * 0.18 * (1.0 - g.a);\n  float a = max(max(r.a, g.a), b.a);\n  float line = step(0.985, hash11(slice + glitchFrame(30.0))) * burst * uGlitch;\n  col += vec3(1.0) * line * 0.5 * a;\n  gl_FragColor = vjOut(col, a);\n}\n"},{"id":"glitch-crt","name":"CRT Scanline Raster Distortion","category":"glitch","blurb":"Curved tube, aperture grille, phosphor bloom, rolling bar and h-sync tears on bursts.","params":[{"name":"uGlitch","label":"Glitch Burst Intensity","type":"float","default":0.55,"min":0,"max":1,"hint":"Burst strength and how often ticks fire (duty 12% + 30% \u00c3\u2014 intensity)."},{"name":"uGlitchFreq","label":"Frequency Interval","type":"float","default":0.35,"min":0.25,"max":2,"unit":"s","hint":"Length of one burst tick. Minimum 0.25 s keeps full-frame changes under 4/s."},{"name":"uScanDensity","label":"Scanlines","type":"float","default":420,"min":50,"max":1200,"unit":"lines","hint":"Lines per frame height; snapped to an integer pixel pitch (no moire)."},{"name":"uChannelOffset","label":"Convergence Error","type":"float","default":0.004,"min":0,"max":0.06,"hint":"Radial R/B misconvergence: clean at the centre, grows toward the corners like a real tube."},{"name":"uSeed","label":"Seed Randomization","type":"float","default":101,"min":0,"max":999},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"},{"name":"uVeil","label":"Raster Veil","type":"float","default":0.3,"min":0,"max":1,"hint":"Glass glow and rolling bar over the whole raster. 0 = nothing drawn outside the logo."}],"presets":[{"name":"Arcade Tube","values":{}},{"name":"Broken Hold","values":{"uGlitch":0.9,"uGlitchFreq":0.8}},{"name":"Hi-Res Monitor","values":{"uScanDensity":540,"uChannelOffset":0.002,"uGlitch":0.2,"uVeil":0.15}}],"source":"/*{\n  \"DESCRIPTION\": \"CRT Scanline Raster Distortion \u00e2\u20ac\u201d Curved tube, aperture grille, phosphor bloom, rolling bar and h-sync tears on bursts.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Glitch & Cyber\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uGlitch\",\"TYPE\":\"float\",\"LABEL\":\"Glitch Burst Intensity\",\"DEFAULT\":0.55,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uGlitchFreq\",\"TYPE\":\"float\",\"LABEL\":\"Frequency Interval\",\"DEFAULT\":0.35,\"MIN\":0.25,\"MAX\":2},\n    {\"NAME\":\"uScanDensity\",\"TYPE\":\"float\",\"LABEL\":\"Scanlines\",\"DEFAULT\":420,\"MIN\":50,\"MAX\":1200},\n    {\"NAME\":\"uChannelOffset\",\"TYPE\":\"float\",\"LABEL\":\"Convergence Error\",\"DEFAULT\":0.004,\"MIN\":0,\"MAX\":0.06},\n    {\"NAME\":\"uSeed\",\"TYPE\":\"float\",\"LABEL\":\"Seed Randomization\",\"DEFAULT\":101,\"MIN\":0,\"MAX\":999},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uVeil\",\"TYPE\":\"float\",\"LABEL\":\"Raster Veil\",\"DEFAULT\":0.3,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// CRT Scanline Raster Distortion \u00c2\u00b7 Glitch & Cyber\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\nfloat glitchClock() { return floor(TIME / max(uGlitchFreq, 0.02)); }\nfloat glitchBurst(float gt) {\n  float b = step(1.0 - uGlitch * 0.85, hash11(gt * 1.371 + uSeed * 0.173));\n  return max(b, step(0.65, uBass * uAudioReact));\n}\n\n// Burst envelope 0..1 for the glitch family. A tick is on for 12% + 30%*uGlitch of the time (capped duty: rare\n// but heavy hits stay possible), decays through the tick, and a kick (uBass*uAudioReact crossing 0.45..0.8,\n// with the analyser's own decay as hysteresis) forces a hit. Ticks never shorter than 0.25 s (photosensitivity).\nfloat glitchGate(float gt) { return step(1.0 - (0.12 + 0.3 * uGlitch), hash11(gt * 1.371 + uSeed * 0.173)); }\nfloat glitchEnv(float gt) {\n  float ph = fract(TIME / max(uGlitchFreq, 0.25));\n  float env = glitchGate(gt) * (1.0 - smoothstep(0.55, 1.0, ph));\n  float hit = smoothstep(0.45, 0.8, uBass * uAudioReact);\n  return max(env, hit);\n}\n// Pose id that re-rolls at 10 Hz independently of the gate (frozen poses read as a slideshow).\nfloat glitchPose() { return mod(floor(TIME * 10.0), 4096.0); }\n// How many consecutive ticks the current run has been on (0..7): lets a smear grow until the run ends.\nfloat glitchRunAge(float gt) {\n  float age = 0.0;\n  for (int k = 1; k < 8; k++) { if (glitchGate(gt - float(k)) < 0.5) break; age += 1.0; }\n  return age;\n}\n// Bounded frame counter for per-frame noise (an unbounded TIME*13.7 hash loses precision after hours).\nfloat glitchFrame(float fps) { return mod(floor(TIME * fps), 4096.0); }\n\n// ---- effect ----\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  float kick = kickN();\n  float gt = glitchClock();\n  float burst = glitchEnv(gt);\n  float pose = glitchPose();\n  vec2 c = uv - 0.5;\n  float k = 0.12 + 0.1 * uGlitch;\n  float breathe = 0.97 * (1.0 - 0.02 * kick);\n  vec2 tuv = 0.5 + c * (1.0 + k * dot(c, c)) * breathe;\n  float inScreen = step(0.0, tuv.x) * step(tuv.x, 1.0) * step(0.0, tuv.y) * step(tuv.y, 1.0);\n  // vertical roll scrolls through the tick instead of a held jump; tears concentrate at the top of the raster\n  float ph = fract(t / max(uGlitchFreq, 0.25));\n  tuv.y = fract(tuv.y + burst * hash11(gt + uSeed) * 0.35 * uGlitch * ph);\n  float topW = pow(1.0 - tuv.y, 6.0);\n  tuv.x += sin(tuv.y * 40.0 + t * 20.0) * 0.02 * burst * uGlitch * (0.25 + topW);\n  tuv.x += (hash11(floor(tuv.y * 240.0) + glitchFrame(60.0)) - 0.5) * 0.003 * uGlitch * (0.3 + topW);\n  float co = uChannelOffset * (0.1 + 4.0 * dot(c, c));\n  vec4 sr = imgClamp(tuv + vec2(co, 0.0)); sr.a = keyed(sr);\n  vec4 sg = imgClamp(tuv); sg.a = keyed(sg);\n  vec4 sb = imgClamp(tuv - vec2(co, 0.0)); sb.a = keyed(sb);\n  vec3 col = vec3(sr.r * sr.a, sg.g * sg.a, sb.b * sb.a);\n  vec3 bloom = vec3(0.0);\n  for (int i = 0; i < 8; i++) {\n    float a = float(i) * 0.785398;\n    vec4 sm = imgClamp(tuv + vec2(cos(a), sin(a)) * 0.006);\n    bloom += sm.rgb * keyed(sm);\n  }\n  col += bloom / 8.0 * 0.5;\n  // integer-pitch scanlines (fade out under 3 px) and an energy-preserving aperture grille\n  float pitch = max(2.0, floor(RENDERSIZE.y / max(uScanDensity, 50.0) + 0.5));\n  float scanAmp = 0.22 * smoothstep(2.0, 3.5, pitch);\n  float scan = 1.0 - scanAmp * (0.5 + 0.5 * cos(6.2831853 * gl_FragCoord.y / pitch));\n  col *= scan;\n  float px = mod(gl_FragCoord.x, 3.0);\n  vec3 mask = vec3(step(px, 1.0), step(1.0, px) * step(px, 2.0), step(2.0, px));\n  col *= mix(vec3(1.0), mask * 2.4 + 0.2, 0.45);\n  float bar = exp(-pow((fract(uv.y - t * 0.15) - 0.5) * 8.0, 2.0)) * 0.12;\n  col += vec3(0.6, 0.9, 1.0) * bar * (col + 0.03 * uVeil);\n  col *= (1.0 - dot(c, c) * 1.3) * inScreen;\n  vec3 glass = vec3(0.02, 0.035, 0.03) * scan * inScreen * uVeil;\n  gl_FragColor = vjOut(col + glass, 0.0);\n}\n"},{"id":"glitch-vhs","name":"VHS Tape Tracking Tear","category":"glitch","blurb":"Smeared chroma, a wandering tracking band, head-switching noise and tape dropouts.","params":[{"name":"uGlitch","label":"Glitch Burst Intensity","type":"float","default":0.55,"min":0,"max":1,"hint":"Burst strength and how often ticks fire (duty 12% + 30% \u00c3\u2014 intensity)."},{"name":"uGlitchFreq","label":"Frequency Interval","type":"float","default":0.35,"min":0.25,"max":2,"unit":"s","hint":"Length of one burst tick. Minimum 0.25 s keeps full-frame changes under 4/s."},{"name":"uScanDensity","label":"Tape Lines","type":"float","default":420,"min":50,"max":1200,"unit":"lines","hint":"Line density for dropouts and head noise."},{"name":"uChannelOffset","label":"Chroma Bleed","type":"float","default":0.012,"min":0,"max":0.06,"hint":"Horizontal chroma smear (alpha-weighted, so letters keep their colour)."},{"name":"uSeed","label":"Seed Randomization","type":"float","default":55,"min":0,"max":999},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Rental Copy","values":{}},{"name":"Worn Tape","values":{"uGlitch":0.9,"uChannelOffset":0.025}},{"name":"Clean Dub","values":{"uGlitch":0.2,"uChannelOffset":0.006}}],"source":"/*{\n  \"DESCRIPTION\": \"VHS Tape Tracking Tear \u00e2\u20ac\u201d Smeared chroma, a wandering tracking band, head-switching noise and tape dropouts.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Glitch & Cyber\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uGlitch\",\"TYPE\":\"float\",\"LABEL\":\"Glitch Burst Intensity\",\"DEFAULT\":0.55,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uGlitchFreq\",\"TYPE\":\"float\",\"LABEL\":\"Frequency Interval\",\"DEFAULT\":0.35,\"MIN\":0.25,\"MAX\":2},\n    {\"NAME\":\"uScanDensity\",\"TYPE\":\"float\",\"LABEL\":\"Tape Lines\",\"DEFAULT\":420,\"MIN\":50,\"MAX\":1200},\n    {\"NAME\":\"uChannelOffset\",\"TYPE\":\"float\",\"LABEL\":\"Chroma Bleed\",\"DEFAULT\":0.012,\"MIN\":0,\"MAX\":0.06},\n    {\"NAME\":\"uSeed\",\"TYPE\":\"float\",\"LABEL\":\"Seed Randomization\",\"DEFAULT\":55,\"MIN\":0,\"MAX\":999},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// VHS Tape Tracking Tear \u00c2\u00b7 Glitch & Cyber\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nfloat vnoise(vec2 p) {\n  vec2 i = floor(p); vec2 f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x), mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);\n}\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\nfloat glitchClock() { return floor(TIME / max(uGlitchFreq, 0.02)); }\nfloat glitchBurst(float gt) {\n  float b = step(1.0 - uGlitch * 0.85, hash11(gt * 1.371 + uSeed * 0.173));\n  return max(b, step(0.65, uBass * uAudioReact));\n}\n\n// Burst envelope 0..1 for the glitch family. A tick is on for 12% + 30%*uGlitch of the time (capped duty: rare\n// but heavy hits stay possible), decays through the tick, and a kick (uBass*uAudioReact crossing 0.45..0.8,\n// with the analyser's own decay as hysteresis) forces a hit. Ticks never shorter than 0.25 s (photosensitivity).\nfloat glitchGate(float gt) { return step(1.0 - (0.12 + 0.3 * uGlitch), hash11(gt * 1.371 + uSeed * 0.173)); }\nfloat glitchEnv(float gt) {\n  float ph = fract(TIME / max(uGlitchFreq, 0.25));\n  float env = glitchGate(gt) * (1.0 - smoothstep(0.55, 1.0, ph));\n  float hit = smoothstep(0.45, 0.8, uBass * uAudioReact);\n  return max(env, hit);\n}\n// Pose id that re-rolls at 10 Hz independently of the gate (frozen poses read as a slideshow).\nfloat glitchPose() { return mod(floor(TIME * 10.0), 4096.0); }\n// How many consecutive ticks the current run has been on (0..7): lets a smear grow until the run ends.\nfloat glitchRunAge(float gt) {\n  float age = 0.0;\n  for (int k = 1; k < 8; k++) { if (glitchGate(gt - float(k)) < 0.5) break; age += 1.0; }\n  return age;\n}\n// Bounded frame counter for per-frame noise (an unbounded TIME*13.7 hash loses precision after hours).\nfloat glitchFrame(float fps) { return mod(floor(TIME * fps), 4096.0); }\n\n// ---- effect ----\nvec3 rgb2yiq(vec3 c) { return vec3(dot(c, vec3(0.299, 0.587, 0.114)), dot(c, vec3(0.596, -0.274, -0.322)), dot(c, vec3(0.211, -0.523, 0.312))); }\nvec3 yiq2rgb(vec3 c) { return vec3(c.x + 0.956 * c.y + 0.621 * c.z, c.x - 0.272 * c.y - 0.647 * c.z, c.x - 1.106 * c.y + 1.703 * c.z); }\n\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  float kick = kickN();\n  float gt = glitchClock();\n  float burst = glitchEnv(gt);\n  float pose = glitchPose();\n  // tracking band slides between its previous and current random position through the tick\n  float ph = fract(t / max(uGlitchFreq, 0.25));\n  float crawl = fract(-t * 0.06 + uSeed * 0.013);\n  float bPrev = burst > 0.3 ? hash11(gt - 1.0 + uSeed) : crawl;\n  float bCur = burst > 0.3 ? hash11(gt + uSeed) : crawl;\n  float bandY = mix(bPrev, bCur, smoothstep(0.0, 0.35, ph));\n  float bandH = 0.03 + 0.03 * uGlitch;\n  float inBand = 1.0 - smoothstep(0.0, bandH, abs(uv.y - bandY));\n  float tear = inBand * (0.4 + burst + kick * 0.8);\n  float jitter = (vnoise(vec2(uv.y * 120.0, t * 40.0)) - 0.5) * 0.06 * tear * uGlitch;\n  float wobble = sin(uv.y * 8.0 + t * 1.3) * 0.0015 + sin(uv.y * 60.0 + t * 7.0) * 0.0006;\n  float head = 1.0 - smoothstep(0.0, 0.05, uv.y);\n  float headShift = head * (hash11(floor(uv.y * 90.0) + glitchFrame(30.0)) - 0.3) * 0.05;\n  vec2 su = uv + vec2(jitter + wobble + headShift, 0.0);\n  // luma: slight horizontal softness with a ringing overshoot (tape bandwidth)\n  float lx = 1.5 / RENDERSIZE.x;\n  vec4 s0 = imgClamp(su); s0.a = keyed(s0);\n  vec4 sl = imgClamp(su - vec2(lx, 0.0)); sl.a = keyed(sl);\n  vec4 sr2 = imgClamp(su + vec2(lx, 0.0)); sr2.a = keyed(sr2);\n  float yL = rgb2yiq(sl.rgb * sl.a).x; float yC = rgb2yiq(s0.rgb * s0.a).x; float yR = rgb2yiq(sr2.rgb * sr2.a).x;\n  float yBlur = (yL + 2.0 * yC + yR) * 0.25;\n  float luma = max(yBlur + 0.35 * (yC - yBlur), 0.0);\n  // chroma: alpha-weighted, centred kernel from -0.5 to +2 x offset (bleeds right, never greys the letters)\n  float co = uChannelOffset * 0.7;\n  vec3 ch = vec3(0.0); float ca = 0.0;\n  for (int i = 0; i < 6; i++) {\n    float off = co * (-0.5 + float(i) * 0.5);\n    vec4 sm = imgClamp(su - vec2(off, 0.0));\n    sm.a = keyed(sm);\n    ch += rgb2yiq(sm.rgb) * sm.a; ca += sm.a;\n  }\n  ch /= max(ca, 0.001);\n  float aOut = max(s0.a, ca / 6.0);\n  vec3 col = max(yiq2rgb(vec3(luma, ch.y * aOut, ch.z * aOut)), 0.0);\n  // dropouts: 40-100 px segments, 2-4 lines tall\n  float fr = glitchFrame(25.0);\n  float ln = floor(uv.y * uScanDensity / 3.0);\n  float seg = floor(gl_FragCoord.x / (40.0 + 60.0 * hash11(ln + fr)));\n  float drop = step(0.997 - 0.003 * uGlitch, hash12(vec2(ln, fr + uSeed))) * step(0.6, hash12(vec2(seg, ln + fr)));\n  float n = hash12(floor(uv * vec2(RENDERSIZE.x * 0.5, uScanDensity)) + glitchFrame(30.0));\n  col += vec3(0.75) * drop + vec3(n * 0.35) * tear + vec3(n * 0.25) * head;\n  col *= 0.94 + 0.06 * sin(uv.y * uScanDensity * 3.14159);\n  gl_FragColor = vjOut(col, max(aOut, max(drop, tear * 0.5 + head * 0.3) * uGlitch));\n}\n"},{"id":"glitch-static","name":"Digital Noise Static","category":"glitch","blurb":"The logo fights through bit-crushed static with inverted block bursts and rolling bands.","params":[{"name":"uGlitch","label":"Glitch Burst Intensity","type":"float","default":0.55,"min":0,"max":1,"hint":"Burst strength and how often ticks fire (duty 12% + 30% \u00c3\u2014 intensity)."},{"name":"uGlitchFreq","label":"Frequency Interval","type":"float","default":0.35,"min":0.25,"max":2,"unit":"s","hint":"Length of one burst tick. Minimum 0.25 s keeps full-frame changes under 4/s."},{"name":"uScanDensity","label":"Band Count","type":"float","default":420,"min":50,"max":1200,"unit":"lines","hint":"Rolling interference bands (density / 200)."},{"name":"uChannelOffset","label":"Chroma Noise","type":"float","default":0.012,"min":0,"max":0.06,"hint":"Colour in the static grain."},{"name":"uSeed","label":"Seed Randomization","type":"float","default":303,"min":0,"max":999},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Dead Channel","values":{}},{"name":"Signal Found","values":{"uGlitch":0.25}},{"name":"Block Storm","values":{"uGlitch":0.8,"uGlitchFreq":0.3,"uChannelOffset":0.03}}],"source":"/*{\n  \"DESCRIPTION\": \"Digital Noise Static \u00e2\u20ac\u201d The logo fights through bit-crushed static with inverted block bursts and rolling bands.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Glitch & Cyber\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uGlitch\",\"TYPE\":\"float\",\"LABEL\":\"Glitch Burst Intensity\",\"DEFAULT\":0.55,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uGlitchFreq\",\"TYPE\":\"float\",\"LABEL\":\"Frequency Interval\",\"DEFAULT\":0.35,\"MIN\":0.25,\"MAX\":2},\n    {\"NAME\":\"uScanDensity\",\"TYPE\":\"float\",\"LABEL\":\"Band Count\",\"DEFAULT\":420,\"MIN\":50,\"MAX\":1200},\n    {\"NAME\":\"uChannelOffset\",\"TYPE\":\"float\",\"LABEL\":\"Chroma Noise\",\"DEFAULT\":0.012,\"MIN\":0,\"MAX\":0.06},\n    {\"NAME\":\"uSeed\",\"TYPE\":\"float\",\"LABEL\":\"Seed Randomization\",\"DEFAULT\":303,\"MIN\":0,\"MAX\":999},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Digital Noise Static \u00c2\u00b7 Glitch & Cyber\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// Minimum width in height-normalised units so hairlines never drop below ~1.2 px (sub-pixel lines shimmer).\nfloat pxMin(float w) { return max(w, 1.2 / RENDERSIZE.y); }\n// Clamped kick drive: Audio Reactivity goes to 2, and an unclamped uBass*uAudioReact blows masks open.\nfloat kickN() { return min(uBass * uAudioReact, 1.0); }\n// Remap a 0..1 LFO so the result holds at 1 above hi and at 0 below lo (a legible hold instead of a scrub).\nfloat holdRamp(float x, float lo, float hi) { return clamp((x - lo) / max(hi - lo, 0.0001), 0.0, 1.0); }\n\nfloat logoCov5(vec2 p, float r) {\n  return (logoP(p) + logoP(p + vec2(r, 0.0)) + logoP(p - vec2(r, 0.0)) + logoP(p + vec2(0.0, r)) + logoP(p - vec2(0.0, r))) * 0.2;\n}\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\nfloat glitchClock() { return floor(TIME / max(uGlitchFreq, 0.02)); }\nfloat glitchBurst(float gt) {\n  float b = step(1.0 - uGlitch * 0.85, hash11(gt * 1.371 + uSeed * 0.173));\n  return max(b, step(0.65, uBass * uAudioReact));\n}\n\n// Burst envelope 0..1 for the glitch family. A tick is on for 12% + 30%*uGlitch of the time (capped duty: rare\n// but heavy hits stay possible), decays through the tick, and a kick (uBass*uAudioReact crossing 0.45..0.8,\n// with the analyser's own decay as hysteresis) forces a hit. Ticks never shorter than 0.25 s (photosensitivity).\nfloat glitchGate(float gt) { return step(1.0 - (0.12 + 0.3 * uGlitch), hash11(gt * 1.371 + uSeed * 0.173)); }\nfloat glitchEnv(float gt) {\n  float ph = fract(TIME / max(uGlitchFreq, 0.25));\n  float env = glitchGate(gt) * (1.0 - smoothstep(0.55, 1.0, ph));\n  float hit = smoothstep(0.45, 0.8, uBass * uAudioReact);\n  return max(env, hit);\n}\n// Pose id that re-rolls at 10 Hz independently of the gate (frozen poses read as a slideshow).\nfloat glitchPose() { return mod(floor(TIME * 10.0), 4096.0); }\n// How many consecutive ticks the current run has been on (0..7): lets a smear grow until the run ends.\nfloat glitchRunAge(float gt) {\n  float age = 0.0;\n  for (int k = 1; k < 8; k++) { if (glitchGate(gt - float(k)) < 0.5) break; age += 1.0; }\n  return age;\n}\n// Bounded frame counter for per-frame noise (an unbounded TIME*13.7 hash loses precision after hours).\nfloat glitchFrame(float fps) { return mod(floor(TIME * fps), 4096.0); }\n\n// ---- effect ----\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float t = TIME;\n  float aud = uAudioReact;\n  float kick = kickN();\n  float gt = glitchClock();\n  float burst = glitchEnv(gt);\n  float pose = glitchPose();\n  float frame = glitchFrame(30.0);\n  vec2 px = floor(gl_FragCoord.xy / 2.0);\n  float stat = hash12(px + frame * 13.7 + uSeed);\n  float statC = hash12(px + frame * 7.1 + 3.0);\n  // analog snow: per-line horizontal streaks on top of the grain\n  float streak = hash12(vec2(floor(gl_FragCoord.x / 6.0), gl_FragCoord.y) + frame);\n  vec2 blk = floor(uv * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0) * 14.0);\n  float bh = hash12(blk + gt * 1.3 + uSeed);\n  float blockOn = step(1.0 - 0.45 * uGlitch, bh) * burst;\n  vec4 lg = imgClamp(uv + vec2((bh - 0.5) * 0.04 * blockOn, 0.0));\n  lg.a = keyed(lg);\n  float reveal = clamp(1.0 - uGlitch * 0.7 + 0.25 * sin(t * 1.3), 0.0, 1.0);\n  float through = step(stat, reveal + 0.2);\n  // the gradient only posterises inside a burst\n  float levels = mix(32.0, 2.0 + floor((1.0 - uGlitch) * 6.0), burst);\n  vec3 lc = floor(lg.rgb * levels + 0.5) / levels;\n  vec3 col = lc * lg.a * mix(1.0, through, 0.6 * uGlitch * burst);\n  // static is strongest on and around the mark; the far field only carries a quarter of it\n  float near = logoCov5(p, 0.12);\n  float sAmt = (0.18 * uGlitch * burst + 0.25 * blockOn + 0.1 * uHigh * aud) * mix(0.08, 1.0, near);\n  vec3 grain = vec3(mix(stat, streak, 0.5)) * sAmt;\n  grain += vec3(statC, hash12(px + frame * 3.3 + 9.0), stat) * uChannelOffset * 16.0 * sAmt;\n  float band = (1.0 - smoothstep(0.0, 0.3, abs(fract(uv.y * uScanDensity / 200.0 - t * 0.5) - 0.5))) * 0.15;\n  col += grain * (1.0 + band * 7.0);\n  // block bursts invert luma only, so the mark keeps its own hues\n  float lum = dot(col, vec3(0.299, 0.587, 0.114));\n  vec3 inv = col * (1.0 - lum) / max(lum, 0.05) * lg.a;\n  col = mix(col, clamp(inv, 0.0, 1.0), blockOn * step(0.5, hash12(blk + 5.0)) * lg.a);\n  float a = max(lg.a, min(sAmt * 2.0, 1.0) * near);\n  gl_FragColor = vjOut(col, a);\n}\n"},{"id":"glitch-beatcut","name":"Beat-Cut Strobe Slicer","category":"glitch","blurb":"VJ jump-cuts on the beat: reframe, flip, fold, 2\u00c3\u20142 tile and slice-shift hits that snap back to a clean hold.","params":[{"name":"uGlitch","label":"Glitch Burst Intensity","type":"float","default":0.55,"min":0,"max":1,"hint":"Chance a beat cuts (kicks always cut) and how long the cut holds before snapping clean. 0 = off."},{"name":"uGlitchFreq","label":"Frequency Interval","type":"float","default":0.35,"min":0.25,"max":2,"unit":"s","hint":"Beat length in seconds (60 \u00c3\u00b7 BPM; 0.484 = 124 BPM). With Beat Phase mapped, cuts land on the beat; unmapped, a free clock at this interval runs. Cut rate is capped at 3/s."},{"name":"uScanDensity","label":"Scanline Density","type":"float","default":420,"min":50,"max":1200,"unit":"lines","hint":"Slice bands for slice-and-shift cuts and the scanline texture on cut frames."},{"name":"uChannelOffset","label":"Color Channel Offset","type":"float","default":0.012,"min":0,"max":0.06,"hint":"RGB split width on cut frames."},{"name":"uSeed","label":"Seed Randomization","type":"float","default":7,"min":0,"max":999,"hint":"Re-rolls which cut lands on which beat."},{"name":"uBeat","label":"Beat Phase","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"beat","hint":"Sawtooth 0\u00e2\u2020\u20191 per beat (app BPM clock). In Resolume, map to a BPM-synced parameter; in TD, a beat CHOP ramp."},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Jump Cut 124","values":{"uGlitchFreq":0.484}},{"name":"Hard Techno","values":{"uGlitchFreq":0.484,"uGlitch":0.85,"uChannelOffset":0.022,"uScanDensity":640,"uAudioReact":1.3}},{"name":"Minimal Cuts","values":{"uGlitchFreq":0.484,"uGlitch":0.3,"uChannelOffset":0.005,"uAudioReact":0.75,"uSeed":311}}],"source":"/*{\n  \"DESCRIPTION\": \"Beat-Cut Strobe Slicer \u00e2\u20ac\u201d VJ jump-cuts on the beat: reframe, flip, fold, 2\u00c3\u20142 tile and slice-shift hits that snap back to a clean hold.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Glitch & Cyber\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uGlitch\",\"TYPE\":\"float\",\"LABEL\":\"Glitch Burst Intensity\",\"DEFAULT\":0.55,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uGlitchFreq\",\"TYPE\":\"float\",\"LABEL\":\"Frequency Interval\",\"DEFAULT\":0.35,\"MIN\":0.25,\"MAX\":2},\n    {\"NAME\":\"uScanDensity\",\"TYPE\":\"float\",\"LABEL\":\"Scanline Density\",\"DEFAULT\":420,\"MIN\":50,\"MAX\":1200},\n    {\"NAME\":\"uChannelOffset\",\"TYPE\":\"float\",\"LABEL\":\"Color Channel Offset\",\"DEFAULT\":0.012,\"MIN\":0,\"MAX\":0.06},\n    {\"NAME\":\"uSeed\",\"TYPE\":\"float\",\"LABEL\":\"Seed Randomization\",\"DEFAULT\":7,\"MIN\":0,\"MAX\":999},\n    {\"NAME\":\"uBeat\",\"TYPE\":\"float\",\"LABEL\":\"Beat Phase\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Beat-Cut Strobe Slicer \u00c2\u00b7 Glitch & Cyber\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\n// ---- effect ----\nvec2 gxBeat(float L) {\n  float q = TIME / L;\n  bool driven = uBeat > 0.0005;\n  float ph = driven ? uBeat : fract(q + 0.5);\n  return vec2(ph, driven ? floor(q - ph + 0.5) : floor(q + 0.5));\n}\nfloat gxEligible(float idx, float L) {\n  float k = exp2(ceil(log2(max(1.0 / (3.0 * L), 1.0)) - 0.001));\n  return step(mod(idx, k), 0.5);\n}\n\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float asp = RENDERSIZE.x / RENDERSIZE.y;\n  float kick = uBass * uAudioReact;\n  float L = max(uGlitchFreq, 0.05);\n  vec2 bt = gxBeat(L);\n  float ph = bt.x;\n  float bi = bt.y;\n  vec3 h = hash32(vec2(bi * 1.371 + 0.37, uSeed * 0.173 + 5.1));\n  float duty = 0.22 + 0.3 * uGlitch;\n  // onset-level estimate: a kick decays ~exp(-6 ph), so this holds steady through the cut window\n  float kEst = kick * exp(6.0 * min(ph, duty));\n  // phrase rhythm: downbeats always eligible, other beats at 40%; intensity sets how many beats actually cut\n  float barW = mod(bi, 4.0) < 0.5 ? 1.0 : 0.4;\n  float gate = step(h.x, uGlitch * 0.8 * mix(0.6, 1.0, barW));\n  float forced = step(0.5, kEst) * step(h.x * 0.7, 0.25 + 0.75 * uGlitch);\n  float cut = gxEligible(bi, L) * step(ph, duty) * step(0.01, uGlitch) * max(gate, forced);\n  // the cut type comes from the beat hash only (the kick level used to pick it and chattered on every attack)\n  float ty = floor(h.y * 4.999);\n  float panX = (hash11(bi * 0.713 + uSeed * 0.31 + 2.0) - 0.5) * 0.7;\n  // highs sub-divide the cut into on/off strips (spatial, so no extra flashes in time)\n  float hi = uHigh * uAudioReact;\n  if (hi > 0.4) {\n    float nb = 4.0 * exp2(floor(min(hi, 1.2) * 2.0));\n    cut *= step(mod(floor(uv.x * nb), 2.0), 0.5);\n  }\n  float neg = cut * step(ph * L, 1.3 / 60.0) * max(step(1.35, kEst), step(h.z, (uGlitch - 0.75) * 0.8));\n  float env = exp(-ph * 5.0);\n  float zoom = 1.0 + (0.04 * min(kick, 1.5) + 0.14 * cut * min(kEst + gate * 0.5, 1.5) * env) * step(0.01, uGlitch);\n  vec2 pz = p / zoom;\n  vec3 rgb;\n  float a;\n  if (cut < 0.5) {\n    vec4 c = logoRGBA(pz);\n    rgb = c.rgb * c.a;\n    a = c.a;\n  } else {\n    vec2 q = pz;\n    if (ty < 0.5) q = vec2(panX, (h.z - 0.5) * 0.08) + pz / 1.45;\n    else if (ty < 1.5) q.y = -q.y;\n    else if (ty < 2.5) q.x = abs(q.x) * (h.z < 0.5 ? -1.0 : 1.0);\n    else if (ty < 3.5) q = uv2p(fract(uv * 2.0)) / zoom;   // 2x2 tile, each copy punches around its own centre\n    float nS = floor(max(uScanDensity, 50.0) / 24.0);\n    float band = floor(uv.y * nS);\n    float bh = hash12(vec2(band + 0.5, bi * 0.917 + uSeed));\n    float big = step(3.5, ty);\n    // slice-and-shift: blocky quantised shifts on half the bands (light 1-step jitter on the other cut types)\n    float sh = floor((bh - 0.5) * mix(1.6, 8.0, big) + 0.5) * 0.04;\n    q.x += sh * step(mix(0.6, 0.45, big), hash12(vec2(band * 1.7 + 3.0, bi)));\n    if (neg > 0.5) {\n      vec4 c0 = logoRGBA(q);\n      float d = 0.032;\n      float pl = max(c0.a, max(logoP(q + vec2(d, 0.0)), max(logoP(q - vec2(d, 0.0)), logoP(q + vec2(0.0, d)))));\n      rgb = mix(vec3(0.85) * pl, (vec3(1.0) - c0.rgb) * 0.12, c0.a);\n      a = pl;\n    } else {\n      vec2 off = vec2(min(uChannelOffset, 0.012) * asp * (0.45 + 0.4 * h.z) * (h.y < 0.5 ? -1.0 : 1.0), 0.0);\n      vec4 sr = logoRGBA(q + off);\n      vec4 sg = logoRGBA(q);\n      vec4 sb = logoRGBA(q - off);\n      // luma anchor: the split never pushes the mark off its own palette for more than 40%\n      rgb = mix(vec3(sr.r * sr.a, sg.g * sg.a, sb.b * sb.a), sg.rgb * sg.a, 0.4);\n      a = max(sg.a, max(sr.a, sb.a));\n      rgb *= 0.84 + 0.16 * step(0.5, fract(uv.y * uScanDensity / 6.0));\n    }\n  }\n  gl_FragColor = vjOut(rgb, a);\n}\n"},{"id":"glitch-pixelsort","name":"Pixel-Sort Alpha Streaks","category":"glitch","blurb":"Asendorf-style sorted streak bands: ink in each row segment is sorted to one end, re-rolled every beat.","params":[{"name":"uGlitch","label":"Glitch Burst Intensity","type":"float","default":0.55,"min":0,"max":1,"hint":"Share of row bands that sort each beat, segment length and how long the sort holds. 0 = untouched logo."},{"name":"uGlitchFreq","label":"Frequency Interval","type":"float","default":0.35,"min":0.25,"max":2,"unit":"s","hint":"Beat length in seconds (60 \u00c3\u00b7 BPM; 0.484 = 124 BPM). With Beat Phase mapped, cuts land on the beat; unmapped, a free clock at this interval runs. Cut rate is capped at 3/s."},{"name":"uScanDensity","label":"Scanline Density","type":"float","default":420,"min":50,"max":1200,"unit":"lines","hint":"Sort row density: gate bands = density \u00c3\u00b7 16, ragged rows = density \u00c3\u00b7 2 per frame height."},{"name":"uChannelOffset","label":"Color Channel Offset","type":"float","default":0.012,"min":0,"max":0.06,"hint":"Channel fringe on the sorted streak edges."},{"name":"uSeed","label":"Seed Randomization","type":"float","default":7,"min":0,"max":999,"hint":"Re-rolls band gating, segment placement and sort direction."},{"name":"uBeat","label":"Beat Phase","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"beat","hint":"Sawtooth 0\u00e2\u2020\u20191 per beat (app BPM clock). In Resolume, map to a BPM-synced parameter; in TD, a beat CHOP ramp."},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Asendorf Rows","values":{"uGlitchFreq":0.484}},{"name":"Melt Down","values":{"uGlitchFreq":0.484,"uGlitch":0.9,"uScanDensity":260,"uChannelOffset":0.02,"uAudioReact":1.3}},{"name":"Fine Sort","values":{"uGlitchFreq":0.484,"uGlitch":0.4,"uScanDensity":900,"uChannelOffset":0.004,"uSeed":99}}],"source":"/*{\n  \"DESCRIPTION\": \"Pixel-Sort Alpha Streaks \u00e2\u20ac\u201d Asendorf-style sorted streak bands: ink in each row segment is sorted to one end, re-rolled every beat.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Glitch & Cyber\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uGlitch\",\"TYPE\":\"float\",\"LABEL\":\"Glitch Burst Intensity\",\"DEFAULT\":0.55,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uGlitchFreq\",\"TYPE\":\"float\",\"LABEL\":\"Frequency Interval\",\"DEFAULT\":0.35,\"MIN\":0.25,\"MAX\":2},\n    {\"NAME\":\"uScanDensity\",\"TYPE\":\"float\",\"LABEL\":\"Scanline Density\",\"DEFAULT\":420,\"MIN\":50,\"MAX\":1200},\n    {\"NAME\":\"uChannelOffset\",\"TYPE\":\"float\",\"LABEL\":\"Color Channel Offset\",\"DEFAULT\":0.012,\"MIN\":0,\"MAX\":0.06},\n    {\"NAME\":\"uSeed\",\"TYPE\":\"float\",\"LABEL\":\"Seed Randomization\",\"DEFAULT\":7,\"MIN\":0,\"MAX\":999},\n    {\"NAME\":\"uBeat\",\"TYPE\":\"float\",\"LABEL\":\"Beat Phase\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Pixel-Sort Alpha Streaks \u00c2\u00b7 Glitch & Cyber\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\n// ---- effect ----\nvec2 gxBeat(float L) {\n  float q = TIME / L;\n  bool driven = uBeat > 0.0005;\n  float ph = driven ? uBeat : fract(q + 0.5);\n  return vec2(ph, driven ? floor(q - ph + 0.5) : floor(q + 0.5));\n}\nfloat gxEligible(float idx, float L) {\n  float k = exp2(ceil(log2(max(1.0 / (3.0 * L), 1.0)) - 0.001));\n  return step(mod(idx, k), 0.5);\n}\n\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float asp = RENDERSIZE.x / RENDERSIZE.y;\n  float kick = uBass * uAudioReact;\n  float L = max(uGlitchFreq, 0.05);\n  vec2 bt = gxBeat(L);\n  float ph = bt.x;\n  float bi = bt.y;\n  float duty = 0.16 + 0.24 * uGlitch;\n  float kEst = min(kick * exp(6.0 * min(ph, duty)), 1.5);\n  float on = min(uGlitch * 4.0, 1.0);\n  p /= 1.0 + 0.035 * min(kick, 1.5) * on;\n  float burst = step(ph, duty) * gxEligible(bi, L) * step(0.001, uGlitch);\n  // the sort grows into the run over the first 30% of the window instead of snapping in fully formed\n  float grow = smoothstep(0.0, 0.3 * duty, ph);\n  float dens = max(uScanDensity, 50.0);\n  float hi = uHigh * uAudioReact;\n  float bandN = floor(dens / 16.0);\n  float band = floor(p.y * bandN);\n  vec3 bh = hash32(vec2(band + 0.5, bi * 1.13 + uSeed * 0.37));\n  // phrase rhythm: downbeats gate more bands than off-beats\n  float barW = mod(bi, 4.0) < 0.5 ? 1.0 : 0.6;\n  float gate = step(bh.x, uGlitch * (0.35 + 0.2 * kEst) * barW);\n  vec4 lg = logoRGBA(p);\n  vec3 rgb = lg.rgb * lg.a;\n  float a = lg.a;\n  if (burst * gate > 0.5) {\n    float row = floor(p.y * dens * 0.5);\n    float rj = hash11(row * 0.731 + bi * 3.7 + uSeed);\n    float W = (0.16 + 0.42 * bh.y) * (0.7 + 0.5 * uGlitch) * (1.0 + 0.6 * kEst) * (1.0 + 0.5 * clamp(hi, 0.0, 1.0));\n    float phase = bh.z * W + (rj - 0.5) * 0.035;\n    float seg = floor((p.x - phase) / W);\n    float dir = hash12(vec2(seg + 3.1, band + bi * 0.37 + uSeed)) < 0.5 ? -1.0 : 1.0;\n    float a0 = phase + seg * W;\n    // 24 stratified taps: ink fraction, the ink span [x0, x1] and colours at both span ends + the mean\n    float cum = 0.0;\n    float x0 = 9.0;\n    float x1 = -9.0;\n    vec3 cLo = vec3(0.0);\n    vec3 cHi = vec3(0.0);\n    vec3 cSum = vec3(0.0);\n    for (int i = 0; i < 24; i++) {\n      float xs = a0 + W * (float(i) + 0.5 + (rj - 0.5) * 0.8) / 24.0;\n      vec4 s = logoRGBA(vec2(xs, p.y));\n      cum += s.a / 24.0;\n      cSum += s.rgb * s.a;\n      if (s.a > 0.5) {\n        if (x0 > 8.0) { x0 = xs; cLo = s.rgb; }\n        x1 = xs;\n        cHi = s.rgb;\n      }\n    }\n    float has = step(0.001, cum) * step(x0, 8.0);\n    float c = mix(x1 - x0, cum * W, grow);\n    // the sorted mass is pushed to the end of the ink span plus a short overshoot (the streak tip), so ink\n    // never travels far from the mark and never piles up against the frame edge\n    float xm = asp * 0.5 - 0.04;\n    float over = min((0.03 + 0.09 * kEst) * (0.5 + uGlitch), 0.08) * grow;\n    float E = dir > 0.0 ? min(x1 + over, min(a0 + W, xm)) : max(x0 - over, max(a0, -xm));\n    E = mix(dir > 0.0 ? x1 : x0, E, grow);\n    float d = dir > 0.0 ? E - p.x : p.x - E;\n    float co = uChannelOffset * 0.9;\n    float mG = step(0.0, d) * step(d, c) * has;\n    float mR = step(0.0, d) * step(d, c + co) * has;\n    float mB = step(0.0, d) * step(d, c - co) * has;\n    // colour runs start -> mean -> end of the ink, ordered dark to bright like a luminance sort\n    vec3 c0 = dir > 0.0 ? cLo : cHi;\n    vec3 c1 = dir > 0.0 ? cHi : cLo;\n    vec3 lw = vec3(0.299, 0.587, 0.114);\n    if (dot(c0, lw) > dot(c1, lw)) { vec3 tmp = c0; c0 = c1; c1 = tmp; }\n    vec3 cm = cSum / max(cum * 24.0, 0.001);\n    float sp = clamp(1.0 - d / max(c, 0.0001), 0.0, 1.0);\n    vec3 base = sp < 0.5 ? mix(c0, cm, sp * 2.0) : mix(cm, c1, sp * 2.0 - 1.0);\n    // sorted gradient (dim start, hot end); fringe pixels outside the mass keep full strength\n    rgb = base * mix(1.0, 0.74 + 0.42 * sp, mG) * vec3(mR, mG, mB);\n    a = max(mG, max(mR, mB));\n  }\n  gl_FragColor = vjOut(rgb, a);\n}\n"},{"id":"glitch-ledwall","name":"LED Pixel-Wall Build","category":"glitch","blurb":"The logo builds on an LED wall: cells ignite along a scanning front, then pixel pitch resolves coarse \u00e2\u2020\u2019 fine until crisp.","params":[{"name":"uGlitch","label":"Glitch Burst Intensity","type":"float","default":0.55,"min":0,"max":1,"hint":"Ignition chaos (random spread around the scanning front); above 0.2, LED-cabinet faults during the build (1-cell mis-maps, low bit depth, dead modules)."},{"name":"uGlitchFreq","label":"Frequency Interval","type":"float","default":0.35,"min":0.25,"max":2,"unit":"s","hint":"How often cabinet faults (mis-mapped, low bit-depth or dead modules) re-roll during the build."},{"name":"uScanDensity","label":"Scanline Density","type":"float","default":420,"min":50,"max":1200,"unit":"lines","hint":"Coarsest LED pitch: rows per frame height = density \u00c3\u00b7 16, doubling each resolve step."},{"name":"uChannelOffset","label":"Color Channel Offset","type":"float","default":0.012,"min":0,"max":0.06,"hint":"RGB sub-pixel fringing: visible R/G/B dies on coarse pitches and channel misregistration."},{"name":"uSeed","label":"Seed Randomization","type":"float","default":7,"min":0,"max":999,"hint":"Re-rolls the ignition order and cabinet faults."},{"name":"uResolve","label":"Build / Resolve Progress","type":"float","default":1,"min":0,"max":1,"auto":{"on":true,"shape":"tri","rate":0.07,"lo":0,"hi":1},"hint":"Ignition sweep (0\u00e2\u20ac\u201c0.3), pitch resolve sweeping left \u00e2\u2020\u2019 right (0.3\u00e2\u20ac\u201c0.94), exact logo hold (0.94\u00e2\u20ac\u201c1)."},{"name":"uBloom","label":"LED Bloom","type":"float","default":0.55,"min":0,"max":1,"hint":"4-neighbour LED bloom around lit pixels (kick flares it)."},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Stadium Build","values":{"uGlitch":0.35}},{"name":"Brand Calm","values":{"uGlitch":0.08,"uBloom":0.35,"uChannelOffset":0.004,"uAudioReact":0.25,"uScanDensity":480},"auto":{"uResolve":{"rate":0.05}}},{"name":"Club Riot","values":{"uGlitch":0.85,"uGlitchFreq":0.2,"uBloom":0.85,"uChannelOffset":0.026,"uAudioReact":1.4,"uScanDensity":400},"auto":{"uResolve":{"rate":0.11}}}],"source":"/*{\n  \"DESCRIPTION\": \"LED Pixel-Wall Build \u00e2\u20ac\u201d The logo builds on an LED wall: cells ignite along a scanning front, then pixel pitch resolves coarse \u00e2\u2020\u2019 fine until crisp.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Glitch & Cyber\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uGlitch\",\"TYPE\":\"float\",\"LABEL\":\"Glitch Burst Intensity\",\"DEFAULT\":0.55,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uGlitchFreq\",\"TYPE\":\"float\",\"LABEL\":\"Frequency Interval\",\"DEFAULT\":0.35,\"MIN\":0.25,\"MAX\":2},\n    {\"NAME\":\"uScanDensity\",\"TYPE\":\"float\",\"LABEL\":\"Scanline Density\",\"DEFAULT\":420,\"MIN\":50,\"MAX\":1200},\n    {\"NAME\":\"uChannelOffset\",\"TYPE\":\"float\",\"LABEL\":\"Color Channel Offset\",\"DEFAULT\":0.012,\"MIN\":0,\"MAX\":0.06},\n    {\"NAME\":\"uSeed\",\"TYPE\":\"float\",\"LABEL\":\"Seed Randomization\",\"DEFAULT\":7,\"MIN\":0,\"MAX\":999},\n    {\"NAME\":\"uResolve\",\"TYPE\":\"float\",\"LABEL\":\"Build / Resolve Progress\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uBloom\",\"TYPE\":\"float\",\"LABEL\":\"LED Bloom\",\"DEFAULT\":0.55,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// LED Pixel-Wall Build \u00c2\u00b7 Glitch & Cyber\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\nfloat glitchClock() { return floor(TIME / max(uGlitchFreq, 0.02)); }\nfloat glitchBurst(float gt) {\n  float b = step(1.0 - uGlitch * 0.85, hash11(gt * 1.371 + uSeed * 0.173));\n  return max(b, step(0.65, uBass * uAudioReact));\n}\n\n// ---- effect ----\nfloat lwIgnite(vec2 ci, float n, float ign, float spread) {\n  vec2 c = (ci + 0.5) / n;\n  float front = c.x / (RENDERSIZE.x / RENDERSIZE.y) + 0.5;\n  float tI = front * (1.0 - spread) + hash12(ci + uSeed * 1.31) * spread;\n  float age = ign - tI;\n  if (age < 0.0) return 0.0;\n  return 1.0 + 1.6 * exp(-age * 18.0);\n}\n// One LED pitch level (n rows per frame height): round dot with R/G/B sub-pixel sampling + 4-neighbour bloom.\nvec4 lwLevel(vec2 p, float n, float ign, float spread, float bloom, float sub, float co, float fringe) {\n  vec2 g = p * n;\n  vec2 ci = floor(g);\n  vec2 f = g - ci - 0.5;\n  float cpx = RENDERSIZE.y / n;\n  vec2 cc = (ci + 0.5) / n;\n  // the pixel's colour is the logo at the cell centre; its R and B dies sit a third of a cell left/right, so on\n  // letter edges they catch slightly different coverage -> sub-pixel colour fringing (strength = fringe)\n  float dx = 0.3333 / n + co;\n  vec4 sR = logoRGBA(cc - vec2(dx, 0.0));\n  vec4 sG = logoRGBA(cc);\n  vec4 sB = logoRGBA(cc + vec2(dx, 0.0));\n  float cov = (sR.a + 2.0 * sG.a + sB.a) * 0.25;\n  vec3 base = (sR.rgb * sR.a + 2.0 * sG.rgb * sG.a + sB.rgb * sB.a) * 0.25;\n  vec3 v = mix(base, vec3(sR.r * sR.a, base.g, sB.b * sB.a), fringe);\n  vec3 lw = vec3(0.299, 0.587, 0.114);\n  v *= dot(base, lw) / max(dot(v, lw), 0.001);   // fringe shifts hue, never luma (no salmon/brown edges)\n  float e = lwIgnite(ci, n, ign, spread);\n  float aa = 1.0 / max(cpx, 1.0);\n  float dotm = 1.0 - smoothstep(0.45 - aa, 0.45 + aa, length(f));\n  float dm = mix(0.9, dotm * 1.3, smoothstep(2.5, 5.0, cpx));\n  // visible R/G/B dies inside each dot on coarse pitches (SMD look), separated by thin dark gaps\n  float stripe = 0.2 * sub * smoothstep(9.0, 15.0, cpx);\n  float gap = smoothstep(0.03, 0.06, abs(abs(f.x) - 0.1667));\n  vec3 sm = vec3(step(f.x, -0.1667), step(-0.1667, f.x) * step(f.x, 0.1667), step(0.1667, f.x)) * gap;\n  sm = mix(vec3(1.0), sm * 2.4, stripe);\n  vec3 col = v * e * dm * sm;\n  float al = cov * min(e, 1.0) * dm;\n  if (e <= 0.0) { col = v * 0.07 * dotm; al = cov * 0.07 * dotm; }\n  // bloom: own cell + 4 neighbours, gaussian around each lit centre (exactly 0 where no lit cell is near)\n  float d = max(1.0 / n, 0.011);\n  float sig2 = 0.56 * d * d;\n  vec2 pc = p - cc;\n  vec3 bl = v * e * exp(-dot(pc, pc) / sig2);\n  for (int k = 0; k < 4; k++) {\n    float ang = float(k) * 1.5707963;\n    vec2 nc = (floor((cc + vec2(cos(ang), sin(ang)) * d) * n) + 0.5) / n;\n    vec4 s = logoRGBA(nc);\n    float en = min(lwIgnite(floor(nc * n), n, ign, spread), 1.6);\n    vec2 pd = p - nc;\n    bl += s.rgb * s.a * en * exp(-dot(pd, pd) / sig2);\n  }\n  return vec4(col + bl * bloom * 0.35, al);\n}\n\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float asp = RENDERSIZE.x / RENDERSIZE.y;\n  float kick = uBass * uAudioReact;\n  float R = clamp(uResolve / 0.78, 0.0, 1.0);\n  float ign = R / 0.3 * 1.08 - 0.04;\n  float res = clamp((R - 0.3) / 0.64, 0.0, 1.0);\n  res *= res;   // ease-in: the coarse, readable-as-LED pitches get most of the time, fine ones pass quickly\n  // the resolve also sweeps left -> right (slight diagonal), so one frame shows the whole pitch ladder;\n  // a kick punches the wall back up to 3 levels coarser (level 1 still reads)\n  float sw = clamp((p.x / asp + 0.5) * 0.85 + (0.5 - p.y) * 0.15, 0.0, 1.0);\n  float punch = clamp((kick - 0.25) / 0.75, 0.0, 1.0) * (1.0 - smoothstep(0.9, 0.97, R));\n  float lev = clamp((res * 1.6 - 0.6 * sw) * 4.0 - 3.0 * punch, 0.0, 4.0);\n  float n0 = floor(max(uScanDensity, 50.0) / 16.0);\n  float l0 = floor(lev);\n  float fr = smoothstep(0.3, 0.7, lev - l0);\n  float spread = 0.15 + 0.6 * uGlitch;\n  float sub = clamp(uChannelOffset * 40.0, 0.0, 1.0);\n  float fringe = clamp(uChannelOffset * 20.0, 0.0, 1.0);\n  float co = uChannelOffset * 0.2;\n  float bloom = uBloom * (1.0 + 1.2 * min(kick, 1.5));\n  // LED-cabinet faults (6x6 coarse cells), only while building \u00e2\u20ac\u201d the hold is the exact logo\n  float gt = glitchClock();\n  float burst = glitchBurst(gt);\n  vec2 cab = floor(p * n0 / 6.0);\n  vec3 mh = hash32(cab + vec2(gt * 0.731, uSeed));\n  // faults need uGlitch above 0.15, so calm brand settings never show them\n  float fault = burst * step(mh.x, max(uGlitch - 0.2, 0.0) * 0.8) * (1.0 - smoothstep(0.7, 0.8, R)) * step(0.015, R);\n  vec2 pm = p;\n  if (fault > 0.5 && mh.y < 0.4) pm.x += (mh.z < 0.5 ? -1.0 : 1.0) / n0;\n  vec4 A;\n  if (l0 > 3.5) {\n    vec4 lg = logoRGBA(pm);\n    A = vec4(lg.rgb * lg.a, lg.a);\n  } else {\n    A = lwLevel(pm, n0 * exp2(l0), ign, spread, bloom, sub, co, fringe);\n    if (fr > 0.001) {\n      vec4 B;\n      if (l0 > 2.5) { vec4 lg = logoRGBA(pm); B = vec4(lg.rgb * lg.a, lg.a); }\n      else B = lwLevel(pm, n0 * exp2(l0 + 1.0), ign, spread, bloom, sub, co, fringe);\n      A = mix(A, B, fr);\n    }\n  }\n  vec3 rgb = A.rgb;\n  // fault looks keep the logo's own hues: low bit-depth module or a dead (dimmed) module\n  if (fault > 0.5 && mh.y >= 0.4) rgb = mh.y < 0.75 ? floor(rgb * 2.0 + 0.5) * 0.5 : rgb * 0.12;\n  gl_FragColor = vjOut(rgb, A.a);\n}\n"},{"id":"glitch-slicestagger","name":"Slice Stagger Settle","category":"glitch","blurb":"Disciplined glitch: thin slices slide in from alternating sides in quantised steps and snap into perfect alignment.","params":[{"name":"uGlitch","label":"Glitch Burst Intensity","type":"float","default":0.55,"min":0,"max":1,"hint":"Stagger spread between slices and slide distance (capped at ~15% of the logo width)."},{"name":"uGlitchFreq","label":"Frequency Interval","type":"float","default":0.35,"min":0.25,"max":2,"unit":"s","hint":"Step interval: larger = fewer, chunkier quantised steps (2\u00e2\u20ac\u201c16 per slide)."},{"name":"uScanDensity","label":"Scanline Density","type":"float","default":420,"min":50,"max":1200,"unit":"lines","hint":"Slice count: slices per frame height = density \u00c3\u00b7 12."},{"name":"uChannelOffset","label":"Color Channel Offset","type":"float","default":0.012,"min":0,"max":0.06,"hint":"Chroma fringe on moving slices only; settled slices are clean."},{"name":"uSeed","label":"Seed Randomization","type":"float","default":7,"min":0,"max":999,"hint":"Re-rolls the per-slice delays and which slices a kick shoves."},{"name":"uStagger","label":"Settle Progress","type":"float","default":1,"min":0,"max":1,"auto":{"on":true,"shape":"tri","rate":0.08,"lo":0,"hi":1},"hint":"Slices slide in and lock (0\u00e2\u20ac\u201c0.6), then hold perfectly aligned."},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Settle","values":{"uAudioReact":0.35}},{"name":"Hairline","values":{"uScanDensity":900,"uGlitch":0.3,"uChannelOffset":0.004}},{"name":"Chunky Steps","values":{"uScanDensity":200,"uGlitchFreq":1,"uGlitch":0.75,"uChannelOffset":0.016}}],"source":"/*{\n  \"DESCRIPTION\": \"Slice Stagger Settle \u00e2\u20ac\u201d Disciplined glitch: thin slices slide in from alternating sides in quantised steps and snap into perfect alignment.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Glitch & Cyber\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uGlitch\",\"TYPE\":\"float\",\"LABEL\":\"Glitch Burst Intensity\",\"DEFAULT\":0.55,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uGlitchFreq\",\"TYPE\":\"float\",\"LABEL\":\"Frequency Interval\",\"DEFAULT\":0.35,\"MIN\":0.25,\"MAX\":2},\n    {\"NAME\":\"uScanDensity\",\"TYPE\":\"float\",\"LABEL\":\"Scanline Density\",\"DEFAULT\":420,\"MIN\":50,\"MAX\":1200},\n    {\"NAME\":\"uChannelOffset\",\"TYPE\":\"float\",\"LABEL\":\"Color Channel Offset\",\"DEFAULT\":0.012,\"MIN\":0,\"MAX\":0.06},\n    {\"NAME\":\"uSeed\",\"TYPE\":\"float\",\"LABEL\":\"Seed Randomization\",\"DEFAULT\":7,\"MIN\":0,\"MAX\":999},\n    {\"NAME\":\"uStagger\",\"TYPE\":\"float\",\"LABEL\":\"Settle Progress\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Slice Stagger Settle \u00c2\u00b7 Glitch & Cyber\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\n// ---- effect ----\nfloat ssEase(float x) { x = clamp(x, 0.0, 1.0); float y = 1.0 - x; return 1.0 - y * y * y; }\n\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float asp = RENDERSIZE.x / RENDERSIZE.y;\n  float kick = uBass * uAudioReact;\n  float S = clamp(uStagger, 0.0, 1.0);\n  float u = S / 0.6;\n  float nS = floor(max(uScanDensity, 50.0) / 12.0);\n  float si = floor(uv.y * nS);\n  float side = mod(si, 2.0) < 0.5 ? -1.0 : 1.0;\n  float spread = 0.2 + 0.55 * uGlitch;\n  float dl = hash11(si * 1.37 + uSeed * 0.71 + 0.3) * spread;\n  float l = clamp((u - dl) / (1.0 - spread), 0.0, 1.0);\n  float steps = clamp(floor(2.8 / max(uGlitchFreq, 0.05)), 4.0, 16.0);\n  float lq = floor(l * steps) / steps;\n  float vis = step(0.0001, u - dl);\n  float amp = 0.19 * (0.35 + 0.65 * uGlitch);\n  float off = side * amp * (1.0 - ssEase(lq));\n  // kick: a subset of slices (re-rolled every 4 step intervals) is shoved sideways in quantised steps;\n  // the bass envelope decays, so they snap straight back into alignment\n  float gt = floor(TIME / (4.0 * max(uGlitchFreq, 0.05)));\n  float sh = hash12(vec2(si + 0.5, gt + uSeed));\n  // the shove fades out as the slices settle, so the hold is a real hold\n  off += step(sh, 0.25) * floor(min(kick, 1.5) * 6.0) / 6.0 * 0.08 * (sh < 0.125 ? -1.0 : 1.0) * (1.0 - smoothstep(0.78, 0.95, S));\n  vec2 q = p - vec2(off, 0.0);\n  float mv = clamp(abs(off) / 0.03, 0.0, 1.0);\n  vec2 co = vec2(uChannelOffset * asp * (0.3 + 8.0 * uChannelOffset) * mv * sign(off), 0.0);\n  vec4 sr = logoRGBA(q + co);\n  vec4 sg = logoRGBA(q);\n  vec4 sb = logoRGBA(q - co);\n  vec3 rgb = vec3(sr.r * sr.a, sg.g * sg.a, sb.b * sb.a);\n  float a = max(sg.a, max(sr.a, sb.a));\n  gl_FragColor = vjOut(rgb * vis, a * vis);\n}\n"},{"id":"glitch-halftone","name":"Bayer Halftone Decay","category":"glitch","blurb":"Row bands break into an LED-matrix Bayer dither or 45\u00c2\u00b0 AM halftone with CMY misregistration, then snap back crisp.","params":[{"name":"uGlitch","label":"Glitch Burst Intensity","type":"float","default":0.55,"min":0,"max":1,"hint":"Burst chance, share of row bands that break up, and how far the dots decay."},{"name":"uGlitchFreq","label":"Frequency Interval","type":"float","default":0.35,"min":0.25,"max":2,"unit":"s","hint":"Burst interval (s): each interval re-rolls which bands dither; bands snap crisp for the last third. Capped at 3 bursts/s."},{"name":"uScanDensity","label":"Scanline Density","type":"float","default":420,"min":50,"max":1200,"unit":"lines","hint":"Dot pitch: cell = 9 \u00c3\u00b7 density of the frame height; each burst band is 4 cells tall."},{"name":"uChannelOffset","label":"Color Channel Offset","type":"float","default":0.012,"min":0,"max":0.06,"hint":"CMY plate misregistration: the three channel dot fields are shifted 120\u00c2\u00b0 apart."},{"name":"uSeed","label":"Seed Randomization","type":"float","default":7,"min":0,"max":999,"hint":"Re-rolls band gating, dither/AM choice and decay pattern."},{"name":"uBeat","label":"Beat Phase","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"beat","hint":"Sawtooth 0\u00e2\u2020\u20191 per beat (app BPM clock). In Resolume, map to a BPM-synced parameter; in TD, a beat CHOP ramp."},{"name":"uLumaKey","label":"Luma Key (black-bg logo)","type":"bool","default":false,"group":"Input","hint":"Treat dark pixels as transparent \u00e2\u20ac\u201d for logos on black with no alpha."},{"name":"uAudioReact","label":"Audio Reactivity","type":"float","default":1,"min":0,"max":2,"group":"Audio"},{"name":"uBass","label":"Audio \u00c2\u00b7 Bass","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-bass"},{"name":"uMid","label":"Audio \u00c2\u00b7 Mid","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-mid"},{"name":"uHigh","label":"Audio \u00c2\u00b7 High","type":"float","default":0,"min":0,"max":1,"group":"Audio","driver":"audio-high"}],"presets":[{"name":"Dot Matrix","values":{"uScanDensity":600}},{"name":"Print Calm","values":{"uGlitch":0.25,"uGlitchFreq":1,"uChannelOffset":0.004,"uScanDensity":700,"uAudioReact":0.3,"uSeed":17}},{"name":"LED Riot","values":{"uGlitch":0.9,"uGlitchFreq":0.24,"uChannelOffset":0.02,"uScanDensity":260,"uAudioReact":1.4}}],"source":"/*{\n  \"DESCRIPTION\": \"Bayer Halftone Decay \u00e2\u20ac\u201d Row bands break into an LED-matrix Bayer dither or 45\u00c2\u00b0 AM halftone with CMY misregistration, then snap back crisp.\",\n  \"CREDIT\": \"VJTB Stinger Studio (logo testbed)\",\n  \"ISFVSN\": \"2\",\n  \"CATEGORIES\": [\"Glitch & Cyber\",\"VJTB\"],\n  \"INPUTS\": [\n    {\"NAME\":\"inputImage\",\"TYPE\":\"image\",\"LABEL\":\"Logo / layer input\"},\n    {\"NAME\":\"uGlitch\",\"TYPE\":\"float\",\"LABEL\":\"Glitch Burst Intensity\",\"DEFAULT\":0.55,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uGlitchFreq\",\"TYPE\":\"float\",\"LABEL\":\"Frequency Interval\",\"DEFAULT\":0.35,\"MIN\":0.25,\"MAX\":2},\n    {\"NAME\":\"uScanDensity\",\"TYPE\":\"float\",\"LABEL\":\"Scanline Density\",\"DEFAULT\":420,\"MIN\":50,\"MAX\":1200},\n    {\"NAME\":\"uChannelOffset\",\"TYPE\":\"float\",\"LABEL\":\"Color Channel Offset\",\"DEFAULT\":0.012,\"MIN\":0,\"MAX\":0.06},\n    {\"NAME\":\"uSeed\",\"TYPE\":\"float\",\"LABEL\":\"Seed Randomization\",\"DEFAULT\":7,\"MIN\":0,\"MAX\":999},\n    {\"NAME\":\"uBeat\",\"TYPE\":\"float\",\"LABEL\":\"Beat Phase\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uLumaKey\",\"TYPE\":\"bool\",\"LABEL\":\"Luma Key (black-bg logo)\",\"DEFAULT\":false},\n    {\"NAME\":\"uAudioReact\",\"TYPE\":\"float\",\"LABEL\":\"Audio Reactivity\",\"DEFAULT\":1,\"MIN\":0,\"MAX\":2},\n    {\"NAME\":\"uBass\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Bass\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uMid\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 Mid\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1},\n    {\"NAME\":\"uHigh\",\"TYPE\":\"float\",\"LABEL\":\"Audio \u00c2\u00b7 High\",\"DEFAULT\":0,\"MIN\":0,\"MAX\":1}\n  ]\n}*/\n\n// Bayer Halftone Decay \u00c2\u00b7 Glitch & Cyber\n// Generated by VJTB Stinger Studio. Single-pass, GLSL ES 1.00-portable ISF 2.0 effect.\n// Apply to a layer/clip holding the logo (alpha, or enable Luma Key for logos on black).\n// uBass / uMid / uHigh: map to your host audio analysis (Resolume: parameter \u00e2\u2020\u2019 Audio/FFT).\n\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }\nvec3 hash32(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yxz + 33.33); return fract((p3.xxy + p3.yzz) * p3.zyx); }\n\n// Closed-form 8x8 ordered-dither threshold in (0,1) for an integer pixel/cell coordinate (no arrays).\nfloat bayer8(vec2 c) {\n  vec2 a0 = mod(floor(c), 2.0); vec2 a1 = mod(floor(c / 2.0), 2.0); vec2 a2 = mod(floor(c / 4.0), 2.0);\n  float b0 = 2.0 * abs(a0.x - a0.y) + a0.y;\n  float b1 = 2.0 * abs(a1.x - a1.y) + a1.y;\n  float b2 = 2.0 * abs(a2.x - a2.y) + a2.y;\n  return (16.0 * b0 + 4.0 * b1 + b2 + 0.5) / 64.0;\n}\n\nmat2 rot2(float a) { float c = cos(a); float s = sin(a); return mat2(c, -s, s, c); }\n\nvec2 uv2p(vec2 uv) { return (uv - 0.5) * vec2(RENDERSIZE.x / RENDERSIZE.y, 1.0); }\nvec2 p2uv(vec2 p) { return p * vec2(RENDERSIZE.y / RENDERSIZE.x, 1.0) + 0.5; }\n\n// Clamped sample of the layer input. Coordinates go through a local first: the ISF-JS reference\n// parser splits IMG_NORM_PIXEL arguments on every comma, so nested calls like clamp(uv, 0.0, 1.0) break it.\nvec4 imgClamp(vec2 uv) { vec2 c = clamp(uv, 0.0, 1.0); return IMG_NORM_PIXEL(inputImage, c); }\n\n// Logo mask from the layer input: straight alpha, or luma-key for logos on black.\nfloat keyed(vec4 c) { return bool(uLumaKey) ? c.a * smoothstep(0.04, 0.3, max(c.r, max(c.g, c.b))) : c.a; }\nfloat logoA(vec2 uv) {\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  return keyed(imgClamp(uv)) * inb.x * inb.y;\n}\nfloat logoP(vec2 p) { return logoA(p2uv(p)); }\nvec4 logoRGBA(vec2 p) {\n  vec2 uv = p2uv(p);\n  vec2 inb = step(vec2(0.0), uv) * step(uv, vec2(1.0));\n  vec4 c = imgClamp(uv);\n  return vec4(c.rgb, keyed(c) * inb.x * inb.y);\n}\n\nfloat logoCov5(vec2 p, float r) {\n  return (logoP(p) + logoP(p + vec2(r, 0.0)) + logoP(p - vec2(r, 0.0)) + logoP(p + vec2(0.0, r)) + logoP(p - vec2(0.0, r))) * 0.2;\n}\n\n// Final write. Input is additive/premultiplied colour; output is straight alpha for ISF hosts,\n// or premultiplied when VJ_PREMULT is defined (TouchDesigner export).\nvec4 vjOutPM(vec4 pm) {\n  pm = max(pm, vec4(0.0));\n  float a = clamp(max(pm.a, max(pm.r, max(pm.g, pm.b))), 0.0, 1.0);\n#ifdef VJ_PREMULT\n  return vec4(min(pm.rgb, vec3(a)), a);\n#else\n  return vec4(min(pm.rgb / max(a, 0.0001), vec3(1.0)), a);\n#endif\n}\nvec4 vjOut(vec3 c, float solid) { return vjOutPM(vec4(c, solid)); }\n\n// ---- effect ----\n// One plate of the halftone. mode 0: ordered Bayer dither of round dots (LED matrix); 1: 45-degree AM dots (radius ~ sqrt c).\nfloat htDot(vec2 p, float cell, float mode, float decay, float y0, float y1, out vec2 cc) {\n  float aa = 1.2 / (RENDERSIZE.y * cell);\n  if (mode < 0.5) {\n    vec2 ci = floor(p / cell);\n    cc = (ci + 0.5) * cell;\n    float c = logoCov5(cc, cell * 0.5) * (1.0 - decay);\n    float on = c > bayer8(ci) ? 1.0 : 0.0;\n    return on * (1.0 - smoothstep(0.42 - aa, 0.42 + aa, length(p / cell - ci - 0.5))) * step(y0, cc.y) * step(cc.y, y1);\n  }\n  vec2 q = rot2(0.7853982) * p / cell;\n  cc = rot2(-0.7853982) * ((floor(q) + 0.5) * cell);\n  float tone = logoCov5(cc, cell * 0.35) * (1.0 - decay);\n  float r = sqrt(tone) * 0.62;\n  // keep only dots that fit inside the band, so no half-dots are sliced off at band edges\n  float inb = step(y0 + r * cell, cc.y) * step(cc.y, y1 - r * cell);\n  return (1.0 - smoothstep(r - aa, r + aa, length(fract(q) - 0.5))) * smoothstep(0.02, 0.08, tone) * inb;\n}\n\nvoid main() {\n  vec2 uv = isf_FragNormCoord;\n  vec2 p = uv2p(uv);\n  float asp = RENDERSIZE.x / RENDERSIZE.y;\n  float kick = uBass * uAudioReact;\n  // photosensitive cap: short intervals are stretched by a power of two so bursts never exceed 3 per second\n  float L = max(uGlitchFreq, 0.02);\n  L *= exp2(ceil(log2(max(1.0 / (3.0 * L), 1.0)) - 0.001));\n  // beat-locked when Beat Phase is mapped (one burst window per beat, capped), free clock otherwise\n  bool driven = uBeat > 0.0005;\n  float q = TIME / L;\n  float ph = driven ? uBeat : fract(q);\n  float gt = mod(driven ? floor(q - ph + 0.5) : floor(q), 4096.0);\n  // bursts come only from the capped clock (no kick-forced bursts that escape the cap); a kick widens the gating\n  float burst = step(1.0 - (0.25 + 0.55 * uGlitch), hash11(gt * 1.371 + uSeed * 0.173));\n  float dens = max(uScanDensity, 50.0);\n  float cell0 = 9.0 / dens;\n  float bandH = cell0 * 4.0;\n  float band = floor(p.y / bandH);\n  vec3 bh = hash32(vec2(band + 0.5, gt * 0.913 + uSeed * 0.37));\n  float on = burst * step(ph, 0.45) * step(bh.x, 0.2 + 0.5 * uGlitch + 0.25 * min(kick, 1.0)) * step(0.001, uGlitch);\n  vec4 lg = logoRGBA(p);\n  vec3 rgb = lg.rgb * lg.a;\n  float a = lg.a;\n  if (on > 0.5) {\n    float hi = uHigh * uAudioReact;\n    // power-of-two pitch changes keep the dot grid aligned with the band edges: kick = 2x cells, highs = finer cells\n    float cell = cell0 * exp2(step(0.5, kick) * step(0.7, uGlitch) - step(0.5, hi));\n    float y0 = band * bandH;\n    float y1 = y0 + bandH;\n    float mode = step(bh.y, 0.35);\n    // decay: a soft gradient across the band thins the dots, so the Bayer cross-hatch (or AM dot size) reads\n    // it deepens over the burst (the logo visibly decays into the dither), then the band snaps back crisp\n    float decay = uGlitch * (0.3 + 0.6 * bh.z) * (0.5 + 0.5 * sin(p.x * 3.0 + bh.z * 6.2831853 + gt * 1.7));\n    decay *= 0.4 + 0.6 * smoothstep(0.0, 0.5, ph);\n    // three plates (C, M, Y) evaluated with a 120-degree misregistration\n    vec2 oC = vec2(uChannelOffset * asp * 0.08, 0.0);\n    vec2 oM = rot2(2.0943951) * oC;\n    vec2 oY = rot2(4.1887902) * oC;\n    vec2 cC; vec2 cM; vec2 cY;\n    float mC = htDot(p + oC, cell, mode, decay, y0 + oC.y, y1 + oC.y, cC);\n    float mM = htDot(p + oM, cell, mode, decay, y0 + oM.y, y1 + oM.y, cM);\n    float mY = htDot(p + oY, cell, mode, decay, y0 + oY.y, y1 + oY.y, cY);\n    vec4 cc = logoRGBA(cM - oM);\n    vec3 dc = mix(vec3(0.85), cc.rgb, smoothstep(0.05, 0.3, cc.a));\n    // each plate carries the logo colour minus one primary; all three in register give back the logo colour\n    rgb = dc * (mC * vec3(0.0, 1.0, 1.0) + mM * vec3(1.0, 0.0, 1.0) + mY * vec3(1.0, 1.0, 0.0)) * 0.55;\n    // pull the plates back toward the logo colour: misregistration shows as crescents, not confetti\n    rgb = mix(rgb, dc * (mC + mM + mY) * 0.55, 0.7);\n    a = max(mC, max(mM, mY));\n  }\n  gl_FragColor = vjOut(rgb, a);\n}\n"}];
